  ui_story_5036_50360101_50_dialog_content = "「数日前に突然北境上空に現れたこの巨像は、\nおそらく暗面からやってきたと推測されている」",
  ui_story_5036_50360101_51_dialog_content = "「この予想は、匿名だが有力な科学者が同意しており、\nアストラ大陸中を騒がせている」",
  ui_story_5036_50360101_52_dialog_content = "「情報筋によると、この巨像にはナビゲーターも乗客もおらず、\nまた、殺傷性のある武器も装備していないという」",
  ui_story_5036_50360101_53_dialog_content = "「しかし、巨像の外部、特に底部に古代科学技術によって造られた、\n巨大スクリーンと音響設備が大量に装着されている」",
  ui_story_5036_50360101_54_dialog_content = "「現在、啓光と白夜城がこの漂泊の巨像を停止させることはできないか、\n調査中であり…」",
  ui_story_5036_50360101_55_dialog_content = "「さらにその後の対応について協議を行っている」",
