  ui_story_5036_50360101_65_dialog_content = "カレン？やっと戻ってきたのね！",
  ui_story_5036_50360101_66_dialog_content = "もう白夜城から出てこないのかと思ったわ。",
  ui_story_5036_50360101_67_dialog_content = "少し前にその巨像のことを聞いて不思議に思ったものだから、\n図書館で資料を調べていたのよ。",
  ui_story_5036_50360101_68_dialog_content = "ということは、何か有力な手がかりを見つけたのね？",
