  ui_story_5036_50360101_72_dialog_content = "そう。100年以上前の空の末裔は、\n故郷にこもって暮らし、光霊とはあまり接触を持たなかった。",
  ui_story_5036_50360101_73_dialog_content = "けれど、ある日突然、\n空の末裔が白夜城や啓光に助けを求めてきたの。",
  ui_story_5036_50360101_74_dialog_content = "その時の情報によると、空の末裔は、\n<color=#FFB400>「イクストウル」</color>という巨像と突然連絡が取れなくなったらしいわ。",
  ui_story_5036_50360101_75_dialog_content = "その「イクストウル」には大きな特徴があって――",
  ui_story_5036_50360101_76_dialog_content = "<color=#FFB400>外側に巨大スクリーンを装着していたそうよ</color>。",
  ui_story_5036_50360101_77_dialog_content = "巨大スクリーン？\nさっきの新聞にも、確かそう書いてあったわ。",
  ui_story_5036_50360101_78_dialog_content = "何より、100年前の空の末裔はその巨像を探し回ったけれど、\n結局見つけられなかった。",
  ui_story_5036_50360101_79_dialog_content = "つまり、新聞記事にあった巨像が、\nその「イクストウル」だってこと？",
  ui_story_5036_50360101_80_dialog_content = "それが私の推測よ。",
