  ui_story_5036_50360101_126_dialog_content = "毎日のように私をまともな記事一つ書けない、\n万年見習いだとバカにしている編集長も、これには驚くでしょうね…",
  ui_story_5036_50360101_127_dialog_content = "空の末裔を追うたくさんの影ノ街の記者の中で、\n真っ先に私が巨像に乗ったなんて。",
