  ui_story_5036_50360101_131_dialog_content = "オホン。皆さん、ご安心ください！\n私はプロの記者ですから。仕事は常に冷静に行っています。",
  ui_story_5036_50360101_132_dialog_content = "そのことじゃないんだ。",
