  ui_story_5036_50360101_135_dialog_content = "私も漂泊の巨像まで同行させていただけませんか？",
  ui_story_5036_50360101_136_dialog_content = "空の末裔の立場を明確に示す、\n感動的な独占取材記事を書くことをお約束します！",
  ui_story_5036_50360101_137_dialog_content = "そうすれば白夜城も啓光も、\n空の末裔の物に触れようなどという考えは捨てることでしょう！",
  ui_story_5036_50360101_138_dialog_content = "ううん…そんな大げさな話にする\nつもりはないんだけどな、アハハ…",
  ui_story_5036_50360101_139_dialog_content = "あら？何かしら？",
  ui_story_5036_50360101_140_dialog_content = "ブランディ、カバンから何か落ちたわよ。\nポスターかしら？",
  ui_story_5036_50360101_141_dialog_content = "あ、本当ですね。\n拾わないと…ありがとうございます！",
  ui_story_5036_50360101_142_dialog_content = "あれ、ポスターに写ってるのって…どこかで見たような気が？",
  ui_story_5036_50360101_143_dialog_content = "え？あ、本当だわ、これってゴルディでしょ！？",
  ui_story_5036_50360101_144_dialog_content = "『ゴーストハウス』の公開後に、\n一度「アンデルセンのゴーストハウス」で会ったことがあったわ。",
  ui_story_5036_50360101_145_dialog_content = "あの作品、好評だったのに、\nもう映画には出ないって言ってたわね。",
  ui_story_5036_50360101_146_dialog_content = "今は何してるのかしら？",
  ui_story_5036_50360101_147_dialog_content = "影ノ街で人気なのは確かみたいね。\nどこに行ってもポスターを見るもの。",
  ui_story_5036_50360101_148_dialog_content = "このポスターは街で見かけるようなものとは違いますよ。",
  ui_story_5036_50360101_149_dialog_content = "数量限定のプレミアムバージョンですから！",
  ui_story_5036_50360101_150_dialog_content = "あなたもゴルディのファンだったの？",
  ui_story_5036_50360101_151_dialog_content = "いいえ…私は「ディディ推し」とは言えませんね。",
  ui_story_5036_50360101_152_dialog_content = "「ディディ推し」？",
  ui_story_5036_50360101_153_dialog_content = "「ディディ推し」とは、ゴルディさんのファンのことです。",
  ui_story_5036_50360101_154_dialog_content = "私は『ゴーストハウス』公開後に、\n取材したことがあるだけです。",
  ui_story_5036_50360101_155_dialog_content = "とても明るく、心のきれいな方だと感じました。\nそよ風が私の周りにかかっていた霧を吹き飛ばしてくれたようでした。",
  ui_story_5036_50360101_156_dialog_content = "彼女に出会っていなかったら、\nこんなにも長い間、見習い記者なんてやっていられなかったかもしれません。",
  ui_story_5036_50360101_157_dialog_content = "それで、彼女の作品を少し気にするようになっただけです。",
  ui_story_5036_50360101_158_dialog_content = "フフフ…それがファンってことでしょ？",
  ui_story_5036_50360101_159_dialog_content = "そ、そうでしょうか？私はそうは思いませんが…\nそれに最近の話だと、ゴルディさんは暴力的になっているとウワサですし…",
  ui_story_5036_50360101_160_dialog_content = "まあ、華やかな舞台に上がる人物には、\n知られざる一面があるものなのでしょう。",
  ui_story_5036_50360101_161_dialog_content = "ですが、私は…暴力をふるう人は好きになれません。",
  ui_story_5036_50360101_162_dialog_content = "あの人が暴力的？そんなはずないわ。",
  ui_story_5036_50360101_163_dialog_content = "有名人にはデマカセの情報だって多いし、\n根も葉もないウワサでしょう？",
  ui_story_5036_50360101_164_dialog_content = "PlayerNameも昔、影ノ街のタブロイドに\n頭が3つで腕が6本の化け物みたいに書かれたことが有るわ。",
  ui_story_5036_50360101_165_dialog_content = "そうだったね。\nあの時は人のウワサの恐ろしさを身をもって知らされたよ。",
  ui_story_5036_50360101_166_dialog_content = "ブランディ、君はあることないこと書いたりしないでね。",
  ui_story_5036_50360101_167_dialog_content = "ご安心ください！",
  ui_story_5036_50360101_168_dialog_content = "私は自分の目で確かめた事実しか記事にしませんので！",
  ui_story_5036_50360101_169_dialog_content = "影ノ街の記者が皆、\n君みたいに良心のある記者だったらいいのにね…",
  ui_story_5036_50360101_170_dialog_content = "良心のある記者…？わ、私がですか？\nそ、そんな…えへへ…",
  ui_story_5036_50360101_171_dialog_content = "<color=#e8d9bb>「警告！警告！前方に正体不明の飛行物体を検知しました」</color>",
  ui_story_5036_50360101_172_dialog_content = "<color=#e8d9bb>「ただちに回避行動を発令してください」</color>",
  ui_story_5036_50360101_173_dialog_content = "正体不明の…飛行物体？",
  ui_story_5036_50360101_174_dialog_content = "ソラヴァンとはずいぶん違った見た目だけど…",
  ui_story_5036_50360101_175_dialog_content = "日差しを浴びて光る材質に、あの構造と形…\nあれが巨像じゃないかしら！？",
  ui_story_5036_50360101_176_dialog_content = "スクリーンは…",
  ui_story_5036_50360101_177_dialog_content = "あ、見えました！\nあの巨大な四角い物体はスクリーンではありませんか？",
  ui_story_5036_50360101_178_dialog_content = "どう見ても私たちの時代の物ではありませんね！",
  ui_story_5036_50360101_179_dialog_content = "きっとそうです！\nあれこそ新聞に出ていた漂泊の巨像です！",
  ui_story_5036_50360101_180_dialog_content = "でも、どうしてソラヴァン、\nあの巨像を識別できないんだろう？",
  ui_story_5036_50360101_181_dialog_content = "僕もナビゲーターの気配を感知できないし…",
  ui_story_5036_50360101_182_dialog_content = "君は本当に、100年前に消えたイクストウルなの？",
  ui_story_5036_50360101_183_dialog_content = "♪ラ…ラララ…♪",
  ui_story_5036_50360101_184_dialog_content = "（誰？誰かが歌ってる？）",
  ui_story_5036_50360101_185_dialog_content = "ねえ、聞こえた？",
  ui_story_5036_50360101_186_dialog_content = "何が？",
  ui_story_5036_50360101_187_dialog_content = "♪ル～ル～♪",
  ui_story_5036_50360101_188_dialog_content = "歌だよ…誰かが、歌ってない？",
  ui_story_5036_50360101_189_dialog_content = "え？誰も歌ってなんかいないわよ。",
  ui_story_5036_50360101_190_dialog_content = "♪ラララ…♪",
  ui_story_5036_50360101_191_dialog_content = "（君は…「イクストウル」のナビゲーター？）",
  ui_story_5036_50360101_192_dialog_content = "♪ル～ル～♪",
  ui_story_5036_50360101_193_dialog_content = "（どうして巨像を捨てたの？）",
  ui_story_5036_50360101_194_dialog_content = "♪ラ…ララ…♪",
  ui_story_5036_50360101_195_dialog_content = "（どうして…）",
  ui_story_5036_50360101_196_dialog_content = "<color=#e8d9bb>「警告！警告！前方に正体不明の飛行物体を検知しました」</color>",
  ui_story_5036_50360101_197_dialog_content = "<color=#e8d9bb>「衝突のリスクを回避するため、3秒後に飛行ルートを自動変更します」</color>",
  ui_story_5036_50360101_198_dialog_content = "<color=#e8d9bb>「3…」</color>",
  ui_story_5036_50360101_199_dialog_content = "<color=#e8d9bb>「2…」</color>",
  ui_story_5036_50360101_200_dialog_content = "ルート変更は停止して。",
  ui_story_5036_50360101_201_dialog_content = "移動を「正体不明の飛行物体」と同じ方向、同じ速度に調整して。",
  ui_story_5036_50360101_202_dialog_content = "随時、向こうの方向と速度に合わせて。",
  ui_story_5036_50360201_1_dialog_content = "<color=#e8d9bb>「警告！警告！正体不明の飛行物体に接近しています」</color>",
  ui_story_5036_50360201_2_dialog_content = "すごい揺れです！\nまさか、漂泊の巨像に衝突したのですか！？",
  ui_story_5036_50360201_3_dialog_content = "怖がることはないわ。\nソラヴァンが減速しただけよ。",
  ui_story_5036_50360201_4_dialog_content = "え？それは残念ですね…\n巨像衝突の瞬間をカメラに収められると思ったのですが。",
  ui_story_5036_50360201_5_dialog_content = "きっと全紙が一面トップで報道したでしょう！",
  ui_story_5036_50360201_6_dialog_content = "本当に衝突していたら、\nカメラを構えるどころの話ではないわ…",
  ui_story_5036_50360201_7_dialog_content = "もしもの話です！",
  ui_story_5036_50360201_8_dialog_content = "それにしても、ブランディのカメラ、\nずいぶん変わってるのね。",
  ui_story_5036_50360201_9_dialog_content = "バイスさん、お目が高い！",
  ui_story_5036_50360201_10_dialog_content = "カメラは貴重な取材道具ですし、\n誰でも持てるというワケではありません。",
  ui_story_5036_50360201_11_dialog_content = "私が自分で部品をあれこれ交換して、\nより衝撃的な写真を撮れるよう工夫しているのです。",
  ui_story_5036_50360201_12_dialog_content = "新聞社に見習い記者として入れたのも、\nこのカメラのおかげなのです！",
  ui_story_5036_50360201_13_dialog_content = "そうなの？じゃあ、あなたのカメラで撮れば、\nきれいに写るのかしら？",
  ui_story_5036_50360201_14_dialog_content = "きれいかどうかは分かりませんが、\n実物を見ているかのような迫真の一枚が撮れることは保証しますよ！",
  ui_story_5036_50360201_15_dialog_content = "<color=#e8d9bb>「飛行軌道修正完了、正体不明の飛行物体と\n相対位置を維持しています」</color>",
  ui_story_5036_50360201_16_dialog_content = "さあ、行こう。",
  ui_story_5036_50360201_17_dialog_content = "え？漂泊の巨像まで、\nまだだいぶ距離があるようですが？",
  ui_story_5036_50360201_18_dialog_content = "どうやって向こうに行くのですか？",
  ui_story_5036_50360201_19_dialog_content = "もちろん、飛んでいくんだ。",
  ui_story_5036_50360201_20_dialog_content = "<anim type=Shake>わあ！！</anim>",
  ui_story_5036_50360201_21_dialog_content = "ほ、本当に飛んでます！？",
  ui_story_5036_50360201_22_dialog_content = "飛空艇なんて初めてです！\n私、興奮してきました！",
  ui_story_5036_50360201_23_dialog_content = "私は今、本当に漂泊の巨像にいるのでしょうか？",
  ui_story_5036_50360201_24_dialog_content = "ああ、これこそ多くの記者が憧れる、ニュースの現場です！",
  ui_story_5036_50360201_25_dialog_content = "おっと…いくら感激していても、\nプロの記者として取材を忘れてはいけませんね。",
  ui_story_5036_50360201_26_dialog_content = "PlayerNameさんに話を聞かなくては！",
  ui_story_5036_50360201_27_dialog_content = "PlayerNameさん、今のお気持ちは…？",
  ui_story_5036_50360201_28_dialog_content = "…",
  ui_story_5036_50360201_29_dialog_content = "おや、ずいぶん顔色が悪いようですね？\nこれは啓光と白夜城に対する無言の抗議でしょうか…",
  ui_story_5036_50360201_30_dialog_content = "暗力だ！急に出てきたものすごい暗力を感知したんだ！",
  ui_story_5036_50360201_31_dialog_content = "え！？まさか、座標の間違いでしょうか？",
  ui_story_5036_50360201_32_dialog_content = "それは無いわ。座標はイルンティ裁判長から直接聞いたものよ。\n間違いはあり得ない。",
  ui_story_5036_50360201_33_dialog_content = "今はあれこれ考えてるヒマはないわ。\nまずは目の前の問題を解決しなくちゃ！",
  ui_story_5036_50360201_34_dialog_content = "<size=45>グォオオ！！！</size>",
  ui_story_5036_50360202_1_dialog_content = "♪ラ…ラララ…♪",
  ui_story_5036_50360202_2_dialog_content = "（また、この歌？）",
  ui_story_5036_50360202_3_dialog_content = "（聞いたことはないメロディのはずなのに、\nなぜか懐かしい気持ちになる）",
  ui_story_5036_50360202_4_dialog_content = "（まるで、もともと僕の血の中に流れていたものを、\n今になって思い出したような…）",
  ui_story_5036_50360202_5_dialog_content = "♪ウォウウォウ♪",
  ui_story_5036_50360202_6_dialog_content = "♪ラララ…♪",
  ui_story_5036_50360202_7_dialog_content = "き、君はいったい…？",
  ui_story_5036_50360202_8_dialog_content = "――空の末裔ごときが、\nこのマシュー様を忘れたとでもいう気か！？",
  ui_story_5036_50360202_9_dialog_content = "白夜城では私を軽んじられる者など居らぬというに！\n何たる侮辱！実に屈辱的だ！",
  ui_story_5036_50360202_10_dialog_content = "ローウェイ、おい…ん？\nお前、何をしている？",
  ui_story_5036_50360202_11_dialog_content = "カレン殿下、ご無事ですか？",
  ui_story_5036_50360202_12_dialog_content = "私は大丈夫よ。この程度の暗鬼、何でもないわ。",
  ui_story_5036_50360202_13_dialog_content = "いい時に駆け付けてくれたわね。\nおかげで、暗鬼が素早く片付いたわ。",
  ui_story_5036_50360202_14_dialog_content = "フン、これはこれは…\nお前を見くびっていたようだ。",
  ui_story_5036_50360202_15_dialog_content = "ローウェイ、いつから手柄の売り込みなど覚えた？",
  ui_story_5036_50360202_16_dialog_content = "調査は終わっていないのに…",
  ui_story_5036_50360202_17_dialog_content = "帰りたがっているヤツがいる。",
  ui_story_5036_50360202_18_dialog_content = "ほう！？",
  ui_story_5036_50360202_19_dialog_content = "ご機嫌取りに同僚の讒言（ざんげん）まで、\nいつの間にどこで覚えたのやら。",
  ui_story_5036_50360202_20_dialog_content = "カレン殿下、そいつの戯言に耳を貸してはなりませぬ。",
  ui_story_5036_50360202_21_dialog_content = "ここ数日の私は実に適切に手際よく、\n白夜城の漂泊の巨像に対する調査作業を進めておりますぞ。",
  ui_story_5036_50360202_22_dialog_content = "殿下には間もなく、私の調査報告書を白夜城の柔らかいビロードの椅子の上で、\nゆっくりお読みになっていただけるでしょう。",
  ui_story_5036_50360202_23_dialog_content = "へ～、じゃあ、うちのシヴォーンに付きまとってたのって、\nカンニングのつもりだったの？",
  ui_story_5036_50360202_24_dialog_content = "ガルー長官、どうかご安心を。",
  ui_story_5036_50360202_25_dialog_content = "調査資料は厳重に保管しておりますので。",
  ui_story_5036_50360202_26_dialog_content = "計画を見破られたようだぞ、\nもうその手は使えないな。",
  ui_story_5036_50360202_27_dialog_content = "我々のデータを検証しようとしていただけだ！\n何も分かって居らんくせに、余計なことを言うな！",
  ui_story_5036_50360202_28_dialog_content = "ガルー先輩！シヴォーン先生！",
  ui_story_5036_50360202_29_dialog_content = "ここへは巨像調査の任務で？",
  ui_story_5036_50360202_30_dialog_content = "あれあれ～、バイス！\n最近やせた？",
  ui_story_5036_50360202_31_dialog_content = "え、そうですか？",
  ui_story_5036_50360202_32_dialog_content = "PlayerName、バイスをイジメるようなら、\nあたしが横取りしちゃうからね～。",
  ui_story_5036_50360202_33_dialog_content = "そ、そんなことは…",
  ui_story_5036_50360202_34_dialog_content = "そうなんだ？へぇ～…",
  ui_story_5036_50360202_35_dialog_content = "ところで、来るのがずいぶん遅かったね？",
  ui_story_5036_50360202_36_dialog_content = "PlayerName、この巨像に\n関わらないつもりなのかと思いかけてたよ。",
  ui_story_5036_50360202_37_dialog_content = "私のつかんだ情報ですと…",
  ui_story_5036_50360202_38_dialog_content = "白夜城と啓光連邦はこの巨像の調査について、\nこれまで一度もPlayerName氏に公式な連絡を行っていませんね？",
  ui_story_5036_50360202_39_dialog_content = "あれ？また知らない女の子だね。",
  ui_story_5036_50360202_40_dialog_content = "はじめまして！\n『デイリー・スクープ速報版』の見習い記者、ブランディです。",
  ui_story_5036_50360202_41_dialog_content = "PlayerName氏の密着取材をさせていただいております。\n今の質問にお答えいただけますか？",
  ui_story_5036_50360202_42_dialog_content = "なぜ巨像を調査していると、\nPlayerName氏に伝えていなかったのですか？",
  ui_story_5036_50360202_43_dialog_content = "啓光連邦と白夜城が、空の末裔に黙って\n巨像を山分けしようとしているという情報は本当ですか？",
  ui_story_5036_50360202_44_dialog_content = "ふ～ん、記者って言ったっけ？\nじゃあ聞くけど、PlayerNameに知らせる義務が啓光にあるの？",
  ui_story_5036_50360202_45_dialog_content = "ガルー先輩！？",
  ui_story_5036_50360202_46_dialog_content = "ええ～？バイスがそんなにビックリしないでよ。",
  ui_story_5036_50360202_47_dialog_content = "アハハ、とりあえず、ちゃんと答えると…",
  ui_story_5036_50360202_48_dialog_content = "啓光連邦は情報が入ってすぐに、\n大勢の隊員で組織した調査団を派遣してる。",
  ui_story_5036_50360202_49_dialog_content = "近辺の空域や地上にも、\n多くの支援部隊が配置されてるよ。",
  ui_story_5036_50360202_50_dialog_content = "ただ、目的はあなたの言ったみたいな、\n巨像の占有じゃない。",
  ui_story_5036_50360202_51_dialog_content = "暗面から漂流してきた巨像が、\n啓光にどんな脅威を及ぼす可能性があるかを調べに来たの。",
  ui_story_5036_50360202_52_dialog_content = "だって、暗面から飛んできたんだよ？\nどんな<color=#FFB400>「乗客」</color>が乗ってるか、分からないでしょ？",
  ui_story_5036_50360202_53_dialog_content = "その点は、白夜城も同一の見解だ。",
  ui_story_5036_50360202_54_dialog_content = "…どうしてこの私がこんな任務で汗水を垂らさねばならぬのか、\nそれだけは解せんがな…",
  ui_story_5036_50360202_55_dialog_content = "この巨像が現れたってことも、\n別に機密情報じゃないよ？",
  ui_story_5036_50360202_56_dialog_content = "そもそも、PlayerNameがなんで知らなかったのか、\nこっちが不思議なぐらい。",
  ui_story_5036_50360202_57_dialog_content = "ええと、ちょっと色々あって…",
  ui_story_5036_50360202_58_dialog_content = "ふ～ん？",
  ui_story_5036_50360202_59_dialog_content = "まぁ、気にすることないわ！\n私たちも遅すぎたってワケじゃないみたいだし。",
  ui_story_5036_50360202_60_dialog_content = "ただ、分からないことが有るわ。\nどうして漂泊の巨像の入口に暗鬼がいたのかしら？",
  ui_story_5036_50360202_61_dialog_content = "カレン殿下、到着早々驚かせてしまい、\n申し訳ございませんが…",
  ui_story_5036_50360202_62_dialog_content = "率直に申し上げますと、\nこの巨像は殿下が足をお運びになるべき場所ではありませんな。",
  ui_story_5036_50360202_63_dialog_content = "チリとホコリまみれのクモの巣があちこちに張っておりますし、\n汚らわしい暗鬼まで無数に潜んでおるのです。",
  ui_story_5036_50360202_64_dialog_content = "幸い、安全上の心配は大きくありませぬ。",
  ui_story_5036_50360202_65_dialog_content = "この数日で大部分の暗鬼は巨像の尾の部分にある、\n<color=#FFB400>封鎖エリア</color>に押し込めております。",
  ui_story_5036_50360202_66_dialog_content = "どうかご安心を。",
  ui_story_5036_50360202_67_dialog_content = "すでに暗鬼掃討の戦力も強化されております。\n私が保証いたしましょう！",
  ui_story_5036_50360202_68_dialog_content = "汚らわしい暗鬼どもが\nこれ以上殿下を煩わせることはございません。",
  ui_story_5036_50360202_69_dialog_content = "よくやってくれたわ、マシュー裁判官。",
  ui_story_5036_50360202_70_dialog_content = "光栄至極。",
  ui_story_5036_50360202_71_dialog_content = "ということは、この巨像は今のところ安全なんだね？",
  ui_story_5036_50360202_72_dialog_content = "エンドコンテンツの<color=#FFB400>封鎖エリア</color>にさえ入らなければ、\n命の心配はないと思うよ～。",
  ui_story_5036_50360202_73_dialog_content = "ガルー、聞いてもいいかな？\nこの巨像の…",
  ui_story_5036_50360202_74_option_content = "制御システムはどうなってるの？",
  ui_story_5036_50360202_75_dialog_content = "僕なら着陸させられるかもしれないよ。",
  ui_story_5036_50360202_76_dialog_content = "あたしもそう思って、\n漂泊の巨像のブリッジを詳しく調べてみたの。",
  ui_story_5036_50360202_77_dialog_content = "でも、制御システムやナビゲートシステムどころか、\n意識モジュールまで破壊されてた…",
  ui_story_5036_50360202_78_dialog_content = "だからPlayerNameでも、\nこの巨像を操縦するのは無理じゃないかな。",
  ui_story_5036_50360202_79_dialog_content = "そんな…じゃあ…",
  ui_story_5036_50360202_80_option_content = "エネルギーコアは？",
  ui_story_5036_50360202_81_dialog_content = "巨像が今も飛行してるってことは、\n動力に問題はないんだよね？",
  ui_story_5036_50360202_82_dialog_content = "問題ないって言っても、間違ってはいないかな。",
  ui_story_5036_50360202_83_dialog_content = "いちおうエネルギーを供給して、\n飛行を維持できてるから。",
  ui_story_5036_50360202_84_dialog_content = "でも、問題なくはないって言っても間違いじゃないよ。",
  ui_story_5036_50360202_85_dialog_content = "暗鬼の攻撃を受けたことがあるみたいで…",
  ui_story_5036_50360202_86_dialog_content = "急に機能停止ってとこまでは行ってないけど、\nエネルギーの変換効率が落ちてる。",
  ui_story_5036_50360202_87_dialog_content = "修理…できるんだよね？",
  ui_story_5036_50360202_88_dialog_content = "動力コアの修理って、\nそう簡単にできることじゃないんだよ。",
  ui_story_5036_50360202_89_dialog_content = "少なくとも、まずは運転を停めて、\nそれから動力コアを切らないと。",
  ui_story_5036_50360202_90_dialog_content = "それからじゃないと、\n十分な点検と修理は無理だね。",
  ui_story_5036_50360202_91_dialog_content = "でも、今のところ、\nこの巨像を停める方法が見つかってないんだよね～…",
  ui_story_5036_50360202_92_dialog_content = "そんな…じゃあ…",
  ui_story_5036_50360202_93_option_content = "スクリーンと音響設備って、どういうこと？",
  ui_story_5036_50360202_94_dialog_content = "この巨像、外側にスクリーンと\n音響設備みたいなものが付いてたよね。",
  ui_story_5036_50360202_95_dialog_content = "うん、そうだよ。\nあれは本物のスクリーンと音響設備ね。",
  ui_story_5036_50360202_96_dialog_content = "しかも、今の技術レベルを\nはるかに超えるハイテク設備！",
  ui_story_5036_50360202_97_dialog_content = "そうとうな年代モノだけど、\nその割には全く損傷がないの。",
  ui_story_5036_50360202_98_dialog_content = "シヴォーンが手伝ってくれたおかげで、\nスクリーンと音響設備の使い方は分かってるよ！",
  ui_story_5036_50360202_99_dialog_content = "あんな大きなスクリーンで映画でも上映したら、\nきっとすごい迫力だろうね！",
  ui_story_5036_50360202_100_dialog_content = "それから…",
  ui_story_5036_50360202_100X1_dialog_content = "他に質問は？",
  ui_story_5036_50360202_100X2_option_content = "ある",
  ui_story_5036_50360202_100X3_option_content = "もうないよ",
  ui_story_5036_50360202_101_dialog_content = "あ、そうだ…",
  ui_story_5036_50360202_102_dialog_content = "中で空の末裔本人か、\n空の末裔の残したものを見つけなかった？",
  ui_story_5036_50360202_103_dialog_content = "ううん、今のところまだ。",
  ui_story_5036_50360202_104_dialog_content = "あ、そうそう、そういえば…",
  ui_story_5036_50360202_105_dialog_content = "シヴォーンが歴史資料を調べて、\nこの巨像に関する情報を見つけてくれたの。",
  ui_story_5036_50360202_106_dialog_content = "見た目から判断しても、規模から判断しても、\nこの巨像は100年前、空の末裔から連絡が取れなくなったと報告があった――",
  ui_story_5036_50360202_107_dialog_content = "<color=#FFB400>イクストウル？</color>",
  ui_story_5036_50360202_108_dialog_content = "な～んだ、知ってたの？",
  ui_story_5036_50360202_109_dialog_content = "だが、残念だったな。\n名前など、知ったところで何の意味もない。",
  ui_story_5036_50360202_110_dialog_content = "邪悪な科学技術を満載した巨像など、\n破壊される他に道はないのだからな。",
  ui_story_5036_50360202_111_dialog_content = "破壊？誰が壊そうとしてるの？",
  ui_story_5036_50360202_112_dialog_content = "誤解はしないでもらいたい。\n私一人で決めたことではないのでな。",
  ui_story_5036_50360202_113_dialog_content = "目下、それが最良の選択肢なのだ。\nここにいる者もほとんどは賛同するだろう。",
  ui_story_5036_50360202_114_dialog_content = "ちょっと、そこのいかにもワルそ～な顔の人…",
  ui_story_5036_50360202_115_dialog_content = "その結論は急ぎすぎなんじゃない？\nあたしは賛同なんてしてないよ。",
  ui_story_5036_50360202_116_dialog_content = "フン、最後には同意せざるを得んさ。",
  ui_story_5036_50360202_117_dialog_content = "マシュー、どういうこと？\nきちんと説明しなさい。",
  ui_story_5036_50360202_118_dialog_content = "カレン殿下、先程の話はお聞きになっていたでしょうな？",
  ui_story_5036_50360202_119_dialog_content = "漂泊の巨像には何の利用価値もありませぬ。\nそのうえ、殲滅できないほど多数の暗鬼が棲みついておるのです。",
  ui_story_5036_50360202_120_dialog_content = "このまま漂流させておいては、\nアストラ大陸に生きる者すべてにとって、脅威となるでしょうな。",
  ui_story_5036_50360202_121_dialog_content = "それから…",
  ui_story_5036_50360202_122_dialog_content = "このまま空を飛ばせておいて、\n万が一白夜城に衝突でもしたら、いかがなさるおつもりですかな？",
  ui_story_5036_50360202_123_dialog_content = "漂泊の巨像の破壊は、\n我らが白夜城を守ることにもつながるのです。",
  ui_story_5036_50360202_124_dialog_content = "殿下は私などよりもよくお分かりだと思いますがね。\n城主様がここにお出ましでも、同じ決断をなさるでしょうな。",
  ui_story_5036_50360202_125_dialog_content = "啓光の探索隊は巨像の痕跡を求めて、\n荒野をずっと捜索し続けてるんです。",
  ui_story_5036_50360202_126_dialog_content = "今こうして、ようやく運転を続ける巨像を発見できたというのに、\n本当に…破壊してしまうんですか？",
  ui_story_5036_50360202_127_dialog_content = "バイス、そんないかにも悪役面なヤツのデタラメなんか、\n真に受けちゃダメだよ。",
  ui_story_5036_50360202_128_dialog_content = "計算は済んでるの。今の巨像の飛行ルートから判断して、\n白夜城に衝突することなんてありえない。",
  ui_story_5036_50360202_129_dialog_content = "掃討を続けていけば、中にいる暗鬼だって、\n必ず全部片づけられるよ。",
  ui_story_5036_50360202_130_dialog_content = "それに、イクストウルは\nそいつが言うほど無価値じゃないし。",
  ui_story_5036_50360202_131_dialog_content = "どの部分をとっても、すごい研究価値があるの。",
  ui_story_5036_50360202_132_dialog_content = "あちこちボロボロだし、\n修理はかなり大変そうだけど…",
  ui_story_5036_50360202_133_dialog_content = "どれほどの労力と時間がかかっても、\nそうする価値はあるはず！",
  ui_story_5036_50360202_134_dialog_content = "それで、分かっているのか？",
  ui_story_5036_50360202_135_dialog_content = "研究対象にできる部分を取り外してから、巨像を撃ち落とす。\nそれにどれだけの代価が必要か。",
  ui_story_5036_50360202_136_dialog_content = "制御の効かない独活（うど）の大木を\n空に飛ばしたままにしておける理由があるとでも？",
  ui_story_5036_50360202_137_dialog_content = "研究対象は完全体であればあるほど、価値があるの！",
  ui_story_5036_50360202_138_dialog_content = "では、論拠を提示していただこう。\nこの巨像を修復できる可能性は？",
  ui_story_5036_50360202_139_dialog_content = "そ、それは…推定にはまだ時間がかかるよ！",
  ui_story_5036_50360202_140_dialog_content = "時間にも待てと言うつもりか？",
  ui_story_5036_50360202_141_dialog_content = "長引けば長引くほど、経費も危険も膨らむもの…",
  ui_story_5036_50360202_142_dialog_content = "いち早く巨像を撃ち落とし、任務を完遂として、\n互いの帰途に着く方がよほど良いと思うが？",
  ui_story_5036_50360202_143_dialog_content = "やはり、あなたが早く帰りたいだけでしょう？",
  ui_story_5036_50360202_144_dialog_content = "カレン殿下、これはあくまで交渉術。\n誤解しないでいただきたいところですな。",
  ui_story_5036_50360202_145_dialog_content = "イクストウルは空の末裔一族のものなんだ。\n誰にも撃墜なんてさせないよ！",
  ui_story_5036_50360202_146_dialog_content = "暗鬼の掃討なら僕も手伝う！",
  ui_story_5036_50360202_147_dialog_content = "イクストウルに価値があるって、証明してみせるよ！",
  ui_story_5036_50360202_148_dialog_content = "その通りよ。私も手を貸すわ。",
  ui_story_5036_50360202_149_dialog_content = "カレン殿下、一体どういうおつもり…",
  ui_story_5036_50360202_150_dialog_content = "あれあれ～？そっちのお姫様も、\nイクストウルを落とすのが惜しいみたいだね～。",
  ui_story_5036_50360202_151_dialog_content = "あら、可愛いわね。\n世の中に手放すのが「惜しい」ものなんて、そうそうないわ。",
  ui_story_5036_50360202_152_dialog_content = "あるとしたら…お代が足りないってだけの話よ。",
  ui_story_5036_50360202_153_dialog_content = "えっ？",
  ui_story_5036_50360202_154_dialog_content = "猫なで声で話しかけられることは気にしないけど、\nいきなりはビックリするよ…",
  ui_story_5036_50360202_155_dialog_content = "シェオルさん？",
  ui_story_5036_50360202_156_dialog_content = "あら、お得意様のPlayerNameじゃない？",
  ui_story_5036_50360202_157_dialog_content = "最近は全然浮遊商会に顔を出してくれないわね？",
  ui_story_5036_50360202_158_dialog_content = "まさか、それでこんなところまでセールスに来たの？",
  ui_story_5036_50360202_159_dialog_content = "アハハハ、あのPlayerNameが、ずいぶん…\nユーモア上手になったじゃない？",
  ui_story_5036_50360202_160_dialog_content = "ある意味、当たってるわよ。",
  ui_story_5036_50360202_161_dialog_content = "ただ、今回売りたいものは、いつもと違うの。",
  ui_story_5036_50360202_162_dialog_content = "ほら、こっちへいらっしゃい！",
  ui_story_5036_50360202_163_dialog_content = "え？",
  ui_story_5036_50360202_164_dialog_content = "傷つくことなんて恐れない。\n失敗も恐くない…",
  ui_story_5036_50360202_165_dialog_content = "進み続ければ、必ず運は巡ってくる。",
  ui_story_5036_50360202_166_dialog_content = "がっかりする必要も、くじける必要もない…",
  ui_story_5036_50360202_167_dialog_content = "このゴルディに全部、お任せ！",
  ui_story_5036_50360202_168_dialog_content = "ってことで、巨像のみんな、\nどうぞよろしくね～！",
  ui_story_5036_50360202_169_dialog_content = "ゴ、ゴルディ？",
  ui_story_5036_50360202_170_dialog_content = "やっほ～、PlayerName！\n久しぶりね！変わりはない？",
  ui_story_5036_50360202_171_dialog_content = "えっ？",
  ui_story_5036_50360202_172_dialog_content = "ゴルディさんがどうしてこんな所に？",
  ui_story_5036_50360202_173_dialog_content = "知り合いなら、話は早いわ。",
  ui_story_5036_50360202_174_dialog_content = "シェオルさん、買いかぶりすぎです。",
  ui_story_5036_50360202_175_dialog_content = "人気のスターを招待してステージをやってもらうお金なんて、\n僕にはありませんよ。",
  ui_story_5036_50360202_176_dialog_content = "フフフ、高いお金を出して、\nわざわざ飛空艇で今大人気のアイドル歌手を連れてきたのは…",
  ui_story_5036_50360202_177_dialog_content = "あなた1人に売り込むことが目的じゃないわ。",
  ui_story_5036_50360202_178_dialog_content = "急にこんなことを言ったら、\nみんなは驚くかもしれないけど…えへへ…",
  ui_story_5036_50360202_179_dialog_content = "私たちは、この漂泊の巨像でアストラ大陸中を驚かす、\n唯一無二のコンサートを開きたいの。",
  ui_story_5036_50360202_180_dialog_content = "この巨像がゴールド・リバーに沿って進んで、\n影ノ街の上空にたどり着いたら…",
  ui_story_5036_50360202_181_dialog_content = "巨像の上から、みんなに私の歌声と祝福を届けてあげたいの！",
  ui_story_5036_50360202_182_dialog_content = "この巨像の巨大スクリーンがあれば、\n影ノ街の人も白夜城の人も、私のコンサートを楽しめるでしょ。",
  ui_story_5036_50360202_183_dialog_content = "フン、庶民はやはり庶民だな…\nなんとバカげた白昼夢だ。",
  ui_story_5036_50360202_184_dialog_content = "それで、デコレーションケーキを身にまとったような娘よ。\nまさか口先だけで、自分を歌手だと売り込むつもりか？",
  ui_story_5036_50360202_185_dialog_content = "何のつもりで「アイドル」などと名乗っているのか知らんが、\nどうせ低俗な何かだろう。",
  ui_story_5036_50360202_186_dialog_content = "ええ～？やっぱり、毎日朝から晩まで\n白夜城みたいな小島に引きこもってたら、よくないね～。",
  ui_story_5036_50360202_187_dialog_content = "「アイドル」が何かも知らないの～？",
  ui_story_5036_50360202_188_dialog_content = "貴様…この私を愚弄する気か！？",
  ui_story_5036_50360202_189_dialog_content = "慌ててる。図星。",
  ui_story_5036_50360202_190_dialog_content = "シヴォーン、こちらの裁判官センセーに\n「アイドル」についての研究報告を簡単に説明してあげて。",
  ui_story_5036_50360202_191_dialog_content = "了解しました。",
  ui_story_5036_50360202_192_dialog_content = "「アイドル」は昨今、\n影ノ街とR・W砂漠で成立し始めた、新しい職業です。",
  ui_story_5036_50360202_193_dialog_content = "歌唱や舞踏、演技、司会など、\n各種エンターテイメントにたずさわっています。",
  ui_story_5036_50360202_194_dialog_content = "従来の歌手、舞踏家、俳優などと比べ、\n聴衆に対する距離感が近いことが特徴で…",
  ui_story_5036_50360202_195_dialog_content = "人的魅力で熱狂的な聴衆、いわゆる「ファン」たちの心をつかみ、\n前向きな向上心といった、精神的な力を届ける存在です。",
  ui_story_5036_50360202_196_dialog_content = "アハハ、おおかたそういうことね。",
  ui_story_5036_50360202_197_dialog_content = "このゴルディは本当にマルチな才能の持ち主なのよ。\nまぁ、今は歌に注力してるけどね。",
  ui_story_5036_50360202_198_dialog_content = "なるほど…",
  ui_story_5036_50360202_199_dialog_content = "…ではない！\n庶民の事情など知ったところで何にもならぬわ！",
  ui_story_5036_50360202_200_dialog_content = "ゴルディの今日があるのは、ずっと私を応援して励ましてくれた、\n「ディディ推し」のみんなのおかげなの。",
  ui_story_5036_50360202_201_dialog_content = "だから、「ディディ推し」のみんなに自分たちの推しが、\n一番大きなステージで歌を歌うところを見せてあげたいの！",
  ui_story_5036_50360202_202_dialog_content = "へ～、アイドルがコンサートをやることは\n別に反対もしないけど…",
  ui_story_5036_50360202_203_dialog_content = "漂泊の巨像でやりたいっていうのは、\nなかなかぶっ飛んだアイデアだね～。",
  ui_story_5036_50360202_204_dialog_content = "さっき、スクリーンや音響設備には、\nまったく損傷がないって言ってたわよね？",
  ui_story_5036_50360202_205_dialog_content = "あなたも熱心な巨像の研究者でしょう？\nそれなら、巨像の設備が実際に動いてる様子、その目で見たくない？",
  ui_story_5036_50360202_206_dialog_content = "う～ん…",
  ui_story_5036_50360202_207_dialog_content = "想像してみて――たくさんの人がゴールド・リバーの川辺に集まって、\n大騒ぎしながら空を見上げたら…",
  ui_story_5036_50360202_208_dialog_content = "巨大なスクリーンでコンサート中継を見ることになるの。",
  ui_story_5036_50360202_209_dialog_content = "飛空艇に乗れば、\n上空からステージを見下ろして観賞もできるわ。",
  ui_story_5036_50360202_210_dialog_content = "きっとアストラ大陸中がお祭り騒ぎになるね…",
  ui_story_5036_50360202_211_dialog_content = "PlayerName、その言い方、ステキね！\nその通り、アストラ大陸中が熱狂する一大イベントになるわよ！",
  ui_story_5036_50360202_212_dialog_content = "この巨像の話を聞いた時、\nホントにびっくりしたの。",
  ui_story_5036_50360202_213_dialog_content = "この子も昔、\n歌声をみんなに伝えるために造られたのかもね～。",
  ui_story_5036_50360202_214_dialog_content = "もしどうしても壊さなきゃいけないって言うなら…",
  ui_story_5036_50360202_215_dialog_content = "せめて最期に、もう１度世界に歌声を響かせてあげたいの！",
  ui_story_5036_50360202_216_dialog_content = "！！！",
  ui_story_5036_50360202_217_dialog_content = "残念だったな。",
  ui_story_5036_50360202_218_dialog_content = "この巨像が明日通過する場所は、人里から離れている。\n撃墜するには絶好の地点だ。",
  ui_story_5036_50360202_219_dialog_content = "それまでにコンサートなど開く時間はなかろう？",
  ui_story_5036_50360202_220_dialog_content = "まぁまぁ、そう急ぐことないじゃない。",
  ui_story_5036_50360202_221_dialog_content = "漂泊の巨像が影ノ街を通過した後、\nさらにゴールド・リバーに沿って進むなら…",
  ui_story_5036_50360202_222_dialog_content = "もっと広くて、誰もいない場所があるでしょ？",
  ui_story_5036_50360202_223_dialog_content = "…それってつまり、海？",
  ui_story_5036_50360202_224_dialog_content = "巨像を海に落とすのですか？",
  ui_story_5036_50360202_225_dialog_content = "…ガルー室長、これはチャンスではないでしょうか…",
  ui_story_5036_50360202_226_dialog_content = "コンサートが成功すれば、巨像の価値を証明できます。\nそうすれば撃墜しない理由ができますし…",
  ui_story_5036_50360202_227_dialog_content = "巨像の修理方法を探すために、\n時間も稼げます。",
  ui_story_5036_50360202_228_dialog_content = "コンサートが失敗しても、\n海上に出てから撃墜すれば遅くはありません。",
  ui_story_5036_50360202_229_dialog_content = "海上ならば、大陸には一切危険が及ばないでしょうし…",
  ui_story_5036_50360202_230_dialog_content = "お願いします！",
  ui_story_5036_50360202_231_dialog_content = "この巨像の破壊、先延ばしにしてください…",
  ui_story_5036_50360202_232_dialog_content = "この巨像のステージで、今まで誰も見たことないような、\n最高のコンサートを開かせてください！",
  ui_story_5036_50360301_1_dialog_content = "<color=#e8d9bb>コンサート開催まで、あと6日</color>",
  ui_story_5036_50360301_2_dialog_content = "そうね…左側が少し低いわ。もう少し上に。",
  ui_story_5036_50360301_3_dialog_content = "こう？",
  ui_story_5036_50360301_4_dialog_content = "今度は右側が低くなったわね…",
  ui_story_5036_50360301_5_dialog_content = "そう？でもこのポスター、\n斜めに貼るのもなかなかじゃない？",
  ui_story_5036_50360301_6_dialog_content = "PlayerName、どう思う？",
  ui_story_5036_50360301_7_dialog_content = "ううん、僕は…専門家じゃないから分からないよ。\nそうだ…ゴルディに聞いてみようか？",
  ui_story_5036_50360301_8_dialog_content = "ワン！",
  ui_story_5036_50360301_9_dialog_content = "わあ～！かわいい！\nいつ見ても触りたくなっちゃうわ～。",
  ui_story_5036_50360301_10_dialog_content = "マシュマロも触られるのは好きみたいよ、ふふふ！",
  ui_story_5036_50360301_11_dialog_content = "ワンワンワン！",
  ui_story_5036_50360301_12_dialog_content = "分かった分かった。\nマシュマロ、いい子だからちょっと待っててね。",
  ui_story_5036_50360301_13_dialog_content = "先にみんなとお話したいの、いい？",
  ui_story_5036_50360301_14_dialog_content = "ワン！",
  ui_story_5036_50360301_15_dialog_content = "それで、そんなに急いで何の用？",
  ui_story_5036_50360301_16_dialog_content = "今、ポスター貼りの手伝いをしてたんだけど、\nどういう貼り方がいいのか分からなくて…",
  ui_story_5036_50360301_17_dialog_content = "え？そんなことしなくていいのよ？",
  ui_story_5036_50360301_18_dialog_content = "ゴルディこそ、遠慮しないで。",
  ui_story_5036_50360301_19_dialog_content = "ゴルディがコンサートを開きたいって言わなかったら、\nイクストウルは今頃とっくに壊されてたかもしれないんだ。",
  ui_story_5036_50360301_20_dialog_content = "設備の調整とかは無理だから、\nポスター貼りぐらい手伝わせてよ。",
  ui_story_5036_50360301_21_dialog_content = "もう十分助けてもらってるわ！",
  ui_story_5036_50360301_22_dialog_content = "みんながいなかったら、私の言う事なんて\n啓光も白夜城も聞いてくれなかったかも知れないもの。",
  ui_story_5036_50360301_23_dialog_content = "漂泊の巨像については、\n大元帥から全権を委任されてはいるけど…",
  ui_story_5036_50360301_24_dialog_content = "もう少し分析してからでないと、\n回答できないかな。",
  ui_story_5036_50360301_25_dialog_content = "分析だと？何を分析すると言うのだ？\nそもそもが絵空事だ。",
  ui_story_5036_50360301_26_dialog_content = "それに庶民の「アイドル」などありがたがる、\n白夜城貴族は居らぬ！",
  ui_story_5036_50360301_27_dialog_content = "今の実力じゃまだ足りないって分かってるわ。\nだから、今回のコンサートは私のソロじゃないの。",
  ui_story_5036_50360301_28_dialog_content = "いろんなところからアイドルを招いて、\n一緒に空飛ぶコンサートを成功させるつもりよ！",
  ui_story_5036_50360301_29_dialog_content = "白夜城と啓光の偉い人たちは、\n「アイドル」なんて知ったことじゃないかもしれないけど…",
  ui_story_5036_50360301_30_dialog_content = "それでもいいの。\nみんなも自分の推しアイドルを推薦してね！",
  ui_story_5036_50360301_31_dialog_content = "僕は賛成！",
  ui_story_5036_50360301_32_dialog_content = "え？／何ぃ？",
  ui_story_5036_50360301_33_dialog_content = "ゴルディが巨像でコンサートを開くことに賛成するよ！",
  ui_story_5036_50360301_34_dialog_content = "ゴルディの言う通りだよ。\nイクストウルの使命は歌声を伝えることだったのかもしれない。",
  ui_story_5036_50360301_35_dialog_content = "空の末裔として、\n僕もイクストウルが使命を果たすところを見てみたい。",
  ui_story_5036_50360301_36_dialog_content = "それに、いろいろな所から集まった皆が偏見を捨てて、\n一緒に楽しむところを見てみたいんだ！",
  ui_story_5036_50360301_37_dialog_content = "イクストウルがこうして現れたのも、\nもしかしたら、僕たちに立ち止まって考えさせるためかもしれない…",
  ui_story_5036_50360301_38_dialog_content = "僕たちは出身や身分を越えて、\n一緒に1つのことを成し遂げられるってことを！",
  ui_story_5036_50360301_39_dialog_content = "だから、ゴルディに…\nイクストウルに、もう少し時間をあげられないかな。",
  ui_story_5036_50360301_40_dialog_content = "僕も…もう少し時間がほしいんだ…",
  ui_story_5036_50360301_41_dialog_content = "僕ならイクストウルを救う方法を、\n見つけられるかもしれないから…",
  ui_story_5036_50360301_42_dialog_content = "今思いだしても、\nあの時のPlayerName、カッコよかったわ！",
  ui_story_5036_50360301_43_dialog_content = "感動で涙が出そうだったもの～。",
  ui_story_5036_50360301_44_dialog_content = "あのシェオルさんが「空ファンの数はディディ推しより多い」って\n言ってたのも、納得よ。",
  ui_story_5036_50360301_45_dialog_content = "そ、そうかな…僕はちょっと興奮しただけで…\n興奮するとつい口数が多くなっちゃうんだ…",
  ui_story_5036_50360301_46_dialog_content = "カッコよかったと言えば、\n私はシェオルさんが一番かしら。",
  ui_story_5036_50360301_47_dialog_content = "必要経費を全額負担するって言って\n微笑みを浮かべた瞬間、まるで後光が射してるみたいだったわ！",
  ui_story_5036_50360301_48_dialog_content = "商人は損をする取引をしないものよ…",
  ui_story_5036_50360301_49_dialog_content = "それだけの財をなげうつということは、\nコンサートがもたらす収益にそうとうな自信があるということね。",
  ui_story_5036_50360301_50_dialog_content = "でも、ゴールド・リバーの川辺で見るならタダでしょ。\nどうやってお金を稼ぐのかしら？",
  ui_story_5036_50360301_51_dialog_content = "…コンサートの宣伝のために、\nもう影ノ街に帰っちゃったのが残念ね…",
  ui_story_5036_50360301_52_dialog_content = "次に会ったら、どうやって元手を回収して利益を出せるのか、\nちゃんと聞いておかなきゃ！",
  ui_story_5036_50360301_53_dialog_content = "バイス、影ノ街に生まれた方がよかったかもしれないわね。",
  ui_story_5036_50360301_54_dialog_content = "金銭のこととなると、\n白夜城で勉強していた時よりも、ずっと真剣な様子だもの。",
  ui_story_5036_50360301_55_dialog_content = "そう？それもこれも、誰かさんのおかげね…",
  ui_story_5036_50360301_56_dialog_content = "え？なんで僕の方を見てるの？",
  ui_story_5036_50360301_57_dialog_content = "ふふ…シェオルさんのビジネスの腕だもの、\n私たちには分かりっこないわ。",
  ui_story_5036_50360301_58_dialog_content = "私たちは自分にできることを全力でやればいいの。",
  ui_story_5036_50360301_59_dialog_content = "そして私の今やるべきことは、\nコンサートの準備をしっかりすること！",
  ui_story_5036_50360301_60_dialog_content = "…",
  ui_story_5036_50360301_61_dialog_content = "PlayerName、何か心配事？",
  ui_story_5036_50360301_62_dialog_content = "いや、ただ考えてたんだ。\nイクストウルのスクリーンや音響設備に問題がないとしても…",
  ui_story_5036_50360301_63_dialog_content = "それだけで本当に君の思い描いてるような、\n地上のはるか遠くまで歌声を届けられるコンサートになるかな？",
  ui_story_5036_50360301_64_dialog_content = "PlayerName、空の末裔の科学技術を信じてないの？",
  ui_story_5036_50360301_65_dialog_content = "もちろん、信じてるよ！ただ…",
  ui_story_5036_50360301_66_dialog_content = "心配なのはよく分かるわ。でも、信じて。\n誰よりも一番コンサートの成功を願ってるのは私なの。",
  ui_story_5036_50360301_67_dialog_content = "シヴォーンさんにいろいろ教えてもらって、\n音量の調節の仕方も覚えたわ。",
  ui_story_5036_50360301_68_dialog_content = "イクストウルの設備があれば、\n100%歌声を地上のみんなに聴いてもらえる、間違いないわ！",
  ui_story_5036_50360301_69_dialog_content = "もうとっくに準備してたんだね！\nさすがはプロのアイドルだ！",
  ui_story_5036_50360301_70_dialog_content = "それはそうと、イクストウルを助ける方法を探してるんでしょ？",
  ui_story_5036_50360301_71_dialog_content = "手がかりはあった？",
  ui_story_5036_50360301_72_dialog_content = "今のところは、まったく何も。",
  ui_story_5036_50360301_73_dialog_content = "うーん、今思えば、\n知らないがゆえの自信ってやつだったのかな…",
  ui_story_5036_50360301_74_dialog_content = "啓光の最高科学責任者にも分からないことを、\nなんで分かるかもしれないなんて思ったんだろう？",
  ui_story_5036_50360301_75_dialog_content = "PlayerName、弱気なことを言っちゃダメよ！",
  ui_story_5036_50360301_76_dialog_content = "<color=#FFB400>幸運の弾丸</color>に聞いてみよっか？",
  ui_story_5036_50360301_77_dialog_content = "幸運の弾丸？",
  ui_story_5036_50360301_78_dialog_content = "そう、弾丸。\nPlayerNameはイクストウルを救う方法を見つけられる？",
  ui_story_5036_50360301_79_dialog_content = "「見つけられる」なら、弾頭を下にして落ちて！",
  ui_story_5036_50360301_80_dialog_content = "さあ、PlayerName。放り投げてみて。",
  ui_story_5036_50360301_81_dialog_content = "放り投げる？こんな風に？",
  ui_story_5036_50360301_82_dialog_content = "<color=#e8d9bb>ヒュン…</color>",
  ui_story_5036_50360301_83_dialog_content = "結構飛ぶね…",
  ui_story_5036_50360301_84_dialog_content = "<color=#e8d9bb>カチャン！</color>",
  ui_story_5036_50360301_85_dialog_content = "ほら、PlayerName！\n見て、頭が下向きに落ちたわ！",
  ui_story_5036_50360301_86_dialog_content = "幸運の弾丸が「見つかる」って言うなら、\n絶対大丈夫よ！",
  ui_story_5036_50360301_87_dialog_content = "本当に？",
  ui_story_5036_50360301_88_dialog_content = "困ったことがある時は、\nいつも幸運の弾丸が答えを見つけてくれたの。",
  ui_story_5036_50360301_89_dialog_content = "だから、あなたにもきっと幸運を届けてくれるわ！",
  ui_story_5036_50360301_90_dialog_content = "うん…そうだね！\nどっちにしたって、僕はあきらめない！",
  ui_story_5036_50360301_91_dialog_content = "ゴルディと話すと元気をもらえるね。",
  ui_story_5036_50360301_92_dialog_content = "そのうち「ディディ推し」になっちゃいそうだ。",
  ui_story_5036_50360301_93_dialog_content = "えへへ、だったら早くなっちゃえば～？",
  ui_story_5036_50360301_94_dialog_content = "だって、私はもう長いこと「空ファン」だもの。",
  ui_story_5036_50360301_95_dialog_content = "えっ？",
  ui_story_5036_50360301_96_dialog_content = "<color=#e8d9bb>カシャ！</color>",
  ui_story_5036_50360301_97_dialog_content = "えっ？",
  ui_story_5036_50360301_98_dialog_content = "も、申し訳ありません！",
  ui_story_5036_50360301_99_dialog_content = "あまりに雰囲気がよかったので、\n思わず記念写真を…",
  ui_story_5036_50360301_100_dialog_content = "わあ、ありがとう！ブランディ！",
  ui_story_5036_50360301_101_dialog_content = "（ゴルディさんが…私の名前を？）",
  ui_story_5036_50360301_102_dialog_content = "さすが影ノ街の新聞社だわ！\n早速コンサートの取材に来てくれたのね？",
  ui_story_5036_50360301_103_dialog_content = "いえ、今日はたまたまPlayerNameさんの独占取材に来ておりまして…",
  ui_story_5036_50360301_104_dialog_content = "そうなんだ。僕を取材したいんだって…",
  ui_story_5036_50360301_105_dialog_content = "へぇ、PlayerNameを…？",
  ui_story_5036_50360301_106_dialog_content = "そうなんだ～、なんだか嫉妬しちゃうわ～。",
  ui_story_5036_50360301_107_dialog_content = "え…？あの、それは…",
  ui_story_5036_50360301_108_dialog_content = "ウフフ、安心して、ブランディ。\nただの冗談よ～。",
  ui_story_5036_50360301_109_dialog_content = "…まさか名前を覚えてくださっているとは思いませんでした。",
  ui_story_5036_50360301_110_dialog_content = "当然の事よ。あの時のインタビュー記事だって、\nちゃんと切り抜いて取ってあるんだから！",
  ui_story_5036_50360301_111_dialog_content = "…ですが、あの記事はうまく書けておらず、\n編集長にもこっぴどく怒られたものですよ？",
  ui_story_5036_50360301_112_dialog_content = "ブランディ、自分の事を\nそんなふうに言っちゃダメよ。",
  ui_story_5036_50360301_113_dialog_content = "だって、誰よりマジメに取材してるじゃない！",
  ui_story_5036_50360301_114_dialog_content = "ほかの人に何を言われたって、\n自分と自分の判断は信じなきゃ！",
  ui_story_5036_50360301_115_dialog_content = "…自分を信じる、ですか？",
  ui_story_5036_50360301_116_dialog_content = "やはりゴルディさんとお話をすると、パワーをいただけるようです。\nまた頑張って仕事を続ける気になりました！",
  ui_story_5036_50360301_117_dialog_content = "それはそうと、先輩記者から、グランドスター劇場でコンサートをするために\nずいぶん準備されていたと聞いていたのですが…",
  ui_story_5036_50360301_118_dialog_content = "この巨像でコンサートをするということは、\nグランドスター劇場での開催は見送られるということですか？",
  ui_story_5036_50360301_119_dialog_content = "それは…",
  ui_story_5036_50360301_120_dialog_content = "「イクストウル」っていう特別な舞台が出てきたのよ？\nこのチャンスを逃す手はないでしょ？",
  ui_story_5036_50360301_121_dialog_content = "影ノ街でのコンサートなら、\n今後いくらでもチャンスがあるもの！",
  ui_story_5036_50360301_122_dialog_content = "そうでしたか…",
  ui_story_5036_50360301_123_dialog_content = "ふふ、でもホントによかった！",
  ui_story_5036_50360301_124_dialog_content = "幸運の弾丸の言う通り、\nスゴ腕の記者さんが見つかったわね！",
  ui_story_5036_50360301_125_dialog_content = "えっ？",
  ui_story_5036_50360301_126_dialog_content = "シェオルさんから、記者を呼んでコンサートを報道してもらうように\n言われてたんだけど、誰に頼んだらいいか悩んでたの。",
  ui_story_5036_50360301_127_dialog_content = "よかったら、ブランディに密着取材をお願いしたいわ！",
  ui_story_5036_50360301_128_dialog_content = "あ、ちょっと急だったかしら？",
  ui_story_5036_50360301_129_dialog_content = "もちろん、よく考えてからでいいわ。",
  ui_story_5036_50360301_130_dialog_content = "（ゴルディさんはやはり、\n優しく心のきれいな方です…）",
  ui_story_5036_50360301_131_dialog_content = "（暴力的になっているというウワサは、\nデマだったのでしょうか？）",
  ui_story_5036_50360301_132_dialog_content = "ちょっと皆、突っ立ってる場合じゃないわ！",
  ui_story_5036_50360301_133_dialog_content = "あっちにもポスターを貼らなきゃいけないのよ。\n急いで貼っちゃいましょ！",
  ui_story_5036_50360301_134_dialog_content = "手の早さだけは立派なもんだ。",
  ui_story_5036_50360301_135_dialog_content = "もうこっちの廊下まで、\n趣味の悪いハデな張り紙だらけだ。",
  ui_story_5036_50360301_136_dialog_content = "アイドルとやらの何がいいのか、\nさっぱり分からないな。",
  ui_story_5036_50360301_137_dialog_content = "ステージに立って、ニコッと笑って客に媚びれば、\n大勢に好かれて拍手をもらえる…",
  ui_story_5036_50360301_138_dialog_content = "俺たちみたいにマジメに地道な仕事をしてる者は\n何の賞賛も得られやしない。",
  ui_story_5036_50360301_139_dialog_content = "まったくだな。こんな奇怪な格好をした歌手など、\n今まで見たことも聞いたこともない。",
  ui_story_5036_50360301_140_dialog_content = "歌と踊りで人の心を癒すだと？\nこういうのは人を惑わせているというのだ。",
  ui_story_5036_50360301_141_dialog_content = "まさか白夜城の者と意見が合う日が来るとは思わなかったな。",
  ui_story_5036_50360301_142_dialog_content = "フンッ、お互い、実に運が悪い。",
  ui_story_5036_50360301_143_dialog_content = "あいつらはただ歌など歌って、\n封鎖を守り、暗鬼を掃討する役目は我々に丸投げだ！",
  ui_story_5036_50360301_144_dialog_content = "それにどういうわけだか、\nここ数日気分が上がらなくてな。",
  ui_story_5036_50360301_145_dialog_content = "当然のことだろうな。",
  ui_story_5036_50360301_146_dialog_content = "オホンッ…",
  ui_story_5036_50360301_147_dialog_content = "！！！",
  ui_story_5036_50360301_148_dialog_content = "バイス中尉！",
  ui_story_5036_50360301_149_dialog_content = "カレン殿下！",
  ui_story_5036_50360301_150_dialog_content = "かしこまらないで。見張り、ご苦労様。",
  ui_story_5036_50360301_151_dialog_content = "…先ほどは身の程もわきまえず、おそれ多いことを申しました。\n殿下、どうか罰をお申し付けください！",
  ui_story_5036_50360301_152_dialog_content = "バイス中尉、私もです！",
  ui_story_5036_50360301_153_dialog_content = "騎士たる者が平民を侮るなど、\nあってはならない行為よ。",
  ui_story_5036_50360301_154_dialog_content = "どうするべきかは、\n言われなくても分かっているわね。",
  ui_story_5036_50360301_155_dialog_content = "ゴルディさん、申し訳ございませんでした！",
  ui_story_5036_50360301_156_dialog_content = "あなたも、きちんと謝って。",
  ui_story_5036_50360301_157_dialog_content = "も、申し訳ありませんでした、ゴルディさん！",
  ui_story_5036_50360301_158_dialog_content = "不遜な言動は騎士の精神を汚すものです。\nどうか、私に裁きをお与えください！",
  ui_story_5036_50360301_159_dialog_content = "分かったわ。それじゃあ、罰として…",
  ui_story_5036_50360301_160_dialog_content = "今日は2人とも早く休んで、いい夢見てね！",
  ui_story_5036_50360301_161_dialog_content = "え…！？",
  ui_story_5036_50360301_162_dialog_content = "いいから、いいから。\n仕事中なんて、誰だってグチの一つも言いたくなるわ。",
  ui_story_5036_50360301_163_dialog_content = "それに、私が来たことで、\nみんなの仕事が増えたのは事実だもの。",
  ui_story_5036_50360301_164_dialog_content = "謝らないといけないのは私の方だわ。",
  ui_story_5036_50360301_165_dialog_content = "シェオルさんに影ノ街から傭兵団を送ってくれるように頼んであるから、\n今後は負担も少しは減ると思うわ。",
  ui_story_5036_50360301_166_dialog_content = "そうすれば、みんなゆっくり休めるようになるでしょ？",
  ui_story_5036_50360301_167_dialog_content = "ええっ…？",
  ui_story_5036_50360301_168_dialog_content = "廊下の突き当りにジュースを用意してあるわ。\n2人とも見張りしてる間、何も飲んでないでしょ？",
  ui_story_5036_50360301_169_dialog_content = "飲んでおいてね！",
  ui_story_5036_50360301_170_dialog_content = "きっと元気が出るわ！",
  ui_story_5036_50360301_171_dialog_content = "…",
  ui_story_5036_50360301_172_dialog_content = "ほら、せっかくそう言ってくれてるのよ。\n何をぼうっとしてるの？",
  ui_story_5036_50360301_173_dialog_content = "カレン殿下…？",
  ui_story_5036_50360301_174_dialog_content = "罰はもうゴルディが決めたこと。\n早く飲み物を取りに行ってきなさい。",
  ui_story_5036_50360301_175_dialog_content = "感謝いたします、カレン殿下！\nそれから、ゴルディさん、ありがとうございます！",
  ui_story_5036_50360301_176_dialog_content = "バイス中尉、ゴルディさん、ありがとうございます！",
  ui_story_5036_50360301_177_dialog_content = "コンサートをやるって、\n考えないといけないことがたくさんあって、ホントに大変ね。",
  ui_story_5036_50360301_178_dialog_content = "兵士のみんなが何を必要としてるかまで、\n考えられてなかったわ…",
  ui_story_5036_50360301_179_dialog_content = "ゴルディ、必要なら白夜城の騎士団から人手を回させるわ。",
  ui_story_5036_50360301_180_dialog_content = "いえ、大丈夫よ。\nそんなことは頼めないわ！",
  ui_story_5036_50360301_181_dialog_content = "もう白火傭兵団の人たちにステージ設営の材料と\nセッティングを頼んであるし。",
  ui_story_5036_50360301_182_dialog_content = "傭兵団が到着したら、\n追加の依頼をすればいいだけだもの！",
  ui_story_5036_50360301_183_dialog_content = "傭兵団に依頼するとなると、\nそれなりの金額になるわよね？",
  ui_story_5036_50360301_184_dialog_content = "その分もシェオルさんが負担してくれるの？",
  ui_story_5036_50360301_185_dialog_content = "…",
  ui_story_5036_50360301_186_dialog_content = "ゴルディ？",
  ui_story_5036_50360301_187_dialog_content = "えっ？",
  ui_story_5036_50360301_188_dialog_content = "ああ…ええ、シェオルさんはたぶん分かってるから、大丈夫よ。",
  ui_story_5036_50360301_189_dialog_content = "じゃあ、何を心配してるの？",
  ui_story_5036_50360301_190_dialog_content = "心配ってほどじゃないわ。",
  ui_story_5036_50360301_191_dialog_content = "ただ、白火傭兵団の人たち、\nそろそろ着いてもいい頃なのに、まだ姿が見えないなと思って…",
  ui_story_5036_50360301_192_dialog_content = "<color=#e8d9bb>ガタガタガタ……</color>",
  ui_story_5036_50360301_193_dialog_content = "足音かな？大勢がこっちに向かってくるみたいだよ？",
  ui_story_5036_50360301_194_dialog_content = "白火傭兵団かしら？ウワサをすればね！",
  ui_story_5036_50360301_195_dialog_content = "ホントにちょうどいい時に来てくれたわ！",
  ui_story_5036_50360301_196_dialog_content = "グォォ――！",
  ui_story_5036_50360301_197_dialog_content = "え？どうして…",
  ui_story_5036_50360301_198_dialog_content = "人違いだったわ！？",
  ui_story_5036_50360301_199_dialog_content = "私は傭兵団にお願いしたいの、暗鬼じゃないわ！",
  ui_story_5036_50360302_1_dialog_content = "ゴルディ、後ろ！",
  ui_story_5036_50360302_2_dialog_content = "えっ？",
  ui_story_5036_50360302_3_dialog_content = "グォォ！",
  ui_story_5036_50360302_4_dialog_content = "失せろ！",
  ui_story_5036_50360302_5_dialog_content = "白火傭兵団！来てくれてよかったわ！",
  ui_story_5036_50360302_6_dialog_content = "ゴルディさん、ご無事ですか？",
  ui_story_5036_50360302_7_dialog_content = "私は大丈夫。\nちょうどいい時に来てくれたわね。",
  ui_story_5036_50360302_8_dialog_content = "「ちょうどいい」とは言えませんね…",
  ui_story_5036_50360302_9_dialog_content = "ステージ設営用の材料集めに、予想以上に時間がかかってしまいました。\n遅くなってしまったことをお詫びします。",
  ui_story_5036_50360302_10_dialog_content = "ただ、巨像の中に暗鬼がいるとは、\n聞いていませんね？",
  ui_story_5036_50360302_11_dialog_content = "実は私も、ここに来てから知ったの。",
  ui_story_5036_50360302_12_dialog_content = "でも、啓光と白夜城の兵士のみんなが、\nほとんどの暗鬼を巨像の尾の方に閉じ込めてくれてるの。",
  ui_story_5036_50360302_13_dialog_content = "まだうろついてる暗鬼もいるみたいだけど。\n今みたいに…",
  ui_story_5036_50360302_14_dialog_content = "でも、大物はいないはずよ。",
  ui_story_5036_50360302_15_dialog_content = "兵士のみんなが\n封鎖から漏れてる暗鬼の掃討を強化してくれてるし…",
  ui_story_5036_50360302_16_dialog_content = "白火傭兵団も手伝ってもらえたら…",
  ui_story_5036_50360302_17_dialog_content = "はぐれた暗鬼どころか、\n封鎖されてる暗鬼たちもあっという間に片づけられちゃいそう！",
  ui_story_5036_50360302_18_dialog_content = "シェオルさんの依頼ですから、\n我々も全力を尽くします。",
  ui_story_5036_50360302_19_dialog_content = "お任せください！",
  ui_story_5036_50360302_20_dialog_content = "じゃあ、お願いね！",
  ui_story_5036_50360302_21_dialog_content = "当然の務めです。\nそれに、影ノ街で聞いた話では…",
  ui_story_5036_50360302_22_dialog_content = "すでにたくさんの方から\nコンサートに参加したいと申し込みがあったそうですね？",
  ui_story_5036_50360302_23_dialog_content = "情報って広がるのがホントに早いのね～。",
  ui_story_5036_50360302_24_dialog_content = "その通りよ！\n私の思ってた以上に、みんながやる気なの！",
  ui_story_5036_50360302_25_dialog_content = "それで、コンサート本番の前に、\n<color=#FFB400>オーディション</color>を開くことになってるの。",
  ui_story_5036_50360302_26_dialog_content = "本番のステージでパフォーマンスする\nアイドルを、そこで選ぶのよ。",
  ui_story_5036_50360302_27_dialog_content = "アイドルの選抜ですか？\n盛り上がりそうですね。",
  ui_story_5036_50360302_28_dialog_content = "明日がオーディションの予選だから、\n傭兵団から何人か、現場の警備の人を出してもらえる？",
  ui_story_5036_50360302_29_dialog_content = "お任せください！",
  ui_story_5036_50360302_30_dialog_content = "お前たち、さあ、仕事だ！",
  ui_story_5036_50360302_31_dialog_content = "おう――！",
  ui_story_5036_50360302_32_dialog_content = "ゴルディって、行動力があるね。",
  ui_story_5036_50360302_33_dialog_content = "アイドルのオーディションなんて、\nすごく大変だよね？",
  ui_story_5036_50360302_34_dialog_content = "私がずっとやりたかったことだもの。\n夢を実現するチャンスが、やっと来たの！",
  ui_story_5036_50360302_35_dialog_content = "大変だなんて、全然思わないわ！",
  ui_story_5036_50360302_36_dialog_content = "アイドルのオーディションをやりたかったってこと？",
  ui_story_5036_50360302_37_dialog_content = "そう！私はステージだけじゃなくて、\nステージを観てくれるみんなのことが大好きなの。",
  ui_story_5036_50360302_38_dialog_content = "その気持ちを、みんなにも伝えていきたいわ！",
  ui_story_5036_50360302_39_dialog_content = "だから、もっとたくさんのアイドルが観客のみんなに\n感動と希望を与えられるようになってほしいって思ってて…",
  ui_story_5036_50360302_40_dialog_content = "私が注目されてるうちに、自分と同じような男の子や女の子が\nアイドルに成長していく姿を見とどけたいの。",
  ui_story_5036_50360302_41_dialog_content = "ゴルディ、アイドルって仕事が本当に大好きなんだね。",
  ui_story_5036_50360302_42_dialog_content = "それでね…",
  ui_story_5036_50360302_43_dialog_content = "PlayerName、オーディションの<color=#FFB400>審査員</color>に\nなってくれないかしら？",
  ui_story_5036_50360302_44_dialog_content = "審査員？僕が？",
  ui_story_5036_50360302_45_dialog_content = "そうよ！審査っていっても、やることは簡単よ。",
  ui_story_5036_50360302_46_dialog_content = "参加者のパフォーマンスを見て、\n自分の好みで誰が最終選考に残るか決めてくれればいいだけ。",
  ui_story_5036_50360302_47_dialog_content = "ホントはシェオルさんにお願いしようと思ってたんだけど、\n宣伝とかで駆け回ってるみたいなの。",
  ui_story_5036_50360302_48_dialog_content = "それでいろいろ考えたけど、\nPlayerNameしかふさわしい人選はないかなって。",
  ui_story_5036_50360302_49_dialog_content = "でも…自信ないよ。",
  ui_story_5036_50360302_50_dialog_content = "そうだ！カレンとバイスも歌は好きだったよね？",
  ui_story_5036_50360302_51_dialog_content = "二人も審査員をやってみる気はない？",
  ui_story_5036_50360302_52_dialog_content = "それは…",
  ui_story_5036_50360302_53_dialog_content = "ええと…",
  ui_story_5036_50360302_54_dialog_content = "あら？PlayerName、知らなかったの？",
  ui_story_5036_50360302_55_dialog_content = "二人とも、オーディションの参加者よ？",
  ui_story_5036_50360302_56_dialog_content = "ええっ！？",
  ui_story_5036_50360302_57_dialog_content = "全然知らなかったよ！？",
  ui_story_5036_50360302_58_dialog_content = "私たちのせいじゃないわ！\nちゃんと話したもの。",
  ui_story_5036_50360302_59_dialog_content = "ちょうど歌声が聞こえたとか言って、\nうわの空だったけど…",
  ui_story_5036_50360302_60_dialog_content = "バイスと相談して決めたことよ。\nコンサートが成功すれば、イクストウルの価値を証明できるかもしれない。",
  ui_story_5036_50360302_61_dialog_content = "そうすれば、啓光の上層部や私の父上に対しても、\n破壊させないよう説得する材料にできるわ。",
  ui_story_5036_50360302_62_dialog_content = "この巨像を制御する方法が見つからなかったとしても…",
  ui_story_5036_50360302_63_dialog_content = "このまま、漂流させ続けることはできるかもしれないわ。",
  ui_story_5036_50360302_64_dialog_content = "そしたら、また100年後に\nアストラ大陸に戻って来るかもしれないでしょ！",
  ui_story_5036_50360302_65_dialog_content = "そんな遠い未来のことまで考えてたの？",
  ui_story_5036_50360302_66_dialog_content = "最初はあなたにも参加してもらおうかって考えたけど…",
  ui_story_5036_50360302_67_dialog_content = "…やめておくことにしたわ。",
  ui_story_5036_50360302_68_dialog_content = "確かにパフォーマンスをやる自信なんてないけど、\nそんなにはっきり言わなくても…",
  ui_story_5036_50360302_69_dialog_content = "審査員にはパフォーマーの素質なんて、\nかならずしも必要じゃないわ。",
  ui_story_5036_50360302_70_dialog_content = "りっぱな審査員になるには、\n人の素質を見抜く目があればいいの！",
  ui_story_5036_50360302_71_dialog_content = "うん…",
  ui_story_5036_50360302_72_dialog_content = "はぁ、結局これしかないか…",
  ui_story_5036_50360302_73_dialog_content = "まったく、思ってもいなかったな…",
  ui_story_5036_50360302_74_dialog_content = "この歳になって、こんなことをやるハメになるとは…",
  ui_story_5036_50360302_75_dialog_content = "ガオオ！",
  ui_story_5036_50360302_76_dialog_content = "シーッ！",
  ui_story_5036_50360302_77_dialog_content = "<size=35>ガオン？</size>",
  ui_story_5036_50360302_78_dialog_content = "おいおい、ドラ。もう夜遅いんだぞ。",
  ui_story_5036_50360302_79_dialog_content = "そんなに大きな声を出したら、みんな驚くだろ？",
  ui_story_5036_50360302_80_dialog_content = "出てきて早々人目を引くなんて、まっぴらごめんだ。",
  ui_story_5036_50360302_81_dialog_content = "グウゥ…",
  ui_story_5036_50360302_82_dialog_content = "よしよし、お前は早くフィアのところに戻れ。",
  ui_story_5036_50360302_83_dialog_content = "ただ、いいか…",
  ui_story_5036_50360302_84_dialog_content = "俺の居場所のことはバラすなよ？",
  ui_story_5036_50360401_1_dialog_content = "編集長、私です！",
  ui_story_5036_50360401_2_dialog_content = "「私」では分からん。",
  ui_story_5036_50360401_3_dialog_content = "…ブランディです。",
  ui_story_5036_50360401_4_dialog_content = "ああ、思い出した。",
  ui_story_5036_50360401_5_dialog_content = "つまらん記事しか書けない見習いだったな？",
  ui_story_5036_50360401_6_dialog_content = "荷物をまとめて出て行ったかと思っていたが。",
  ui_story_5036_50360401_7_dialog_content = "この間最後のチャンスをいただけると\nおっしゃっていましたよね？",
  ui_story_5036_50360401_8_dialog_content = "ああ、そういえばそんなこともあったな。\nで、どうした？大スクープでも取ったか？",
  ui_story_5036_50360401_9_dialog_content = "ええ！編集長、ご存じですか？",
  ui_story_5036_50360401_10_dialog_content = "私は今、イクストウル…\nあの話題の巨像の上にいるのです！",
  ui_story_5036_50360401_11_dialog_content = "それで？",
  ui_story_5036_50360401_12_dialog_content = "影ノ街上空への到着に合わせて、\nこの巨像を使った大規模なコンサートが開催されます！",
  ui_story_5036_50360401_13_dialog_content = "時間は貴重なんだ。\n私の知らない情報だけ話してもらえるか？",
  ui_story_5036_50360401_14_dialog_content = "ええと、それは…",
  ui_story_5036_50360401_15_dialog_content = "私、今回のコンサートの記者に指名されました！\nオーディションの司会も担当させてもらえるそうです！",
  ui_story_5036_50360401_16_dialog_content = "フン、公認記者の立場なんぞ、\n何がそんなに嬉しいのだか…",
  ui_story_5036_50360401_17_dialog_content = "どうやら、まだ分かっていないようだな。",
  ui_story_5036_50360401_18_dialog_content = "私が求めているのは大スクープだ！\n誰もが目を見張り、驚愕するような特ダネだけだ！",
  ui_story_5036_50360401_19_dialog_content = "え？編集長！…編集長？",
  ui_story_5036_50360401_20_dialog_content = "…大スクープ、ですか。",
  ui_story_5036_50360401_21_dialog_content = "<color=#e8d9bb>コンサート開催まで、あと5日</color>",
  ui_story_5036_50360401_22_dialog_content = "皆様、お待たせいたしました！",
  ui_story_5036_50360401_23_dialog_content = "<color=#FFB400>シャイニングスターズ・空中コンサート</color>\nオーディションにようこそ！",
  ui_story_5036_50360401_24_dialog_content = "書類審査を通過し、専用の飛空艇でこの巨像までやってきた皆さんは今、\nどのようなお気持ちなのでしょうか？",
  ui_story_5036_50360401_25_dialog_content = "感動？興奮？それとも緊張でしょうか？",
  ui_story_5036_50360401_26_dialog_content = "思いつかずとも、あせる必要はありません！\nなぜなら、今からさらなる感動と興奮が始まるからです！",
  ui_story_5036_50360401_27_dialog_content = "ただ今より、オーディション第1審査を開始します！",
  ui_story_5036_50360401_28_dialog_content = "わああ――！",
  ui_story_5036_50360401_29_dialog_content = "皆さん、落ち着いてください。\nまずはオーディションの選抜ルールをご説明します。",
  ui_story_5036_50360401_30_dialog_content = "ご覧ください。会場に6名の審査員をお招きしております。",
  ui_story_5036_50360401_31_dialog_content = "フフフ、アイドル育成ゲームなら詳しいよ！",
  ui_story_5036_50360401_32_dialog_content = "歌唱力、ダンス、容貌、スタイル、会話力、知能――\nこの6項目で審査させていただきます。",
  ui_story_5036_50360401_33_dialog_content = "もちろん、1項目でも突出した才能が見られれば、\n高く評価されることになりますよ！",
  ui_story_5036_50360401_34_dialog_content = "私心なく、唯美的で、高尚で、曇りなく清らかで、心洗うパフォーマンス。\nそれが私の求めるものだ…",
  ui_story_5036_50360401_35_dialog_content = "見せてみるがいい！出来るものならな！",
  ui_story_5036_50360401_36_dialog_content = "全員、健闘を祈る。",
  ui_story_5036_50360401_37_dialog_content = "一緒に天空のステージから地上に光を届けましょう！",
  ui_story_5036_50360401_38_dialog_content = "こ、こんにちは！\n一人一人のパフォーマンスをしっかり観させてもらいます！",
  ui_story_5036_50360401_39_dialog_content = "ルールは簡単！\n6名の審査員のうち、4名から票を獲得できれば…",
  ui_story_5036_50360401_40_dialog_content = "2回戦に進み、最終ステージへの出場権を争うことができます。",
  ui_story_5036_50360401_41_dialog_content = "また、審査員6名全員の票を得た候補者は、\nその場でコンサート本番への出場権が与えられます！",
  ui_story_5036_50360401_42_dialog_content = "一度は合格できなくても、気を落とすことはありません。\n参加者全員に、3回までの挑戦権が与えられています。",
  ui_story_5036_50360401_43_dialog_content = "イクストウル内のリハーサル室は\nご自由に使っていただいて構いません。",
  ui_story_5036_50360401_44_dialog_content = "それでは、皆さんも待ちきれないことでしょう！\n早速オーディションを開始いたします！",
  ui_story_5036_50360401_45_dialog_content = "それでは、番号を呼ばれた参加者から前に出て、\nパフォーマンスを披露してください！",
  ui_story_5036_50360401_46_dialog_content = "エントリーナンバー1番…啓光合唱団の皆さんです！",
  ui_story_5036_50360401_47_dialog_content = "オーディションが始まったわね。\n見に行かなくていいの？",
  ui_story_5036_50360401_48_dialog_content = "ええ、今はいいわ。",
  ui_story_5036_50360401_49_dialog_content = "何をやるかも、まだ決まってないし。",
  ui_story_5036_50360401_50_dialog_content = "他の人のパフォーマンスなんて観ちゃったら、\nますます緊張するだけだもの。",
  ui_story_5036_50360401_51_dialog_content = "実は、私もまだよ。",
  ui_story_5036_50360401_52_dialog_content = "はじめは参加者が少なくて、コンサート開催が\n危うくなってはいけないと思って参加することにしたけれど…",
  ui_story_5036_50360401_53_dialog_content = "多くの人が集まっているようだし…",
  ui_story_5036_50360401_54_dialog_content = "私が出る幕ではないかもしれないわね。",
  ui_story_5036_50360401_55_dialog_content = "え？啓光と白夜城は一組ずつ「推薦」枠があるって聞いたわ。",
  ui_story_5036_50360401_56_dialog_content = "こっちは啓光合唱団よ。\n白夜城側はてっきりカレンだと思ってたけど？",
  ui_story_5036_50360401_57_dialog_content = "ありがとうございました！",
  ui_story_5036_50360401_58_dialog_content = "全員の動きがそろった、力強いパフォーマンスでした。\n歌詞も心を奮い立たせるもので、啓光の兵士の意気込みを存分に表現しています。",
  ui_story_5036_50360401_59_dialog_content = "私の知る限り、この合唱団は啓光各地を巡回公演しています。\nステージでの堂々と安定したパフォーマンスはさすがでした。",
  ui_story_5036_50360401_60_dialog_content = "とてもすばらしかったです。\n引き続き頑張ってください！",
  ui_story_5036_50360401_61_dialog_content = "コメント、ありがとうございました。",
  ui_story_5036_50360401_62_dialog_content = "エントリーナンバー1番、啓光合唱団の得票数は――",
  ui_story_5036_50360401_63_dialog_content = "6票、満点です！",
  ui_story_5036_50360401_64_dialog_content = "一番手のプレッシャーにも負けず、\nみごと、本番への出場権を手にしました！おめでとうございます！",
  ui_story_5036_50360401_65_dialog_content = "ありがとうございます！\n皆さんの期待に応えられるよう精一杯頑張ります！",
  ui_story_5036_50360401_66_dialog_content = "それでは、次に参りましょう！\nエントリーナンバー2番――白夜城聖歌隊、キーティン！",
  ui_story_5036_50360401_67_dialog_content = "なるほど、あの子たちが出るのね。",
  ui_story_5036_50360401_68_dialog_content = "でも、めったに無いチャンスを譲っちゃうなんて、\n惜しくないの？",
  ui_story_5036_50360401_69_dialog_content = "めったに無いチャンスだからこそ、\n本当に必要な人に譲るべきなのよ。",
  ui_story_5036_50360401_70_dialog_content = "な～んだ…",
  ui_story_5036_50360401_71_dialog_content = "え？",
  ui_story_5036_50360401_72_dialog_content = "じゃあ、オーディションに参加するのは私だけ？",
  ui_story_5036_50360401_73_dialog_content = "あ～、分かったわ！",
  ui_story_5036_50360401_74_dialog_content = "本番のステージは、\n白夜城からも観られるはずだものね…",
  ui_story_5036_50360401_75_dialog_content = "さては、身内の目の前でステージに立つのが、\n恥ずかしくなったんでしょ？",
  ui_story_5036_50360401_76_dialog_content = "そういうことではないわ…",
  ui_story_5036_50360401_77_dialog_content = "だったら、見せてよ…",
  ui_story_5036_50360401_78_dialog_content = "カレンの実力を。",
  ui_story_5036_50360401_79_dialog_content = "これが～♪",
  ui_story_5036_50360401_80_dialog_content = "私たちのパフォーマンス～♪",
  ui_story_5036_50360401_81_dialog_content = "さあ、どうぞ♪",
  ui_story_5036_50360401_82_dialog_content = "お次はお偉いさんたちの番～♪",
  ui_story_5036_50360401_83_dialog_content = "なんと優雅な合唱だ！",
  ui_story_5036_50360401_84_dialog_content = "さすがソルラド殿下が\n直々にお選びになったお子たちである！",
  ui_story_5036_50360401_85_dialog_content = "まさに天使の歌声と言うにふさわしい！\n心の奥底から清らかになった気分だ！",
  ui_story_5036_50360401_86_dialog_content = "庶民ども、この場に居合わせたことに感謝するがいい！",
  ui_story_5036_50360401_87_dialog_content = "光の神のご慈悲によって、\nこの神聖なる歌声を耳にすることができたのだからな。",
  ui_story_5036_50360401_88_dialog_content = "お偉いさんのパフォーマンス♪",
  ui_story_5036_50360401_89_dialog_content = "本当に面白い～♪",
  ui_story_5036_50360401_90_dialog_content = "次から次へと♪",
  ui_story_5036_50360401_91_dialog_content = "口からデマカセ♪",
  ui_story_5036_50360401_92_dialog_content = "なんと！話し方まで美しきメロディのようだ！",
  ui_story_5036_50360401_93_dialog_content = "皮肉だ。気づいてないのか？",
  ui_story_5036_50360401_94_dialog_content = "なんということでしょう！？",
  ui_story_5036_50360401_95_dialog_content = "キーティン合唱団も6票獲得、コンサート本番への出場権を手にしました！\nおめでとうございます！",
  ui_story_5036_50360401_96_dialog_content = "2組とも6票獲得だと？\nおいおい！ヤラセじゃないだろうな？",
  ui_story_5036_50360401_97_dialog_content = "失礼ですが、エントリーナンバー3番のバーバラさんですか？",
  ui_story_5036_50360401_98_dialog_content = "バーバラはこっちだよ～！",
  ui_story_5036_50360401_99_dialog_content = "うるさい人のことは放っておいて～。\nバーバラこそステージに立つために生まれた、本物のアイドルなんだから！",
  ui_story_5036_50360401_100_dialog_content = "フン、まず音程をとれるようになってから、\nステージに立つことだな。",
  ui_story_5036_50360401_101_dialog_content = "他人の心配をするヒマがあるなら、\n歌の練習したら～？",
  ui_story_5036_50360401_102_dialog_content = "あの、お2人とも…",
  ui_story_5036_50360401_103_dialog_content = "まったく、信じられないぜ。",
  ui_story_5036_50360401_104_dialog_content = "R・Wにイモくせぇラブソングなんか歌うヤツがいるとはな。",
  ui_story_5036_50360401_105_dialog_content = "ええ！？そんなことないでしょ～？",
  ui_story_5036_50360401_106_dialog_content = "レジーナの騒音こそ、歌だと思ってる人がいるなんて～。",
  ui_story_5036_50360401_107_dialog_content = "あん！？なんだと？",
  ui_story_5036_50360401_108_dialog_content = "もう一度言ってみな！",
  ui_story_5036_50360401_109_dialog_content = "あれ、ちょっと。\nどうしてステージに他の人が立ってるの？",
  ui_story_5036_50360401_110_dialog_content = "エントリーナンバー3番はバーバラでしょ？",
  ui_story_5036_50360401_111_dialog_content = "申し訳ありませんが…\n3番バーバラ選手、4番レジーナ選手。",
  ui_story_5036_50360401_112_dialog_content = "ルール違反のため、審査員の判断により、\n1回目の審査は不合格となりました。",
  ui_story_5036_50360401_113_dialog_content = "改めて2度目の審査にご参加ください。",
  ui_story_5036_50360401_114_dialog_content = "え！？/はあ！？",
  ui_story_5036_50360401_115_dialog_content = "…ああ、分かったわ。",
  ui_story_5036_50360401_116_dialog_content = "何が？",
  ui_story_5036_50360401_117_dialog_content = "バイス、1人でオーディションに出るのが、\n寂しいのでしょう？",
  ui_story_5036_50360401_118_dialog_content = "ううっ…",
  ui_story_5036_50360401_119_dialog_content = "…いいわ、認める。その通りよ。",
  ui_story_5036_50360401_120_dialog_content = "だって、今までずっと、\n何でも一緒にやってきたじゃない。",
  ui_story_5036_50360401_121_dialog_content = "急に1人にされたら、\n私だってさみしくなることもあるわ。",
  ui_story_5036_50360401_122_dialog_content = "ええ、そうね。",
  ui_story_5036_50360401_123_dialog_content = "さみしがり屋さんに付き合ってあげましょうか。",
  ui_story_5036_50360401_124_dialog_content = "さみしがり屋なんかじゃないわ！",
  ui_story_5036_50360401_125_dialog_content = "フフフ…",
  ui_story_5036_50360401_126_dialog_content = "でも、確かにステージに立つなら、たった1人より…",
  ui_story_5036_50360401_127_dialog_content = "あの時みたいに一緒にステージに上がった方が\nずっと楽しめそうね。",
  ui_story_5036_50360401_128_dialog_content = "えっ？",
  ui_story_5036_50360401_129_dialog_content = "どうしたの？急に思い出話なんて。",
  ui_story_5036_50360401_130_dialog_content = "あの時は全力を出すことしか、\n考えていなかったわ。",
  ui_story_5036_50360401_131_dialog_content = "そうね、実は私も…",
  ui_story_5036_50360401_132_dialog_content = "ううん、実に惜しい結果でした…",
  ui_story_5036_50360401_133_dialog_content = "エントリーナンバー1番、2番に続いて、\nステージ本番への直通キップを手に入れた参加者はまだおりません…",
  ui_story_5036_50360401_134_dialog_content = "いよいよ、本日最後の参加者の登場です。",
  ui_story_5036_50360401_135_dialog_content = "いったいどのようなパフォーマンスを\n見せてくれるのでしょうか？",
  ui_story_5036_50360401_136_dialog_content = "どーも、審査員のみなさん。",
  ui_story_5036_50360401_137_dialog_content = "俺はヴィック。\n普段は珍獣の研究をしてる。",
  ui_story_5036_50360401_138_dialog_content = "ヴィック！？",
  ui_story_5036_50360401_139_dialog_content = "あれ？PlayerNameじゃないか？",
  ui_story_5036_50360401_140_dialog_content = "ハハハ、知り合いが審査員だったとはな。",
  ui_story_5036_50360401_141_dialog_content = "いちおう言っておくが、\nPlayerNameが審査員だってことは、今まで知らなかったぜ。",
  ui_story_5036_50360401_142_dialog_content = "本当に、あのヴィック？",
  ui_story_5036_50360401_143_dialog_content = "見間違えたかと思ったよ！\nどうしてこんな所に？",
  ui_story_5036_50360401_144_dialog_content = "もちろん、アイドルとして、\n貴重なステージに立たせてもらうためさ！",
  ui_story_5036_50360401_145_dialog_content = "アイドル志望だったなんて知らなかったよ。",
  ui_story_5036_50360401_146_dialog_content = "それに、珍獣研究の分野では\nもう名の知れた有名人なんでしょ？",
  ui_story_5036_50360401_147_dialog_content = "おいおい、珍獣研究者はアイドルになっちゃいけないって\n法律でもあんのか？",
  ui_story_5036_50360401_148_dialog_content = "俺に言わせればな…",
  ui_story_5036_50360401_149_dialog_content = "今の時代、誰だってアイドルになれる可能性があるんだ！",
  ui_story_5036_50360401_150_dialog_content = "誰でもステージに上がって、\nほんの一瞬の青春を輝かせられるんだよ。",
  ui_story_5036_50360401_151_dialog_content = "「誰だってアイドルになれる」…",
  ui_story_5036_50360401_152_dialog_content = "…とってもステキだわ！",
  ui_story_5036_50360401_153_dialog_content = "あなたの「アイドル観」、最高だわ！\nパフォーマンスが楽しみね！",
  ui_story_5036_50360401_154_dialog_content = "なんと！本日のオーディションで初めて、\nゴルディさんが食いついた！",
  ui_story_5036_50360401_155_dialog_content = "いったいどのようなパフォーマンスを\n見せてくれるのでしょうか？",
  ui_story_5036_50360401_156_dialog_content = "では、ヴィックさん、どうぞ！",
  ui_story_5036_50360401_157_dialog_content = "じゃあ、朗読を披露させてもらおう。\nオッホン…",
  ui_story_5036_50360401_158_dialog_content = "ああ！万物の息吹あふれる、春がやってきた。",
  ui_story_5036_50360401_159_dialog_content = "春は珍獣たちが生命力を存分に輝かせる季節だ。",
  ui_story_5036_50360401_160_dialog_content = "（朗読ってアリなのかな…？）",
  ui_story_5036_50360401_161_dialog_content = "（しかもこの内容、\nヴィックが自分で書いた『珍獣大百科』だ…）",
  ui_story_5036_50360401_162_dialog_content = "君も感じるだろう？森の中に、荒野の上に。\n命が歌い。喜びが満ちあふれている！",
  ui_story_5036_50360401_163_dialog_content = "だが、そんな春に、\n独り静かに息をひそめる珍獣がいる…",
  ui_story_5036_50360401_164_dialog_content = "そう、<color=#FFB400>ウロボロス</color>だ。\nアストラ大陸で、もっとも<color=#FFB400>寿命の長い</color>珍獣と言われている。",
  ui_story_5036_50360401_165_dialog_content = "成体となった時には…",
  ui_story_5036_50360401_166_dialog_content = "申し訳ありませんが、少し中断します！",
  ui_story_5036_50360401_167_dialog_content = "審査員からの質問です。\n他のパフォーマンスはありませんか？",
  ui_story_5036_50360401_168_dialog_content = "すまんがそれはできないな。\nコレしか用意してないもんでね。",
  ui_story_5036_50360401_169_dialog_content = "そうなの？…残念だわ。",
  ui_story_5036_50360401_170_dialog_content = "表現力は素晴らしかったけど、\n朗読すること自体も内容も、今回のコンサートには合わないわ。",
  ui_story_5036_50360401_171_dialog_content = "でも、ガッカリしないで！",
  ui_story_5036_50360401_172_dialog_content = "私の経験から言って、とってもいい声を持ってるわ！\n見た目も悪くないし！",
  ui_story_5036_50360401_173_dialog_content = "歌やダンスをやれば、\nきっとステキなパフォーマンスになる、間違いないわ！",
  ui_story_5036_50360401_174_dialog_content = "第一線で活躍してるスターと肩を並べることだって、\n夢じゃないかも！",
  ui_story_5036_50360401_175_dialog_content = "次の挑戦では、\n別のパフォーマンスを見られることを期待してるわ。",
  ui_story_5036_50360401_176_dialog_content = "楽しみにしてるから、頑張ってね！",
  ui_story_5036_50360401_177_dialog_content = "そこまで言われたら、やってみるしかないかな…",
  ui_story_5036_50360401_178_dialog_content = "（ゴルディ、宝物でも見つけたみたいに\n目を輝かせてる…）",
  ui_story_5036_50360401_179_dialog_content = "（ヴィックに本当にアイドルの素質が…？\nいや、まさか…）",
  ui_story_5036_50360401_180_dialog_content = "参加者の皆さん、審査員の皆さん、お疲れ様でした。\n本日のオーディションはここまでです。",
  ui_story_5036_50360401_181_dialog_content = "オーディションはまだまだ続きます。\n引き続き応援をお願いいたします！",
  ui_story_5036_50360401_182_dialog_content = "それでは明日、またお会いましょう！",
  ui_story_5036_50360401_183_dialog_content = "PlayerName、ゴルディ、オーディションは終わったの？",
  ui_story_5036_50360401_184_dialog_content = "うん、終わったよ。審査員ってもっと気楽なものだと思ってたけど、\n皆のパフォーマンスを観るって結構疲れるんだね。",
  ui_story_5036_50360401_185_dialog_content = "そういえば2人とも、どうして出てこなかったの？",
  ui_story_5036_50360401_186_dialog_content = "もう少し一緒に練習してから、参加しようと思って。",
  ui_story_5036_50360401_187_dialog_content = "一緒に練習？",
  ui_story_5036_50360401_188_dialog_content = "そうよ。あれこれ考えて、\nやっぱり2人で出た方が楽しいってことになったの。",
  ui_story_5036_50360401_189_dialog_content = "聞き間違いではないわ。\nそれほど驚くことではないでしょう？",
  ui_story_5036_50360401_190_dialog_content = "私とバイスは二人一組で出場するわ。",
  ui_story_5036_50360401_191_dialog_content = "仲良しデュオで出場なんて、ステキ！",
  ui_story_5036_50360401_192_dialog_content = "何をやるかは決まってるの？",
  ui_story_5036_50360401_193_dialog_content = "歌を披露するつもりよ。\nいくつか候補を考えたわ。",
  ui_story_5036_50360401_194_dialog_content = "ただ、実際に練習していたら、\nどの曲がいいか迷ってしまって…",
  ui_story_5036_50360401_195_dialog_content = "オーディションに間に合うかしら…？",
  ui_story_5036_50360401_196_dialog_content = "心配いらないわ、\nヒミツだけど…教えてあげる！",
  ui_story_5036_50360401_197_dialog_content = "実はね、私も何を歌うかで迷ってるの。ふふ…",
  ui_story_5036_50360401_198_dialog_content = "自分の曲がたくさんあるのに？",
  ui_story_5036_50360401_199_dialog_content = "そうよ。でも、どの曲もイクストウルのステージには\nふさわしくない気がして…",
  ui_story_5036_50360401_200_dialog_content = "でも、大丈夫！\nそのうちインスピレーションが浮かんでくるわ！",
  ui_story_5036_50360401_201_dialog_content = "つまり、イクストウルでのステージのために、\n新曲を作るつもりということね。",
  ui_story_5036_50360401_202_dialog_content = "シーッ！今はアイデアだけだけどね。ふふふ。",
  ui_story_5036_50360401_203_dialog_content = "ちゃんと曲になるかどうかもまだ分からないから、\nほかの人たちにはナイショよ！",
  ui_story_5036_50360401_204_dialog_content = "作詞作曲も自分でできるってこと？",
  ui_story_5036_50360401_205_dialog_content = "すごいわ！",
  ui_story_5036_50360401_206_dialog_content = "全部が全部、自分で作ったものじゃないけどね。",
  ui_story_5036_50360401_207_dialog_content = "時々、メロディが急に頭の中に浮かんでくるから…",
  ui_story_5036_50360401_208_dialog_content = "それをメモしておいて、あとで曲にするの。",
  ui_story_5036_50360401_209_dialog_content = "自分の求めてるメロディが、\nいつもちょうどよく浮かんでくるわけじゃないの。",
  ui_story_5036_50360401_210_dialog_content = "メロディが…頭の中に浮かんでくる…？",
  ui_story_5036_50360401_211_dialog_content = "♪ル～ル～♪",
  ui_story_5036_50360401_212_dialog_content = "♪ラララ…♪",
  ui_story_5036_50360401_213_dialog_content = "実は、イクストウルに近づいた時からずっと、\n僕の頭の中にたまにメロディが流れてくるようになったんだ。",
  ui_story_5036_50360401_214_dialog_content = "メロディというより、\n誰かが歌を口ずさんでる感じなんだけど…",
  ui_story_5036_50360401_215_dialog_content = "え！？ホント？",
  ui_story_5036_50360401_216_dialog_content = "空の末裔は音楽を愛する種族だって聞いたことがあるわ！",
  ui_story_5036_50360401_217_dialog_content = "PlayerNameにも生まれつき音楽の才能があるのかもね！",
  ui_story_5036_50360401_218_dialog_content = "そ、そうなのかな？",
  ui_story_5036_50360401_219_dialog_content = "イクストウルがインスピレーションをくれたってこと？",
  ui_story_5036_50360401_220_dialog_content = "あり得るわ！",
  ui_story_5036_50360401_221_dialog_content = "あ、そうだ。",
  ui_story_5036_50360401_222_dialog_content = "イクストウルって、そもそも空の末裔一族のものでしょ。",
  ui_story_5036_50360401_223_dialog_content = "イクストウルの上で、空の末裔が書いた曲を歌ったら、\nすっごく意義のあるステージになると思わない！？",
  ui_story_5036_50360401_224_dialog_content = "PlayerName！",
  ui_story_5036_50360401_225_dialog_content = "よかったら、その頭に浮かんできたメロディ、教えてくれない？",
  ui_story_5036_50360401_226_dialog_content = "もちろん、構わないよ。",
  ui_story_5036_50360401_227_dialog_content = "待て――！",
  ui_story_5036_50360401_228_dialog_content = "あれ？何かあったのかな？",
  ui_story_5036_50360401_229_dialog_content = "グォォ！",
  ui_story_5036_50360401_230_dialog_content = "PlayerName、メロディはまたあとで聞かせて！",
  ui_story_5036_50360402_1_dialog_content = "お話の邪魔をして申し訳ありません。",
  ui_story_5036_50360402_2_dialog_content = "封鎖エリアで暗鬼掃討中、気を失った者がおりまして。\nその隙を狙って暗鬼が逃げ出してしまったのです。",
  ui_story_5036_50360402_3_dialog_content = "啓光と白夜城の兵士の援護のおかげで事態は収拾できています。",
  ui_story_5036_50360402_4_dialog_content = "気を失った人はどうしたの？\nケガはなかった？",
  ui_story_5036_50360402_5_dialog_content = "ご安心ください。\nすでに意識が戻っていますし、大きな問題もありません。",
  ui_story_5036_50360402_6_dialog_content = "暗鬼掃討のお仕事がキツすぎたのかしら？",
  ui_story_5036_50360402_7_dialog_content = "ゴルディさんのおかげで、全員が十分な休息をとれています。\n任務自体は大したことではありません。",
  ui_story_5036_50360402_8_dialog_content = "本人の話ですと、\n食事をとれていなかったそうです。",
  ui_story_5036_50360402_9_dialog_content = "食事はちゃんと出してるはずよ？",
  ui_story_5036_50360402_10_dialog_content = "その件については、その者の分が何者かに盗まれたらしく…\n補充する時間がなかったようです。",
  ui_story_5036_50360402_11_dialog_content = "食事が盗まれた？",
  ui_story_5036_50360402_12_dialog_content = "まさか！俺もやられたか？",
  ui_story_5036_50360402_13_dialog_content = "どうしたの？負傷した？",
  ui_story_5036_50360402_14_dialog_content = "バイス中尉、報告します。\n負傷はしておりません。",
  ui_story_5036_50360402_15_dialog_content = "ただ、持ち歩いていた配給食まで、\nなくなってしまったようです。",
  ui_story_5036_50360402_16_dialog_content = "配給食「まで」？",
  ui_story_5036_50360402_17_dialog_content = "はい。最近仲間の数人が同じような目に遭っています。",
  ui_story_5036_50360402_18_dialog_content = "どういう訳か、配給された食料がいつの間にか紛失しているのです。",
  ui_story_5036_50360402_19_dialog_content = "持ち歩いていれば安全かと思ったのですが…",
  ui_story_5036_50360402_20_dialog_content = "暗鬼との戦闘中に落としたわけではないの？",
  ui_story_5036_50360402_21_dialog_content = "我々もそう思っていたので、\nご報告はせずにいたのですが…",
  ui_story_5036_50360402_22_dialog_content = "<color=#FFB400>「泥棒オバケ」</color>です…\n「泥棒オバケ」のしわざに決まっています！",
  ui_story_5036_50360402_23_dialog_content = "「泥棒オバケ」？",
  ui_story_5036_50360402_24_dialog_content = "カレン殿下はご存じないかもしれませんが、\nこの巨像に「泥棒オバケ」がいるのです！",
  ui_story_5036_50360402_25_dialog_content = "誰にも気づかれないように\n獲物の気を失わせ…",
  ui_story_5036_50360402_26_dialog_content = "そのすきに、我々が身に着けている高価な宝石などを、\n盗んでいくのです！",
  ui_story_5036_50360402_27_dialog_content = "私の宝石のはめられた懐中時計も、\nそれで奪われてしまいました…",
  ui_story_5036_50360402_28_dialog_content = "食料や宝石を奪われた？",
  ui_story_5036_50360402_29_dialog_content = "暗鬼ではなさそうね。",
  ui_story_5036_50360402_30_dialog_content = "盗人…",
  ui_story_5036_50360402_31_dialog_content = "そういう手口、どこかで見たことあるような…？",
  ui_story_5036_50360402_32_dialog_content = "いつだったか、そんなことがあったよね…？",
  ui_story_5036_50360402_33_dialog_content = "この巨像に泥棒が紛れ込んでるの？",
  ui_story_5036_50360402_34_dialog_content = "ゴルディさん、実は我々の方でも似たような問題が起こっているようです。",
  ui_story_5036_50360402_35_dialog_content = "私どもだけではなく、オーディションの参加者たちにも、\n菓子や酒がなくなったと訴えている者がいます。",
  ui_story_5036_50360402_36_dialog_content = "ひどい！こんなところまで来て\n悪いことをする誰かがいるの！？",
  ui_story_5036_50360402_37_dialog_content = "ゴルディ、オーディションの参加者たちを\n不安にさせてはいけないわ。",
  ui_story_5036_50360402_38_dialog_content = "カレンの言う通りね。急いで対策して、参加者の皆に\n主催者側を信用してもらえるようにしないと。",
  ui_story_5036_50360402_39_dialog_content = "傭兵さん、誰かに影ノ街で\n食料を調達してきてもらえないかしら？",
  ui_story_5036_50360402_40_dialog_content = "オーディションの参加者と兵士のみんなの食料を\n確保しないといけないわ。",
  ui_story_5036_50360402_41_dialog_content = "相当な量になりますから、\nおそらく数人の人手が必要になるでしょう。",
  ui_story_5036_50360402_42_dialog_content = "お願いするわ。経費はちゃんと記録しておいてね。",
  ui_story_5036_50360402_43_dialog_content = "分かりました！",
  ui_story_5036_50360402_44_dialog_content = "…",
  ui_story_5036_50360402_45_dialog_content = "ゴルディ、大丈夫？",
  ui_story_5036_50360402_46_dialog_content = "…",
  ui_story_5036_50360402_47_dialog_content = "ゴルディ？",
  ui_story_5036_50360402_48_dialog_content = "え？…ええ！心配いらないわ。",
  ui_story_5036_50360402_49_dialog_content = "2人も安心して練習しててね。\nこの件の心配はしないで～。",
  ui_story_5036_50360402_50_dialog_content = "私が、絶対に…",
  ui_story_5036_50360402_51_dialog_content = "絶対にコンサートの邪魔はさせないから！",
  ui_story_5036_50360501_1_dialog_content = "傭兵さん…",
  ui_story_5036_50360501_2_dialog_content = "いったいどうやったの！？",
  ui_story_5036_50360501_3_dialog_content = "このステージ、夢みたいだわ！",
  ui_story_5036_50360501_4_dialog_content = "スクリーンは新品みたいにきれいになってるし、\n色が変えられる照明まである！",
  ui_story_5036_50360501_5_dialog_content = "正直に言わせてもらうと…",
  ui_story_5036_50360501_6_dialog_content = "影ノ街で見たどんなステージよりも、胸が躍るわ！",
  ui_story_5036_50360501_7_dialog_content = "気に入っていただけたようで、光栄です。",
  ui_story_5036_50360501_8_dialog_content = "我々はシェオルさんに言われた通りにしたまでのことです。",
  ui_story_5036_50360501_9_dialog_content = "それは違うわ。",
  ui_story_5036_50360501_10_dialog_content = "シェオルさん、言ってたもの。傭兵団の人たちってほとんどは仕事が雑だから、\n私たちが欲しいような質のものは造れないって。",
  ui_story_5036_50360501_11_dialog_content = "でも、白火傭兵団なら\nいつも仕事が丁寧でまじめだから、信頼できるって。",
  ui_story_5036_50360501_12_dialog_content = "ただ、残念だわ…",
  ui_story_5036_50360501_13_dialog_content = "こんなにステキなステージが、\nたった1回しか使えないなんて…",
  ui_story_5036_50360501_14_dialog_content = "お望みであれば…",
  ui_story_5036_50360501_15_dialog_content = "後々、影ノ街にもそっくりそのまま、\n同じステージを造ってさしあげますよ。",
  ui_story_5036_50360501_16_dialog_content = "後々？",
  ui_story_5036_50360501_17_dialog_content = "そうね…\nその時まだアイドルをやってれば、だけど…",
  ui_story_5036_50360501_18_dialog_content = "はい？",
  ui_story_5036_50360501_19_dialog_content = "なんでもないわ。\nそれより、泥棒の手がかりは見つかった？",
  ui_story_5036_50360501_20_dialog_content = "今のところ、手がかりはありません。",
  ui_story_5036_50360501_21_dialog_content = "非常にずる賢い相手のようで、\n有用な手がかりが何一つ見つかっておりません。",
  ui_story_5036_50360501_22_dialog_content = "せいぜい、多くは夜に盗まれているということしか…",
  ui_story_5036_50360501_23_dialog_content = "十分よ。",
  ui_story_5036_50360501_24_dialog_content = "夜は私も一緒にパトロールするわ。",
  ui_story_5036_50360501_25_dialog_content = "ゴルディさんも…ですか？",
  ui_story_5036_50360501_26_dialog_content = "ふふふ、人気絶頂のアイドルと一緒に仕事をしたがらないなんて、\nあなたが初めてかもね？",
  ui_story_5036_50360501_27_dialog_content = "そのようなことはありませんが…\n曲作りでお忙しいのではと思いまして。",
  ui_story_5036_50360501_28_dialog_content = "人気アイドルの実力を見くびらないでよね！",
  ui_story_5036_50360501_29_dialog_content = "ステージで披露できる歌なら、たくさんあるんだから。",
  ui_story_5036_50360501_30_dialog_content = "確かに、空の末裔のメロディで新曲を作りたくはあるけど…",
  ui_story_5036_50360501_31_dialog_content = "PlayerNameが教えてくれたメロディ、\nたった1小節だけで、広げるアイデアが無いの。",
  ui_story_5036_50360501_32_dialog_content = "たった1小節？",
  ui_story_5036_50360501_33_dialog_content = "聴いてみたい？",
  ui_story_5036_50360501_34_dialog_content = "い、いえ、決して個人的に歌を聴きたくて、\n申し上げたわけでは！",
  ui_story_5036_50360501_35_dialog_content = "そう？でも、私はこの出来立てでピカピカのステージで、\nちょっと歌ってみたいな～、って思ったから。",
  ui_story_5036_50360501_36_dialog_content = "♪ラ…♪",
  ui_story_5036_50360501_37_dialog_content = "♪ラ…ラララ…♪",
  ui_story_5036_50360501_38_dialog_content = "グォォ――！",
  ui_story_5036_50360501_39_dialog_content = "この間逃げ出した暗鬼かしら？\nステージの下に隠れてたの！？",
  ui_story_5036_50360501_40_dialog_content = "ゴルディさんが歌を口ずさんだとたんに、\n暗鬼が現れましたね？",
  ui_story_5036_50360501_41_dialog_content = "暗鬼の中にも「ディディ推し」がいるのでしょうか…？",
  ui_story_5036_50360502_1_dialog_content = "そうでした、ステージが今夜完成予定だったはず…",
  ui_story_5036_50360502_2_dialog_content = "誰かが来る前に真っ先に写真を撮らなくては！\nステージ全体を様々な角度から撮影しましょう！",
  ui_story_5036_50360502_3_dialog_content = "私が求めているのは大スクープだ！\n誰もが目を見張り、驚愕するような特ダネだけだ！",
  ui_story_5036_50360502_4_dialog_content = "編集長はいつも無理難題ばかりです。",
  ui_story_5036_50360502_5_dialog_content = "大スクープが、\nそこらに都合よく転がってるワケないじゃないですか…",
  ui_story_5036_50360502_6_dialog_content = "どうにかイクストウルに関する情報を真っ先に手に入れて、\n他社を出し抜ければ…",
  ui_story_5036_50360502_7_dialog_content = "おや、ステージにもう先客が…？",
  ui_story_5036_50360502_8_dialog_content = "ホントに暗鬼も「ディディ推し」だったらいいのに～。",
  ui_story_5036_50360502_9_dialog_content = "ゴルディさん、変わった趣味でいらっしゃいますね…",
  ui_story_5036_50360502_10_dialog_content = "ちょっと、どういうこと？",
  ui_story_5036_50360502_11_dialog_content = "も、申し訳ありません！",
  ui_story_5036_50360502_12_dialog_content = "ふふふ…まぁ、私が言い方が悪かったもの。",
  ui_story_5036_50360502_13_dialog_content = "暗鬼も歌が分かればいいのにって思っただけよ。",
  ui_story_5036_50360502_14_dialog_content = "歌に込められた愛や平和への願いを感じれば、\n暗鬼たちももしかしたら、影響されて…",
  ui_story_5036_50360502_15_dialog_content = "暴力をふるうことなんて、\nやめるかもしれないわ。",
  ui_story_5036_50360502_16_dialog_content = "そう思う事って、おごりすぎかしら？",
  ui_story_5036_50360502_17_dialog_content = "「影響」？「暴力」…？",
  ui_story_5036_50360502_18_dialog_content = "いったい何の話でしょう…？\n遠すぎてよく聞こえませんね…",
  ui_story_5036_50360502_19_dialog_content = "もう少し近づいて…",
  ui_story_5036_50360502_20_dialog_content = "<color=#e8d9bb>ガタンッ！</color>",
  ui_story_5036_50360502_21_dialog_content = "うっ！？なんて運が悪い…",
  ui_story_5036_50360502_22_dialog_content = "なぜこんな所に木箱が…",
  ui_story_5036_50360502_23_dialog_content = "今の音、ステージまで聞こえたでしょうか？",
  ui_story_5036_50360502_24_dialog_content = "…どうやら、気づかれてはいないようですね。",
  ui_story_5036_50360502_25_dialog_content = "誰！？",
  ui_story_5036_50360502_26_dialog_content = "！？",
  ui_story_5036_50360502_27_dialog_content = "み、見つかった…？",
  ui_story_5036_50360502_28_dialog_content = "だ、大丈夫。たまたま通りかかっただけだと説明すれば、\nゴルディさんなら、きっと…",
  ui_story_5036_50360502_29_dialog_content = "信じてくれますよね？",
  ui_story_5036_50360502_30_dialog_content = "<color=#e8d9bb>バリッ！</color>",
  ui_story_5036_50360502_31_dialog_content = "逃げてもムダよ！",
  ui_story_5036_50360502_32_dialog_content = "え？え？…ええ？",
  ui_story_5036_50360502_33_dialog_content = "私とは反対の方向…",
  ui_story_5036_50360502_34_dialog_content = "他にも誰か隠れていたのでしょうか？",
  ui_story_5036_50360502_35_dialog_content = "ゴルディさんが、まさか我々よりも感覚が鋭いとは。",
  ui_story_5036_50360502_36_dialog_content = "板の下に誰かが隠れているとは気づきませんでした。",
  ui_story_5036_50360502_37_dialog_content = "でも残念…板をはがす前に逃げられちゃったわ。",
  ui_story_5036_50360502_38_dialog_content = "見てください。食べかけの乾パンです。",
  ui_story_5036_50360502_39_dialog_content = "包装からして、啓光の配給品ですね。",
  ui_story_5036_50360502_40_dialog_content = "啓光の配給品？",
  ui_story_5036_50360502_41_dialog_content = "でも、啓光の人たちはステージ付近を担当してないわ。",
  ui_story_5036_50360502_42_dialog_content = "はい。最近仲間の数人が同じような目に遭っています。",
  ui_story_5036_50360502_43_dialog_content = "どういう訳か、配給された食料がいつの間にか紛失しているのです。",
  ui_story_5036_50360502_44_dialog_content = "まさか…",
  ui_story_5036_50360502_45_dialog_content = "<color=#e8d9bb>サッ――</color>",
  ui_story_5036_50360502_46_dialog_content = "今のは…？ネズミでしょうか？",
  ui_story_5036_50360502_47_dialog_content = "いいえ、違うわ！",
  ui_story_5036_50360502_48_dialog_content = "マシュマロ、今飛び出していったのが見えたでしょ？",
  ui_story_5036_50360502_49_dialog_content = "急いで追いかけて！",
  ui_story_5036_50360502_50_dialog_content = "ワン！ワンワンワン！",
  ui_story_5036_50360502_51_dialog_content = "ハイ？",
  ui_story_5036_50360502_52_dialog_content = "ハイハイ！！",
  ui_story_5036_50360502_53_dialog_content = "マシュマロ、捕まえなくていいわ。\nちょっとの間泳がせて、ついていきましょ。",
  ui_story_5036_50360502_54_dialog_content = "あの子をエサにすれば、\n<color=#FFB400>「大物」</color>が釣れそう！",
  ui_story_5036_50360502_55_dialog_content = "ハーイ！",
  ui_story_5036_50360502_56_dialog_content = "ん…？なんだ？",
  ui_story_5036_50360502_57_dialog_content = "おいおい、ビッカー。\nさっきまで全然相手してくれなかったくせに…",
  ui_story_5036_50360502_58_dialog_content = "急に甘えてくるなんて、\nどういう風の吹き回しだ？",
  ui_story_5036_50360502_59_dialog_content = "ワン！",
  ui_story_5036_50360502_60_dialog_content = "おいおい、嬢ちゃん。\nそのポッチャリした犬、しっかり見ておいてくれないと困るなぁ。",
  ui_story_5036_50360502_61_dialog_content = "ビッカーはデリケートで臆病なんだ。\nビックリするとすぐ腹の調子を悪くしちまうんでな…",
  ui_story_5036_50360502_62_dialog_content = "あなたが泥棒オバケ？",
  ui_story_5036_50360502_63_dialog_content = "オバケ？\nずいぶん人聞きの悪いことを言うなぁ。",
  ui_story_5036_50360502_64_dialog_content = "信じられないか？\nだったら、唇でも噛んでみせてやるよ…",
  ui_story_5036_50360502_65_dialog_content = "アイテテテ！",
  ui_story_5036_50360502_66_dialog_content = "ほら、これで分かっただろ。俺は生きてるからな、当然痛みを感じる。\n幽霊は痛がったりしないもんだろ？",
  ui_story_5036_50360502_67_dialog_content = "（話が通じなさそうね…）",
  ui_story_5036_50360502_68_dialog_content = "（でも、この声には聞き覚えがあるような…）",
  ui_story_5036_50360502_69_dialog_content = "オバケであろうとなかろうと、\nコンサートを台無しにしようとするなら、絶対に許さないわ！",
  ui_story_5036_50360502_70_dialog_content = "正直に白状しなさい！",
  ui_story_5036_50360502_71_dialog_content = "<color=#e8d9bb>シャリン！</color>",
  ui_story_5036_50360502_72_dialog_content = "これ、飾りじゃないわよ！",
  ui_story_5036_50360502_73_dialog_content = "おいおい…",
  ui_story_5036_50360502_74_dialog_content = "落ち着いて話し合おうぜ？\nビックリして、転んじまうところだったよ。",
  ui_story_5036_50360502_75_dialog_content = "ずいぶん着ぶくれしてるみたいね。\n盗んだものを隠してるんじゃない？",
  ui_story_5036_50360502_76_dialog_content = "ちょうど飼い慣らしたばっかりの子を抱えてるのさ。\n今ゆっくり眠ってるところなんだ。",
  ui_story_5036_50360502_77_dialog_content = "信じられないわ。",
  ui_story_5036_50360502_78_dialog_content = "だったら、もう少し他人の気持ちが分かるようにならなきゃな。",
  ui_story_5036_50360502_79_dialog_content = "普段から本や新聞をたくさん読んで、慈善活動でもして…\nうーん、俺にできるアドバイスはそれくらいだな。",
  ui_story_5036_50360502_80_dialog_content = "ハハハ、用がそれだけなら、失礼するぜ。",
  ui_story_5036_50360502_81_dialog_content = "服の中を見せなさい！",
  ui_story_5036_50360502_82_dialog_content = "そりゃ困ったな。\nこんな真っ暗闇じゃ、どうせ何も見えやしないと思うが…",
  ui_story_5036_50360502_83_dialog_content = "清く正しいオトシゴロの男子として、\nそんなハレンチなことはできないな。",
  ui_story_5036_50360502_84_dialog_content = "マシュマロ、行って！",
  ui_story_5036_50360502_85_dialog_content = "ワンワン！",
  ui_story_5036_50360502_86_dialog_content = "おいおい、気をつけろよ――",
  ui_story_5036_50360502_87_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5036_50360502_88_dialog_content = "…あーあ、結局転んじまったか。",
  ui_story_5036_50360502_89_dialog_content = "おや？これは…\n今日のオーディションに出ていた男ではありませんか？",
  ui_story_5036_50360502_90_dialog_content = "やっぱり…参加者に紛れ込んでたのね。",
  ui_story_5036_50360502_91_dialog_content = "イテテテテ…",
  ui_story_5036_50360502_92_dialog_content = "あ…あなただったの！？",
  ui_story_5036_50360502_93_dialog_content = "ホゥホゥホゥ！",
  ui_story_5036_50360502_94_dialog_content = "服の中からフクロウが出てきましたよ？",
  ui_story_5036_50360502_95_dialog_content = "盗んだものじゃないの？\n私が疑心暗鬼になってただけだったのかしら…",
  ui_story_5036_50360502_96_dialog_content = "だから言ったろ――",
  ui_story_5036_50360502_97_dialog_content = "<color=#e8d9bb>ドサッ――チャリンチャリン…</color>",
  ui_story_5036_50360502_98_dialog_content = "これは！？フクロウの羽の中から大量の宝石が！",
  ui_story_5036_50360502_99_dialog_content = "ハハハ…な？俺は泥棒じゃないって。",
  ui_story_5036_50360502_100_dialog_content = "アリガタモドキドリ君よ、君はまったく困ったもんだな。\nなんだってまた盗みなんてしたんだ？",
  ui_story_5036_50360502_101_dialog_content = "ホウ…",
  ui_story_5036_50360502_102_dialog_content = "どういうつもり！？\n証拠が目の前に出て来たのに、まだ言い逃れできると思ってる！？",
  ui_story_5036_50360502_103_dialog_content = "だからよ…落ち着いて話そう、な？",
  ui_story_5036_50360502_104_dialog_content = "許さないわ！",
  ui_story_5036_50360502_105_dialog_content = "うっ…",
  ui_story_5036_50360502_106_dialog_content = "ゴルディさん！？",
  ui_story_5036_50360502_107_dialog_content = "心配しないで、\nとりあえず気絶させただけ。",
  ui_story_5036_50360502_108_dialog_content = "こんな所で言い逃れに付き合う時間も労力も惜しいもの。",
  ui_story_5036_50360502_109_dialog_content = "連れて行って、やるべきことが片付いたら、\nゆっくり話を聞くことにしましょ。",
  ui_story_5036_50360502_110_dialog_content = "<color=#e8d9bb>カシャ！</color>",
  ui_story_5036_50360502_111_dialog_content = "なんと…",
  ui_story_5036_50360502_112_dialog_content = "暴力的になっているというウワサが、\n本当だったなんて…",
  ui_story_5036_50360502_113_dialog_content = "でも、この写真があれば…",
  ui_story_5036_50360601_1_dialog_content = "今度は何だ？",
  ui_story_5036_50360601_2_dialog_content = "やりました！すっぱ抜きましたよ！\n誰もが目を見張って驚愕する特ダネを！",
  ui_story_5036_50360601_3_dialog_content = "せいぜい私の時間を無駄にしないでもらいたいな。",
  ui_story_5036_50360601_4_dialog_content = "今度は満足していただけます！",
  ui_story_5036_50360601_5_dialog_content = "編集長、アイドルのゴルディが\n暴力行為をしているというウワサはご存じですよね――",
  ui_story_5036_50360601_6_dialog_content = "（ここはどこだろう？）",
  ui_story_5036_50360601_7_dialog_content = "（…あれ？いつ天空ノ谷に戻ってきたんだっけ？\n確か僕は…）",
  ui_story_5036_50360601_8_dialog_content = "（…どこにいたんだっけ？）",
  ui_story_5036_50360601_9_dialog_content = "♪ラ…ラララ…♪",
  ui_story_5036_50360601_10_dialog_content = "（このメロディは…そうだ、あのメロディだ！）",
  ui_story_5036_50360601_11_dialog_content = "♪ルルル～♪",
  ui_story_5036_50360601_12_dialog_content = "（誰が歌ってるんだろう？）",
  ui_story_5036_50360601_13_dialog_content = "<color=#e8d9bb>シュッ…</color>",
  ui_story_5036_50360601_14_dialog_content = "（何かが飛んで行った？巨像かな？）",
  ui_story_5036_50360601_15_dialog_content = "（ついて行ってみよう…）",
  ui_story_5036_50360601_16_dialog_content = "♪ラララ…♪",
  ui_story_5036_50360601_17_dialog_content = "♪ル～ル～♪",
  ui_story_5036_50360601_18_dialog_content = "♪ラ…ララ…♪",
  ui_story_5036_50360601_19_dialog_content = "（女の子だ。ずっと歌ってる）",
  ui_story_5036_50360601_20_dialog_content = "あ、来たんだね！？",
  ui_story_5036_50360601_21_dialog_content = "（え？話しかけられてる？）",
  ui_story_5036_50360601_22_dialog_content = "キュウキュウ！",
  ui_story_5036_50360601_23_dialog_content = "（なんだ、あっちの巨像みたいな動物と話してたのか）",
  ui_story_5036_50360601_24_dialog_content = "お歌を聞きにきたの？\nあなたは本当に歌が好きだね。",
  ui_story_5036_50360601_25_dialog_content = "うーん、でも、そろそろ歌詞をつけないとなぁ。",
  ui_story_5036_50360601_26_dialog_content = "（この子の服と気配…間違いない、空の末裔だ！）",
  ui_story_5036_50360601_27_dialog_content = "（いつか他の空の末裔に会える日が来るって、信じてた！）",
  ui_story_5036_50360601_28_dialog_content = "ふぅ、ちょっとのどが渇いちゃった。",
  ui_story_5036_50360601_29_dialog_content = "木の実でも摘んでこようかな？",
  ui_story_5036_50360601_30_dialog_content = "キュウキュウ！",
  ui_story_5036_50360601_31_dialog_content = "ねえ、君！",
  ui_story_5036_50360601_32_dialog_content = "ちょっと待って！",
  ui_story_5036_50360601_33_dialog_content = "え？",
  ui_story_5036_50360601_34_dialog_content = "<color=#e8d9bb>ドンドンドン！</color>",
  ui_story_5036_50360601_35_dialog_content = "待って！",
  ui_story_5036_50360601_36_dialog_content = "…え？",
  ui_story_5036_50360601_37_dialog_content = "…夢か…",
  ui_story_5036_50360601_38_dialog_content = "<color=#e8d9bb>コンサート開催まで、あと4日</color>",
  ui_story_5036_50360601_39_dialog_content = "<color=#e8d9bb>ドンドン！ドンドン！</color>",
  ui_story_5036_50360601_40_dialog_content = "PlayerName、大丈夫！？",
  ui_story_5036_50360601_41_dialog_content = "あ、今開けるよ！",
  ui_story_5036_50360601_42_dialog_content = "PlayerName、ずいぶんぐっすり寝てたわね。",
  ui_story_5036_50360601_43_dialog_content = "何度も強くノックしてたのよ、聞こえなかったの？",
  ui_story_5036_50360601_44_dialog_content = "万一、暗鬼が部屋に侵入していたらと思って…",
  ui_story_5036_50360601_45_dialog_content = "もう少しで、2人でドアを蹴破るところだったわ。",
  ui_story_5036_50360601_46_dialog_content = "ごめん、ごめん…夢を見てて…\nちょっと寝ぼけてたんだ。",
  ui_story_5036_50360601_47_dialog_content = "また夢ね…",
  ui_story_5036_50360601_48_dialog_content = "また？",
  ui_story_5036_50360601_49_dialog_content = "カレン、忘れたの？",
  ui_story_5036_50360601_50_dialog_content = "PlayerName、よくおかしな夢を見るでしょ。",
  ui_story_5036_50360601_51_dialog_content = "そういえば…\n今朝は、私もおかしな夢を見たわね。",
  ui_story_5036_50360601_52_dialog_content = "天空ノ谷にいたような気がしたわ。",
  ui_story_5036_50360601_53_dialog_content = "けれど、天空ノ谷にいたのはPlayerNameではなくて、\n会ったことのない女の子だったの。",
  ui_story_5036_50360601_54_dialog_content = "私もよ！同じ夢を見たわ！",
  ui_story_5036_50360601_55_dialog_content = "私とカレン、そこまで息が合うようになるなんて…",
  ui_story_5036_50360601_56_dialog_content = "きっと、ここ数日の特訓のおかげね！",
  ui_story_5036_50360601_57_dialog_content = "僕も似たような夢を見たよ。",
  ui_story_5036_50360601_58_dialog_content = "え？",
  ui_story_5036_50360601_59_dialog_content = "女の子が天空ノ谷で歌を歌ってた。",
  ui_story_5036_50360601_60_dialog_content = "最近ずっと頭の中に流れてくる、\nあのメロディを…",
  ui_story_5036_50360601_61_dialog_content = "私の夢の中では歌は歌ってなかったわ。\nただ家を掃除してただけね。",
  ui_story_5036_50360601_62_dialog_content = "私は読書している様子を見たわ。",
  ui_story_5036_50360601_63_dialog_content = "それぞれ少しずつ違う夢を見たのね。",
  ui_story_5036_50360601_64_dialog_content = "同じ経験をもつ者同士は、\n似たような夢を見ることがあると聞いたことがあるわ。",
  ui_story_5036_50360601_65_dialog_content = "似たような経験をすると、似たような記憶が残って、\n夢も似てくるそうね。",
  ui_story_5036_50360601_66_dialog_content = "「昼間考えていることが夢になる」と言う事でしょうね。",
  ui_story_5036_50360601_67_dialog_content = "けれど、それぞれの性格は違うから、\nどんなに似ていようとも細かいところには違いが出るの。",
  ui_story_5036_50360601_68_dialog_content = "そんなこと…？\n興奮して損しちゃったわ。",
  ui_story_5036_50360601_69_dialog_content = "そんなことより、\n私たちのおしゃべりに付き合っていていいのかしら？",
  ui_story_5036_50360601_70_dialog_content = "今日はオーディションの2日目でしょう？\nPlayerNameは審査員ではなかった？",
  ui_story_5036_50360601_71_dialog_content = "あっ！！！忘れるところだった！",
  ui_story_5036_50360601_72_dialog_content = "♪ルルル～♪",
  ui_story_5036_50360601_73_dialog_content = "♪ラ…ララ…♪",
  ui_story_5036_50360601_74_dialog_content = "これが僕の聞いたメロディの全部だよ。\nやっと最初から最後まで歌えた…！",
  ui_story_5036_50360601_75_dialog_content = "ふわぁ～…",
  ui_story_5036_50360601_76_dialog_content = "へ、下手すぎたかな…？",
  ui_story_5036_50360601_77_dialog_content = "そうじゃないの…昨日よく眠れなかったせいだわ。\n目の前であくびなんて失礼よね。ごめんなさい。",
  ui_story_5036_50360601_78_dialog_content = "まさか、夢のせいで眠れなかったってわけじゃないよね？",
  ui_story_5036_50360601_79_dialog_content = "ふふふ、PlayerNameって想像力が豊かね～。",
  ui_story_5036_50360601_80_dialog_content = "昨日の夜は、ステージをチェックしてたの。",
  ui_story_5036_50360601_81_dialog_content = "それから封鎖されてる暗鬼の掃討も手伝って、\n夜明け近くになってようやく終わったの。",
  ui_story_5036_50360601_82_dialog_content = "傭兵団に任せたんじゃないの？",
  ui_story_5036_50360601_83_dialog_content = "えへへ、部屋にいても、じっとしてられなくて。",
  ui_story_5036_50360601_84_dialog_content = "部屋にこもってあれこれ悩むより、\n少しでも何か手伝った方がいいと思わない？",
  ui_story_5036_50360601_85_dialog_content = "さすが影ノ街で大人気のアイドルだね。\nでも、頑張りすぎじゃないかな？",
  ui_story_5036_50360601_86_dialog_content = "そんな細かいところまで、\n君がやることないんじゃない？",
  ui_story_5036_50360601_87_dialog_content = "細かいことの積み重ねが、\nコンサートの成功につながるのよ。",
  ui_story_5036_50360601_88_dialog_content = "私にとってはすっごく大事なコンサートなの。\nどんなアクシデントも、未然に防がなくちゃ！",
  ui_story_5036_50360601_89_dialog_content = "そこまで完璧にこだわるなんて…\n何だか、これが一生で最後のコンサートみたいな気迫だね。",
  ui_story_5036_50360601_90_dialog_content = "そ、そう？えへへ…",
  ui_story_5036_50360601_91_dialog_content = "そうだ、本題に戻るけど、\nPlayerNameの歌ってくれたメロディ…",
  ui_story_5036_50360601_92_dialog_content = "やさしくて、おだやかで、心が癒されるわ。\n空の末裔らしい、誰でも気に入りそうなメロディね！",
  ui_story_5036_50360601_93_dialog_content = "まさに私の求めていた音楽そのものだわ！",
  ui_story_5036_50360601_94_dialog_content = "ホントにこれ、ステージで歌ってもいいの？",
  ui_story_5036_50360601_95_dialog_content = "もちろん！作曲家になろうなんて思ったことはないし、\n好きなようにして！",
  ui_story_5036_50360601_96_dialog_content = "人気のアイドル歌手に歌ってもらえるなら、\n僕もうれしいよ。",
  ui_story_5036_50360601_97_dialog_content = "歌詞についても何か思いついたら、教えてね！",
  ui_story_5036_50360601_98_dialog_content = "あ、そうそう…PlayerNameに聞きたいことがあったの。",
  ui_story_5036_50360601_99_dialog_content = "1回目のオーディションで最後に登場した人のこと、覚えてる？",
  ui_story_5036_50360601_100_dialog_content = "ヴィックのこと？",
  ui_story_5036_50360601_101_dialog_content = "あの人って、PlayerNameの友だち？",
  ui_story_5036_50360601_102_dialog_content = "そうだね…弟子と知り合いになって以来だね。\n友だちと言ってもいいと思うよ。",
  ui_story_5036_50360601_103_dialog_content = "ただ、オーディションに参加するなんて聞いてなかったよ。\n投票もしてない。",
  ui_story_5036_50360601_104_dialog_content = "ひいきはしてないから、心配しないで！",
  ui_story_5036_50360601_105_dialog_content = "そうじゃないの…あの人、昔から…\n物を盗んだりするクセはあった？",
  ui_story_5036_50360601_106_dialog_content = "え？盗み…？どうしてそんなことを聞くの？",
  ui_story_5036_50360601_107_dialog_content = "昨日の夜遅くに…",
  ui_story_5036_50360601_108_dialog_content = "た、助けてくれ！",
  ui_story_5036_50360601_109_dialog_content = "グォォ――！",
  ui_story_5036_50360601_110_dialog_content = "逃がすか！",
  ui_story_5036_50360601_111_dialog_content = "ヴィックが暗鬼に追いかけられて、暗鬼が傭兵に追いかけられてる？\nいったい、何があったの！？",
  ui_story_5036_50360602_1_dialog_content = "ゴルディさん、PlayerNameさん、\n他の審査員の方々はもうおそろいですよ。",
  ui_story_5036_50360602_2_dialog_content = "準備ができたのでしたら、お二人も…",
  ui_story_5036_50360602_3_dialog_content = "お助けぇ！",
  ui_story_5036_50360602_4_dialog_content = "オーディション会場に向かってください。",
  ui_story_5036_50360602_5_dialog_content = "グォォ！",
  ui_story_5036_50360602_6_dialog_content = "食らえ！",
  ui_story_5036_50360602_7_dialog_content = "どうやら、それどころではなさそうですね…？",
  ui_story_5036_50360602_8_dialog_content = "た、助けてくれ！",
  ui_story_5036_50360602_9_dialog_content = "暗鬼はもう倒したわよ。\nそんなに叫ぶことないでしょ？",
  ui_story_5036_50360602_10_dialog_content = "ふぅ…はぁ…ふぅ…",
  ui_story_5036_50360602_11_dialog_content = "また暗鬼と一緒に閉じ込められるのかと思ったら、\nそりゃ声も上げるさ！",
  ui_story_5036_50360602_12_dialog_content = "モジャの長い爪のおかげで、\nどうにかドアはこじ開けられたが…",
  ui_story_5036_50360602_13_dialog_content = "そうでなきゃ、叫ぶこともできなかっただろうさ。",
  ui_story_5036_50360602_14_dialog_content = "それはごめんなさい！\n命を危険にさらすつもりまではなかったの！",
  ui_story_5036_50360602_15_dialog_content = "あなたを閉じ込める前は、\n部屋に暗鬼なんていなかったの。ホントよ！",
  ui_story_5036_50360602_16_dialog_content = "…",
  ui_story_5036_50360602_17_dialog_content = "ゴルディさん、暗鬼は部屋の通風孔からはい出てきたようです。",
  ui_story_5036_50360602_18_dialog_content = "通風孔が封鎖エリアとつながっていたようで…",
  ui_story_5036_50360602_19_dialog_content = "通風孔？でも、格子がしっかりはまっていたはずよ？",
  ui_story_5036_50360602_20_dialog_content = "なるほど…分かったわ。",
  ui_story_5036_50360602_21_dialog_content = "あなた、通風孔から逃げようとしたでしょ？\nそれで暗鬼が気づいたんだわ！",
  ui_story_5036_50360602_22_dialog_content = "ふっ…ハハハ。",
  ui_story_5036_50360602_23_dialog_content = "あんな息苦しい部屋じゃ、\n換気でもしないといられないからな。",
  ui_story_5036_50360602_24_dialog_content = "どういうこと？\nなんでヴィックが閉じ込められてたの？",
  ui_story_5036_50360602_25_dialog_content = "PlayerName、ごめんなさい。",
  ui_story_5036_50360602_26_dialog_content = "あなたのお友達みたいだけど、\nここ数日盗みを働いていた泥棒オバケ、その人なの。",
  ui_story_5036_50360602_27_dialog_content = "ヴィックが？盗み？",
  ui_story_5036_50360602_28_option_content = "その可能性も無くはないね",
  ui_story_5036_50360602_29_dialog_content = "本を出してるぐらいの珍獣研究者ではあるけど、\nそれも何年も前のことだし…",
  ui_story_5036_50360602_30_dialog_content = "新しい本も書けず、収入もなく…\n最後の手段として盗みに走ったってこと？",
  ui_story_5036_50360602_31_dialog_content = "どんなに落ちぶれようと、お金は自分の力で稼ぐものよ。",
  ui_story_5036_50360602_32_dialog_content = "他人様のものを自分のものにするなんて、\n許されないわ！",
  ui_story_5036_50360602_33_option_content = "そんなはずないよ！？",
  ui_story_5036_50360602_34_dialog_content = "ヴィックは本も出したことのある、珍獣の研究者だよ。\n弟子も何人かいるんだ。",
  ui_story_5036_50360602_35_dialog_content = "どんなに落ちぶれたって、\n盗みなんて働くはずは…",
  ui_story_5036_50360602_36_dialog_content = "PlayerName、信じたくないのは分かるわ。",
  ui_story_5036_50360602_37_dialog_content = "正直言うと、私もよ。\nオーディションでは、すごい才能の持ち主だって思ったから…",
  ui_story_5036_50360602_38_dialog_content = "でも昨日、彼のポケットから、盗まれた食べ物や宝石が出てきたの。\n揺るがぬ証拠が有るわ。",
  ui_story_5036_50360602_39_dialog_content = "まあまあ、こっちの話も聞いてくれって…",
  ui_story_5036_50360602_40_dialog_content = "言い訳はもう聞き飽きたわ。",
  ui_story_5036_50360602_41_dialog_content = "あれだけ証拠がそろってたのに、\nまだ言い逃れする気？",
  ui_story_5036_50360602_42_dialog_content = "分かった分かった…\nここ数日の盗難事件、俺に責任があるってことは認めるよ。",
  ui_story_5036_50360602_43_dialog_content = "ヴィック！まさか本当に君が「泥棒オバケ」…！？",
  ui_story_5036_50360602_44_dialog_content = "だが…いいか、よく聞いてくれ。\n確かに、俺の責任ではあるが…",
  ui_story_5036_50360602_45_dialog_content = "この俺、つまり、かの偉大なる珍獣研究者、ヴィック様が、\n盗みを働いたことは一度だってない！",
  ui_story_5036_50360602_46_dialog_content = "最近騒がれてた「泥棒オバケ」の正体ってのは…\n俺の連れてる珍獣だ。",
  ui_story_5036_50360602_47_dialog_content = "ハイ…",
  ui_story_5036_50360602_48_dialog_content = "ホウ…",
  ui_story_5036_50360602_49_dialog_content = "ウキュウキュ、ウキュキュ～！",
  ui_story_5036_50360602_50_dialog_content = "肩に乗ってるモジャモジャした子、\nなんだか怒ってるみたいね？",
  ui_story_5036_50360602_51_dialog_content = "ああ、モジャは\n「自分は違う、あの2匹だ！」って言ってるんだ。",
  ui_story_5036_50360602_52_dialog_content = "ウキュッ！",
  ui_story_5036_50360602_53_dialog_content = "普段は、日替わりでいろんなエサを食わせてやってるんだが…",
  ui_story_5036_50360602_54_dialog_content = "今回は大急ぎで出てきちまったもんでね。\n1種類しかエサを持ってきてなかったんだ。",
  ui_story_5036_50360602_55_dialog_content = "で、エサに飽きた2匹が、\n何も言わずに、どこかに行っちまったんだが…",
  ui_story_5036_50360602_56_dialog_content = "泥棒が出たってウワサを聞いて、\nすぐに察しはついた。",
  ui_story_5036_50360602_57_dialog_content = "それで昨日の夜、苦労してやっと、\n2匹を捕まえたってワケさ。",
  ui_story_5036_50360602_58_dialog_content = "そこで私たちに捕まったってこと？",
  ui_story_5036_50360602_59_dialog_content = "そうさ。すごい偶然だよな、ハハハ…",
  ui_story_5036_50360602_60_dialog_content = "食べ物を盗んだのは分かったけど、\n宝石はどう説明するつもり？",
  ui_story_5036_50360602_61_dialog_content = "ひょっとしてアリガタモドキドリのせいかな？",
  ui_story_5036_50360602_62_dialog_content = "その通りだ。アリガタモドキドリは催眠ガスを出せるから、\n護身のために連れてきてたんだが…",
  ui_story_5036_50360602_63_dialog_content = "キラキラ光るお宝が大好きな珍獣だからな。\nちゃんと見てないと…",
  ui_story_5036_50360602_64_dialog_content = "「気を失わせて物を盗んだ」ってことになっちまうんだよ。",
  ui_story_5036_50360602_65_dialog_content = "ま、どっちも珍獣の習性だ。\n悪気はないんだよ。",
  ui_story_5036_50360602_66_dialog_content = "悪いのは、ちゃんと見てなかった俺ってことになるかな。",
  ui_story_5036_50360602_67_dialog_content = "宝石やらコインやらは、きちんと持ち主に返すよ。",
  ui_story_5036_50360602_68_dialog_content = "それでも許さないってなら、\n慰謝料を払ってもいい…",
  ui_story_5036_50360602_69_dialog_content = "ただ、珍獣たちに罰を与えるのだけは止めてくれ！\nコイツらには、本当に悪意があったワケじゃないんだ！",
  ui_story_5036_50360602_70_dialog_content = "ハイハイ、ハイ…",
  ui_story_5036_50360602_71_dialog_content = "…",
  ui_story_5036_50360602_72_dialog_content = "いいわ。ただし、約束したことは絶対に守ってね。",
  ui_story_5036_50360602_73_dialog_content = "持ち主に物を返して、謝罪して、弁償する…\nきちんとやってね。",
  ui_story_5036_50360602_74_dialog_content = "そうすりゃ、薄暗い部屋に閉じ込められないで済むのか？",
  ui_story_5036_50360602_75_dialog_content = "ああいうのは結構こたえるタチなんでね…",
  ui_story_5036_50360602_76_dialog_content = "約束してあげてもいいわ。",
  ui_story_5036_50360602_77_dialog_content = "その代わり、やることをやったら、\nすぐにイクストウルから出て行って。",
  ui_story_5036_50360602_78_dialog_content = "あん？そいつは厳しいな。\nアイドルになるって夢が、まだかなってないんだ！",
  ui_story_5036_50360602_79_dialog_content = "あんたも前に言ってただろ？\n俺の次の挑戦を楽しみにしてるって。",
  ui_story_5036_50360602_80_dialog_content = "確かにすばらしい素質はあるし、\n言ってることも立派だったと思うけど…",
  ui_story_5036_50360602_81_dialog_content = "なんとなく分かるの。\nあなた、ここに来た本当の理由はオーディションじゃない…そうでしょ？",
  ui_story_5036_50360602_82_dialog_content = "！！！",
  ui_story_5036_50360602_83_dialog_content = "…そこまでお見通しなら、\nこれ以上隠し続ける理由もないか。",
  ui_story_5036_50360602_84_dialog_content = "その通りだよ。\n俺はウロボロスっていう珍獣を探しに来た。",
  ui_story_5036_50360602_85_dialog_content = "ウロボロスってのは、\nある程度まで成長すると卵の状態に戻るんだ。",
  ui_story_5036_50360602_86_dialog_content = "そこからさらに時間が経つと、もう一度殻を破って出てくる。\nそういうサイクルを繰り返して、永遠に生き続けられるんだ。",
  ui_story_5036_50360602_87_dialog_content = "永遠に生き続ける動物なんているんだ！？",
  ui_story_5036_50360602_88_dialog_content = "ガキの頃から、自分が両親の実の子じゃないとは知ってたんだが…",
  ui_story_5036_50360602_89_dialog_content = "最近になって、俺の血筋はそいつと何かつながりがあるらしいって分かったんだ。\nだから、何としても見つけなきゃならないんだよ。",
  ui_story_5036_50360602_89X1_dialog_content = "ウロボロスを見つけりゃ、自分の出生が分かる。\nそうすりゃ、実の親も見つかるかもしれないだろ？",
  ui_story_5036_50360602_90_dialog_content = "ただ、ウロボロスに関する資料は少ししかなくてな。\n唯一分かってるのは…巨像の近くが好きらしいって事なんだ。",
  ui_story_5036_50360602_91_dialog_content = "ダメ師匠、また記憶を失くすまで飲んでたの！？\n早く起きてよ！",
  ui_story_5036_50360602_92_dialog_content = "アストラ大陸中の巨像に関係する遺跡、全部調べたよ！\nPlayerNameのソラヴァンも！",
  ui_story_5036_50360602_93_dialog_content = "でも、ウロボロスの手がかりなんて、まったくナシ！",
  ui_story_5036_50360602_94_dialog_content = "そもそもウロボロスなんて珍獣、本当にいるの！？",
  ui_story_5036_50360602_96_dialog_content = "またフィアをからかったんじゃないでしょーね！？",
  ui_story_5036_50360602_97_dialog_content = "フン！今度あたしにウロボロス探しなんて言い出したら、\nタダじゃおかないから！",
  ui_story_5036_50360602_98_dialog_content = "…アストラ大陸中の巨像の遺跡を調べたんだが、\nウロボロスの手がかりは見つからなかった。",
  ui_story_5036_50360602_99_dialog_content = "それで、今まさに飛んでる、\nこの巨像へ探しに来たってワケさ。",
  ui_story_5036_50360602_100_dialog_content = "それで、もうウロボロスの手がかりは見つかったの？",
  ui_story_5036_50360602_101_dialog_content = "いいや…だが、予感がするんだ。強烈な予感がな。",
  ui_story_5036_50360602_102_dialog_content = "ウロボロスはイクストウルの中にいる！",
  ui_story_5036_50360602_103_dialog_content = "だから、俺にここでウロボロスを探させてくれ！",
  ui_story_5036_50360602_104_dialog_content = "天涯孤独だったこの俺に、\n家族探しのチャンスをくれ！",
  ui_story_5036_50360602_105_dialog_content = "話は終わり？",
  ui_story_5036_50360602_106_dialog_content = "ああ、それ以上言うことは無い。",
  ui_story_5036_50360602_107_dialog_content = "ふふふ…あなたの話、\n影ノ街の三流映画より大それたストーリーね。",
  ui_story_5036_50360602_108_dialog_content = "視野が広がった気分だわ。\nお礼を言わなくちゃ。",
  ui_story_5036_50360602_109_dialog_content = "へへ、礼なんていいさ。\nこんなに話の通じる人だとは思わなかったぜ。",
  ui_story_5036_50360602_110_dialog_content = "最初からきちんと説明すりゃよかったな。",
  ui_story_5036_50360602_111_dialog_content = "じゃあ、話も終わったことだし…",
  ui_story_5036_50360602_112_dialog_content = "イクストウルから出て行ってくれる？",
  ui_story_5036_50360602_113_dialog_content = "え？",
  ui_story_5036_50360602_114_dialog_content = "出口までお送りします。",
  ui_story_5036_50360602_115_dialog_content = "おいおい、待ってくれ！なぁ、話はまだ終わってないぜ！\nまだ続きがあるんだ。",
  ui_story_5036_50360602_116_dialog_content = "さっきのは全部冗談だ！ハハハ！",
  ui_story_5036_50360602_116X1_dialog_content = "アドリブで雰囲気を盛り上げて、ファンを引き込むって言うのも、\nアイドルに必要な能力だろ？",
  ui_story_5036_50360602_116X2_dialog_content = "ゴルディさんに俺のそういう能力を見てもらって、\n本気でオーディションに参加したいってことを示そうとしただけさ。",
  ui_story_5036_50360602_117_dialog_content = "アドリブで雰囲気を盛り上げる？",
  ui_story_5036_50360602_118_dialog_content = "俺の話を聞いて、引き込まれただろ？",
  ui_story_5036_50360602_119_dialog_content = "…",
  ui_story_5036_50360602_120_dialog_content = "（確かにさっきから、\n彼のペースに完全に乗せられてる）",
  ui_story_5036_50360602_121_dialog_content = "（私には足りないものがあるってシェオルさんに言われたけど、\nそれって、こういうことなのかしら？）",
  ui_story_5036_50360602_124_dialog_content = "俺は本気でアイドルになりたいんだ。\nオーディション、受けさせてくれよぉ。",
  ui_story_5036_50360602_125_dialog_content = "俺を信じられないのは、まあ仕方ないとしても…\nPlayerNameも信じられないってのか？",
  ui_story_5036_50360602_126_dialog_content = "PlayerNameはコンサートの特別ゲストであり、審査員よ。\nもちろん信じてるわ。",
  ui_story_5036_50360602_127_dialog_content = "だったら、話は早い…",
  ui_story_5036_50360602_128_dialog_content = "PlayerName、俺の大事な弟子のフィアには、\n何度も助けられてるよな？",
  ui_story_5036_50360602_129_dialog_content = "うーん…そ、そうだね…？",
  ui_story_5036_50360602_130_dialog_content = "ってことは、俺は四捨五入すれば\nPlayerNameの恩人ってことになるだろ？",
  ui_story_5036_50360602_131_dialog_content = "お、恩人…？",
  ui_story_5036_50360602_132_dialog_content = "だから、審査員として、\n俺が怪しいヤツじゃないって、保証してくれないか？",
  ui_story_5036_50360602_133_dialog_content = "…",
  ui_story_5036_50360602_134_dialog_content = "な？ゴルディさん、\nPlayerNameが保証してくれるってさ。",
  ui_story_5036_50360602_135_dialog_content = "こいつの顔に免じて、俺を追い出さないでくれ。\nいいだろ？",
  ui_story_5036_50360602_136_dialog_content = "PlayerName、ホントに保証できる？",
  ui_story_5036_50360602_137_dialog_content = "ぼ…僕は…",
  ui_story_5036_50360602_138_dialog_content = "PlayerName、ちょっと耳を貸せ…",
  ui_story_5036_50360602_139_dialog_content = "まさか、本当に気付いてないワケじゃないだろうな？\n封鎖エリアにめちゃくちゃ強い光力があるだろ？",
  ui_story_5036_50360602_140_dialog_content = "え！？",
  ui_story_5036_50360602_141_dialog_content = "昨晩はただ泥棒を捕まえようとしていただけだったのですね…",
  ui_story_5036_50360602_142_dialog_content = "だとすると、写真が掲載されてしまったら、\n誤解を招くのでは…？",
  ui_story_5036_50360602_143_dialog_content = "<color=#e8d9bb>ブーン…</color>",
  ui_story_5036_50360602_144_dialog_content = "ブランディ！お前のスクープ写真とやら、\nいつになったら送って来るんだ！？",
  ui_story_5036_50360602_145_dialog_content = "編集長、その件はもう少し調査が必要です！",
  ui_story_5036_50360602_146_dialog_content = "調査？今さら何を調べるって言うんだ！？",
  ui_story_5036_50360602_147_dialog_content = "真相なんかどうだっていい！\n読者の興味を引くものがいい記事だ！",
  ui_story_5036_50360602_148_dialog_content = "ですが…",
  ui_story_5036_50360602_149_dialog_content = "写真が出ないと言うなら、\nもう連絡してこなくていい！",
  ui_story_5036_50360602_150_dialog_content = "編集長！編集長！？",
  ui_story_5036_50360701_1_dialog_content = "PlayerName、参加者へのコメントが\nどんどんプロらしくなってるわね～！",
  ui_story_5036_50360701_2_dialog_content = "もしかしたら、\n本物のアイドルプロデューサーになれるかも！",
  ui_story_5036_50360701_3_dialog_content = "ただ…",
  ui_story_5036_50360701_4_dialog_content = "ヴィックのことが気がかり？",
  ui_story_5036_50360701_5_dialog_content = "ええ、ごめんなさい。",
  ui_story_5036_50360701_6_dialog_content = "PlayerNameが保証してくれてはいるけど、\nやっぱり安心できなくて。",
  ui_story_5036_50360701_7_dialog_content = "すぐ近くのリハーサル室を使ってもらってるの。\nでも、ちゃんと練習してるのか不安だわ。",
  ui_story_5036_50360701_8_dialog_content = "他の人の練習を邪魔してないかしら…？",
  ui_story_5036_50360701_9_dialog_content = "ダメ、やっぱり確かめに行ってくるわ！",
  ui_story_5036_50360701_10_dialog_content = "それなら…僕が見て来るよ。",
  ui_story_5036_50360701_11_dialog_content = "僕が保証してるんだから、監督する責任があるし…",
  ui_story_5036_50360701_12_dialog_content = "ゴルディ、昨日からずっと働き詰めなんでしょ？\n少し休んだ方がいいよ。",
  ui_story_5036_50360701_13_dialog_content = "うん…そうね。歌詞も書かなきゃいけないし…\nPlayerNameがせっかく託してくれたメロディだもの、いい曲にしなくちゃ！",
  ui_story_5036_50360701_14_dialog_content = "じゃあ、彼のことはPlayerNameに任せたわ！",
  ui_story_5036_50360701_15_dialog_content = "ふわぁ～…ん？何か言ったか？",
  ui_story_5036_50360701_16_dialog_content = "今日の調子はどう？",
  ui_story_5036_50360701_17_dialog_content = "なかなかだよ。",
  ui_story_5036_50360701_18_dialog_content = "よく眠れたからな！",
  ui_story_5036_50360701_19_dialog_content = "リハーサルのことを聞いてるんだけど…",
  ui_story_5036_50360701_20_dialog_content = "まさか、今日は一日中寝てて、\nリハーサルしてなかったとか？",
  ui_story_5036_50360701_21_dialog_content = "そのことはもう説明しただろ？\nまあ、いいさ。もう1回話してやるよ。",
  ui_story_5036_50360701_22_dialog_content = "ウロボロスの話はウソじゃない。\nオーディションに出たいってのは口実だ。",
  ui_story_5036_50360701_23_dialog_content = "俺はイクストウルに乗り込んで、\nウロボロスを探したかっただけなんだよ。",
  ui_story_5036_50360701_24_dialog_content = "それは分かってるよ。でも、封鎖エリアからは、\n強い光力なんて感知できなかった。",
  ui_story_5036_50360701_25_dialog_content = "あそこには眠ってる暗鬼しかいないよ。",
  ui_story_5036_50360701_26_dialog_content = "ウロボロスは卵の中にいる間、\n強い光力は出せない。",
  ui_story_5036_50360701_27_dialog_content = "つまり、それならウロボロスがまだ殻の中にいるってことだ！",
  ui_story_5036_50360701_28_dialog_content = "どうして「ウロボロスがイクストウルの中にいる」\nって前提で考えてるの？",
  ui_story_5036_50360701_29_dialog_content = "直感さ――珍獣研究者としてのな。",
  ui_story_5036_50360701_30_dialog_content = "じゃあ、裏付けはないってことだね。",
  ui_story_5036_50360701_31_dialog_content = "最近、フィアの気持ちが分かってきた気がするよ…",
  ui_story_5036_50360701_32_dialog_content = "まだ俺を封鎖エリアに入れてもらえるよう、\n説得できてないのか？",
  ui_story_5036_50360701_33_dialog_content = "どうやって切り出せっていうの？",
  ui_story_5036_50360701_34_dialog_content = "ゴルディがわざわざ傭兵団に頼んで、厳重に警備させてるんだ。\n誰も中に入って騒ぎを起こさないように。",
  ui_story_5036_50360701_35_dialog_content = "仮にウロボロスが本当にイクストウルの中にいたとしても、\nコンサートが終わってから探すしかないんじゃない？",
  ui_story_5036_50360701_36_dialog_content = "お？ってことは、コンサートが終わるまで、\nイクストウルにいてもいいのか？",
  ui_story_5036_50360701_37_dialog_content = "オーディションに受かればね。",
  ui_story_5036_50360701_38_dialog_content = "合格できなかったらすぐにここを出ていかなきゃいけないんだ。\nオーディションのルールに書いてあったはずだよ。",
  ui_story_5036_50360701_39_dialog_content = "オーディションに受かるか…\nそれなら簡単だ。",
  ui_story_5036_50360701_40_dialog_content = "え？何か策があるの？",
  ui_story_5036_50360701_41_dialog_content = "モジャに宙返りさせるってのはどうだ？",
  ui_story_5036_50360701_42_dialog_content = "動物の芸？\nそういうのはサーカス団でやるものでしょ。",
  ui_story_5036_50360701_43_dialog_content = "これはアイドルのオーディションなのよ？",
  ui_story_5036_50360701_44_dialog_content = "参加するオーディションを間違えてるんじゃない？",
  ui_story_5036_50360701_45_dialog_content = "おや、もめごとでしょうか？",
  ui_story_5036_50360701_46_dialog_content = "もめごとにはニュースがつきもの…\nしっかり記録しておかなければ！",
  ui_story_5036_50360701_47_dialog_content = "おい、ジロジロ見るな！\nそうだ、お前のことだよ！",
  ui_story_5036_50360701_48_dialog_content = "ん？俺のことを知ってるのか？",
  ui_story_5036_50360701_49_dialog_content = "知ってるにきまってるさ。",
  ui_story_5036_50360701_50_dialog_content = "そりゃ珍しい！\nこんなところで俺の本の読者に会えるなんて――",
  ui_story_5036_50360701_51_dialog_content = "お前、最近捕まったっていう「泥棒オバケ」だろ？",
  ui_story_5036_50360701_52_dialog_content = "え？泥棒は捕まったんじゃなかったの？\nなんでまだオーディションにいるの？",
  ui_story_5036_50360701_53_dialog_content = "貴重な参加枠がもったいないわ。",
  ui_story_5036_50360701_54_dialog_content = "よく聞け、泥棒。\nどんな汚い手を使ったか知らないが…",
  ui_story_5036_50360701_55_dialog_content = "俺たちのステージや夢を汚すようなまねは、\nここにいる誰一人として許さないからな！",
  ui_story_5036_50360701_56_dialog_content = "まじめにオーディションを受ける気がないなら、\nさっさと出ていけ！",
  ui_story_5036_50360701_57_dialog_content = "まあ、まあ、そう熱くなるなって…",
  ui_story_5036_50360701_58_dialog_content = "その件は誤解だ。\n俺は本気でオーディションを受けに来てるんだ。",
  ui_story_5036_50360701_59_dialog_content = "それだけじゃないぜ。\n俺はオーディションに受かって、本番のステージに立つつもりだ。",
  ui_story_5036_50360701_60_dialog_content = "サーカス団のまね事で？",
  ui_story_5036_50360701_61_dialog_content = "おいおい、さっきのはただの冗談だよ。",
  ui_story_5036_50360701_62_dialog_content = "何のパフォーマンスも準備しないで、\nエントリーなんてするわけないだろ？",
  ui_story_5036_50360701_63_dialog_content = "だったら、見せてみろよ。\nいったい何をやるつもりだ？",
  ui_story_5036_50360701_64_dialog_content = "そうだそうだ！",
  ui_story_5036_50360701_65_dialog_content = "見せてみろ！",
  ui_story_5036_50360701_66_dialog_content = "それなら…",
  ui_story_5036_50360701_67_dialog_content = "どうした？何をぐずぐずしてる？",
  ui_story_5036_50360701_68_dialog_content = "さっさと始めてみろ！",
  ui_story_5036_50360701_69_dialog_content = "そう焦るなって。\nやりゃあいいんだろ？",
  ui_story_5036_50360701_70_dialog_content = "オッホン…それではご覧あれ――\nドラゴライオンのダンスだ！",
  ui_story_5036_50360701_71_dialog_content = "ドラゴライオンの求愛行動を参考にしたダンスだ。\nよ～く見とけよ～。",
  ui_story_5036_50360701_72_dialog_content = "それッ！",
  ui_story_5036_50360701_73_dialog_content = "フンッ！",
  ui_story_5036_50360701_74_dialog_content = "なに…？これが…ダンス？",
  ui_story_5036_50360701_75_dialog_content = "骨折が治ったばかりで、\nまだ歩き慣れないヤツみたいだ…",
  ui_story_5036_50360701_76_dialog_content = "次は宙返りだ、よく見とけ！",
  ui_story_5036_50360701_77_dialog_content = "それっ！",
  ui_story_5036_50360701_78_dialog_content = "<color=#e8d9bb>ガン！</color>",
  ui_story_5036_50360701_79_dialog_content = "アイテテテテテテ！",
  ui_story_5036_50360701_80_dialog_content = "アハハハハ！",
  ui_story_5036_50360701_81_dialog_content = "ずいぶんハデに腰を打ったわ？",
  ui_story_5036_50360701_82_dialog_content = "よくそんなヘマができるな。\nある意味、天才だよ！",
  ui_story_5036_50360701_83_dialog_content = "珍獣研究者、アイドルに転向。\nイクストウルにて他のアイドルたちから集中砲火…",
  ui_story_5036_50360701_84_dialog_content = "編集長が満足する記事になるでしょうか…？",
  ui_story_5036_50360701_85_dialog_content = "ヴィック、大丈夫？",
  ui_story_5036_50360701_86_dialog_content = "まったく…年寄りに優しいのはPlayerNameだけだ。",
  ui_story_5036_50360701_87_dialog_content = "尻を何かにぶつけたみたいでな…\n肩を貸してもらえるか？",
  ui_story_5036_50360701_88_dialog_content = "分かったよ…",
  ui_story_5036_50360701_89_dialog_content = "あれ、まさか、ぶつけたのって…通風孔！？",
  ui_story_5036_50360701_90_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_5036_50360701_91_dialog_content = "おや、何の音でしょうか？",
  ui_story_5036_50360701_92_dialog_content = "ハハハ…また通風孔をやっちまったか？",
  ui_story_5036_50360701_93_dialog_content = "グォォ！！！",
  ui_story_5036_50360701_94_dialog_content = "ここの通風孔にも暗鬼が！？",
  ui_story_5036_50360701_95_dialog_content = "早く逃げろ――！",
  ui_story_5036_50360702_1_dialog_content = "グォォ！！！",
  ui_story_5036_50360702_2_dialog_content = "咲き誇れ！",
  ui_story_5036_50360702_3_dialog_content = "ゴルディさんの戦う姿はなんとも…\nう～む、やはり早急にウワサの真相を突き止める必要がありそうです。",
  ui_story_5036_50360702_4_dialog_content = "おっと、いけません！\n撮影を忘れていました…",
  ui_story_5036_50360702_5_dialog_content = "みんな、ケガはない？",
  ui_story_5036_50360702_6_dialog_content = "大丈夫ですが、何人かはずいぶん怯えてます。",
  ui_story_5036_50360702_7_dialog_content = "ゴルディさんのおかげで助かりました。\nありがとうございます！",
  ui_story_5036_50360702_8_dialog_content = "それにしても、ポスターと同じで…\nいや、ポスターで見るよりずっときれいだ…！",
  ui_story_5036_50360702_9_dialog_content = "え？ゴルディさん！？",
  ui_story_5036_50360702_10_dialog_content = "私、デビュー当時からの「ディディ推し」なんです！",
  ui_story_5036_50360702_11_dialog_content = "ゴルディさん、サインいただけませんか！？",
  ui_story_5036_50360702_12_dialog_content = "ゴルディさん！ゴルディさん！",
  ui_story_5036_50360702_13_dialog_content = "ごめんなさい。あとで通風孔はきちんと塞いでもらうわ。\n食事も届けてもらうから。",
  ui_story_5036_50360702_14_dialog_content = "元はと言えば、あの泥棒が悪いんです。\nあいつが通風孔を壊さなければ、こんな騒ぎになっていません！",
  ui_story_5036_50360702_15_dialog_content = "おまけに、ダンスも下手なのよ！",
  ui_story_5036_50360702_16_dialog_content = "出ていけ！出ていけ！",
  ui_story_5036_50360702_17_dialog_content = "そう言われても…",
  ui_story_5036_50360702_18_dialog_content = "俺は本気でオーディションを受ける気なんだ。",
  ui_story_5036_50360702_19_dialog_content = "へぇ？",
  ui_story_5036_50360702_20_dialog_content = "最後まで続ける覚悟があるの？",
  ui_story_5036_50360702_21_dialog_content = "ウロボロスのために…",
  ui_story_5036_50360702_22_dialog_content = "必ずだ！",
  ui_story_5036_50360702_23_dialog_content = "何がなんでもやってみせるさ！",
  ui_story_5036_50360702_24_dialog_content = "（理由も根拠もない、自信と決意…懐かしいわ）",
  ui_story_5036_50360702_25_dialog_content = "（まだ何の訓練も受けてなかった頃、私も自信満々に\nもっと大きなステージに立ってみせるなんて、言ったことがあったっけ…）",
  ui_story_5036_50360702_26_dialog_content = "（気のせいかしら？）",
  ui_story_5036_50360702_27_dialog_content = "（私…ついつい、この人に昔の自分を重ねてしまっている？）",
  ui_story_5036_50360702_28_dialog_content = "（「信じる」ことの力を、\n私もこの人もかたくなに信じ続けてるから？）",
  ui_story_5036_50360702_29_dialog_content = "必ず最後まで残ってみせる！",
  ui_story_5036_50360702_30_dialog_content = "…",
  ui_story_5036_50360702_31_dialog_content = "分かったわ…最後にもう1度だけ、信じてあげる。",
  ui_story_5036_50360702_32_dialog_content = "出ていけ！出ていけ！",
  ui_story_5036_50360702_33_dialog_content = "みんな、聞いて！",
  ui_story_5036_50360702_34_dialog_content = "彼が泥棒だって言うのは、誤解だったの。",
  ui_story_5036_50360702_35_dialog_content = "今は事件も解決してるし、失くなったものは全部持ち主の元に戻って、\n彼が補償もするって約束してくれてるわ。",
  ui_story_5036_50360702_36_dialog_content = "だから、オーディションには\n引き続き参加してもらってるの。",
  ui_story_5036_50360702_37_dialog_content = "でも、彼のせいで騒ぎが起こったのも事実よ。",
  ui_story_5036_50360702_38_dialog_content = "だから、最後にもう1度だけ、\nチャンスをあげてくれない？",
  ui_story_5036_50360702_39_dialog_content = "オーディションに受からなかった時は、\nその場でここから出て行ってもらうから。",
  ui_story_5036_50360702_40_dialog_content = "あと2日しかないんですよ？\nあれじゃどんなに訓練したって無理だ。",
  ui_story_5036_50360702_41_dialog_content = "でも、ゴルディさんがそういうなら…",
  ui_story_5036_50360702_42_dialog_content = "ゴルディさんの判断を信じます！",
  ui_story_5036_50360702_43_dialog_content = "フン、こいつのダンスでもオーディションに受かるなら…",
  ui_story_5036_50360702_44_dialog_content = "オーディションをする意味が無いと思うけどな。",
  ui_story_5036_50360702_45_dialog_content = "安心して！みんなの信頼を裏切ったりはしないわ！",
  ui_story_5036_50360702_46_dialog_content = "ゴルディ！ゴルディ！",
  ui_story_5036_50360702_47_dialog_content = "オホン…ええと、ありがとな、ゴルディさん。",
  ui_story_5036_50360702_48_dialog_content = "何をぼーっとしてるの？",
  ui_story_5036_50360702_49_dialog_content = "え？",
  ui_story_5036_50360702_50_dialog_content = "場所を探して、早く練習を始めて。",
  ui_story_5036_50360702_51_dialog_content = "だが、今日はもう遅いし…",
  ui_story_5036_50360702_52_dialog_content = "言ったでしょう？\nあなたの声は素晴らしいし、見た目も十分。",
  ui_story_5036_50360702_53_dialog_content = "それだけでもう、大勢の参加者よりずっと有利なの。",
  ui_story_5036_50360702_54_dialog_content = "でも、本気で最後まで残りたいなら…",
  ui_story_5036_50360702_55_dialog_content = "私の言った通りにすることね。",
  ui_story_5036_50360801_1_dialog_content = "<color=#e8d9bb>コンサート開催まで、あと3日</color>",
  ui_story_5036_50360801_2_dialog_content = "♪ア～アアア～…",
  ui_story_5036_50360801_3_dialog_content = "ストップストップ！",
  ui_story_5036_50360801_4_dialog_content = "その歌をステージでやるつもり？",
  ui_story_5036_50360801_5_dialog_content = "フフフ、言っただろ。\nちゃんと何をやるかは考えてあるって。",
  ui_story_5036_50360801_6_dialog_content = "そもそも歌って言っていいのかな…？",
  ui_story_5036_50360801_7_dialog_content = "このメロディはな、わざわざ北境の山奥の森まで足を運んで、\nようやく出会えたオーロラヨナキドリから教えてもらったんだ。",
  ui_story_5036_50360801_8_dialog_content = "そこに珍獣研究者である俺が精魂込めて書き上げた、\nワイルドな歌詞を乗せれば…",
  ui_story_5036_50360801_9_dialog_content = "どうやったっていい歌になるってもんさ。",
  ui_story_5036_50360801_10_dialog_content = "オッホン…",
  ui_story_5036_50360801_11_dialog_content = "曲はまぁ、大して問題ないわ。\nただ、歌唱力は伸ばさないとね。",
  ui_story_5036_50360801_12_dialog_content = "ゴルディ…ずいぶん優しい評価だね…",
  ui_story_5036_50360801_13_dialog_content = "確かに優しすぎますね。",
  ui_story_5036_50360801_14_dialog_content = "PlayerNameはともかく、\n新聞記者まで俺を笑いに来たのか？",
  ui_story_5036_50360801_15_dialog_content = "わ、私は事実を述べたまでのことです。",
  ui_story_5036_50360801_16_dialog_content = "ブランディは中立の目線を保てる、\n良心あるプロよ。",
  ui_story_5036_50360801_17_dialog_content = "あなたの歌声がブランディの心に響いてないのなら、\n問題は自分にあると考えた方がいいわね。",
  ui_story_5036_50360801_18_dialog_content = "そうか…？なるほど、分かったぞ。お前、耳をケガしてるんだな？\nそれで俺の歌声のすばらしさが分からないんだろ？",
  ui_story_5036_50360801_19_dialog_content = "そういうことじゃないわ！",
  ui_story_5036_50360801_20_dialog_content = "はぁ、要するに…",
  ui_story_5036_50360801_21_dialog_content = "歌を上手に歌うには、\nまずは正しい呼吸法を知らなきゃいけないの。",
  ui_story_5036_50360801_22_dialog_content = "呼吸のしかたなんて、改めて覚える必要あるのか？",
  ui_story_5036_50360801_23_dialog_content = "オーディションに受かりたいなら、\n言う通りにしなさい。",
  ui_story_5036_50360801_24_dialog_content = "は…はい先生！？",
  ui_story_5036_50360801_25_dialog_content = "息を吸う時はお腹をふくらませて、\n吐く時はお腹をへこませる――",
  ui_story_5036_50360801_26_dialog_content = "腹式呼吸よ。",
  ui_story_5036_50360801_27_dialog_content = "まずは10分間やってみて。",
  ui_story_5036_50360801_28_dialog_content = "寝てる時のモジャみたいだな…",
  ui_story_5036_50360801_29_dialog_content = "すぅ～…はぁ～…",
  ui_story_5036_50360801_30_dialog_content = "その調子よ。もう少し息を長く続けて。",
  ui_story_5036_50360801_31_dialog_content = "すぅ――はぁ――",
  ui_story_5036_50360801_32_dialog_content = "いい感じだわ、そのまま。",
  ui_story_5036_50360801_33_dialog_content = "すぅ…はぁ…",
  ui_story_5036_50360801_34_dialog_content = "すぅ…すぅ…",
  ui_story_5036_50360801_35_dialog_content = "…ヴィック、寝ちゃってない？",
  ui_story_5036_50360801_36_dialog_content = "すぅ…すぅ…すぅ…",
  ui_story_5036_50360801_37_dialog_content = "起きなさい！",
  ui_story_5036_50360801_38_dialog_content = "なんだフィア、そう怒るなって！…ん？",
  ui_story_5036_50360801_39_dialog_content = "あ、ゴルディさん…\nああいや、ゴルディ先生！",
  ui_story_5036_50360801_40_dialog_content = "呼吸法の練習をしてるのよ、\n寝てる場合じゃないわ。",
  ui_story_5036_50360801_41_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_5036_50360801_42_dialog_content = "呼吸法の後は、発声練習よ。",
  ui_story_5036_50360801_43_dialog_content = "ヴィック、あなたの声の質は素晴らしいわ。\nただし、覚えておいて――",
  ui_story_5036_50360801_44_dialog_content = "きちんとした発声法を身に付けずに、\nノドだけで歌ったら、一生治らない傷になることもあるの。",
  ui_story_5036_50360801_45_dialog_content = "そうは言うが、どうすりゃ、\nその「きちんとした発声方法」ってのを身に付けられるんだ？",
  ui_story_5036_50360801_46_dialog_content = "いい質問ね。",
  ui_story_5036_50360801_47_dialog_content = "私のヒミツの練習法を特別に伝授してあげるわ！",
  ui_story_5036_50360801_48_dialog_content = "よ～く見てて！\nまずは唇をとがらせて、それから…",
  ui_story_5036_50360801_49_dialog_content = "ブルブルブルブル…",
  ui_story_5036_50360801_50_dialog_content = "ブルブルブルブル…",
  ui_story_5036_50360801_51_dialog_content = "あら？上手だわ、ずいぶん覚えが速いのね！",
  ui_story_5036_50360801_52_dialog_content = "ハハハ、これぐらい難しくもなんともないさ！",
  ui_story_5036_50360801_53_dialog_content = "野外調査で発情期のドロサイを引きつける時に、\nよくこういう音を出してるからな。",
  ui_story_5036_50360801_54_dialog_content = "ブルブルブルブル…",
  ui_story_5036_50360801_55_dialog_content = "うまくいけば、1度に10頭以上集まったりするんだ。",
  ui_story_5036_50360801_56_dialog_content = "そ、そうなの？",
  ui_story_5036_50360801_57_dialog_content = "よかった、今は空の上で…",
  ui_story_5036_50360801_58_dialog_content = "とにかく、この練習を続ければ、\n声の通りがよくなって、息も続くようになるの。",
  ui_story_5036_50360801_59_dialog_content = "オーディションの最終日まで2日もないけど…",
  ui_story_5036_50360801_60_dialog_content = "1日しっかり練習すれば、呼吸法と発声法は\n身体に覚え込ませることができるわ。それで歌がぐっとうまくなるはずよ。",
  ui_story_5036_50360801_61_dialog_content = "ドロサイの鳴きマネをするだけで、歌がうまくなるのか？",
  ui_story_5036_50360801_62_dialog_content = "だったら、もっといろんな珍獣の鳴きマネをすれば、\n効果が上がるかもな！",
  ui_story_5036_50360801_63_dialog_content = "ハイ、ハイハイ！",
  ui_story_5036_50360801_64_dialog_content = "ハイ？",
  ui_story_5036_50360801_65_dialog_content = "ホゥ、ホゥホゥホゥ！",
  ui_story_5036_50360801_66_dialog_content = "ホゥ？",
  ui_story_5036_50360801_67_dialog_content = "ウキュ～ウキュキュ～！",
  ui_story_5036_50360801_68_dialog_content = "ウキュ？",
  ui_story_5036_50360801_69_dialog_content = "はいはい、それぐらいにして…",
  ui_story_5036_50360801_70_dialog_content = "ドロサイの鳴きマネだけでいいわ。",
  ui_story_5036_50360801_71_dialog_content = "ああ？なんだ、考えて損したな。",
  ui_story_5036_50360801_72_dialog_content = "それより、もっと努力が必要なものがあるわ――ダンスよ。",
  ui_story_5036_50360801_73_dialog_content = "歌も大事だけど、\nダンスはパフォーマンス全体の魅力につながるの。",
  ui_story_5036_50360801_74_dialog_content = "だから、あなたの曲に振付けをするわ。",
  ui_story_5036_50360801_75_dialog_content = "その前に、身体の柔らかさがどんなものか、確かめさせて。",
  ui_story_5036_50360801_76_dialog_content = "私が簡単な動きをして見せるから、\nがんばってマネしてね。",
  ui_story_5036_50360801_77_dialog_content = "PlayerName、伴奏をお願い！",
  ui_story_5036_50360801_78_dialog_content = "分かった、任せて！",
  ui_story_5036_50360801_79_dialog_content = "音楽が始まったわ。\nリズムに乗って！",
  ui_story_5036_50360801_80_dialog_content = "1、2、ステップ、前！",
  ui_story_5036_50360801_81_dialog_content = "左、右！",
  ui_story_5036_50360801_82_dialog_content = "左…右…うーん…\nなんだか左右が分からなくなってきたな…？",
  ui_story_5036_50360801_83_dialog_content = "手を上げて！宙で円を描く！",
  ui_story_5036_50360801_84_dialog_content = "左手を前に、はい、戻して！",
  ui_story_5036_50360801_85_dialog_content = "右手を前に、はい、戻して！",
  ui_story_5036_50360801_86_dialog_content = "左足…いや、右手だったか！？",
  ui_story_5036_50360801_87_dialog_content = "ステップを止めちゃダメ！",
  ui_story_5036_50360801_88_dialog_content = "なんと、見間違いではありませんよね？",
  ui_story_5036_50360801_89_dialog_content = "あのゴルディさんが…",
  ui_story_5036_50360801_90_dialog_content = "影ノ街で大人気のゴルディさんが今、\n私の目の前でダンスを踊っている？",
  ui_story_5036_50360801_91_dialog_content = "古株の「ディディ推し」だって、\nこんな体験はそうそうできませんよ！",
  ui_story_5036_50360801_X91_dialog_content = "おっと、落ち着かなければ…\nあの件の真相はまだ突き止められていないのです…",
  ui_story_5036_50360801_92_dialog_content = "それにしても…ヴィックさんとは対照的に、\nゴルディさんの動きのしなやかさはひときわ美しいですね！",
  ui_story_5036_50360801_93_dialog_content = "急いで記録しなければ！",
  ui_story_5036_50360801_94_dialog_content = "腕を大きく広げて、\n夢をつかんで、強く胸に抱きしめる！",
  ui_story_5036_50360801_95_dialog_content = "1、2、ステップ、ジャンプ！",
  ui_story_5036_50360801_96_dialog_content = "左手を振って、右手を振って！",
  ui_story_5036_50360801_97_dialog_content = "はぁ…はぁ…ま、まだ終わらないのか…？",
  ui_story_5036_50360801_98_dialog_content = "最後に両手を上げて～…",
  ui_story_5036_50360801_99_dialog_content = "くるっと一回転！",
  ui_story_5036_50360801_100_dialog_content = "くるっと…",
  ui_story_5036_50360801_101_dialog_content = "<color=#e8d9bb>ドスン！！！</color>",
  ui_story_5036_50360801_102_dialog_content = "アイタッ！イテテテテ…",
  ui_story_5036_50360801_103_dialog_content = "転ぶの、今日はこれで何度目？",
  ui_story_5036_50360801_104_dialog_content = "ハハハ、いつもの事だ、平気さ。",
  ui_story_5036_50360801_105_dialog_content = "信じられない…あなたの身体の動き、\n歩き始めたばかりの赤ちゃんよりフラフラだわ。",
  ui_story_5036_50360801_106_dialog_content = "しかも、たったこれぐらいの運動で息が上がるなんて、\nいつもはまったく身体を動かしてないの？",
  ui_story_5036_50360801_107_dialog_content = "睡眠って身体を動かすことに入るか？",
  ui_story_5036_50360801_108_dialog_content = "困ったわ…こればっかりは1日や2日で\nどうにかなるものじゃないし…",
  ui_story_5036_50360801_109_dialog_content = "<color=#e8d9bb>さらにしばらくして</color>",
  ui_story_5036_50360801_110_dialog_content = "今のステップはどう？覚えられる？",
  ui_story_5036_50360801_111_dialog_content = "行ったり来たりしながら手を振るだけだろ？\nハハハ、覚えたさ！",
  ui_story_5036_50360801_112_dialog_content = "最低限のシンプルな振りつけだけど…",
  ui_story_5036_50360801_113_dialog_content = "歌う時は全身全霊、曲の世界にひたって、\nその気持ちをダンスに込めるのよ。",
  ui_story_5036_50360801_114_dialog_content = "気持ちをダンスに？\nよく分からないな…",
  ui_story_5036_50360801_115_dialog_content = "ヴィック、アイドルに一番必要な能力ってなんだと思う？",
  ui_story_5036_50360801_116_dialog_content = "歌か…いや、ダンスか？",
  ui_story_5036_50360801_117_dialog_content = "正解でも不正解でもあるわ。",
  ui_story_5036_50360801_118_dialog_content = "アイドルに歌とダンスは欠かせない。\nそれは間違っていないわ。",
  ui_story_5036_50360801_119_dialog_content = "でも、歌とダンスは\n大切なことを伝えるための手段にすぎないの。",
  ui_story_5036_50360801_120_dialog_content = "アイドルにとって一番大切なことは、\n何事にも屈せず、あきらめない信念と情熱よ。",
  ui_story_5036_50360801_121_dialog_content = "その信念と情熱を、\n歌とダンスでみんなに届けるの。",
  ui_story_5036_50360801_122_dialog_content = "へえ…",
  ui_story_5036_50360801_123_dialog_content = "<size=35>そこについては、\nもう合格と言ってもいいかもしれないけどね…</size>",
  ui_story_5036_50360801_124_dialog_content = "ん？何か言ったか先生？",
  ui_story_5036_50360801_125_dialog_content = "オホン…まずは自分を感動させられなければ、\n他の人を感動させることなんてできないわ。",
  ui_story_5036_50360801_126_dialog_content = "教えられることはもう全部教えたから、\nあとはあなたの努力次第よ。",
  ui_story_5036_50360801_127_dialog_content = "オーディションでは、\nひいきしないからね～。",
  ui_story_5036_50360801_128_dialog_content = "正確に言えば、残り時間は1日半…",
  ui_story_5036_50360801_129_dialog_content = "あと1日半だけ耐えれば…\nウロボロスを探せるってことだ！",
  ui_story_5036_50360801_130_dialog_content = "ゴルディ！",
  ui_story_5036_50360801_131_dialog_content = "わざわざありがとう。\n結局、君にいろいろ面倒をかけちゃったね…",
  ui_story_5036_50360801_132_dialog_content = "いいのよ。参加者にアドバイスするのも仕事のうちだから。\n気にしないで！",
  ui_story_5036_50360801_133_dialog_content = "ヴィックがいろいろ迷惑をかけちゃったし、\nもう愛想を尽かされちゃったんじゃないかって、本当は心配してたんだ。",
  ui_story_5036_50360801_134_dialog_content = "正直言うと、確かに手が焼けるわね～。",
  ui_story_5036_50360801_135_dialog_content = "でも、彼にはすばらしい素質があるわ。",
  ui_story_5036_50360801_136_dialog_content = "もしホントにアイドルになるなら、\n私にとってもいい刺激になるはず。",
  ui_story_5036_50360801_137_dialog_content = "ん？俺が褒められてるのか？",
  ui_story_5036_50360801_138_dialog_content = "そういうことは俺にも聞かせてもらいたいな。",
  ui_story_5036_50360801_139_dialog_content = "そうだ、大事なことを忘れてたわ。",
  ui_story_5036_50360801_140_dialog_content = "アイドルはね、\n元気いっぱいであることが一番の基本なの。",
  ui_story_5036_50360801_141_dialog_content = "で、私の元気になるヒケツがあるんだけど、知りたい？",
  ui_story_5036_50360801_142_dialog_content = "ああ？\n…どこからそんなカゴいっぱいの暗鬼を…？",
  ui_story_5036_50360801_143_dialog_content = "うふふ…もちろん、捕まえてきたの。",
  ui_story_5036_50360801_144_dialog_content = "グォォ！",
  ui_story_5036_50360801_145_dialog_content = "元気のヒケツって…まさか暗鬼と戦う気か？",
  ui_story_5036_50360801_146_dialog_content = "珍獣は使っちゃダメよ？",
  ui_story_5036_50360801_147_dialog_content = "自分の力で倒してね～。",
  ui_story_5036_50360801_148_dialog_content = "なに！？",
  ui_story_5036_50360801_149_dialog_content = "グォォ！！！",
  ui_story_5036_50360801_150_dialog_content = "うわぁ、来るな！",
  ui_story_5036_50360801_151_dialog_content = "やっぱりあなた、\n自分で戦えるんじゃない！",
  ui_story_5036_50360801_152_dialog_content = "疲れることは嫌いなんでね。",
  ui_story_5036_50360801_153_dialog_content = "動きは止めちゃダメ！",
  ui_story_5036_50360801_154_dialog_content = "戦いながら、歌って踊るの！",
  ui_story_5036_50360801_155_dialog_content = "ああ？？？",
  ui_story_5036_50360801_156_dialog_content = "あんた…悪魔か！？",
  ui_story_5036_50360801_157_dialog_content = "グォォ――！",
  ui_story_5036_50360802_1_dialog_content = "<color=#e8d9bb>コンサート開催まで、あと2日</color>",
  ui_story_5036_50360802_2_dialog_content = "会場の皆、手を上げてくれ！\nさあ、一緒に…",
  ui_story_5036_50360802_3_dialog_content = "もう1回だ！",
  ui_story_5036_50360802_4_dialog_content = "あ、あの人…本当にあの時の泥棒？",
  ui_story_5036_50360802_5_dialog_content = "そのはずだが、まるで違うような…",
  ui_story_5036_50360802_6_dialog_content = "♪みんな元気な春がやってきた♪",
  ui_story_5036_50360802_7_dialog_content = "♪動物たちも家からぴょこん♪",
  ui_story_5036_50360802_8_dialog_content = "♪森も荒れ野もあちこちに♪",
  ui_story_5036_50360802_9_dialog_content = "♪きれいな歌声あふれてる♪",
  ui_story_5036_50360802_10_dialog_content = "歌詞だって大したことないのに…",
  ui_story_5036_50360802_11_dialog_content = "身体が勝手に動いちまう…",
  ui_story_5036_50360802_12_dialog_content = "♪さあ、見てごらん。あれは誰？♪",
  ui_story_5036_50360802_13_dialog_content = "♪毛むくじゃらのビッカーだ。\n「ハイハイ」！元気に歌ってる♪",
  ui_story_5036_50360802_14_dialog_content = "ハイハイハイ～！",
  ui_story_5036_50360802_15_dialog_content = "ハイハイハイ！",
  ui_story_5036_50360802_16_dialog_content = "♪さあ、見てごらん。あれは誰？♪",
  ui_story_5036_50360802_17_dialog_content = "♪角を曲がれば、アリガタモドキドリ！\nポケットの中身、気を付けて♪",
  ui_story_5036_50360802_18_dialog_content = "ホゥホゥホゥ～。",
  ui_story_5036_50360802_19_dialog_content = "ホゥホゥホゥ！",
  ui_story_5036_50360802_20_dialog_content = "…ゴルディ、ヴィックの\nそっくりさんでも見つけてきたの？",
  ui_story_5036_50360802_21_dialog_content = "えっ？",
  ui_story_5036_50360802_22_dialog_content = "だって…たった1日半で、\nこんなに変わるの！？",
  ui_story_5036_50360802_23_dialog_content = "目の前にいるのが本当にあのヴィックだなんて、\n信じられないよ…",
  ui_story_5036_50360802_24_dialog_content = "まるで別人じゃない！",
  ui_story_5036_50360802_25_dialog_content = "言ったでしょ。あの人にはアイドルの才能があるって。",
  ui_story_5036_50360802_26_dialog_content = "彼はダイヤモンドの原石よ。\n少し磨いてあげれば、まぶしい光を放つようになるわ。",
  ui_story_5036_50360802_27_dialog_content = "う～ん、いい仕事してるね～！",
  ui_story_5036_50360802_28_dialog_content = "これが育成ゲームの面白みってやつだよね～。",
  ui_story_5036_50360802_29_dialog_content = "歌唱力、ダンス、容貌、スタイル、会話力、知能――\n6項目全て、ほぼ満点です。",
  ui_story_5036_50360802_30_dialog_content = "オーディションもここにきてようやく、\n6項目全能選手が現れましたね！",
  ui_story_5036_50360802_31_dialog_content = "このような演芸もどきに、\nこの私が見入るだと…！？",
  ui_story_5036_50360802_32_dialog_content = "…光の神よ、どうかお許しください…",
  ui_story_5036_50360802_33_dialog_content = "確かに、大きく進歩している。",
  ui_story_5036_50360802_34_dialog_content = "♪ブルブルブルブル…♪",
  ui_story_5036_50360802_35_dialog_content = "♪ウロボロスの卵を知ってるかい？♪",
  ui_story_5036_50360802_36_dialog_content = "♪ブルブルブルブル…♪",
  ui_story_5036_50360802_37_dialog_content = "♪見つけてみせるさ～絶対に～♪",
  ui_story_5036_50360802_38_dialog_content = "へへ、俺のパフォーマンスは以上だ。\nありがとう！",
  ui_story_5036_50360802_39_dialog_content = "ヴィック！ヴィック！ヴィック！ヴィック！",
  ui_story_5036_50360802_40_dialog_content = "ヴィックさんのパフォーマンスに会場全体が沸き上がっております！",
  ui_story_5036_50360802_41_dialog_content = "最高のパフォーマンスをありがとうございました！",
  ui_story_5036_50360802_42_dialog_content = "ですが、厳しい審査員の皆さんの評価はまだ分かりません！",
  ui_story_5036_50360802_43_dialog_content = "まずはゴルディさんにお聞きしましょう！",
  ui_story_5036_50360802_44_dialog_content = "何も言うことはないわ。",
  ui_story_5036_50360802_45_dialog_content = "ああ？おとといの晩から\n寝ずに練習してたのに、不合格か？",
  ui_story_5036_50360802_46_dialog_content = "だったら、寝てりゃあよかったな…",
  ui_story_5036_50360802_47_dialog_content = "文句もつけようもないほど、\nすばらしかったと言いたいの。",
  ui_story_5036_50360802_48_dialog_content = "投票結果が答えてくれるはずよ。",
  ui_story_5036_50360802_49_dialog_content = "それでは、投票結果が出たようです…",
  ui_story_5036_50360802_50_dialog_content = "ヴィックさんは出場権を獲得できるのでしょうか？",
  ui_story_5036_50360802_51_dialog_content = "結果は…",
  ui_story_5036_50360802_52_dialog_content = "結果は？",
  ui_story_5036_50360802_53_dialog_content = "<size=45>6票、満点合格です！</size>",
  ui_story_5036_50360802_54_dialog_content = "へぇ～？あの新人君、オーディションに受かったって～。\n誰かさんもプレッシャーを感じてるんじゃな～い？",
  ui_story_5036_50360802_55_dialog_content = "バーバラが元気になる歌、\n歌ってあげよっかな～？",
  ui_story_5036_50360802_56_dialog_content = "私の目の前をウロチョロするな！\n砂糖菓子みたいな歌なんかウンザリだぜ！",
  ui_story_5036_50360802_57_dialog_content = "でも～、レジーナちゃんが落ちちゃったら、\nバーバラさみしいな～。",
  ui_story_5036_50360802_58_dialog_content = "お前が先に通ったのは、出場順が先だっただけだ！",
  ui_story_5036_50360802_59_dialog_content = "よく見ておくんだな！\n私の歌を聞けば、審査員もシロートどもを通したことを後悔するぜ！",
  ui_story_5036_50360802_60_dialog_content = "ヴィックさん、今のお気持ちは？",
  ui_story_5036_50360802_61_dialog_content = "ようやく…寝られる…",
  ui_story_5036_50360802_62_dialog_content = "目が覚めたら…",
  ui_story_5036_50360802_63_dialog_content = "ウロボロスを…探しに…",
  ui_story_5036_50360802_64_dialog_content = "ヴィックさん？",
  ui_story_5036_50360802_65_dialog_content = "ヴィックさん！？どうされました！？",
  ui_story_5036_50360802_66_dialog_content = "すぅ…すぅ…すぅ…",
  ui_story_5036_50360802_67_dialog_content = "ええと…あの…ヴィックさん…",
  ui_story_5036_50360802_68_dialog_content = "ステージで寝るのはおやめください！",
  ui_story_5036_50360802_69_dialog_content = "そうとう深く眠ってるわね。",
  ui_story_5036_50360802_70_dialog_content = "あんなに騒がしい会場で、\n穏やかに寝ていられるなんて…",
  ui_story_5036_50360802_71_dialog_content = "本当だね。傭兵に部屋まで担がれていった時も、\n目を覚まさなかったし…",
  ui_story_5036_50360802_72_dialog_content = "でも、誰もが目を見張る進歩だったわ。",
  ui_story_5036_50360802_73_dialog_content = "あれほど疲れきっているなんて、\nきっと2日間、猛特訓だったのでしょうね。",
  ui_story_5036_50360802_74_dialog_content = "君たちだって、\nすごくがんばってたでしょ？",
  ui_story_5036_50360802_75_dialog_content = "6票の満点だったじゃない。",
  ui_story_5036_50360802_76_dialog_content = "ふふふ…予想通りの結果ってところかしら？",
  ui_story_5036_50360802_77_dialog_content = "確かにちょっと、疲れたけどね。",
  ui_story_5036_50360802_78_dialog_content = "今日は早めに休みましょう。",
  ui_story_5036_50360802_79_dialog_content = "明日はまた1日中、リハーサルよ。",
  ui_story_5036_50360802_80_dialog_content = "今日は夢なんか見てる余裕もなさそう…",
  ui_story_5036_50360802_81_dialog_content = "そうね、じゃあ、おやすみなさい。",
  ui_story_5036_50360802_82_dialog_content = "え？バイス？カレン？",
  ui_story_5036_50360802_83_dialog_content = "何をそんなに急いでるの？",
  ui_story_5036_50360802_84_dialog_content = "じゃあ…",
  ui_story_5036_50360802_85_dialog_content = "僕も早めに休もうかな。",
  ui_story_5036_50360901_1_dialog_content = "…ここはどこだろう…？",
  ui_story_5036_50360901_2_dialog_content = "ここは巨像…みたいだ。\nあれは…このまえ夢に出てきた空の末裔の女の子かな？",
  ui_story_5036_50360901_3_dialog_content = "また夢を見てる？",
  ui_story_5036_50360901_4_dialog_content = "あなたが「イクストウル」？",
  ui_story_5036_50360901_5_dialog_content = "はい。あなたが私の新しいナビゲーターですね？",
  ui_story_5036_50360901_6_dialog_content = "そうよ！シャミナードっていうの、よろしくね！",
  ui_story_5036_50360901_7_dialog_content = "（情景が変わった…巨像のブリッジみたいだ）",
  ui_story_5036_50360901_8_dialog_content = "イクストウル、どうしてあなたにはスクリーンとか、\n変わった音響設備とかがたくさん付いてるの？",
  ui_story_5036_50360901_9_dialog_content = "お友だちに聞いてみたけど、\nみんな他の巨像では見たことないって言ってたよ。",
  ui_story_5036_50360901_10_dialog_content = "それについては、私も理由を知りません。",
  ui_story_5036_50360901_11_dialog_content = "はるか昔の記憶は、風に乗って流れてきた歌声のように\nもう消えてしまいました。",
  ui_story_5036_50360901_12_dialog_content = "そう、残念だね…",
  ui_story_5036_50360901_13_dialog_content = "でも、みんなイクストウルのことが大好きよ！",
  ui_story_5036_50360901_14_dialog_content = "だって、天空ノ谷中に響く音楽を流せるのは、\nあなただけだもん。",
  ui_story_5036_50360901_15_dialog_content = "ありがとうございます。\nそのように言っていただけて、私もうれしいです。",
  ui_story_5036_50360901_16_dialog_content = "イクストウル、旅に出ようよ！",
  ui_story_5036_50360901_17_dialog_content = "どうして突然そのような提案を？",
  ui_story_5036_50360901_18_dialog_content = "今日、先生が言ってたの。アストラ大陸には、\n戦争や暗鬼に苦しんでいる人がまだたくさんいて…",
  ui_story_5036_50360901_19_dialog_content = "希望も見えないまま、苦しい生活を送ってるんだって。\nだから、そういう人たちに歌を歌ってあげたいの！",
  ui_story_5036_50360901_20_dialog_content = "歌じゃ暗鬼は倒せないし、\n実際に何かをあげられるわけじゃないけど…",
  ui_story_5036_50360901_21_dialog_content = "でも…みんなに銃や大砲の音じゃない音を\n聞かせてあげたいの！",
  ui_story_5036_50360901_22_dialog_content = "そのような場所に行くのは危険だと思います。",
  ui_story_5036_50360901_23_dialog_content = "わかってる。でも、私の歌が少しでも慰めや希望になるなら、\nどんなに危険な所でも、怖くない。",
  ui_story_5036_50360901_24_dialog_content = "了解しました。",
  ui_story_5036_50360901_25_dialog_content = "それでは、出発しましょう。",
  ui_story_5036_50360901_26_dialog_content = "また夢を見てたのかな…？\nでも、今日の夢はこの前のとは違う…誰かの記憶みたいだった。",
  ui_story_5036_50360901_27_dialog_content = "シャミナード…あの女の子の名前かな？",
  ui_story_5036_50360901_28_dialog_content = "僕が知らないうちに、\n空の末裔が残した気持ちを感知したってことかな？",
  ui_story_5036_50360901_29_dialog_content = "巨像に乗ってアストラ大陸を巡って歌う空の末裔…\nゴルディみたいだ。",
  ui_story_5036_50360901_30_dialog_content = "ふわぁ…あれ、長い夢だった気がしたけど、\n実際は1時間しか寝てなかったんだ。",
  ui_story_5036_50360901_31_dialog_content = "すぐには寝付けそうもないし、\n何か食べようかな…",
  ui_story_5036_50360901_32_dialog_content = "<color=#e8d9bb>トントントン――！</color>",
  ui_story_5036_50360901_33_dialog_content = "（こんな夜遅くに誰だろう？）",
  ui_story_5036_50360901_34_dialog_content = "今開けるよ！",
  ui_story_5036_50360901_35_dialog_content = "PlayerName、ごめんなさい。\n起こしちゃった？",
  ui_story_5036_50360901_36_dialog_content = "ゴルディ？どうしたの？\nちょうど目が覚めちゃったところだけど…",
  ui_story_5036_50360901_37_dialog_content = "実はお願いしたいことがあって…\nコンサートの成功に関わることなの！",
  ui_story_5036_50360901_38_dialog_content = "え？まさか、深刻なこと！？\nイクストウルが墜落しそうとか？",
  ui_story_5036_50360901_39_dialog_content = "そこまで深刻ではないけど…\nねえ、最近、変わった夢を見たことはない？",
  ui_story_5036_50360901_40_dialog_content = "広い山と谷が出てきて、\n女の子の歌声が聞こえるの。",
  ui_story_5036_50360901_41_dialog_content = "見たよ。どうしてか分からないけど、\n最近は毎晩そんな感じの夢を見るんだ。",
  ui_story_5036_50360901_42_dialog_content = "天空ノ谷で、知らない空の末裔の女の子が歌ってる夢。",
  ui_story_5036_50360901_43_dialog_content = "やっぱり、空の末裔だったのね！？",
  ui_story_5036_50360901_44_dialog_content = "服を見れば、すぐ分かると思うけど？",
  ui_story_5036_50360901_45_dialog_content = "おかしな夢だなとは思ってたけど、\n悪夢ってわけでもないから、今まで気にしてなかったんだ。",
  ui_story_5036_50360901_46_dialog_content = "あ、そういえば…\nこの前は単なる偶然だろうって話じゃなかった？",
  ui_story_5036_50360901_47_dialog_content = "最初はそう思ってたんだけど、\nでも今は…この巨像にいる全員が同じ夢を見たっていうの！",
  ui_story_5036_50360901_48_dialog_content = "全員が同じ夢！？",
  ui_story_5036_50360901_49_dialog_content = "そう。1人や2人だったら偶然って言えるかもしれないけど、\n全員が同じ夢を見るのは、さすがにヘンでしょ！？",
  ui_story_5036_50360901_50_dialog_content = "それで、みんな不安がってて…",
  ui_story_5036_50360901_51_dialog_content = "ここ2日、夢のせいで眠れなかったって\n苦情を言う参加者も増えてるわ。",
  ui_story_5036_50360901_52_dialog_content = "睡眠不足だと、\nコンサートのパフォーマンスにも影響するし…",
  ui_story_5036_50360901_53_dialog_content = "つまり、夢の原因になってる問題を見つけて、\nみんながゆっくり休めるようにしたいんだね？",
  ui_story_5036_50360901_54_dialog_content = "私も自分で調べてみようとしたけど、\n空の末裔みたいに感知能力があるわけじゃないから、何も分からなくて…",
  ui_story_5036_50360901_55_dialog_content = "PlayerName、手伝ってくれる？",
  ui_story_5036_50360901_56_dialog_content = "もちろん。\nコンサートが無事に開催できるように力を貸すよ！",
  ui_story_5036_50360901_57_dialog_content = "ありがとう！",
  ui_story_5036_50360901_58_dialog_content = "でも、イクストウルは大きいし、感知能力があるといっても、\n1度で巨像全体を調べられるわけじゃないよ。",
  ui_story_5036_50360901_59_dialog_content = "どこから手を付けたらいいかな？",
  ui_story_5036_50360901_60_dialog_content = "それは…私にも分からないわ…",
  ui_story_5036_50360901_61_dialog_content = "だったら、尾の方から調べりゃいいさ。",
  ui_story_5036_50360901_62_dialog_content = "ヴィック！？どこから出てきたの？",
  ui_story_5036_50360901_63_dialog_content = "あさっては本番よ。\n練習してた方がいいんじゃないかしら？",
  ui_story_5036_50360901_64_dialog_content = "つれないこと言うなって。\nおかしな夢で困ってるんだろ？",
  ui_story_5036_50360901_65_dialog_content = "睡眠の質が保てなきゃ、\n練習する元気だって出やしないさ。",
  ui_story_5036_50360901_66_dialog_content = "確かにその通りなんだけど、\nヴィックに言われると間違ってるように聞こえるなぁ…",
  ui_story_5036_50360901_67_dialog_content = "ハハハ、そりゃ思い込みって奴さ。",
  ui_story_5036_50360901_68_dialog_content = "そもそも、自分から何かをしようとする時点で、怪しい…",
  ui_story_5036_50360901_69_dialog_content = "…あ、思い出した。巨像の尾の辺りでウロボロスを探したいって言ってたね。\nついでに自分の目的も果たすつもりだね！",
  ui_story_5036_50360901_70_dialog_content = "そんなんじゃないさ。1人でも多けりゃ何かの助けになる。\n俺を連れて行っても、損はしないだろ？",
  ui_story_5036_50360901_71_dialog_content = "いいわ。でも、明日の練習はしっかり見張らせてもらうから。\nサボっちゃダメよ。",
  ui_story_5036_50360901_72_dialog_content = "珍獣の研究者はウソをつかないさ。",
  ui_story_5036_50360901_73_dialog_content = "とにかく、まずはおかしな夢を解決することだ。",
  ui_story_5036_50360901_74_dialog_content = "（ヴィックがこんなにやる気を出すなんて、やっぱり怪しい）",
  ui_story_5036_50360901_75_dialog_content = "（いったい、何を考えてるんだろう？）",
  ui_story_5036_50360901_76_dialog_content = "巨像の尾って…暗鬼をたくさん封鎖してる場所よ？",
  ui_story_5036_50360901_77_dialog_content = "そんな危険な場所から調べるって言うのに、\n何か根拠があるの？",
  ui_story_5036_50360901_78_dialog_content = "いや、何も。",
  ui_story_5036_50360901_79_option_content = "まともに相手にしない方がいいよ",
  ui_story_5036_50360901_80_dialog_content = "おいおい、PlayerName。一緒に戦った仲じゃないか。\n冷たいこと言うなよ！",
  ui_story_5036_50360901_81_option_content = "…",
  ui_story_5036_50360901_82_dialog_content = "…",
  ui_story_5036_50360901_83_dialog_content = "まだまだ若いねぇ。\n小さい事でビクビクするなって。",
  ui_story_5036_50360901_84_dialog_content = "確かな証拠ってワケじゃないが、\nそれなりの理由はあるさ。",
  ui_story_5036_50360901_85_dialog_content = "巨像の頭の方にいた暗鬼は全部片づけ終わってるし、\n今はみんな、自由に出入りできてる。",
  ui_story_5036_50360901_86_dialog_content = "ってことは、もうそれなりに\n調べは済んでるってことだろ？",
  ui_story_5036_50360901_87_dialog_content = "確かにそうね。もし異常があったなら、\n啓光と白夜城の人たちがとっくに見つけてるはずだわ。",
  ui_story_5036_50360901_88_dialog_content = "だったら、残ってる後ろが怪しい…ってことにならないか？",
  ui_story_5036_50360901_89_dialog_content = "でも、暗鬼がたくさん集まってるんだよ。\n僕たち3人だけじゃ危なくないかな？",
  ui_story_5036_50360901_90_dialog_content = "それは俺ももう考えたさ。\nアリガタモドキドリに手伝ってもらえばいい話だ。",
  ui_story_5036_50360901_91_dialog_content = "暗鬼たちは眠らせておいて、そのスキに静かに中に入りゃいい。\nそうすりゃ戦わずに済む。",
  ui_story_5036_50360901_92_dialog_content = "泥棒する時も、そういう手口だったの？",
  ui_story_5036_50360901_93_dialog_content = "そりゃもちろん…って、んなワケあるか！",
  ui_story_5036_50360901_94_dialog_content = "言っただろ、この間のことは、\nアリガタモドキドリの習性が引き起こした誤解だ。",
  ui_story_5036_50360901_95_dialog_content = "今回役に立てば、ちょうど埋め合わせになるだろ？",
  ui_story_5036_50360901_96_dialog_content = "…まあ、いいわ。\nそのことはコンサートが無事に終わってからにしましょ。",
  ui_story_5036_50360901_97_dialog_content = "あなたの言うことも、確かに一理あるわ。\n後ろの方から調べることにしましょ。",
  ui_story_5036_50360901_98_dialog_content = "そうだね、じゃあ行こう。",
  ui_story_5036_50360901_99_dialog_content = "ゴルディさんが暴力的になっているというウワサについて、\n質問しようと思っていたのですが…",
  ui_story_5036_50360901_100_dialog_content = "まさか3人が一緒に行動しているところに出くわすとは！",
  ui_story_5036_50360901_101_dialog_content = "遠くから様子をうかがってよかった…\nPlayerNameさんに感知されるところでした。",
  ui_story_5036_50360901_102_dialog_content = "ただ、ここからでは何を話しているのか聞こえませんね…",
  ui_story_5036_50360901_103_dialog_content = "あの方向だと…\nまさか、巨像の尾の方へ向かっているのでしょうか？",
  ui_story_5036_50360901_104_dialog_content = "何か匂いますね。付いていきましょう…",
  ui_story_5036_50360901_105_dialog_content = "暗いな…暗鬼がいつ出てきてもおかしくないね。\n何だか落ち着かないよ。",
  ui_story_5036_50360901_106_dialog_content = "安心しろって。\nこいつに任せときゃいいんだ。ほら。",
  ui_story_5036_50360901_107_dialog_content = "ホゥホゥ――！",
  ui_story_5036_50360901_108_dialog_content = "『ノ、ノラ様！？』",
  ui_story_5036_50360901_109_dialog_content = "ホゥホゥホゥ！",
  ui_story_5036_50360901_110_dialog_content = "『お褒めにあずかり光栄です。\nこれまで以上に努力いたします！』",
  ui_story_5036_50360901_111_dialog_content = "『褒められるなんて、おかしなこともあるものだ…\nそれにしても、やけに眠い…』",
  ui_story_5036_50360901_112_dialog_content = "『ぐぅ…』",
  ui_story_5036_50360901_113_dialog_content = "どうだ、うまくいったろ？",
  ui_story_5036_50360901_114_dialog_content = "…本当に珍獣の能力、悪用してないんだよね？",
  ui_story_5036_50360901_115_dialog_content = "アリガタモドキドリは俺の友だちだから、\n喜んで助けてくれてるってだけだ…",
  ui_story_5036_50360901_116_dialog_content = "真っ暗ね…",
  ui_story_5036_50360901_117_dialog_content = "うう…ダメよ、しっかりしなきゃ…！",
  ui_story_5036_50360901_118_dialog_content = "ゴルディ、大丈夫？",
  ui_story_5036_50360901_119_dialog_content = "え！？だ、大丈夫よ！",
  ui_story_5036_50360901_120_dialog_content = "私はアイドルだもの、大丈夫に決まってるでしょ！\nちょっと疲れちゃったから、少しだけ休みたいなって思っただけ。",
  ui_story_5036_50360901_121_dialog_content = "マシュマロ、抱っこさせて。",
  ui_story_5036_50360901_122_dialog_content = "ワン！",
  ui_story_5036_50360901_123_dialog_content = "はあ…やわらかくてフワフワ…\nうん、元気になったわ！",
  ui_story_5036_50360901_124_dialog_content = "先に進みましょ！",
  ui_story_5036_50360901_125_dialog_content = "（ゴルディの様子がおかしい…\n暗い場所が苦手なのかな？）",
  ui_story_5036_50360901_126_dialog_content = "もうだいぶ歩いたわね。\nそろそろ巨像の一番後ろにも近いんじゃないかしら？",
  ui_story_5036_50360901_X126_dialog_content = "PlayerName、この近くに何かいる？",
  ui_story_5036_50360901_127_dialog_content = "感知してみるよ。",
  ui_story_5036_50360901_128_option_content = "感知！",
  ui_story_5036_50360901_129_dialog_content = "（この近くには眠ってる暗鬼しかいないみたいだ）",
  ui_story_5036_50360901_130_dialog_content = "（でも、なぜだろう？何かいるような感じがする。\n考えすぎかな？）",
  ui_story_5036_50360901_131_dialog_content = "（…いや、違う。この感覚は…）",
  ui_story_5036_50360901_132_dialog_content = "（初めて天空ノ谷に戻った時と似てる…\n過去の空の末裔が残していった感情だ！）",
  ui_story_5036_50360901_133_dialog_content = "（感知してみよう）",
  ui_story_5036_50360901_134_dialog_content = "うわっ！？イ、イクストウル、これは何！？",
  ui_story_5036_50360901_135_dialog_content = "慌てることはありません、シャミナード。\n暗鬼ではありません。",
  ui_story_5036_50360901_136_dialog_content = "資料によれば、ウロボロスという動物だと思われます。\n光霊に対しても、空の末裔に対しても友好的な生き物です。",
  ui_story_5036_50360901_137_dialog_content = "よかったぁ、暗鬼じゃないのね。",
  ui_story_5036_50360901_138_dialog_content = "キュウキュウ！",
  ui_story_5036_50360901_139_dialog_content = "アハハ、くすぐったいよ。",
  ui_story_5036_50360901_140_dialog_content = "どう？何か感知できた？",
  ui_story_5036_50360901_141_dialog_content = "シャミナード…あの子の名前…",
  ui_story_5036_50360901_142_dialog_content = "シャミナード？空の末裔の女の子のこと？",
  ui_story_5036_50360901_143_dialog_content = "うん、彼女が残した気持ちを感知したんだ。それから…",
  ui_story_5036_50360901_144_dialog_content = "ウロボロスも！",
  ui_story_5036_50360901_145_dialog_content = "なんだって！？",
  ui_story_5036_50360901_146_dialog_content = "ウロボロスを見たのか！？\n詳しく教えてくれ！",
  ui_story_5036_50360901_147_dialog_content = "ちょ、ちょっと待って、手を放して！\nこんなに揺らされたら吐きそうだよ！",
  ui_story_5036_50360901_148_dialog_content = "先に話せ！そうしたら手を放してやる！",
  ui_story_5036_50360901_149_dialog_content = "僕が感知したのは過去のウロボロス！\n今のじゃないよ！",
  ui_story_5036_50360901_150_dialog_content = "過去の？",
  ui_story_5036_50360901_151_dialog_content = "うん、この巨像のかつての主人で、\n皆が夢で見た空の末裔の女の子は、シャミナードって名前みたいだ。",
  ui_story_5036_50360901_152_dialog_content = "その子がウロボロスに出会って、\nそのまま巨像に住まわせてあげてたみたいだ。",
  ui_story_5036_50360901_153_dialog_content = "でも資料から考えれば、\n少なくとも100年は前のことだよ。",
  ui_story_5036_50360901_154_dialog_content = "ウロボロスはもう、\nここにはいないんじゃないかな…",
  ui_story_5036_50360901_155_dialog_content = "む…",
  ui_story_5036_50360901_156_dialog_content = "とにかく、まずは手を放してくれる？",
  ui_story_5036_50360901_157_dialog_content = "ウロボロスの居場所が分かったワケじゃないが、\n重要な情報であることには変わりない…",
  ui_story_5036_50360901_158_dialog_content = "もう少し感知をがんばってくれ！\nなぁ、空の末裔くん！",
  ui_story_5036_50360901_159_dialog_content = "俺の大事な弟子のフィアと一緒に冒険しただろ？\n俺に借りを返すと思って！",
  ui_story_5036_50360901_160_dialog_content = "僕がいつ君に借りを作ったの！？",
  ui_story_5036_50360901_161_dialog_content = "ちょっと待って！\n今は夢のことを解決するのが先でしょ？",
  ui_story_5036_50360901_162_dialog_content = "なんで急にウロボロス探しになるの？",
  ui_story_5036_50360901_163_dialog_content = "あ、そうだった！\n目的がずれるところだった！",
  ui_story_5036_50360901_164_dialog_content = "チッチッチ、それは違うな、お若いの…",
  ui_story_5036_50360901_165_dialog_content = "さっきウロボロスに出会った空の末裔は、\n夢に出てきた女の子だって言わなかったか？",
  ui_story_5036_50360901_166_dialog_content = "確かにそうだわ…夢の方の調査を続けるにしても、\n今はその女の子が手がかりになるわね。",
  ui_story_5036_50360901_167_dialog_content = "…ってことだから、ウロボロスに関する情報も、\n気にかけておいてくれよ。",
  ui_story_5036_50360901_168_dialog_content = "うまくタダ働きさせられてる気分になってきた…",
  ui_story_5036_50360901_169_dialog_content = "タダ働きとは人聞きが悪いな。\n困ってる年寄りを助けてるんだ、立派な行いじゃないか。",
  ui_story_5036_50360901_170_dialog_content = "君って、本当に口がうまいね…",
  ui_story_5036_50360901_171_dialog_content = "ははは、それほどでも。",
  ui_story_5036_50360901_172_dialog_content = "夢の調査、やっぱりPlayerNameにお願いして正解だったわ。",
  ui_story_5036_50360901_173_dialog_content = "PlayerName、ほかの場所も感知してみてくれない？\n似たような何かが残ってないの？",
  ui_story_5036_50360901_174_dialog_content = "その子の記憶の中に、\n夢の原因になってる情報があるかもしれないわ。",
  ui_story_5036_50360901_175_dialog_content = "うん、やってみるよ。",
  ui_story_5036_50360901_176_dialog_content = "ここはまだ来たことないわね。",
  ui_story_5036_50360901_177_dialog_content = "さっきの廊下よりも巨像の尾に近いから、\n新しい手がかりが何か見つかるかも。",
  ui_story_5036_50360901_178_dialog_content = "ゴルディ、ヴィック。\n何か背筋が寒くならない？",
  ui_story_5036_50360901_179_dialog_content = "確かにちょっと寒気がするな。\n暗力のせいか？",
  ui_story_5036_50360901_180_dialog_content = "いや、暗力はほとんど感じないよ。\nただ、よく分からないけど、緊張して…",
  ui_story_5036_50360901_181_dialog_content = "ああ、暗いのが苦手なのか？",
  ui_story_5036_50360901_182_dialog_content = "そ、そうじゃないよ！",
  ui_story_5036_50360901_183_dialog_content = "なに、恥ずかしがることじゃないさ。",
  ui_story_5036_50360901_184_dialog_content = "シーラも小さい頃は暗い所が怖くてな。\n夜になると風の音に驚いて、大泣きしてたもんだ。",
  ui_story_5036_50360901_185_dialog_content = "ドラゴライオンは鳥類を狩る以外に――ハックション！",
  ui_story_5036_50360901_186_dialog_content = "あれ？風邪？",
  ui_story_5036_50360901_187_dialog_content = "そ、そうじゃないわ…クシュン！",
  ui_story_5036_50360901_188_dialog_content = "ただ、急にくしゃみが出ただけ…",
  ui_story_5036_50360901_189_dialog_content = "やっぱり風邪をひいてるんじゃない？",
  ui_story_5036_50360901_190_dialog_content = "いいえ。\nきっとあの男が私の悪口を言ってるのね。",
  ui_story_5036_50360901_191_dialog_content = "帰ってきたら、\nじっくり「尋問」させてもらうわ。",
  ui_story_5036_50360901_192_dialog_content = "また適当なこと言ってるでしょ？",
  ui_story_5036_50360901_193_dialog_content = "そんなことはないさ。\nウソだと思うなら、シーラに聞いてみろって。",
  ui_story_5036_50360901_194_dialog_content = "別にいいよ。今は他にやることがあるし…",
  ui_story_5036_50360901_X194_dialog_content = "この近くに…何か残されてるみたいだ。\n感知してみるよ。",
  ui_story_5036_50360901_195_option_content = "感知！",
  ui_story_5036_50360901_196_dialog_content = "♪朝日を映す朝露は♪",
  ui_story_5036_50360901_197_dialog_content = "♪かすかに美しくきらめくよ♪",
  ui_story_5036_50360901_198_dialog_content = "（これは…巨像を起動する時のメロディだ！）",
  ui_story_5036_50360901_199_dialog_content = "キュウキュウ――キュウ！",
  ui_story_5036_50360901_200_dialog_content = "わ！？ウロボロス、寝てたんじゃないの？\nどうしてここに！？",
  ui_story_5036_50360901_201_dialog_content = "キュウ――♪キュウ――♪",
  ui_story_5036_50360901_202_dialog_content = "歌ってるの？\nしかも、いま私が歌ってた曲じゃない！？",
  ui_story_5036_50360901_203_dialog_content = "あなた、歌を覚えたの！？",
  ui_story_5036_50360901_204_dialog_content = "キュウ――♪キュウキュウ♪",
  ui_story_5036_50360901_205_dialog_content = "そのメロディは「そうだ」って意味！？",
  ui_story_5036_50360901_206_dialog_content = "驚きました。空の末裔が巨像の操縦に使う旋律を、\n動物が交流の手段にするとは…",
  ui_story_5036_50360901_207_dialog_content = "感知できたよ…",
  ui_story_5036_50360901_208_dialog_content = "ただ、今度のはすごく断片的で短かった。",
  ui_story_5036_50360901_209_dialog_content = "どんな内容だ？話してくれ。",
  ui_story_5036_50360901_210_dialog_content = "夢に関することは出てきた？",
  ui_story_5036_50360901_211_dialog_content = "夢とは関係なさそうだね。",
  ui_story_5036_50360901_212_dialog_content = "喜びの感情だった。\nシャミナードがウロボロスの能力に気づいた時みたいだ。",
  ui_story_5036_50360901_213_dialog_content = "ウロボロスは、空の末裔が巨像の操縦に使うメロディを覚えて、\n気持ちを表現したり、人と交流することができたみたいだね。",
  ui_story_5036_50360901_214_dialog_content = "おお？そいつは新発見だ！",
  ui_story_5036_50360901_215_dialog_content = "大手柄だぞ、PlayerName！\n俺からは何も出ないがな。",
  ui_story_5036_50360901_216_dialog_content = "…",
  ui_story_5036_50360901_217_dialog_content = "だが、ウロボロスと巨像の間に何か深い関係があるってことは、\n確かに古書にも書いてあった。",
  ui_story_5036_50360901_218_dialog_content = "ウロボロスにも何か、\n精神的な能力があると考えずにはいられないな…",
  ui_story_5036_50360901_219_dialog_content = "それこそ…夢を見させる、とかな。",
  ui_story_5036_50360901_220_dialog_content = "ホントに！？",
  ui_story_5036_50360901_221_dialog_content = "もしウソだったら、お仕置きよ！",
  ui_story_5036_50360901_222_dialog_content = "おいおい、ウソなんて言わないって！",
  ui_story_5036_50360901_223_dialog_content = "ただ、何もかもが推測だ。\n100%の保証なんかできないぜ。",
  ui_story_5036_50360901_224_dialog_content = "怪しいわね…",
  ui_story_5036_50360901_225_dialog_content = "PlayerName、どう思う？",
  ui_story_5036_50360901_226_option_content = "ヴィックを信じる",
  ui_story_5036_50360901_227_dialog_content = "ヴィックはよくデタラメを言うし、\n何でもいい加減だけど…",
  ui_story_5036_50360901_228_dialog_content = "珍獣に関する知識だけは確かだよ。",
  ui_story_5036_50360901_229_dialog_content = "そこは信じてあげてもいいと思う。",
  ui_story_5036_50360901_230_dialog_content = "そうそう、年寄りの言うことは聞くもんだ。",
  ui_story_5036_50360901_231_dialog_content = "分かった、PlayerNameの判断を信じるわ。",
  ui_story_5036_50360901_232_option_content = "信じない",
  ui_story_5036_50360901_233_dialog_content = "信じない方がいいと思うよ。\n本当のことを言ったためしがほとんどないし。",
  ui_story_5036_50360901_234_dialog_content = "年寄りにつらく当たるなんて、\nひどいじゃないか、うう…",
  ui_story_5036_50360901_235_dialog_content = "ほらね。今みたいに年寄りって言ったり、\n永遠の18歳だって言ったり…",
  ui_story_5036_50360901_236_dialog_content = "若者には分からないさ。\n身体は老いても、心は老いないもんなんだよ。",
  ui_story_5036_50360901_237_dialog_content = "ま、確かに信用できないわね！",
  ui_story_5036_50360901_238_dialog_content = "ううっ…",
  ui_story_5036_50360901_239_dialog_content = "ただ、今はウロボロスを調べるしか、\n手がかりはないね。",
  ui_story_5036_50360901_240_dialog_content = "まだ続けるしかないの？\nううん…そうよね、簡単にあきらめちゃいけないわ。",
  ui_story_5036_50360901_241_dialog_content = "先に進みましょ。\n他のところも調べてみなくちゃ。",
  ui_story_5036_50360901_242_dialog_content = "進んでは止まって…\nいったい何をしているのでしょう？",
  ui_story_5036_50360901_243_dialog_content = "おまけに、知らないうちに封鎖エリアに入っていますし…\n何とも薄気味悪いところです…怖くなってきました…",
  ui_story_5036_50360901_244_dialog_content = "<color=#e8d9bb>ヒュ――</color>",
  ui_story_5036_50360901_245_dialog_content = "か、風の音でしょうか…！？\nや、やっぱり帰った方がよさそうですね？質問は今度でも…",
  ui_story_5036_50360901_246_dialog_content = "い、いけません！ブランディ、あなたは真実を追いかけるプロの記者ですよ！\nここであきらめてはいけません！",
  ui_story_5036_50360901_247_dialog_content = "付いていきましょう…",
  ui_story_5036_50360901_248_dialog_content = "もうどれくらい歩いた？20分くらいかしら？",
  ui_story_5036_50360901_249_dialog_content = "入り組んだ廊下だな…\n同じところをグルグル回ってる気がするぞ。",
  ui_story_5036_50360901_250_dialog_content = "PlayerName、巨像で長いこと暮らしてたんだろ？\n道を知らないのか？",
  ui_story_5036_50360901_251_dialog_content = "僕が詳しいのはソラヴァンだけだよ。\n巨像全体の構造まではよく知らないし…",
  ui_story_5036_50360901_252_dialog_content = "そうもそうよね。感知能力を使ってみるのはどう？",
  ui_story_5036_50360901_253_dialog_content = "この近くに空の末裔の子の感情が残ってるなら、\n道を教えてくれるかもしれないわ。",
  ui_story_5036_50360901_254_dialog_content = "確かにそうだね。試してみるよ。",
  ui_story_5036_50360901_255_option_content = "感知！",
  ui_story_5036_50360901_256_dialog_content = "イクストウル、大変だよ！",
  ui_story_5036_50360901_257_dialog_content = "ウロボロスがこんなのになっちゃった！",
  ui_story_5036_50360901_258_dialog_content = "ううぅ…どうしちゃったの？\nもうウロボロスには会えないの？",
  ui_story_5036_50360901_259_dialog_content = "今まではずっとウロボロスがいたから、\n暗鬼の襲撃もしのいで来られたのに…",
  ui_story_5036_50360901_260_dialog_content = "心配はいりません、シャミナード。",
  ui_story_5036_50360901_261_dialog_content = "ウロボロスは非常に寿命の長い生き物です。\n一定の年齢になると卵に変化し、再び孵化（ふか）して新たな生を受けるのです。",
  ui_story_5036_50360901_262_dialog_content = "ウロボロスはあなたを信じているのです。最も弱い状態の時、\nあなたなら守ってくれると信じているから、ここで卵になったのでしょう。",
  ui_story_5036_50360901_263_dialog_content = "待っていれば、また一緒に旅ができます。",
  ui_story_5036_50360901_264_dialog_content = "そうなんだ？",
  ui_story_5036_50360901_265_dialog_content = "よかった、じゃあ、また一緒に旅ができるんだね。\nもうウロボロスに会えないかと思っちゃった。",
  ui_story_5036_50360901_266_dialog_content = "だったら、大事に守ってあげなくちゃ。\nそうだ、卵は一番丈夫な部屋に置こっと！",
  ui_story_5036_50360901_267_dialog_content = "あそこなら、暗鬼がたくさん来ても大丈夫だもんね！",
  ui_story_5036_50360901_268_dialog_content = "見えたよ！今度はすごくはっきり見えた！",
  ui_story_5036_50360901_269_dialog_content = "シャミナードは、ウロボロスの卵を\n巨像で一番丈夫な部屋に置くって言って…",
  ui_story_5036_50360901_X269_dialog_content = "あっちへ走っていったよ。",
  ui_story_5036_50360901_270_dialog_content = "だったら、すぐに見に行ってみようぜ。\n新しい手がかりが見つかるかもしれない。",
  ui_story_5036_50360901_271_dialog_content = "ずいぶん年月が経ってるんだよ？\n手がかりなんて残ってるかな…",
  ui_story_5036_50360901_272_dialog_content = "とにかく、まずは見に行ってみましょ。",
  ui_story_5036_50361001_1_dialog_content = "もう10分以上は歩いてるんじゃない？\nどうしてまだ着かないの？",
  ui_story_5036_50361001_2_dialog_content = "いくらイクストウルが大きいからって、\nそろそろ着いてもいい頃でしょ？",
  ui_story_5036_50361001_3_dialog_content = "まさか、本当に同じところをグルグル回ってるのかな？",
  ui_story_5036_50361001_4_dialog_content = "分からないわ…\nただ、気分も悪くなってきたわね。",
  ui_story_5036_50361001_5_dialog_content = "ここ、気味が悪いわ…\nさっきから鳥肌が立ちっぱなしだもの。",
  ui_story_5036_50361001_6_dialog_content = "野外調査だと、方向を見失って\n同じところを回ってるってのは、よくあることだ。",
  ui_story_5036_50361001_7_dialog_content = "そういう時には、印をつけるのさ。",
  ui_story_5036_50361001_8_dialog_content = "よさそうな方法だね。誰かペンか何か、持ってる？",
  ui_story_5036_50361001_9_dialog_content = "持ってないな。",
  ui_story_5036_50361001_10_dialog_content = "私もよ。でも、これがあるわ。",
  ui_story_5036_50361001_11_dialog_content = "コンサートのポスター？\nなんで調査に持ってきたの？",
  ui_story_5036_50361001_12_dialog_content = "ファンのみんなにサインを求められることがよくあるけど、\nいつも色紙を持ってるとは限らないでしょ。",
  ui_story_5036_50361001_13_dialog_content = "でも、みんなの気持ちに応えてあげたいから、\nいつもポスターを持ち歩いて、色紙代わりにしてるの。",
  ui_story_5036_50361001_14_dialog_content = "ファン思いなんだね！",
  ui_story_5036_50361001_15_dialog_content = "いつでもどこでもファンのためを思って行動するのは、\nアイドルの基本だもの！",
  ui_story_5036_50361001_16_dialog_content = "ポスターか。まぁ、確かに目立っていいかもな。",
  ui_story_5036_50361001_17_dialog_content = "まずは1枚ここに貼って、先に進みましょ！",
  ui_story_5036_50361001_18_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_5036_50361001_19_dialog_content = "またしばらく歩いたけど、左も右も何の変化もないね。",
  ui_story_5036_50361001_20_dialog_content = "お？ありゃ、さっき貼ったポスターじゃないか？",
  ui_story_5036_50361001_21_dialog_content = "ホントだわ。\nやっぱりずっと同じところを歩いてたのね！",
  ui_story_5036_50361001_22_dialog_content = "いや、ちょっと待って。\nこのポスター、ちょっとおかしい…",
  ui_story_5036_50361001_23_dialog_content = "このポスターのゴルディ、髪が黒いよ？\n表情も何だか硬いし…",
  ui_story_5036_50361001_24_dialog_content = "どういうこと？\n誰かのイタズラ！？",
  ui_story_5036_50361001_25_dialog_content = "この辺はまだ誰も探索してない場所だろ？\n俺たち3人以外には誰もいないはずだがな。",
  ui_story_5036_50361001_26_dialog_content = "まさか…",
  ui_story_5036_50361001_27_option_content = "誰かに尾行されてる？",
  ui_story_5036_50361001_28_dialog_content = "過激なファンかしら？\nあ…もしかして、誰かがコンサートを邪魔しにきた？",
  ui_story_5036_50361001_29_dialog_content = "いずれにしても、怖いことに変わりはないね…",
  ui_story_5036_50361001_30_dialog_content = "急いでここを離れよう。",
  ui_story_5036_50361001_31_option_content = "暗鬼が！？",
  ui_story_5036_50361001_32_dialog_content = "だが、途中にいた暗鬼は全部、\nアリガタモドキドリが眠らせたぞ？",
  ui_story_5036_50361001_33_dialog_content = "今もまだ起きてはいないはずだ。",
  ui_story_5036_50361001_34_dialog_content = "ここはやっぱりおかしいわ。\n急いで離れましょう！",
  ui_story_5036_50361001_35_dialog_content = "でも、どっちに行けばいいんだろう？",
  ui_story_5036_50361001_36_dialog_content = "ずっと同じところを歩いてたなら、\n別の方向に向かって歩き続ければいいはずよ！",
  ui_story_5036_50361001_37_dialog_content = "こっちね！",
  ui_story_5036_50361001_38_dialog_content = "おいおい、ゆっくり走ってくれ、\n年寄りを置いてくなって！",
  ui_story_5036_50361001_39_dialog_content = "ちょっと、そんなに速く行かないで！？",
  ui_story_5036_50361001_40_dialog_content = "こ、このポスター、本当におかしいです！",
  ui_story_5036_50361001_41_dialog_content = "ま、まままま待って…\n置いていかないでくださいっ！",
  ui_story_5036_50361001_42_dialog_content = "ふぅ…はぁ…さっきとは違う場所に着いたみたいね。",
  ui_story_5036_50361001_43_dialog_content = "もしかして、ここがシャミナードの言ってた部屋かな？",
  ui_story_5036_50361001_44_dialog_content = "作りは丈夫そうだけど、長い間補修されてないんだろうね。\n壁はもうボロボロだ。",
  ui_story_5036_50361001_45_dialog_content = "不気味な感じもするし、\nここには居たくないな…",
  ui_story_5036_50361001_46_dialog_content = "それ以外も傷だらけね…\nいつ暗鬼が出てきてもおかしくなさそう。",
  ui_story_5036_50361001_47_dialog_content = "ガサッ――",
  ui_story_5036_50361001_48_dialog_content = "誰かいるわ！\nそこにいるのは誰？",
  ui_story_5036_50361001_49_dialog_content = "出てきなさい！",
  ui_story_5036_50361001_50_dialog_content = "ううっ！？こ、攻撃しないでください、私です！",
  ui_story_5036_50361001_51_dialog_content = "あなたのことじゃないわ！",
  ui_story_5036_50361001_52_dialog_content = "えっ？",
  ui_story_5036_50361001_53_dialog_content = "ブランディ？どうしてここに…\n…危ない！後ろ！",
  ui_story_5036_50361001_54_dialog_content = "グオオ――！",
  ui_story_5036_50361001_55_dialog_content = "避けて！",
  ui_story_5036_50361001_56_dialog_content = "あ！ゴルディさん！？",
  ui_story_5036_50361001_57_dialog_content = "（ゴルディさんに助けられた…！？）",
  ui_story_5036_50361001_58_dialog_content = "私の目の前で誰かを傷つけようなんて、許さないわ！",
  ui_story_5036_50361001_59_dialog_content = "正義の裁きを受けなさい！",
  ui_story_5036_50361001_60_dialog_content = "ウウ――ワン！",
  ui_story_5036_50361002_1_dialog_content = "はぁ…危ないところでした！",
  ui_story_5036_50361002_2_dialog_content = "もう大丈夫よ、最後の1匹も倒したわ！",
  ui_story_5036_50361002_3_dialog_content = "大丈夫？ケガはない？",
  ui_story_5036_50361002_4_dialog_content = "大丈夫です。腰は抜けてしまいましたが…",
  ui_story_5036_50361002_5_dialog_content = "つけられてたのか。\n誰かに見られてるような気がしたワケだ。",
  ui_story_5036_50361002_6_dialog_content = "どうして君がここに？\n僕たちを尾行してたの？",
  ui_story_5036_50361002_7_dialog_content = "ダメよ、ブランディ。\nストーキングなんて！",
  ui_story_5036_50361002_8_dialog_content = "うう…私はストーカーではありません！",
  ui_story_5036_50361002_9_dialog_content = "真実を確かめるためにきただけです！",
  ui_story_5036_50361002_10_dialog_content = "真実を確かめる？夢のことを調べてるの？",
  ui_story_5036_50361002_11_dialog_content = "夢の方ではなく、別件です…こっそり調べるつもりだったのですが…\n見つかってしまったからには、単刀直入にお聞きしましょう。",
  ui_story_5036_50361002_12_dialog_content = "ゴルディさん、グランドスター劇場の\nオーナーをご存じですね？",
  ui_story_5036_50361002_13_dialog_content = "え？ええと…\nそう言われれば、なんとなく覚えてるわ。",
  ui_story_5036_50361002_14_dialog_content = "まさか、そいつも俺みたいに殴られたのか！？",
  ui_story_5036_50361002_15_dialog_content = "ヴィック、ちょっと黙ってて…",
  ui_story_5036_50361002_16_dialog_content = "短期間だけど、一緒に仕事しようとしたことがあるわ。\n意見が合わなくて、結局ナシになっちゃったけど…",
  ui_story_5036_50361002_17_dialog_content = "意見が合わない、ですか…では、なぜ別の影ノ街の会場ではなく、\nわざわざ困難の多いこの巨像でコンサートを開くことにしたのですか？",
  ui_story_5036_50361002_18_dialog_content = "ほかの劇場のオーナーにも、みんな断られたからよ。",
  ui_story_5036_50361002_19_dialog_content = "では、なぜ断られたのか、理由はご存じですか？",
  ui_story_5036_50361002_20_dialog_content = "それは…話すと長くなるわ。",
  ui_story_5036_50361002_21_dialog_content = "グランドスター劇場のオーナーは『デイリー・スクープ速報版』に\nあなたにケガをさせられたと話しています。",
  ui_story_5036_50361002_X21_dialog_content = "どういうこと？\nまさか、本当にゴルディがやったって言いたいの？",
  ui_story_5036_50361002_22_dialog_content = "弊社の編集長が傷も確認しています。\n顔は腫れ上がり、アザだらけで、見ているだけでも痛々しく…",
  ui_story_5036_50361002_23_dialog_content = "そんなことはしてないわ！\nあの男の方こそ、何もしてない子どもたちを傷つけていたのよ！",
  ui_story_5036_50361002_24_dialog_content = "私自身も、あなたがやったとは信じたくありません。\nで、ですが…記者として真実を突き止める義務があります！",
  ui_story_5036_50361002_25_dialog_content = "身の潔白と相手の罪について、証拠はあるのですか？",
  ui_story_5036_50361002_26_dialog_content = "もちろん、真実を話して、疑いを晴らすわ。",
  ui_story_5036_50361002_27_dialog_content = "10日くらい前のことよ。\nちょうど私はコンサート会場を探していたの。",
  ui_story_5036_50361002_28_dialog_content = "いろいろ考えた結果、コンサート会場に一番いいと思って、\nグランドスター劇場に決めたの。",
  ui_story_5036_50361002_29_dialog_content = "それで、前もって慣れておくために、\nリハーサルをさせてもらったの。",
  ui_story_5036_50361002_30_dialog_content = "ラ――♪ラララ♪",
  ui_story_5036_50361002_31_dialog_content = "<color=#e8d9bb>バン――！</color>",
  ui_story_5036_50361002_32_dialog_content = "！！",
  ui_story_5036_50361002_33_dialog_content = "助けて！！",
  ui_story_5036_50361002_34_dialog_content = "あら？何の音？",
  ui_story_5036_50361002_35_dialog_content = "ここはガキの来るところじゃない！\nとっとと出ていけ！",
  ui_story_5036_50361002_36_dialog_content = "汚らしいネズミどもめ、\n劇場が汚れるだろうが！",
  ui_story_5036_50361002_37_dialog_content = "あっ！",
  ui_story_5036_50361002_38_dialog_content = "やめて！弟になにするの！？",
  ui_story_5036_50361002_39_dialog_content = "何をしてるの！？",
  ui_story_5036_50361002_40_dialog_content = "これはこれは、ゴルディ君じゃないか。\n何でもないさ、心配はいらない。",
  ui_story_5036_50361002_41_dialog_content = "チケットも買わずにタダ聞きしようとする貧乏人のガキがいたんだ。\nすぐに追い払ってやる。",
  ui_story_5036_50361002_42_dialog_content = "コンサートじゃないんでしょ？\nそのお姉ちゃんが練習してるのを聴くのもダメなの？",
  ui_story_5036_50361002_43_dialog_content = "練習だろうと、歌を聴きたければ、金を払え！",
  ui_story_5036_50361002_44_dialog_content = "この私に口答えとは、\nよほど痛い目に遭わないと分からないようだな！",
  ui_story_5036_50361002_45_dialog_content = "うわぁぁ！",
  ui_story_5036_50361002_X45_dialog_content = "助けて！！",
  ui_story_5036_50361002_46_dialog_content = "やめなさい！",
  ui_story_5036_50361002_47_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_5036_50361002_48_dialog_content = "うっ！ゲホ、ゴホ…",
  ui_story_5036_50361002_49_dialog_content = "この私に手を上げたな？\n私はグランドスター劇場のオーナーだぞ！",
  ui_story_5036_50361002_50_dialog_content = "オーナーだからなんだっていうの？\n罪のない子どもに手をあげるなんて許されないわ！",
  ui_story_5036_50361002_51_dialog_content = "何をしたのか、分かっているのか！？",
  ui_story_5036_50361002_52_dialog_content = "エヘン、オホン…",
  ui_story_5036_50361002_53_dialog_content = "これでは我がシアターでのコンサートは\n考え直させてもらわないといけないだろうな、ゴルディ君。",
  ui_story_5036_50361002_54_dialog_content = "…そう、残念ね…",
  ui_story_5036_50361002_55_dialog_content = "…つまり、暴力をふるったワケではなく、子どもたちを守ろうとして、\n勢いで相手を転ばせてしまったということですか？",
  ui_story_5036_50361002_56_dialog_content = "ウワサで聞いた話と全然違います！",
  ui_story_5036_50361002_57_dialog_content = "ウワサなんてデタラメよ。",
  ui_story_5036_50361002_58_dialog_content = "それに、オーナーはしりもちをついただけのはずよ。\n顔なんてケガさせてないわ！",
  ui_story_5036_50361002_59_dialog_content = "信じられないなら、子どもたちに聞いてみなさい。",
  ui_story_5036_50361002_60_dialog_content = "（…もともとゴルディさんは正義感あふれる行動で知られています。\n他人にむやみに暴力をふるうとは思えませんが…）",
  ui_story_5036_50361002_61_dialog_content = "では、なぜ最初からそう釈明しなかったのですか？",
  ui_story_5036_50361002_62_dialog_content = "私はアイドルだもの。\n弱いところなんて見せられないわ。",
  ui_story_5036_50361002_63_dialog_content = "劇場のオーナーたちがグルになって会場を貸してくれないのは、\n私の名誉を傷つけたいからでしょ。",
  ui_story_5036_50361002_64_dialog_content = "私がファンのみんなに影ノ街でコンサートをやるって\n約束したのを知っていて、破らせようとしてるのよ。",
  ui_story_5036_50361002_65_dialog_content = "コンサートが出来なかったら、\nみんなをがっかりさせちゃう…",
  ui_story_5036_50361002_X65_dialog_content = "アイドルとして、そんなこと許されないわ！",
  ui_story_5036_50361002_X66_dialog_content = "だから、どうあっても、\n約束通りコンサートを成功させたいの。",
  ui_story_5036_50361002_X67_dialog_content = "ファンのみんなの応援と愛には、\nかならず答えるってところを見せたいの！",
  ui_story_5036_50361002_66_dialog_content = "ひどい人たちだね！",
  ui_story_5036_50361002_67_dialog_content = "今の私にできることはただ一つ――\n誰も見たことないようなコンサートをやって、皆に楽しんでもらうことよ！",
  ui_story_5036_50361002_68_dialog_content = "どうせ知名度がなければ、\n誰も話を聞いてくれないし、信じてももらえないしね。",
  ui_story_5036_50361002_69_dialog_content = "だから、あの時は何も言わないことにしたの。\n困ってる姿をみんなに見せるわけにはいかないでしょ？",
  ui_story_5036_50361002_70_dialog_content = "（そこまでの覚悟だとは…）",
  ui_story_5036_50361002_71_dialog_content = "（ウソをついている様子はありません。\nそれに、私を暗鬼から救ってくれた…）",
  ui_story_5036_50361002_72_dialog_content = "ふぅ…よかったです…あやうくデマを信じて、\nゴルディさんを悪い人だと思ってしまうところでした。",
  ui_story_5036_50361002_73_dialog_content = "この件については、\n後日その子たちから裏を取ることにします。",
  ui_story_5036_50361002_X73_dialog_content = "もしあなたの言った通りであれば、きちんと記事にして、\nウワサがデマであることを証明します！",
  ui_story_5036_50361002_74_dialog_content = "よかった！",
  ui_story_5036_50361002_75_dialog_content = "感動のシーンは冒険が終わってからにしてもらえるか？\n今はまだ、やるべきことが終わっちゃいないんでな。",
  ui_story_5036_50361002_76_dialog_content = "そうだったわね！\nPlayerName、今私たちはどのあたりにいるの？",
  ui_story_5036_50361002_77_dialog_content = "感知した方向からすると、\nもうすぐシャミナードが卵を置いた場所に着くはずだよ。",
  ui_story_5036_50361002_78_dialog_content = "もう1度確かめてみるね…",
  ui_story_5036_50361002_79_option_content = "感知！",
  ui_story_5036_50361002_80_dialog_content = "グオォォ――！",
  ui_story_5036_50361002_81_dialog_content = "<color=#e8d9bb>ドンッ――！</color>",
  ui_story_5036_50361002_82_dialog_content = "きゃあ――！",
  ui_story_5036_50361002_83_dialog_content = "どうしよう、ドアが破られちゃう…",
  ui_story_5036_50361002_84_dialog_content = "巨像で一番丈夫な部屋でも、侵入が防げないなんて…",
  ui_story_5036_50361002_85_dialog_content = "イクストウル？イクストウル！！",
  ui_story_5036_50361002_86_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5036_50361002_87_dialog_content = "ううっ…イクストウルまで…",
  ui_story_5036_50361002_88_dialog_content = "ダメ、ダメだよ…勇気を出さなきゃ！\n私がウロボロスを守るんだから！",
  ui_story_5036_50361002_89_dialog_content = "とにかく、どこかに隠さなきゃ…",
  ui_story_5036_50361002_90_dialog_content = "隠し棚なら、きっと大丈夫だよね？",
  ui_story_5036_50361002_91_dialog_content = "ウロボロス、ここでおとなしく隠れててね…",
  ui_story_5036_50361002_92_dialog_content = "私が…絶対守ってあげるから！",
  ui_story_5036_50361002_93_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_5036_50361002_94_dialog_content = "<color=#e8d9bb>ガラガラ…</color>",
  ui_story_5036_50361002_95_dialog_content = "グォォ…",
  ui_story_5036_50361002_96_dialog_content = "暗鬼が…",
  ui_story_5036_50361002_97_dialog_content = "私はこっちよ！",
  ui_story_5036_50361002_98_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5036_50361002_99_dialog_content = "痛い…",
  ui_story_5036_50361002_100_dialog_content = "すごく…寒いよ…",
  ui_story_5036_50361002_101_dialog_content = "イクストウル…ウロボロス…いるの？",
  ui_story_5036_50361002_102_dialog_content = "お家に…帰りたい…",
  ui_story_5036_50361002_103_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5036_50361002_104_dialog_content = "キュウ――！",
  ui_story_5036_50361101_1_dialog_content = "…",
  ui_story_5036_50361101_2_dialog_content = "PlayerName？",
  ui_story_5036_50361101_3_dialog_content = "…",
  ui_story_5036_50361101_4_dialog_content = "PlayerName、大丈夫？何が見えたの？",
  ui_story_5036_50361101_5_dialog_content = "シャミナードの…最期の記憶…",
  ui_story_5036_50361101_6_dialog_content = "ウロボロスが卵になった後、\nシャミナードとイクストウルは暗鬼の襲撃に遭ったんだ。",
  ui_story_5036_50361101_7_dialog_content = "ウロボロスを守ろうとして、\nシャミナードは卵を隠し棚に隠した。",
  ui_story_5036_50361101_8_dialog_content = "それから、暗鬼を自分の方に引きつけて…\nそ、それで…",
  ui_story_5036_50361101_9_dialog_content = "…もう言わなくていいわ。",
  ui_story_5036_50361101_10_dialog_content = "その子、最後の最後までウロボロスの卵を守ってたのか。",
  ui_story_5036_50361101_11_dialog_content = "よくやったんじゃないか？\nちょっとやりすぎた感じだがな…",
  ui_story_5036_50361101_12_dialog_content = "ヴィック、こんな時に軽口は…",
  ui_story_5036_50361101_13_dialog_content = "軽口じゃないさ。\nほら、見てみろよ、その壁の隙間だ。",
  ui_story_5036_50361101_14_dialog_content = "何かあるの？",
  ui_story_5036_50361101_15_dialog_content = "わぁ！",
  ui_story_5036_50361101_16_dialog_content = "ゴルディ、どうしたの？",
  ui_story_5036_50361101_17_dialog_content = "これ…なに？模様のついた壁…じゃないわよね…",
  ui_story_5036_50361101_18_dialog_content = "巨像の素材や金属じゃないだろうな。\nたぶん…卵の殻だ。",
  ui_story_5036_50361101_19_dialog_content = "卵の殻？そう言われてみれば、\nあの模様、感知で見たウロボロスの卵みたいだ。",
  ui_story_5036_50361101_20_dialog_content = "まだここにあったんだね。でも、どうしてこんなに大きいの？\n壁を破っちゃいそうだよ！",
  ui_story_5036_50361101_21_dialog_content = "ウロボロスの卵って、スイカぐらいの大きさでしょ？\n女の子が抱えて走ってたぐらいなんだから。",
  ui_story_5036_50361101_22_dialog_content = "ウロボロスの卵…ヴィックさんの作り話ではなかったのですか？\nまさか、作り話が現実に！？",
  ui_story_5036_50361101_23_dialog_content = "ヴィック、どういうこと？",
  ui_story_5036_50361101_24_dialog_content = "さっぱり分からんなぁ。",
  ui_story_5036_50361101_25_dialog_content = "ええ？珍獣の専門家でしょ？",
  ui_story_5036_50361101_26_dialog_content = "専門家だからこそ、適当なことは言えないのさ。",
  ui_story_5036_50361101_27_dialog_content = "俺に分かるのは…この卵はとっくにかえるはずの時期は過ぎてるのに、\nどういうわけか、卵のままってことだけだ。",
  ui_story_5036_50361101_28_dialog_content = "だが、卵の中のウロボロスはまだ生きてる。\nずっと成長し続けてるから、こんなにデカいんだろうな。",
  ui_story_5036_50361101_29_dialog_content = "それ以上のことは、何とも言えんな。",
  ui_story_5036_50361101_30_dialog_content = "ウロボロスってのは超希少種なんだ。\n資料だってごくわずかしかない。",
  ui_story_5036_50361101_31_dialog_content = "ようするに、ウロボロスについては\nほとんど何も分かってない！",
  ui_story_5036_50361101_32_dialog_content = "出まかせだと思ってたのに、\nホントにいるなんて…",
  ui_story_5036_50361101_33_dialog_content = "それで、この卵がおかしな夢の原因なのですか？",
  ui_story_5036_50361101_34_dialog_content = "かもな。",
  ui_story_5036_50361101_35_dialog_content = "かも？",
  ui_story_5036_50361101_36_dialog_content = "俺だって確証があるわけじゃない。\n推測しかできないね。",
  ui_story_5036_50361101_37_dialog_content = "前からずっと気になってたんだ。\nウロボロスはどうやって卵の時期を過ごすのかってことをな。",
  ui_story_5036_50361101_38_dialog_content = "考えてもみろよ。卵になっちまったら、\n攻撃どころか、逃げることもできないんだぜ？",
  ui_story_5036_50361101_39_dialog_content = "だが、仮説としてこう考えられる。\nコイツは卵の時期には、精神に作用するような能力を使えるのかもしれない。",
  ui_story_5036_50361101_40_dialog_content = "おかしな夢を見させる、あるいは幻視や幻聴を起こすみたいな力で\n他の生物を怖がらせて、近づけないようにする…とかな。",
  ui_story_5036_50361101_41_dialog_content = "そうすりゃ、身を守れるだろ。",
  ui_story_5036_50361101_42_dialog_content = "つまり、私たちがおかしな夢を見たり、\n気分が悪くなってるのも、そのせいだと言いたいの…？",
  ui_story_5036_50361101_43_dialog_content = "さっき見たポスターがおかしくなってたのも全部、\nウロボロスのせいっていうこと？",
  ui_story_5036_50361101_44_dialog_content = "ああ。今のところ、それが一番理にかなった説明だろ？",
  ui_story_5036_50361101_45_dialog_content = "だったら、やるべきこともハッキリしたわね。\nなんとかしてこの卵を移動させなくちゃ！",
  ui_story_5036_50361101_46_option_content = "卵を？",
  ui_story_5036_50361101_47_option_content = "移動させる？",
  ui_story_5036_50361101_48_dialog_content = "そうよ！",
  ui_story_5036_50361101_49_dialog_content = "このまま置いておいたら、ウロボロスの能力のせいで、\nみんなが困り続けることになるわ。",
  ui_story_5036_50361101_50_dialog_content = "コンサートの開催にも影響が出ちゃう…",
  ui_story_5036_50361101_51_dialog_content = "ダメだな。",
  ui_story_5036_50361101_52_dialog_content = "どうして？",
  ui_story_5036_50361101_53_dialog_content = "こんなデカい卵が壁にはまってるんだぞ？",
  ui_story_5036_50361101_54_dialog_content = "どうやってここから出す？\nどうやって動かす？",
  ui_story_5036_50361101_55_dialog_content = "傭兵団の人たちに頼んで掘り出してもらって、\n飛空艇で運び出せばいいだけじゃない？",
  ui_story_5036_50361101_56_dialog_content = "こんな丈夫な壁が相手だぜ？\n卵を掘り出せる頃には、コンサートは終わってるだろうよ。",
  ui_story_5036_50361101_57_dialog_content = "そんな…",
  ui_story_5036_50361101_58_dialog_content = "それにな、ウロボロスは超希少種なんだ。\nこいつが最後の卵ってことだってありうる。",
  ui_story_5036_50361101_59_dialog_content = "万が一掘り出す途中で殻を傷つけでもしたら、\nウロボロスの命が危ない。",
  ui_story_5036_50361101_60_dialog_content = "その責任があんたに負えるか？",
  ui_story_5036_50361101_61_dialog_content = "それは…",
  ui_story_5036_50361101_62_dialog_content = "俺の言うことを聞く気があるなら、\nコンサートはいっそのこと止めちまった方がいいと思うぜ。",
  ui_story_5036_50361101_63_dialog_content = "コンサートはどこでだって開けるし、チャンスはいくらでもあるだろ。\nだったら、ウロボロスが孵化してから――",
  ui_story_5036_50361101_64_dialog_content = "ダメ！！",
  ui_story_5036_50361101_65_dialog_content = "このコンサートは私にとって<color=#FFB400>特別な意味</color>があるの。\n簡単にはあきらめないわ！",
  ui_story_5036_50361101_66_dialog_content = "ほかのことは譲れても…\nこのコンサートだけは譲れないの！",
  ui_story_5036_50361101_67_dialog_content = "確かにそうですね。\nコンサート開催はゴルディさんとファンとの約束ですし…",
  ui_story_5036_50361101_68_dialog_content = "（特別な意味…？\nゴルディ、どうしてそんなに必死なんだろう）",
  ui_story_5036_50361101_69_dialog_content = "そりゃあ、参ったな…",
  ui_story_5036_50361101_70_dialog_content = "…",
  ui_story_5036_50361101_71_dialog_content = "（2人とも一歩も譲る気はないみたいだ…\n何とかしなくちゃ）",
  ui_story_5036_50361101_72_dialog_content = "他に方法はないのかな？",
  ui_story_5036_50361101_73_dialog_content = "卵を運び出さずに、精神的な影響だけを取り除けない？",
  ui_story_5036_50361101_74_dialog_content = "そうですよ。ヴィックさんは珍獣研究者なのでしょう？\n何か方法はないのですか？",
  ui_story_5036_50361101_75_dialog_content = "まったく、最近の若いモンときたら…\n年寄りを困らせることばかり言うなぁ。",
  ui_story_5036_50361101_76_dialog_content = "ま、そういうもんか。\n俺の弟子もみんな、俺に助けを求めてばっかりだしな。",
  ui_story_5036_50361101_77_dialog_content = "今の発言、そっくりそのまま\nシーラとフィアに伝えておくよ。",
  ui_story_5036_50361101_78_dialog_content = "ん？俺がなんか言ったかな？\nすまんが記憶にないな。",
  ui_story_5036_50361101_79_dialog_content = "冗談はここまでにして、\nちゃんと話し合おうよ…",
  ui_story_5036_50361101_80_dialog_content = "オホン…方法が考えつかないわけじゃない。\nただ、ちと面倒でな。効くかどうかの保証もない。",
  ui_story_5036_50361101_81_dialog_content = "まずは話を聞かせて。\nコンサートが開けるなら、どんな面倒なことでもやって見せるわ！",
  ui_story_5036_50361101_82_dialog_content = "PlayerName、君が見た記憶の中で、\nシャミナードは卵のせいで気分が悪くなってたりしたか？",
  ui_story_5036_50361101_83_dialog_content = "うーん、そう言われると…そんなことはなかった気がする。",
  ui_story_5036_50361101_84_dialog_content = "そこだよ。",
  ui_story_5036_50361101_85_dialog_content = "ウロボロスがやってることは、一種の自己防衛だ。\n能力は危険を感じた時だけ使うもんさ。",
  ui_story_5036_50361101_86_dialog_content = "この巨像の中の脅威を排除して、\nウロボロスが安全だと感じれば、影響は消えるはずだ。",
  ui_story_5036_50361101_87_dialog_content = "巨像の中にいる暗鬼を全部片づければいいってこと？",
  ui_story_5036_50361101_88_dialog_content = "そういうことになるかな。",
  ui_story_5036_50361101_89_dialog_content = "分かったわ、お安い御用よ！",
  ui_story_5036_50361101_90_dialog_content = "ちょ、ちょっと待ってください！",
  ui_story_5036_50361101_91_dialog_content = "これほど大きな巨像の中にいる暗鬼を全部片づけるなんて、\n私たち4人では無理ではありませんか？",
  ui_story_5036_50361101_92_dialog_content = "そうだね…",
  ui_story_5036_50361101_93_dialog_content = "しかも、それで効果があるとも限らないんでしょ？",
  ui_story_5036_50361101_94_dialog_content = "試してみないことには分からんからなぁ。",
  ui_story_5036_50361101_95_dialog_content = "近くにいる暗鬼だけを倒して、それから壁の隙間を埋めて、\n他の暗鬼が近づけないようにするのはどう？",
  ui_story_5036_50361101_96_dialog_content = "うーん…それでも同じようなもんかな？",
  ui_story_5036_50361101_97_dialog_content = "試してみてもいいかもな。",
  ui_story_5036_50361101_98_dialog_content = "じゃあ、始めましょう！",
  ui_story_5036_50361101_99_dialog_content = "コンサートのために！",
  ui_story_5036_50361102_1_dialog_content = "PlayerName、手伝って。",
  ui_story_5036_50361102_2_dialog_content = "石を壁まで押して、隙間をふさぐの。",
  ui_story_5036_50361102_3_dialog_content = "分かった！",
  ui_story_5036_50361102_4_dialog_content = "えーいっ――！",
  ui_story_5036_50361102_5_dialog_content = "ふぅ…これで最後ね？",
  ui_story_5036_50361102_6_dialog_content = "そうだな、なかなかうまくやったじゃないか。",
  ui_story_5036_50361102_7_dialog_content = "さすが、俺が指揮しただけのことはある！",
  ui_story_5036_50361102_8_dialog_content = "ただ座って応援してただけだったような…",
  ui_story_5036_50361102_9_dialog_content = "この歳で力仕事はムリってもんさ。",
  ui_story_5036_50361102_10_dialog_content = "ですが、気味の悪い感じは薄らいだ気がしますね…",
  ui_story_5036_50361102_11_dialog_content = "そうだね。まだかすかに感じるけど、\nさっきに比べたら、ずっとよくなった。",
  ui_story_5036_50361102_12_dialog_content = "俺の仮説が正しかったようだな。",
  ui_story_5036_50361102_13_dialog_content = "次はどうすればいいの？\nほかの暗鬼も倒せばいい？",
  ui_story_5036_50361102_14_dialog_content = "これでたぶん問題はないだろう。\nあとは…",
  ui_story_5036_50361102_15_dialog_content = "戻って寝て、おかしな夢を見るかどうか確かめるだけだ！",
  ui_story_5036_50361102_16_dialog_content = "戻って寝るだけ！？",
  ui_story_5036_50361102_17_dialog_content = "仕方ないだろ？ウロボロスに関する資料は少ないんだ。\n実践で検証するしかないんだよ。",
  ui_story_5036_50361102_18_dialog_content = "それもそうね…",
  ui_story_5036_50361102_19_dialog_content = "もう遅いし、みんな疲れたでしょ。",
  ui_story_5036_50361102_20_dialog_content = "この場は戻って休むことにしましょ。\n結果も確かめられるしね。",
  ui_story_5036_50361102_21_dialog_content = "これでダメなら…また別の方法を考えるわ。",
  ui_story_5036_50361102_22_dialog_content = "これだけ努力したのです。きっと大丈夫ですよ！",
  ui_story_5036_50361102_23_dialog_content = "そうね、ありがとう！",
  ui_story_5036_50361102_24_dialog_content = "じゃあ、戻ろうか。また明日！",
  ui_story_5036_50361102_25_dialog_content = "<color=#e8d9bb>翌朝…コンサート開催まで、あと1日</color>",
  ui_story_5036_50361102_26_dialog_content = "ふう、久しぶりによく寝られたなぁ。",
  ui_story_5036_50361102_27_dialog_content = "昨日は疲れてたから、部屋に戻ってすぐに寝ちゃった…\n夢を見る余裕もなかったってところかな…",
  ui_story_5036_50361102_28_dialog_content = "あっ！PlayerName！",
  ui_story_5036_50361102_29_dialog_content = "今起きたばっかりなら、\n今日の早起きゲームはまたあたしの勝ちだね～！",
  ui_story_5036_50361102_30_dialog_content = "おはよう。昨日はよく眠れた？",
  ui_story_5036_50361102_31_dialog_content = "★3高品質の睡眠だったよ～！",
  ui_story_5036_50361102_32_dialog_content = "ここのところ毎日見てた\n空の末裔の女の子の夢も見なかったし。",
  ui_story_5036_50361102_33_dialog_content = "本当？よかった！",
  ui_story_5036_50361102_34_dialog_content = "おかしな夢が見られるなんてレアなイベントだし、\nちょっと残念だけど。",
  ui_story_5036_50361102_35_dialog_content = "アハハ…とにかく、よく眠れたならよかった。",
  ui_story_5036_50361102_36_dialog_content = "あたしはリハーサルを見に行くから、またあとでね～！",
  ui_story_5036_50361102_37_dialog_content = "うん、また後で！",
  ui_story_5036_50361102_38_dialog_content = "よかった。昨日の努力はムダじゃなかったんだ！",
  ui_story_5036_50361102_39_dialog_content = "きっとゴルディも心配してるだろうから、\n急いで教えてあげなきゃ。",
  ui_story_5036_50361102_40_dialog_content = "この時間は…たぶん、リハーサル室だね。",
  ui_story_5036_50361102_41_dialog_content = "PlayerName、おはよう！",
  ui_story_5036_50361102_42_dialog_content = "昨日は遅かったんだから、もう少し寝ててもよかったのに。",
  ui_story_5036_50361102_43_dialog_content = "十分よく寝たから、大丈夫だよ。",
  ui_story_5036_50361102_44_dialog_content = "それより、昨日の努力はムダじゃなかったみたいだよ。\nさっきガルーに聞いたんだけど、夢は見なかったって。",
  ui_story_5036_50361102_45_dialog_content = "ええ、私もほかの参加者に聞いてみたけど、\nみんなよく眠れたって！",
  ui_story_5036_50361102_46_dialog_content = "ホントによかった！",
  ui_story_5036_50361102_47_dialog_content = "ホントに…",
  ui_story_5036_50361102_48_option_content = "ゴルディ、大丈夫？",
  ui_story_5036_50361102_49_dialog_content = "なんだか疲れてるみたいだね？",
  ui_story_5036_50361102_50_dialog_content = "え？そう？",
  ui_story_5036_50361102_51_dialog_content = "アイドルなら、いつだって元気いっぱい、疲れ知らずよ！",
  ui_story_5036_50361102_52_option_content = "どうしてそんなに疲れてるの？",
  ui_story_5036_50361102_53_dialog_content = "え？そう？",
  ui_story_5036_50361102_54_dialog_content = "気のせいでしょ？私は元気いっぱいよ！",
  ui_story_5036_50361102_55_dialog_content = "（いや、今のは見間違いじゃない。もしかして…）",
  ui_story_5036_50361102_56_dialog_content = "…ずっと無理に元気なふりをしてない？",
  ui_story_5036_50361102_57_dialog_content = "…！",
  ui_story_5036_50361102_58_dialog_content = "ちょっと考えれば、すぐに分かることだよ。\n君だって昨日は遅かったんだから。",
  ui_story_5036_50361102_59_dialog_content = "それで今日は、早くから練習やオーディションの対応をしないといけない。\nどう考えても、ゆっくり休むヒマが無かったでしょ？",
  ui_story_5036_50361102_60_dialog_content = "大丈夫よ。だって、私はアイドルだもの。\nアイドルっていうのは――",
  ui_story_5036_50361102_61_option_content = "アイドルも人でしょ？",
  ui_story_5036_50361102_62_dialog_content = "アイドルだって、疲れもするし、休憩が必要だよ。",
  ui_story_5036_50361102_63_dialog_content = "どうしてこのコンサートに必死になってるのかは、\nよく知らないけど…",
  ui_story_5036_50361102_64_dialog_content = "でも、まずは仕事のことを忘れて、ゆっくり休まないと…",
  ui_story_5036_50361102_65_dialog_content = "はぁ…",
  ui_story_5036_50361102_66_dialog_content = "PlayerNameにはもういろいろ手伝ってもらってるし、\nホントのこと、話しても構わないかな…",
  ui_story_5036_50361102_67_dialog_content = "え？「ホントのこと」？",
  ui_story_5036_50361102_X67_dialog_content = "実はね…このコンサート、ファンとの約束ってだけじゃないの。\nシェオルさんとの約束でもあるのよ。",
  ui_story_5036_50361102_68_dialog_content = "…そういう契約なの。",
  ui_story_5036_50361102_69_dialog_content = "契約？シェオルさんと？",
  ui_story_5036_50361102_70_dialog_content = "シェオルさんはアイドルって言うお仕事の将来性と\n私の能力を見込んで、投資するって言ってくれたわ。",
  ui_story_5036_50361102_71_dialog_content = "だから、お金の事で私の一番の後ろ盾になってくれてるの。\nその代わり、私にはシェオルさんとの約束を実現する義務があるのよ。",
  ui_story_5036_50361102_72_dialog_content = "契約で決められた期間のうちに\n影ノ街でコンサートを開催して、そのコンサートで――",
  ui_story_5036_50361102_73_dialog_content = "「アイドル」という存在と私の名前を\n白夜城と影ノ街のみんなに広めないといけないの。",
  ui_story_5036_50361102_74_dialog_content = "シェオルさんにだまされてるんじゃない？\nいくら君でもそんなことは…",
  ui_story_5036_50361102_75_dialog_content = "私一人の人気だけじゃ、確かに無理があるわ。\nでも、きちんとした計画があれば、できないことじゃないと思ってる。",
  ui_story_5036_50361102_76_dialog_content = "ただ、途中でアクシデントがあって…\n会場が借りられなくなっちゃってたの。",
  ui_story_5036_50361102_77_dialog_content = "どうしようもないって時に、巨像のニュースを見て…\nホントに幸運が空から降ってきたと思ったわ！",
  ui_story_5036_50361102_78_dialog_content = "契約の期限は明日よ。これが最後のチャンスなの。\nだから、このコンサートは絶対に成功させるわ。",
  ui_story_5036_50361102_79_dialog_content = "失敗すれば、私はシェオルさんが負担したお金を補償するために、\n大きな借金を背負うことになる…",
  ui_story_5036_50361102_80_dialog_content = "そうなったら、アイドルとしての私はきっと、もう終わりよ。",
  ui_story_5036_50361102_81_dialog_content = "そんなプレッシャーを抱えてたなんて知らなかった…\nだとしても、がんばりすぎだよ！",
  ui_story_5036_50361102_82_dialog_content = "そんなことはないわ。\nだって、これが私の責任だもの。",
  ui_story_5036_50361102_83_dialog_content = "アイドルは、応援してくれるファンのみんなに\n歌で喜びと希望を届けるために存在するの。",
  ui_story_5036_50361102_84_dialog_content = "ファンの応援と愛がなかったら、\nアイドルも存在できないわ。",
  ui_story_5036_50361102_85_dialog_content = "自分を好きって言ってくれるファンがたくさん待ってるの。\n全身全霊で応えないなんて、できる？",
  ui_story_5036_50361102_86_dialog_content = "私の歌をもっとたくさんの人に聴いてもらうためなら、\n命を賭けてでも、頑張らなくちゃ！",
  ui_story_5036_50361102_87_dialog_content = "うん…その通りだ！",
  ui_story_5036_50361102_88_dialog_content = "でも、君は1人じゃない。\n僕も一緒に努力するよ！",
  ui_story_5036_50361102_89_dialog_content = "手伝えることがあれば何でも言って！",
  ui_story_5036_50361102_90_dialog_content = "ありがとう、PlayerName！",
  ui_story_5036_50361102_91_dialog_content = "一緒にコンサートを成功させて、\nイクストウルを守りましょ！",
  ui_story_5036_50361201_1_dialog_content = "<color=#e8d9bb>翌日、コンサート開催まで、15分</color>",
  ui_story_5036_50361201_2_dialog_content = "もうすぐ始まるわ。\nみんな、準備はいい？",
  ui_story_5036_50361201_3_dialog_content = "おーっ！",
  ui_story_5036_50361201_4_dialog_content = "いよいよ始まるのか？実に楽しみだな…",
  ui_story_5036_50361201_5_dialog_content = "（まったく、庶民どものお遊びに\nいつまで付き合わされねばならんのだ…）",
  ui_story_5036_50361201_6_dialog_content = "顔がゆがんでいる。",
  ui_story_5036_50361201_7_dialog_content = "考えていること全部、顔に出ている。",
  ui_story_5036_50361201_8_dialog_content = "黙らんか。",
  ui_story_5036_50361201_9_dialog_content = "よかった！やっとゲームが始まるね～！",
  ui_story_5036_50361201_10_dialog_content = "応援ゲームで勝負だよ！準備はいい？",
  ui_story_5036_50361201_11_dialog_content = "準備はできています…はぁ…",
  ui_story_5036_50361201_12_dialog_content = "何をモタモタしてるんだ？\nさっさと私のロックで観客全員、屈服させてやりたいぜ！",
  ui_story_5036_50361201_13_dialog_content = "もう、レジーナはおバカさんでイヤになっちゃう！\nこれはアイドルコンサートなんだよ？アイドルが主役なの！",
  ui_story_5036_50361201_14_dialog_content = "R・Wのアイドルであるバーバラこそ、\nこのステージにふさわしい存在だもんね！",
  ui_story_5036_50361201_15_dialog_content = "お前のガキのママゴトみたいな歌で、\n観客の心はつかめやしねぇ！",
  ui_story_5036_50361201_16_dialog_content = "なんですって～！？",
  ui_story_5036_50361201_17_dialog_content = "あの2人はいつも通りにぎやかだなぁ…\n騒ぎにならなきゃいいけど…",
  ui_story_5036_50361201_18_dialog_content = "そうね。あの2人にはオープニングを歌ってもらうし…",
  ui_story_5036_50361201_19_dialog_content = "そうなんだ…え？待って！？\nあの2人を？一緒に！？",
  ui_story_5036_50361201_20_dialog_content = "ほ、本当に大丈夫かな…！？",
  ui_story_5036_50361201_21_dialog_content = "実は私もちょっと心配してるの。\nでも2人とも、どうしても自分が先だって譲らなくて…",
  ui_story_5036_50361201_22_dialog_content = "だから仕方なく、一緒に出てもらうことにしたの。",
  ui_story_5036_50361201_23_dialog_content = "きっと大丈夫よ。誰にも負けないすばらしいオープニングにするって、\n自信まんまんで約束してくれたもの！",
  ui_story_5036_50361201_24_dialog_content = "「殺意まんまん」じゃなくて…？",
  ui_story_5036_50361201_25_dialog_content = "2人を信じてあげましょ！仲は悪いのかもしれないけど、\n音楽に対する気持ちは本物よ。",
  ui_story_5036_50361201_26_dialog_content = "そうだね。\nステージではちゃんと協力してくれることを願うよ…",
  ui_story_5036_50361201_27_dialog_content = "このコンサートにはイクストウルの運命もかかってるんだ！",
  ui_story_5036_50361201_28_dialog_content = "PlayerNameってイクストウルのこと、\n大切に思ってるのね。",
  ui_story_5036_50361201_29_dialog_content = "だって、動ける巨像と言えば、ソラヴァンとトラベラーの他には\nイクストウルしかいないんだ。",
  ui_story_5036_50361201_30_dialog_content = "どの巨像も、それぞれが空の末裔と密接な関わりを持ってる。\n巨像は空の末裔が存在してた証なんだよ。",
  ui_story_5036_50361201_31_dialog_content = "だから、できるだけ完全な形で残って欲しいんだ。\nそうすれば、今はもういない同族の皆も喜ぶと思う…",
  ui_story_5036_50361201_32_dialog_content = "それにイクストウルを直せたら、\nソラヴァンにも仲間ができて、寂しくなくなるかもしれないでしょ。",
  ui_story_5036_50361201_33_dialog_content = "PlayerName、安心して。私が力を貸すから！",
  ui_story_5036_50361201_34_dialog_content = "私たちもよ！",
  ui_story_5036_50361201_35_dialog_content = "万が一何かが起こったら、\n私が秩序の維持に努めるわ。",
  ui_story_5036_50361201_36_dialog_content = "やっぱりカレンは頼りになるわ！",
  ui_story_5036_50361201_37_dialog_content = "2人とも、準備万端みたいだね。",
  ui_story_5036_50361201_38_dialog_content = "当然でしょ。\n今日のために、秘密兵器まで用意してあるのよ！",
  ui_story_5036_50361201_39_dialog_content = "何を歌うつもり？",
  ui_story_5036_50361201_40_dialog_content = "最初は学生時代に歌った曲にしようと思っていたのだけれど…\nどうしても何か足りない気がしてならなかったの。",
  ui_story_5036_50361201_41_dialog_content = "一緒に旅をした時の感動、困難を乗り越えた後一緒に笑ったこと…\nもっとたくさん、共通の思いがあると思って。",
  ui_story_5036_50361201_42_dialog_content = "そうそう。\n聞いてみたら、カレンも同じことを考えてたって言うじゃない！",
  ui_story_5036_50361201_43_dialog_content = "それで、新しい曲を一緒に作ろうって話になったの！",
  ui_story_5036_50361201_44_dialog_content = "うわぁ、楽しみだなぁ！",
  ui_story_5036_50361201_45_dialog_content = "レジーナ、バーバラ、カレン、バイス、ヴィック…",
  ui_story_5036_50361201_46_dialog_content = "…あら？ヴィックはどうしたの？",
  ui_story_5036_50361201_47_dialog_content = "ヴィック？さっき来る途中で\n部屋の前を通ったけど、誰もいなかったよ。",
  ui_story_5036_50361201_48_dialog_content = "とっくに来てるのかと思ってた。",
  ui_story_5036_50361201_49_dialog_content = "PlayerNameも見てないの？",
  ui_story_5036_50361201_50_dialog_content = "もう、困ったわね…\nもうすぐ本番なのに、どこに行ったの？",
  ui_story_5036_50361201_51_dialog_content = "ウロボロスの卵を見に行ったんじゃないかな？",
  ui_story_5036_50361201_52_dialog_content = "ヴィックは珍獣のことばかり考えてるし、\nいつでもどこでも寝られるから…",
  ui_story_5036_50361201_53_dialog_content = "もしかしたら、卵の近くで寝てるのかも。",
  ui_story_5036_50361201_54_dialog_content = "探してくるよ。",
  ui_story_5036_50361201_55_dialog_content = "頼んでいい？",
  ui_story_5036_50361201_56_dialog_content = "うん、僕に任せて。",
  ui_story_5036_50361201_57_dialog_content = "話は私も聞いたわ。\n卵って、封鎖エリアにあるんでしょ？",
  ui_story_5036_50361201_58_dialog_content = "1人じゃ危険よ。私も一緒に行くわ！",
  ui_story_5036_50361201_59_dialog_content = "そうね、私も行くわ。",
  ui_story_5036_50361201_60_dialog_content = "ステージからだいぶ離れてるから、\n往復するだけでもずいぶん時間がかかるよ。",
  ui_story_5036_50361201_61_dialog_content = "2人とも出番があるでしょ？\nここでゆっくり準備しててよ。",
  ui_story_5036_50361201_62_dialog_content = "あなた1人では暗鬼と戦えないでしょう？",
  ui_story_5036_50361201_63_dialog_content = "大丈夫だよ。僕とゴルディとヴィックで、\n途中の道にいた暗鬼はあの時に全部倒してあるから。",
  ui_story_5036_50361201_64_dialog_content = "1人でも危険はないよ。",
  ui_story_5036_50361201_65_dialog_content = "分かったわ。気を付けて、急いで戻ってきてね。",
  ui_story_5036_50361201_66_dialog_content = "安心して。",
  ui_story_5036_50361201_67_dialog_content = "それじゃ、私たちもコンサートの準備よ！",
  ui_story_5036_50361201_68_dialog_content = "ヴィックが間に合わなかったら、\n2人に先に出てもらえる？",
  ui_story_5036_50361201_69_dialog_content = "ええ、分かったわ！",
  ui_story_5036_50361201_70_dialog_content = "私も異論はないわ。",
  ui_story_5036_50361201_71_dialog_content = "まだ始まらないのか？",
  ui_story_5036_50361201_72_dialog_content = "もうすぐだろ、ほら見ろよ！",
  ui_story_5036_50361201_73_dialog_content = "みんな、お待たせ～！",
  ui_story_5036_50361201_74_dialog_content = "シャイニングスターズ――空中コンサート、いよいよスタートよ～！",
  ui_story_5036_50361201_75_dialog_content = "うお――！！",
  ui_story_5036_50361201_76_dialog_content = "<color=#e8d9bb>その頃</color>",
  ui_story_5036_50361201_77_dialog_content = "あら？あれは何かしら…？",
  ui_story_5036_50361201_78_dialog_content = "雲の間から、キラキラしたものが…巨像かしら？",
  ui_story_5036_50361201_79_dialog_content = "何だかにぎやかね。\n今、空中コンサートと聞こえた？",
  ui_story_5036_50361201_80_dialog_content = "最近極夜地帯から流れてきたという、巨像でございますね。",
  ui_story_5036_50361201_81_dialog_content = "アイドルを名乗るゴルディと言う人物が、\nあの巨像の上で演奏会を開催するとか…",
  ui_story_5036_50361201_82_dialog_content = "影ノ街の新聞に掲載されておりました。",
  ui_story_5036_50361201_83_dialog_content = "そうなの？おもしろそうね。",
  ui_story_5036_50361201_84_dialog_content = "どこかいい場所を探して、\n何が起こるか見てみましょう。",
  ui_story_5036_50361201_85_dialog_content = "かしこまりました。",
  ui_story_5036_50361201_86_dialog_content = "お姉ちゃん、見て！おっきな物が飛んでる！",
  ui_story_5036_50361201_87_dialog_content = "本当だ、巨像だわ！",
  ui_story_5036_50361201_88_dialog_content = "あれは…なんだろう？\n誰かが写ってるみたいだけど…",
  ui_story_5036_50361201_89_dialog_content = "あっ！あの時の、歌の上手なお姉ちゃんじゃない！？",
  ui_story_5036_50361201_90_dialog_content = "ホントだ！歌のお姉ちゃんだ！コンサートの場所、見つかったんだね！\n巨像の上でやるなんて！",
  ui_story_5036_50361201_91_dialog_content = "チケットがなくても、ちゃんと聞こえるよ。\nホントにスゴイなぁ！",
  ui_story_5036_50361201_92_dialog_content = "あっちに飛んでいったわ。\n私たちも急いで追いつきましょ！",
  ui_story_5036_50361201_93_dialog_content = "川に沿って走るの。\n歌のお姉ちゃんを応援しに行くよ！",
  ui_story_5036_50361201_94_dialog_content = "みんなの熱い思い、ここまで届いてるわ～！",
  ui_story_5036_50361201_95_dialog_content = "まずは、R・W砂漠からやってきたアイドル！\n炎のような情熱いっぱいの歌でオープニングよ！",
  ui_story_5036_50361201_96_dialog_content = "レジーナとバーバラの2人！拍手で迎えてあげて！",
  ui_story_5036_50361201_97_dialog_content = "激しい炎で燃やし尽くせ！",
  ui_story_5036_50361201_98_dialog_content = "私の愛を捧げるよ～♪",
  ui_story_5036_50361201_99_dialog_content = "<size=40>押し寄せろ、吹っ飛ばせ、ブッ壊せ！！</size>",
  ui_story_5036_50361201_100_dialog_content = "<size=45>♪あなたに会える、ときめく心♪</size>",
  ui_story_5036_50361201_101_dialog_content = "（チッ！あっちの音がデケぇ…！）/（もう！あっちの音が大きい…！）",
  ui_story_5036_50361201_102_dialog_content = "（負けてられるか！！！）/（負けられない！！！）",
  ui_story_5036_50361201_103_dialog_content = "<size=40>♪そうだ、俺たちは――♪</size>",
  ui_story_5036_50361201_104_dialog_content = "<size=45>♪ホントのことを聞かせて～、だって私は――♪</size>",
  ui_story_5036_50361201_105_dialog_content = "<size=50>♪ロックンローラー！！！♪</size>",
  ui_story_5036_50361201_106_dialog_content = "<size=50>♪アイドル！！！♪</size>",
  ui_story_5036_50361201_107_dialog_content = "なんだ、この歌は…？\n歌詞はバラバラだし、音もデカすぎる！！",
  ui_story_5036_50361201_108_dialog_content = "何が何だか分からないぞ！\nとにかくうるさいだけだ！",
  ui_story_5036_50361201_109_dialog_content = "たいへん！ステージでケンカを始めちゃったの！？\n仲良く協力するって約束だったのに…",
  ui_story_5036_50361201_110_dialog_content = "このままじゃアクシデントだわ！\n軌道修正しないと…",
  ui_story_5036_50361201_111_dialog_content = "♪砂漠みたいに熱い思い、胸がドキドキ～♪",
  ui_story_5036_50361201_112_dialog_content = "（おい、どういうことだ？\n司会が急に歌いだしたぞ！？）",
  ui_story_5036_50361201_113_dialog_content = "（リハーサルにはこんなのなかったよ！？）",
  ui_story_5036_50361201_114_dialog_content = "（2人に伝わるといいんだけど…\nお願い！私の幸運！）",
  ui_story_5036_50361201_115_dialog_content = "♪あなたに伝えたい、この気持ち…\nそれは――♪",
  ui_story_5036_50361201_116_dialog_content = "♪それは――♪",
  ui_story_5036_50361201_117_dialog_content = "♪それは――♪",
  ui_story_5036_50361201_118_dialog_content = "<size=45>ラブ！！！</size>",
  ui_story_5036_50361201_119_dialog_content = "永遠に燃えろ！",
  ui_story_5036_50361201_120_dialog_content = "ずっとずっと変わらない～♪",
  ui_story_5036_50361201_121_dialog_content = "<size=50>赤く燃え上がれ、レディーゼルオイルのように♪</size>",
  ui_story_5036_50361201_122_dialog_content = "（よかった、成功ね！\n2人ともやっと息が合ったわ…）",
  ui_story_5036_50361201_123_dialog_content = "（今のうちにステージを下りましょ…）",
  ui_story_5036_50361201_124_dialog_content = "ロックだ！突き進め、振り返るな！",
  ui_story_5036_50361201_125_dialog_content = "私の気持ちを手に取って～♪",
  ui_story_5036_50361201_126_dialog_content = "<size=50>響き渡れ、この歌♪</size>",
  ui_story_5036_50361201_127_dialog_content = "ん？だんだんいい感じになってきたな…",
  ui_story_5036_50361201_128_dialog_content = "ゴルディさん、ステキです！\nできる限りすべてをカメラに収めなくては！",
  ui_story_5036_50361201_129_dialog_content = "まったく異なる曲調が一つに調和するなんて、面白い試みだわ。\n観客も増えてきたようね…",
  ui_story_5036_50361201_130_dialog_content = "実に興味深いわ！\n白夜城では見たことが無いたぐいのコンサートね！",
  ui_story_5036_50361201_131_dialog_content = "巨像は飛び去っていくようですね。",
  ui_story_5036_50361201_132_dialog_content = "うちの飛空艇を出しなさい。",
  ui_story_5036_50361201_133_dialog_content = "！？",
  ui_story_5036_50361201_134_dialog_content = "こんな面白そうな物、\n一等席で観なければ、後悔するわ！",
  ui_story_5036_50361201_135_dialog_content = "巨像でコンサートだと！？\n今まで見たこともないぞ！",
  ui_story_5036_50361201_136_dialog_content = "フフ…盛り上がって来たわね。",
  ui_story_5036_50361201_137_dialog_content = "商人も大勢集まり始めてる…\n船で追いかけてまで観てる人もいるわね。",
  ui_story_5036_50361201_138_dialog_content = "あの子に投資して正解だったわ。",
  ui_story_5036_50361201_139_dialog_content = "ヴィックとPlayerNameがまだ戻らないの？",
  ui_story_5036_50361201_140_dialog_content = "そうみたい。",
  ui_story_5036_50361201_141_dialog_content = "世話が焼けるわね…",
  ui_story_5036_50361201_142_dialog_content = "仕方ないわ。\n先にステージに上がってもらえる？",
  ui_story_5036_50361201_143_dialog_content = "ええ！",
  ui_story_5036_50361201_144_dialog_content = "2人とも、情熱的な歌をありがとう！",
  ui_story_5036_50361201_145_dialog_content = "皆も盛り上がってる？\n私もドキドキしてきたわ！",
  ui_story_5036_50361201_146_dialog_content = "お次の登場は――\nみんなも聞いたことあるかしら？",
  ui_story_5036_50361201_147_dialog_content = "1人は白夜城の騎士でプリンセス、\nもう1人は啓光連邦の軍人…",
  ui_story_5036_50361201_148_dialog_content = "でも、所属の違いを乗り越えて、\n最高の友だちとして、空の末裔と一緒に冒険を続ける、ウワサの2人！",
  ui_story_5036_50361201_149_dialog_content = "今日は、2人の旅の美しい思い出を曲にして、\nみんなと分かち合ってくれるそうよ！",
  ui_story_5036_50361201_150_dialog_content = "では、バイスとカレンの2人！\n拍手で迎えてあげて！",
  ui_story_5036_50361201_151_dialog_content = "お客さんでいっぱいね。\nPlayerNameが見てないのは、ちょっと残念だけど…",
  ui_story_5036_50361201_152_dialog_content = "緊張する必要はないわ。\n私たちなら大丈夫。",
  ui_story_5036_50361201_153_dialog_content = "そうね！じゃあ、始めましょ！",
  ui_story_5036_50361201_154_dialog_content = "♪思いもよらないことばかり♪",
  ui_story_5036_50361201_155_dialog_content = "♪地図にもない旅路の先には♪",
  ui_story_5036_50361201_156_dialog_content = "♪何が待っているの？♪",
  ui_story_5036_50361201_157_dialog_content = "♪期待に胸を膨らませ♪",
  ui_story_5036_50361201_158_dialog_content = "♪あなたと出会い、共に進む道♪",
  ui_story_5036_50361201_159_dialog_content = "♪離れ離れになっても、必ずまた一緒に歩けるわ♪",
  ui_story_5036_50361201_160_dialog_content = "♪共に歩む旅路♪",
  ui_story_5036_50361201_161_dialog_content = "♪出会って、そして一緒に泣いて笑って♪",
  ui_story_5036_50361201_162_dialog_content = "♪いつまでも照らし合う仲間♪",
  ui_story_5036_50361201_163_dialog_content = "♪空を巡る2つの星♪",
  ui_story_5036_50361201_164_dialog_content = "ガルーが事前に設置しておいてくれた伝送装置のおかげで、\nここからでも巨像のコンサートが楽しめます。",
  ui_story_5036_50361201_165_dialog_content = "新しい形式の娯楽として、\n参考にする価値がありますね…",
  ui_story_5036_50361201_166_dialog_content = "シェルター内部でも小規模なテストを実施して、\n効果を確かめてみてはいかがでしょう？",
  ui_story_5036_50361201_167_dialog_content = "よかろう、やってみろ。",
  ui_story_5036_50361201_168_dialog_content = "え？は、はい、了解しました！",
  ui_story_5036_50361201_169_dialog_content = "驚いているようだな。何かあったか？",
  ui_story_5036_50361201_170_dialog_content = "いえ、大元帥様は娯楽に対して\n慎重な態度をとられるものとばかり…",
  ui_story_5036_50361201_171_dialog_content = "ハハハ、むろん、慎重な態度だ。\nだが、よく見てみろ。",
  ui_story_5036_50361201_172_dialog_content = "私に歌のことはよく分からんが、\nバイス中尉が今、心から楽しんでいるということは分かる。",
  ui_story_5036_50361201_173_dialog_content = "そのような高揚こそ、\n我々に必要なものではないか？",
  ui_story_5036_50361201_174_dialog_content = "こんなところまで\nカレンちゃんとバイスちゃんの歌が聞こえてくるなんて…",
  ui_story_5036_50361201_175_dialog_content = "すっごく上手！\nさっすがカレンちゃん！",
  ui_story_5036_50361201_176_dialog_content = "ラファエル。\nお前はここに残り、警備を強化せよ。",
  ui_story_5036_50361201_177_dialog_content = "それから、飛空艇を準備させるのだ。\nただし、静かにことを運べ。",
  ui_story_5036_50361201_178_dialog_content = "え？城主様、今からお出かけですか？",
  ui_story_5036_50361201_179_dialog_content = "あの巨像にはいかなる脅威があるか、いまだ分かっておらぬ。\n城主たる余が直々に調べ、万一に備えねばなるまい。",
  ui_story_5036_50361201_180_dialog_content = "は、はい！",
  ui_story_5036_50361201_181_dialog_content = "…はぁ…",
  ui_story_5036_50361201_182_dialog_content = "城主様、いつになったら、\nカレンちゃんがかわいいって素直に言えるようになるんだろ？",
  ui_story_5036_50361201_183_dialog_content = "<color=#e8d9bb>その頃、イクストウル内部</color>",
  ui_story_5036_50361201_184_dialog_content = "この声は…バイスとカレンの歌だ！",
  ui_story_5036_50361201_185_dialog_content = "もう2人の番が回ってきちゃったのか。\nゆっくり歩きすぎたかな…",
  ui_story_5036_50361201_186_dialog_content = "そろそろ着くはずなんだけど…",
  ui_story_5036_50361201_187_dialog_content = "さすが一緒に冒険してきた仲間同士、息がぴったりね！",
  ui_story_5036_50361201_188_dialog_content = "さて、ここでちょっとお話…\n「アイドル」っていう言葉が持つ意味は、人それぞれかもしれないわ。",
  ui_story_5036_50361201_189_dialog_content = "でも、アイドルが皆の力を一つにできる存在っていうことは、\nみんなも同じ考えだと思うの。",
  ui_story_5036_50361201_190_dialog_content = "次にステージに上がってもらうのは、\n啓光連邦でみんなの心を一つにまとめてきた、啓光合唱団のみんなよ…",
  ui_story_5036_50361201_191_dialog_content = "心が燃えるような軍歌を披露してもらっちゃうわ！",
  ui_story_5036_50361201_192_dialog_content = "わあああ！！",
  ui_story_5036_50361201_193_dialog_content = "ふぅ～、バイス、カレン、お疲れ様！",
  ui_story_5036_50361201_194_dialog_content = "私たちはなんてことないわ！",
  ui_story_5036_50361201_195_dialog_content = "でも、もうずいぶん経つのに、\nPlayerNameとヴィックがまだ戻ってないわね。",
  ui_story_5036_50361201_196_dialog_content = "確かにおかしいわね。巨像の中が広いとはいっても、\nこれほど時間がかかるはずはない。",
  ui_story_5036_50361201_197_dialog_content = "ううん…",
  ui_story_5036_50361201_198_dialog_content = "カレン、やっぱり探しに行きましょ。",
  ui_story_5036_50361201_199_dialog_content = "私もそう思っていたところよ。\n出番も終わったことだし、万が一を考えた方がよさそうね。",
  ui_story_5036_50361201_200_dialog_content = "分かったわ。2人とも気を付けて。\nカーテンコールまでには戻ってきてね！",
  ui_story_5036_50361201_201_dialog_content = "ええ。",
  ui_story_5036_50361201_202_dialog_content = "行きましょう。",
  ui_story_5036_50361201_203_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_5036_50361201_204_dialog_content = "啓光合唱団どころか、\n白夜城の聖歌隊の歌ももうすぐ終わっちゃう…",
  ui_story_5036_50361201_205_dialog_content = "PlayerNameたち、どうしちゃったのかしら？\nやっぱり、何かあったんじゃ…？",
  ui_story_5036_50361201_206_dialog_content = "心配だわ…でも、トリの私がもうすぐ出番なのに、\nステージを離れるわけにはいかないし…",
  ui_story_5036_50361201_207_dialog_content = "あの歌はどうしても、聴いてもらいたい…",
  ui_story_5036_50361201_208_dialog_content = "PlayerNameたちと私の努力の結晶だもの…",
  ui_story_5036_50361201_209_dialog_content = "歌い終わったら、探しに行かないと…",
  ui_story_5036_50361201_210_dialog_content = "コンサートももうすぐおしまい！\nみんな、存分に楽しんでもらえた？",
  ui_story_5036_50361201_211_dialog_content = "まだまだ足りな～い！！",
  ui_story_5036_50361201_212_dialog_content = "ありがとう！みんなの熱い思い、受け取ったわ！",
  ui_story_5036_50361201_213_dialog_content = "最後の曲は…私の歌よ！",
  ui_story_5036_50361201_214_dialog_content = "おお！！いよいよゴルディが歌うぞ！",
  ui_story_5036_50361201_215_dialog_content = "この曲には、特別な意味があるの。\n空の末裔たちが巨像と交流する時に使っていたメロディを歌にしたものよ。",
  ui_story_5036_50361201_216_dialog_content = "空の末裔はこのメロディで巨像を動かして、\n世界を巡っていたの。",
  ui_story_5036_50361201_217_dialog_content = "そして今、100年の旅を終えて戻ってきたこの巨像の上で、\n空の末裔のメロディが再び響き渡ることになるわ！！",
  ui_story_5036_50361201_218_dialog_content = "うお――！！",
  ui_story_5036_50361201_219_dialog_content = "（そう、今よ…この瞬間が、一番大事な時！）",
  ui_story_5036_50361201_220_dialog_content = "ディディ！ディディ！",
  ui_story_5036_50361201_221_dialog_content = "（この曲でみんなの愛とPlayerNameの頑張りに応えてみせる！）",
  ui_story_5036_50361201_222_dialog_content = "♪星たちよ、空に輝く光♪",
  ui_story_5036_50361201_223_dialog_content = "♪渡り鳥は翼を広げ♪",
  ui_story_5036_50361201_224_dialog_content = "♪はるか彼方へ飛び立つ♪",
  ui_story_5036_50361201_225_dialog_content = "♪星の光の導きよ、どこまでも♪",
  ui_story_5036_50361201_226_dialog_content = "ゴルディ！ゴルディ！",
  ui_story_5036_50361201_227_dialog_content = "ああ…ゴルディさんの歌を生で聴けるとは…",
  ui_story_5036_50361201_228_dialog_content = "これまでの苦労もムダではありませんでした！",
  ui_story_5036_50361201_229_dialog_content = "♪出会いへの期待に♪",
  ui_story_5036_50361201_230_dialog_content = "♪勇気があふれ、心が躍る♪",
  ui_story_5036_50361201_231_dialog_content = "（え…？急に眠くなってきた…）",
  ui_story_5036_50361201_232_dialog_content = "（ダメ、まだ歌の途中よ！）",
  ui_story_5036_50361201_233_dialog_content = "♪前に進むの♪",
  ui_story_5036_50361201_234_dialog_content = "♪あなたに会える、その場所まで♪",
  ui_story_5036_50361201_235_dialog_content = "（どういうこと…？なんだか…目の前が…）",
  ui_story_5036_50361201_236_dialog_content = "キュウ――！",
  ui_story_5036_50361201_237_dialog_content = "（この声…どこから…？）",
  ui_story_5036_50361201_238_dialog_content = "（目が…でも、ダメ、寝てはダメ…だって、コンサートが、まだ…）",
  ui_story_5036_50361301_1_dialog_content = "<color=#e8d9bb>その頃、封鎖エリア</color>",
  ui_story_5036_50361301_2_dialog_content = "どういうこと…？\nまた同じ場所に出た…？",
  ui_story_5036_50361301_3_dialog_content = "この前と同じ道を歩いてるはず…\nなんで着かないんだろう…？",
  ui_story_5036_50361301_4_dialog_content = "まさか、ウロボロスの力がまた戻ってる…？",
  ui_story_5036_50361301_5_dialog_content = "だいぶ時間がかかってる…\nコンサート、もうすぐ終わっちゃうんじゃないかな？",
  ui_story_5036_50361301_6_dialog_content = "あ、あれは…！やっと着いた…",
  ui_story_5036_50361301_7_dialog_content = "ん？PlayerNameか。\nどうしてこんな所にいるんだ？",
  ui_story_5036_50361301_8_dialog_content = "コンサートがつまらなすぎて、\nこっそり昼寝でもしに来たか？",
  ui_story_5036_50361301_9_dialog_content = "僕はそんなに無責任じゃないよ！",
  ui_story_5036_50361301_10_dialog_content = "ヴィックこそ、どうしてここにいるの！？\n皆が君を待ってるんだよ！",
  ui_story_5036_50361301_11_dialog_content = "俺の出番？ああ、歌のことか…",
  ui_story_5036_50361301_12_dialog_content = "俺にはムリだ。",
  ui_story_5036_50361301_13_dialog_content = "どうして！？素質があるってゴルディも言ってたし、\n振り付けまでしてもらったでしょ？今になって逃げ出すってこと？",
  ui_story_5036_50361301_14_dialog_content = "ハハハ…確かにそんなこともあったが、\n俺には本当にムリなんだよ。",
  ui_story_5036_50361301_15_dialog_content = "他のヤツらの練習を見ただろ？",
  ui_story_5036_50361301_16_dialog_content = "ステージに上がるには長い間の練習と情熱が必要だ。\n悪いが、俺にはどちらもありゃしない。",
  ui_story_5036_50361301_17_dialog_content = "コンサートにも、アイドルにも、興味はないさ。\n年寄りにはキツいしな。",
  ui_story_5036_50361301_18_dialog_content = "ステージに上がったって、\n若いヤツらの足を引っ張るだけ…",
  ui_story_5036_50361301_19_dialog_content = "出来もしないことに手を出すより、出来ることをやった方がいいだろ？\n卵がコンサートの邪魔をしないように見張ってるとかな。",
  ui_story_5036_50361301_20_dialog_content = "…興味ないって言いながら、コンサートのこと、\nちゃんと気にしてるんだね。",
  ui_story_5036_50361301_21_dialog_content = "ガキどもに借りを作りたくないだけさ。",
  ui_story_5036_50361301_22_dialog_content = "もう十分、作ってると思うけど…",
  ui_story_5036_50361301_23_dialog_content = "オッホン！弟子は別だ！\nあれは教育上必要なことだからな！",
  ui_story_5036_50361301_24_dialog_content = "それより、ここに来るまでに感じなかったか？\nウロボロスの能力がまた戻ってるんだ。",
  ui_story_5036_50361301_25_dialog_content = "感じたよ。おかげでずいぶん道に迷った。",
  ui_story_5036_50361301_26_dialog_content = "つまり、ウロボロスが何かの危険を感じて、\n身を守ろうとしてるってことだ。",
  ui_story_5036_50361301_27_dialog_content = "でも、この辺りの暗鬼は全部倒してあるし、\n隙間も塞いだんだよ？",
  ui_story_5036_50361301_28_dialog_content = "近くに誰もいないからかもな。",
  ui_story_5036_50361301_29_dialog_content = "今はコンサートの真っ最中だろ？\n全員がここから一番遠い、巨像の頭の方のステージに集まってる。",
  ui_story_5036_50361301_30_dialog_content = "ここで何か起こっても、\n俺たち以外は間に合わないだろうな。",
  ui_story_5036_50361301_31_dialog_content = "それでウロボロスが不安になったってこと？",
  ui_story_5036_50361301_32_dialog_content = "そうかもって話だ。",
  ui_story_5036_50361301_33_dialog_content = "まったく、ウロボロスってのはずいぶん臆病な生き物らしいな。\nこの巨像で長い間隠れてたってのに、今さら怖がるなんて。",
  ui_story_5036_50361301_34_dialog_content = "出会いがあるから、別れが怖くなるんだよ。",
  ui_story_5036_50361301_35_dialog_content = "僕も巨像で17年間1人で暮らしてた時は、\nソラヴァンがいてくれたし、孤独なんて感じなかった。",
  ui_story_5036_50361301_36_dialog_content = "でも今、皆と離れ離れになれって言われたら、\n僕はきっと、やっぱり離れたくないって思うよ。",
  ui_story_5036_50361301_37_dialog_content = "そうだな。",
  ui_story_5036_50361301_38_dialog_content = "ところで、さっき「邪魔しないように」って言ってたけど…",
  ui_story_5036_50361301_39_dialog_content = "コンサートはもう始まってるんだよ。\n邪魔される可能性なんてあるの？",
  ui_story_5036_50361301_40_dialog_content = "お？意外と鋭いねぇ。",
  ui_story_5036_50361301_41_dialog_content = "言ったろ。原因はよく分からんが、この卵はずっと孵化しなかった。\nだから、こんなにデカくなったんだって。",
  ui_story_5036_50361301_42_dialog_content = "逆に言えば、いつ孵化するかも分からないってことだ。",
  ui_story_5036_50361301_43_dialog_content = "卵でこの大きさじゃ、出てきたウロボロスがちょっとでも動いたら、\n巨像全体に影響が及ぶだろうな。",
  ui_story_5036_50361301_44_dialog_content = "えっ…！？",
  ui_story_5036_50361301_45_dialog_content = "つまり…この卵はいつ爆発するか分からない\n爆弾と同じぐらい危険ってこと！？",
  ui_story_5036_50361301_46_dialog_content = "そういうこった。",
  ui_story_5036_50361301_47_dialog_content = "だから、卵を見てないといけないのさ。\nコンサート成功のためだけじゃない。俺たちの安全のためにもな。",
  ui_story_5036_50361301_48_dialog_content = "見落としがちな危険に気付けたんだ。\nPlayerNameには珍獣研究の素質があるかもな。",
  ui_story_5036_50361301_49_dialog_content = "どうだ、俺の弟子になってみるか？",
  ui_story_5036_50361301_50_option_content = "いいね",
  ui_story_5036_50361301_51_dialog_content = "珍獣って面白そうだし、\n絶滅しそうな種族もたくさんいるんでしょ？",
  ui_story_5036_50361301_52_dialog_content = "保護できれば、すごく意味があると思う。",
  ui_story_5036_50361301_53_dialog_content = "よく言った、PlayerName。\nいや、もう弟子と呼ぶべきか？",
  ui_story_5036_50361301_54_dialog_content = "先に言っておくけど、君の使いっ走りはしないよ。",
  ui_story_5036_50361301_55_dialog_content = "おいおい、ひどいなぁ。\nそんなことをさせるようなヤツだと思ってたのか？",
  ui_story_5036_50361301_56_option_content = "やめておくよ",
  ui_story_5036_50361301_57_dialog_content = "珍獣研究には興味あるけど、\nフィアやシーラの苦労を知ってるから…",
  ui_story_5036_50361301_58_dialog_content = "動物どころか師匠の面倒も見なくちゃいけないし、\nしかも調査の経費も出ないなんて…",
  ui_story_5036_50361301_59_dialog_content = "普通の人じゃ耐えられないよ！",
  ui_story_5036_50361301_60_dialog_content = "俺たちの原動力は珍獣への愛だ。\nそもそも、見返りなんざ求めちゃいないのさ。",
  ui_story_5036_50361301_61_dialog_content = "ま、イヤだって言うなら、無理強いはしないさ。",
  ui_story_5036_50361301_62_dialog_content = "それにしても、来るまでにずいぶん時間がかかっちゃったよ。\nコンサート、どうなってるだろう？",
  ui_story_5036_50361301_63_dialog_content = "とりあえず、戻ってゴルディに伝えるね。\n皆が心配してるから。",
  ui_story_5036_50361301_64_dialog_content = "ああ、じゃあ俺はこのまま――",
  ui_story_5036_50361301_65_dialog_content = "キュウ――！",
  ui_story_5036_50361301_66_dialog_content = "今の音は…？",
  ui_story_5036_50361301_67_dialog_content = "何にも聞こえないぞ？幻聴じゃないのか？",
  ui_story_5036_50361301_68_dialog_content = "カレン、今、ヘンな音が聞こえなかった？",
  ui_story_5036_50361301_69_dialog_content = "動物の鳴き声かしら…？",
  ui_story_5036_50361301_70_dialog_content = "うっ…",
  ui_story_5036_50361301_71_dialog_content = "カレン！？大丈夫？どうして急に…",
  ui_story_5036_50361301_72_dialog_content = "急に…こんなに…眠く…",
  ui_story_5036_50361301_73_dialog_content = "ウロボロスの鳴き声…みたいな…",
  ui_story_5036_50361301_74_dialog_content = "（あれ？どうして急に…眠く…）",
  ui_story_5036_50361301_75_dialog_content = "PlayerName？どうした？おい、起きろ！",
  ui_story_5036_50361301_76_dialog_content = "仕方ない、奥の手だ…ビッカー！\n今のうちだ！こいつのポケットの中の白夜コイン、全部食べていいぞ！",
  ui_story_5036_50361301_77_dialog_content = "ハイ！",
  ui_story_5036_50361301_78_dialog_content = "えっ！？ちょ、ちょっと、やめて！！",
  ui_story_5036_50361301_79_dialog_content = "苦労して貯めたお小遣いなんだ！！",
  ui_story_5036_50361301_80_dialog_content = "目が覚めたみたいだな。",
  ui_story_5036_50361301_81_dialog_content = "徹夜でもしてたのか？\n気絶したのかと思ったぞ。",
  ui_story_5036_50361301_82_dialog_content = "徹夜？そんなことないよ。\n昨日はちゃんと早寝したんだ。",
  ui_story_5036_50361301_83_dialog_content = "おかしいなぁ。ウロボロスの鳴き声を聞いたとたん、\n急にものすごく眠くなって…",
  ui_story_5036_50361301_84_dialog_content = "ウロボロスの鳴き声？\n俺には何も聞こえなかったぞ？",
  ui_story_5036_50361301_85_dialog_content = "本当だよ！信じられないなら、よく耳を澄ませてみてよ！\nまた聞こえるかもしれないから。",
  ui_story_5036_50361301_86_dialog_content = "そうか？どれどれ…",
  ui_story_5036_50361301_87_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5036_50361301_88_dialog_content = "やっぱり聞こえないぞ。\n気のせいじゃないのか？",
  ui_story_5036_50361301_89_dialog_content = "でも…",
  ui_story_5036_50361301_90_dialog_content = "<color=#e8d9bb>ドクン――</color>",
  ui_story_5036_50361301_91_dialog_content = "また何か音がした！\nでも、今度は鳴き声じゃない！",
  ui_story_5036_50361301_92_dialog_content = "この音は…！",
  ui_story_5036_50361301_93_dialog_content = "今度は聞こえたの？",
  ui_story_5036_50361301_94_dialog_content = "<color=#e8d9bb>ドクン――ドクン――</color>",
  ui_story_5036_50361301_95_dialog_content = "ああ、はっきりとな。",
  ui_story_5036_50361301_96_dialog_content = "…心臓の鼓動の音だ。",
  ui_story_5036_50361301_97_dialog_content = "卵から聞こえてくる。",
  ui_story_5036_50361301_98_dialog_content = "え！？\nつまり…ウロボロスの卵が、いまかえるって事？",
  ui_story_5036_50361301_99_dialog_content = "…ったく、こんな時に…タイミングが悪いな。",
  ui_story_5036_50361301_100_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_5036_50361301_101_dialog_content = "今度は何！？",
  ui_story_5036_50361301_102_dialog_content = "PlayerName、気を付けろ！",
  ui_story_5036_50361301_103_dialog_content = "このあいだ塞いだ隙間に何かがぶつかってきてるぞ！",
  ui_story_5036_50361301_104_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_5036_50361301_105_dialog_content = "グオオ――！",
  ui_story_5036_50361301_106_dialog_content = "ヴィック！暗鬼が！",
  ui_story_5036_50361301_107_dialog_content = "モジャ！助けてくれ！",
  ui_story_5036_50361302_1_dialog_content = "どうして暗鬼がこんなにたくさん！？",
  ui_story_5036_50361302_2_dialog_content = "辺りの暗鬼は全部片づけたはずだよ？",
  ui_story_5036_50361302_3_dialog_content = "たぶん別のところから、わざわざ来たんだろう。",
  ui_story_5036_50361302_4_dialog_content = "急に暴れだすなんて…\nウロボロスのふ化と関係あるのかもしれないな。",
  ui_story_5036_50361302_5_dialog_content = "とにかく、ゴルディたちに知らせなきゃ！",
  ui_story_5036_50361302_6_dialog_content = "ウロボロスが動き出すなら、\n巨像にいるのは危ない！",
  ui_story_5036_50361302_7_dialog_content = "皆を避難させないと！",
  ui_story_5036_50361302_8_dialog_content = "確かに、ここにいるのは得策じゃないな。",
  ui_story_5036_50361302_9_dialog_content = "ウロボロスが動き出したら、\n部屋ごと崩れちまうかもしれないし…",
  ui_story_5036_50361302_10_dialog_content = "俺もさっさと退散するか。",
  ui_story_5036_50361302_11_dialog_content = "こっちだ、PlayerName！\nしっかりついて来いよ！",
  ui_story_5036_50361302_12_dialog_content = "待って！あそこに誰か倒れてない！？",
  ui_story_5036_50361302_13_dialog_content = "…バイスとカレンだ！？",
  ui_story_5036_50361302_14_dialog_content = "2人とも、起きて！",
  ui_story_5036_50361302_15_dialog_content = "どうしたんだろう…？\n全然起きない…",
  ui_story_5036_50361302_16_dialog_content = "こいつもウロボロスのせいか？",
  ui_story_5036_50361302_17_dialog_content = "その2人も連れて逃げるぞ！\nここにいたら危ない！",
  ui_story_5036_50361302_18_dialog_content = "うん、2人は僕が連れてく！",
  ui_story_5036_50361302_19_dialog_content = "よいしょ――うわあ！",
  ui_story_5036_50361302_20_dialog_content = "PlayerName、鍛え方が足りないみたいだな！",
  ui_story_5036_50361302_21_dialog_content = "皮肉を言ってる場合じゃないよ！\n早く、手伝って！",
  ui_story_5036_50361302_22_dialog_content = "俺じゃ何の助けにもならないぜ。\nそういうわけだから――",
  ui_story_5036_50361302_23_dialog_content = "モジャ、出番だ！",
  ui_story_5036_50361302_24_dialog_content = "ウキュッ！",
  ui_story_5036_50361302_25_dialog_content = "モジャって大きくなれたの！？",
  ui_story_5036_50361302_26_dialog_content = "そういう珍獣だからな。\nしかも、毛の柔らかさはそのままだ。",
  ui_story_5036_50361302_27_dialog_content = "枕にすると寝心地が最高なんだ。\nちょっと触ってみろよ、初回は無料にしてやる。",
  ui_story_5036_50361302_28_dialog_content = "今は遠慮しとくよ…",
  ui_story_5036_50361302_29_dialog_content = "とにかく、モジャ！\nバイスとカレンをお願い！",
  ui_story_5036_50361302_30_dialog_content = "ウキュウ――！",
  ui_story_5036_50361302_31_dialog_content = "行こう、急いで皆のところに戻らなきゃ！",
  ui_story_5036_50361302_32_dialog_content = "これは…",
  ui_story_5036_50361302_33_dialog_content = "全員眠っちまったか…",
  ui_story_5036_50361302_34_dialog_content = "ゴルディは…ステージに倒れてるな。",
  ui_story_5036_50361302_35_dialog_content = "…",
  ui_story_5036_50361302_36_dialog_content = "ゴルディ！起きて！",
  ui_story_5036_50361302_37_dialog_content = "ダメだ、起きない…",
  ui_story_5036_50361302_38_dialog_content = "妙な状態だな。光力の影響がある。",
  ui_story_5036_50361302_39_dialog_content = "やっぱりウロボロスの影響？",
  ui_story_5036_50361302_40_dialog_content = "でも、ウロボロスが原因なら、どうして僕たち2人は何ともなくて、\n他の皆は眠ったままなの？",
  ui_story_5036_50361302_41_dialog_content = "俺たちが特別だからさ。",
  ui_story_5036_50361302_42_dialog_content = "お前は空の末裔で、\n感知っていう精神に関わる不思議な能力を持ってる…",
  ui_story_5036_50361302_43_dialog_content = "でもって、俺はウロボロスと血のつながりがあるらしいからな。\n抵抗力みたいのがあるんじゃないか？",
  ui_story_5036_50361302_44_dialog_content = "皆を起こす方法はないの？",
  ui_story_5036_50361302_45_dialog_content = "さあなぁ…",
  ui_story_5036_50361302_46_dialog_content = "でも…ウロボロスと深いつながりがあるんでしょ？\n何も知らないの？",
  ui_story_5036_50361302_47_dialog_content = "悪いが、つながりがあるったって、寿命が少し長いぐらいでな…\n別に特殊能力があるわけじゃないんだ。",
  ui_story_5036_50361302_48_dialog_content = "そっちこそ、試してみたらどうだ？",
  ui_story_5036_50361302_49_dialog_content = "感知能力を使えば、\n俺には分からないことが分かるかもしれないぞ？",
  ui_story_5036_50361302_50_dialog_content = "分かった。やってみるしかないね…",
  ui_story_5036_50361401_1_dialog_content = "私は…眠っちゃったはず…",
  ui_story_5036_50361401_2_dialog_content = "ここは…天空ノ谷？\nまさか、また夢を見てるの？",
  ui_story_5036_50361401_3_dialog_content = "でも、今度は少し違うみたいね。\n前よりずっとはっきり見える…",
  ui_story_5036_50361401_4_dialog_content = "白い塔もくっきり見えてる…",
  ui_story_5036_50361401_5_dialog_content = "あら？塔の上を飛んでるのは…",
  ui_story_5036_50361401_6_dialog_content = "龍？",
  ui_story_5036_50361401_7_dialog_content = "やっぱり夢を見てるのね！",
  ui_story_5036_50361401_8_dialog_content = "ダメよ、ゴルディ！早く目を覚まして！\nコンサートはまだ終わってないの！",
  ui_story_5036_50361401_9_dialog_content = "太ももをつねれば、目が覚めるってよく言うわよね…",
  ui_story_5036_50361401_10_dialog_content = "つねってみましょ！",
  ui_story_5036_50361401_11_dialog_content = "えい――痛たた！",
  ui_story_5036_50361401_12_dialog_content = "なんでまだ目が覚めないの？\n今のじゃ足りなかった？",
  ui_story_5036_50361401_13_dialog_content = "♪ラ――ララ♪",
  ui_story_5036_50361401_14_dialog_content = "この歌声…聞き覚えがあるわ…\nあの空の末裔の女の子…シャミナードが歌ってる？",
  ui_story_5036_50361401_15_dialog_content = "♪濡れた…つばさで…♪",
  ui_story_5036_50361401_16_dialog_content = "歌詞もはっきり聞こえるわ…",
  ui_story_5036_50361401_17_dialog_content = "今まではやっとメロディが聞き取れるくらいの、\nかすかな歌声だったのに…",
  ui_story_5036_50361401_18_dialog_content = "♪…故郷へ♪",
  ui_story_5036_50361401_19_dialog_content = "あっちから聞こえてくるみたいね…",
  ui_story_5036_50361401_20_dialog_content = "♪胸をかすめる記憶♪",
  ui_story_5036_50361401_21_dialog_content = "♪そびえたつ白い塔♪",
  ui_story_5036_50361401_22_dialog_content = "♪導きの光はいずこ♪",
  ui_story_5036_50361401_23_dialog_content = "（きれいなメロディなのに、\n悲しみに満ちた歌声…）",
  ui_story_5036_50361401_24_dialog_content = "♪めぐりつづける♪",
  ui_story_5036_50361401_25_dialog_content = "♪夢の中にある故郷♪",
  ui_story_5036_50361401_26_dialog_content = "…あれ？私の他に誰かいるなんて！",
  ui_story_5036_50361401_27_dialog_content = "（えっ！？話しかけられた！？）",
  ui_story_5036_50361401_28_dialog_content = "（今まではこんなことなかった…\nじゃあ、これって夢じゃないの？）",
  ui_story_5036_50361401_29_dialog_content = "は、はじめまして。あなたはシャミナードね？\n私はゴルディ、アイドルよ！",
  ui_story_5036_50361401_30_dialog_content = "え？どうして私の名前を知ってるの？",
  ui_story_5036_50361401_31_dialog_content = "PlayerNameって言う空の末裔の友だちがいて、\nあなたの記憶を感知したことがあるの。",
  ui_story_5036_50361401_32_dialog_content = "そうなんだ！？アハハ、何だか恥ずかしいなぁ。",
  ui_story_5036_50361401_33_dialog_content = "ところで、アイドルって何？",
  ui_story_5036_50361401_34_dialog_content = "アイドルっていうのは、歌で喜びや希望を届ける職業よ。\n私もそういう、プロのアイドルの一人なの！",
  ui_story_5036_50361401_35_dialog_content = "へえ、すごい！私もアイドルになりたいな！",
  ui_story_5036_50361401_36_dialog_content = "私が教えてあげるわ！でも、今はダメなの。\n急いでコンサートに戻って、歌を最後まで歌わなくちゃ！",
  ui_story_5036_50361401_37_dialog_content = "どうすればここから出られるか、知らない？",
  ui_story_5036_50361401_38_dialog_content = "ごめんね、分からない…",
  ui_story_5036_50361401_39_dialog_content = "私もずっとここを出られないし…",
  ui_story_5036_50361401_40_dialog_content = "出られない？",
  ui_story_5036_50361401_41_dialog_content = "（それもそうよね…\nだって、本物の彼女はもう…）",
  ui_story_5036_50361401_42_dialog_content = "（でも、だとしたら…\nいま私に見えているのは、いったい何？）",
  ui_story_5036_50361401_43_dialog_content = "フフフ、大丈夫よ！",
  ui_story_5036_50361401_44_dialog_content = "必ず方法は見つかるわ！",
  ui_story_5036_50361401_45_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_5036_50361401_46_dialog_content = "あら？何の音？",
  ui_story_5036_50361401_47_dialog_content = "あいつらだ！",
  ui_story_5036_50361401_48_dialog_content = "急いで逃げて！あいつらが来たよ！",
  ui_story_5036_50361401_49_dialog_content = "あいつら？誰のこと？",
  ui_story_5036_50361401_50_dialog_content = "暗鬼よ！",
  ui_story_5036_50361401_51_dialog_content = "グオオ――！",
  ui_story_5036_50361401_52_dialog_content = "ホントに暗鬼だわ！\nそれに、どうしてこんなにたくさん！？",
  ui_story_5036_50361401_53_dialog_content = "グォォ――！",
  ui_story_5036_50361401_54_dialog_content = "それに、どこから…！？",
  ui_story_5036_50361401_55_dialog_content = "まただ…また来たんだ！\nゴルディ、早く隠れて！",
  ui_story_5036_50361401_56_dialog_content = "でも、こんな数じゃ隠れようがないわ！\n戦うしかないわよ！",
  ui_story_5036_50361401_57_dialog_content = "暗鬼に好き勝手なんてさせないわ！",
  ui_story_5036_50361402_1_dialog_content = "くっ――！",
  ui_story_5036_50361402_2_dialog_content = "まずいわ…次から次に…これじゃキリがないわ！",
  ui_story_5036_50361402_3_dialog_content = "グォォ！",
  ui_story_5036_50361402_4_dialog_content = "きゃあ！",
  ui_story_5036_50361402_5_dialog_content = "早く逃げて！私のことはいいから！\n暗鬼はそのうち消えるから、放っておいて大丈夫！",
  ui_story_5036_50361402_6_dialog_content = "え？消える？",
  ui_story_5036_50361402_7_dialog_content = "キュウ――",
  ui_story_5036_50361402_8_dialog_content = "キュウ――！",
  ui_story_5036_50361402_9_dialog_content = "龍が光ってる！？",
  ui_story_5036_50361402_10_dialog_content = "まぶしい…何も見えないわ――！",
  ui_story_5036_50361402_11_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5036_50361402_12_dialog_content = "とにかく、暗鬼からできるだけ遠くに…あら？\n暗鬼はどこに行ったの？",
  ui_story_5036_50361402_13_dialog_content = "もう大丈夫、全部消えたよ。",
  ui_story_5036_50361402_13X1_dialog_content = "ウロボロスが消してくれたの！",
  ui_story_5036_50361402_13X2_dialog_content = "そうだ、まだ紹介してなかったよね？\nウロボロスって言うのは、空を飛んでるあの子だよ！",
  ui_story_5036_50361402_14_dialog_content = "消した？\nさっきの光で倒したということ？",
  ui_story_5036_50361402_15_dialog_content = "ううん、違うよ。ウロボロスにそんな力はないもん。\nただ、夢を元通りにしただけ。",
  ui_story_5036_50361402_16_dialog_content = "やっぱり、ここは夢の中だったのね…",
  ui_story_5036_50361402_17_dialog_content = "そう、ここはウロボロスが私に創ってくれた、\n夢の世界なの。",
  ui_story_5036_50361402_18_dialog_content = "空の末裔のお友達は、見たんでしょ？\n私の最後に何があったか…",
  ui_story_5036_50361402_19_dialog_content = "ええ…",
  ui_story_5036_50361402_20_dialog_content = "卵を守るために私が犠牲になったって知って、\nウロボロスはとても悲しんでくれたの。",
  ui_story_5036_50361402_21_dialog_content = "それから、家に帰りたいっていう私の願いも感じとったの。\nそれで、夢の世界に天空ノ谷と、今あなたが見てる私を創り出したんだ。",
  ui_story_5036_50361402_22_dialog_content = "でも、この夢の中の天空ノ谷を守るために、\nウロボロスはずっと眠り続けるしかなくなっちゃったの。",
  ui_story_5036_50361402_23_dialog_content = "じゃあ、さっきの暗鬼は？",
  ui_story_5036_50361402_24_dialog_content = "あれは私の恐怖の表れだよ。",
  ui_story_5036_50361402_25_dialog_content = "私の気持ちが夢の中に暗鬼を作り出して、\n何度も何度も襲ってくるの。",
  ui_story_5036_50361402_26_dialog_content = "でも、大丈夫。ウロボロスが守ってくれるから。\n夢を元通りにして、怖い暗鬼たちを消してくれるの！",
  ui_story_5036_50361402_27_dialog_content = "…あ、そっか…じゃあ、ウロボロスにお願いすれば、\n出られるかもしれないね？",
  ui_story_5036_50361402_28_dialog_content = "いい考えね！聞いてみるわ！",
  ui_story_5036_50361402_29_dialog_content = "うん！でも、ここから出ていく前に、\nもう少し一緒におしゃべりしてくれない？",
  ui_story_5036_50361402_30_dialog_content = "私もあなたともう少し話していたいけど、\nみんながきっと待ってるわ。",
  ui_story_5036_50361402_31_dialog_content = "長くは引き止めないから！\n1つだけ教えてほしいの、ダメ？",
  ui_story_5036_50361402_32_dialog_content = "もちろん、構わないわ！何を聞きたいの？",
  ui_story_5036_50361402_33_dialog_content = "今、天空ノ谷はどうなってるの？",
  ui_story_5036_50361402_34_dialog_content = "お願い、教えて！すごく知りたいの！",
  ui_story_5036_50361402_35_dialog_content = "え？天空ノ谷…",
  ui_story_5036_50361402_36_dialog_content = "ごめんなさい、行ったことがないの…",
  ui_story_5036_50361402_37_dialog_content = "そっか…",
  ui_story_5036_50361402_38_dialog_content = "でも、悲しむことないわ！私は行ったことがないけど、\nとっても頼りになる空の末裔の友だちがいるの！",
  ui_story_5036_50361402_39_dialog_content = "さっきお話してくれた友だちのこと？",
  ui_story_5036_50361402_40_dialog_content = "そうよ、PlayerNameっていうの。\nすごい人なんだから！",
  ui_story_5036_50361402_41_dialog_content = "私も実際に会うまでは、巨像に乗ってあちこちを旅してる、\n空の末裔だってことしか知らなかったけど…",
  ui_story_5036_50361402_42_dialog_content = "たくさん友だちがいて、一緒に遊んだり、\n暗鬼と戦ったりしてきたってウワサだったわ。",
  ui_story_5036_50361402_43_dialog_content = "心配事もなさそうだし、\n自由に生きられてうらやましいなって思ってたの。",
  ui_story_5036_50361402_44_dialog_content = "でも、実際に会って初めて、\nPlayerNameも苦労してきたんだって知ったわ。",
  ui_story_5036_50361402_45_dialog_content = "最初はたった1人で地下で暮らしてたんだけど、\n友だちに出会って、地上に出て太陽の光を見たんですって。",
  ui_story_5036_50361402_46_dialog_content = "今も空の末裔の最後の生き残りとして、努力を続けてるわ。\n無くなっちゃった天空ノ谷の再建もしてるって聞いたわ。",
  ui_story_5036_50361402_47_dialog_content = "えっ…？",
  ui_story_5036_50361402_48_dialog_content = "天空ノ谷が…無くなっちゃったって言った？\n空の末裔も…たった1人だけ？",
  ui_story_5036_50361402_49_dialog_content = "あっ…ち、違うの…そういうことじゃなくて…\n私が言いたかったのは――",
  ui_story_5036_50361402_50_dialog_content = "私の…故郷が…？",
  ui_story_5036_50361402_51_dialog_content = "家には…天空ノ谷には…もう帰れないの…？",
  ui_story_5036_50361402_52_dialog_content = "どうして…どうして！？",
  ui_story_5036_50361402_53_dialog_content = "<color=#e8d9bb>バリン！</color>",
  ui_story_5036_50361402_54_dialog_content = "<color=#e8d9bb>ガシャン――！</color>",
  ui_story_5036_50361402_55_dialog_content = "夢の世界が…崩れ始めた！？\n私が口を滑らせちゃったせいで…",
  ui_story_5036_50361402_56_dialog_content = "お、落ち着いて！",
  ui_story_5036_50361402_57_dialog_content = "お家に…帰りたい…ううっ…",
  ui_story_5036_50361402_58_dialog_content = "落ち着くどころじゃなさそうね…",
  ui_story_5036_50361402_59_dialog_content = "<color=#e8d9bb>ドカン――！</color>",
  ui_story_5036_50361402_60_dialog_content = "キュウ、キュウ――！",
  ui_story_5036_50361402_61_dialog_content = "世界がどんどん壊れてる…\n元に戻る気配もない…",
  ui_story_5036_50361402_62_dialog_content = "ど、どうしましょ…\n「7」のつかない数字を数えればなんとかなるかしら…？",
  ui_story_5036_50361402_63_dialog_content = "ダメよ…じっとしてたらダメ！\nとにかく壊れ始めてるところから離れなくちゃ！",
  ui_story_5036_50361402_64_dialog_content = "あの塔なら丈夫そうだわ。\nてっぺんまで行けば、ウロボロスにも近づけるし…",
  ui_story_5036_50361402_65_dialog_content = "シャミナード、行きましょ――きゃあ！",
  ui_story_5036_50361402_66_dialog_content = "ううぅ…",
  ui_story_5036_50361402_67_dialog_content = "痛いわ！どうして突き放したの！？",
  ui_story_5036_50361402_68_dialog_content = "シャミナード？シャミナード！\nお願いだから、少し落ち着いて！！",
  ui_story_5036_50361402_69_dialog_content = "もう聞こえてもないのかしら…",
  ui_story_5036_50361402_70_dialog_content = "このままじゃ、シャミナードも夢の世界も危ないわ！",
  ui_story_5036_50361402_71_dialog_content = "なんとかして、夢の世界を元通りにしなくちゃ…",
  ui_story_5036_50361402_72_dialog_content = "ウロボロスがなんとかしてくれるといいけど！",
  ui_story_5036_50361402_73_dialog_content = "ずいぶん高いわね…だいぶ登ってきたのに、\nまだ頂上に着かないの？",
  ui_story_5036_50361402_74_dialog_content = "暗くて空っぽだし…何をするところなのかしら？",
  ui_story_5036_50361402_75_dialog_content = "ダメ、怖がってる場合じゃないわ！",
  ui_story_5036_50361402_76_dialog_content = "グォォ…",
  ui_story_5036_50361402_77_dialog_content = "暗鬼も集まって来てるわ！？",
  ui_story_5036_50361402_78_dialog_content = "…それも当然かしら。夢の世界の真ん中にあるし、\n一番安全そうな建物だもの。",
  ui_story_5036_50361402_79_dialog_content = "暗鬼だって避難しに来るわよね。",
  ui_story_5036_50361402_80_dialog_content = "今は構ってられないわ。\nまずは塔の一番上まで行かなきゃ！",
  ui_story_5036_50361402_81_dialog_content = "光が…出口だわ！",
  ui_story_5036_50361402_82_dialog_content = "やっと着いた！",
  ui_story_5036_50361402_83_dialog_content = "キュウキュウ！",
  ui_story_5036_50361402_84_dialog_content = "ウロボロス、お願いよ！",
  ui_story_5036_50361402_85_dialog_content = "夢の世界を元に戻して！\nシャミナードを落ち着かせて！",
  ui_story_5036_50361402_86_dialog_content = "キュウ…",
  ui_story_5036_50361402_87_dialog_content = "（なんだか困ってるみたい…\nもしかして、できないってこと？）",
  ui_story_5036_50361402_88_dialog_content = "（どうしたらいいの！？）",
  ui_story_5036_50361402_89_dialog_content = "<color=#e8d9bb>バリン…</color>",
  ui_story_5036_50361402_90_dialog_content = "空まで！？",
  ui_story_5036_50361402_91_dialog_content = "キュウ！キュウ――！",
  ui_story_5036_50361402_92_dialog_content = "ウロボロスも苦しそう…",
  ui_story_5036_50361402_93_dialog_content = "<color=#e8d9bb>ドカン――！</color>",
  ui_story_5036_50361402_94_dialog_content = "ああっ！？塔が崩れちゃう！？",
  ui_story_5036_50361402_95_dialog_content = "きゃあああ――！！！",
  ui_story_5036_50361402_96_dialog_content = "ゴルディ、手をつかんで！",
  ui_story_5036_50361402_97_dialog_content = "PlayerName！？",
  ui_story_5036_50361402_98_dialog_content = "どうしてここに！？",
  ui_story_5036_50361402_99_dialog_content = "ウロボロスの卵に異変があって、\nヴィックと2人で急いでステージに戻ったら…",
  ui_story_5036_50361402_100_dialog_content = "全員眠ってて、しかも君だけ、\n光力術にかかってるような状態だったんだ。",
  ui_story_5036_50361402_101_dialog_content = "ウロボロスの卵に？\nそんな…どうして今！？",
  ui_story_5036_50361402_102_dialog_content = "歌を聞いたからかもな。",
  ui_story_5036_50361402_103_dialog_content = "巨像を動かす時に使われてたメロディなんだろ？\nウロボロスにとっちゃ、目覚ましの音に聞こえたのかもしれない。",
  ui_story_5036_50361402_104_dialog_content = "え…！？",
  ui_story_5036_50361402_105_dialog_content = "とにかく、このままのんびりおしゃべりしてたら、\n俺の腕がもたんぞ――",
  ui_story_5036_50361402_106_dialog_content = "ヴィック、頑張って！！",
  ui_story_5036_50361402_107_dialog_content = "ハハハ…そこまで頼りない大人に見えるか！？",
  ui_story_5036_50361402_108_dialog_content = "よし、ゴルディを引っ張りあげるぞ！",
  ui_story_5036_50361402_109_dialog_content = "しっかりつかまって！",
  ui_story_5036_50361402_110_dialog_content = "ううっ…！",
  ui_story_5036_50361402_111_dialog_content = "目が覚めた…出られたの…！？",
  ui_story_5036_50361402_112_dialog_content = "大丈夫？",
  ui_story_5036_50361402_113_dialog_content = "大丈夫よ…ちょっとめまいがするだけ…",
  ui_story_5036_50361402_114_dialog_content = "本採用ですか！？とうとう私も…\nあれ…ええ？…ゆ、夢だったのですか…？",
  ui_story_5036_50361402_115_dialog_content = "うっ…私…どうしちゃったのかしら？",
  ui_story_5036_50361402_116_dialog_content = "頭が痛い…眠ってしまっていた…？",
  ui_story_5036_50361402_117_dialog_content = "ふわぁぁ…おはよ～。それともこんばんは？",
  ui_story_5036_50361402_118_dialog_content = "観客席で眠っていただと！？\nくっ、服を徹底的に洗わねば…",
  ui_story_5036_50361402_119_dialog_content = "おお、みんな起きたみたいだな。",
  ui_story_5036_50361402_120_dialog_content = "夢の世界は…？元に戻ったの？",
  ui_story_5036_50361402_121_dialog_content = "それは無いと思うね…",
  ui_story_5036_50361402_122_dialog_content = "ウロボロスの卵が、もうすぐかえるんだ。",
  ui_story_5036_50361501_1_dialog_content = "<color=#e8d9bb>影ノ街、ゴールド・リバー沿岸</color>",
  ui_story_5036_50361501_2_dialog_content = "おい、いったいどうなってるんだ？\n歌いながら倒れちまったぞ？",
  ui_story_5036_50361501_3_dialog_content = "歌のお姉ちゃん、大丈夫かな…？",
  ui_story_5036_50361501_4_dialog_content = "歌のお姉ちゃんは強いんだよ、きっと大丈夫！",
  ui_story_5036_50361501_5_dialog_content = "あの2人はなんだ？見たことねぇヤツらだな。\nステージで何してるんだ？",
  ui_story_5036_50361501_6_dialog_content = "まったく訳が分からねえ。\n時間の無駄だな、帰るぞ。",
  ui_story_5036_50361501_7_dialog_content = "あら、そうかしら？",
  ui_story_5036_50361501_8_dialog_content = "そんなに急いで結論を出すことはないんじゃない？\nもしかしたら…演出かも。",
  ui_story_5036_50361501_9_dialog_content = "何ぃ？",
  ui_story_5036_50361501_10_dialog_content = "演出じゃないかしら？\n歌やダンスばっかりじゃ、みんな飽きちゃうでしょ？",
  ui_story_5036_50361501_11_dialog_content = "きっと予想外の演出をして、\n観客を驚かせようとしてるのよ。",
  ui_story_5036_50361501_12_dialog_content = "そういうことだから、皆さん。\nもう少し観てみない？きっと満足できると思うわ。",
  ui_story_5036_50361501_13_dialog_content = "ふーむ…ここはもう少し待ってみるか…",
  ui_story_5036_50361501_14_dialog_content = "ありがとう！\n飲み物とお菓子も用意してるわよ。",
  ui_story_5036_50361501_15_dialog_content = "どうぞ、食べながら待って。",
  ui_story_5036_50361501_16_dialog_content = "（…騒ぎはおさめたけど…）",
  ui_story_5036_50361501_17_dialog_content = "（ゴルディ、いったい何があったの？）",
  ui_story_5036_50361501_18_dialog_content = "（ゴルディもPlayerNameたちも…\n絶対に無事でいてちょうだいよ…？）",
  ui_story_5036_50361501_19_dialog_content = "<color=#e8d9bb>その頃、イクストウル</color>",
  ui_story_5036_50361501_20_dialog_content = "なんて言ったの！？ウロボロスの卵が！？",
  ui_story_5036_50361501_21_dialog_content = "急がないと。一刻を争うんだ。",
  ui_story_5036_50361501_22_dialog_content = "とにかく、ウロボロスが孵化して動き出したら、\n巨像のバランスが崩れて、危険なことになりかねないんだ。",
  ui_story_5036_50361501_23_dialog_content = "今すぐ皆を避難させないと。",
  ui_story_5036_50361501_24_dialog_content = "それも今すぐだ。\nでないと…ああ、もう間に合わないか…",
  ui_story_5036_50361501_25_dialog_content = "グォォ――！！！",
  ui_story_5036_50361501_26_dialog_content = "暗鬼が飛び出してきたわ！？",
  ui_story_5036_50361501_27_dialog_content = "皆、寝ぼけていないで！\nすぐに防衛態勢を！",
  ui_story_5036_50361501_28_dialog_content = "はっ！",
  ui_story_5036_50361501_29_dialog_content = "グオオ！",
  ui_story_5036_50361501_30_dialog_content = "行かせるか！",
  ui_story_5036_50361501_31_dialog_content = "ええい、汚らわしい！\nこの数はどういうことだ！？",
  ui_story_5036_50361501_32_dialog_content = "緊急事態だ、防衛に徹しろ。\n余計なことは後だ。",
  ui_story_5036_50361501_33_dialog_content = "分かっておるわ！",
  ui_story_5036_50361501_34_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_5036_50361501_35_dialog_content = "巨像が揺れてる？\nいよいよラスボス登場って感じかな！？",
  ui_story_5036_50361501_36_dialog_content = "皆さん、しっかりつかまってください！\n巨像の中で何かが動いているようです！",
  ui_story_5036_50361501_37_dialog_content = "キュウ――！",
  ui_story_5036_50361501_38_dialog_content = "大きい！！",
  ui_story_5036_50361501_39_dialog_content = "ホントに…あの卵がかえったのね！",
  ui_story_5036_50361501_40_dialog_content = "グォォ！！！",
  ui_story_5036_50361501_41_dialog_content = "暗鬼がウロボロスと戦い始めた！？",
  ui_story_5036_50361501_42_dialog_content = "キュウ――キュウ――！",
  ui_story_5036_50361501_43_dialog_content = "お姉ちゃん、見て！巨像の上！",
  ui_story_5036_50361501_44_dialog_content = "巨像の上に…龍がいる！？",
  ui_story_5036_50361501_45_dialog_content = "あ！巨像、揺れてる！\n落ちてきそう！",
  ui_story_5036_50361501_46_dialog_content = "<color=#e8d9bb>ガタン！</color>",
  ui_story_5036_50361501_47_dialog_content = "まずいな…ウロボロスは\n孵化したばかりで、まだ飛べないんだ！",
  ui_story_5036_50361501_48_dialog_content = "このまま暗鬼にやられ続けたら、\nもっと暴れるぞ！",
  ui_story_5036_50361501_49_dialog_content = "どうにかして、おとなしくさせられない？",
  ui_story_5036_50361501_50_dialog_content = "感知してみるってのはどうだ？",
  ui_story_5036_50361501_51_dialog_content = "やってみる！",
  ui_story_5036_50361501_52_option_content = "「ウロボロス、止まって！」",
  ui_story_5036_50361501_53_dialog_content = "キュウ――！",
  ui_story_5036_50361501_54_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_5036_50361501_55_dialog_content = "うわっ！",
  ui_story_5036_50361501_56_dialog_content = "ダメだ、全然言うことを聞いてくれない！",
  ui_story_5036_50361501_57_dialog_content = "ステージが…暗鬼だらけ…",
  ui_story_5036_50361501_58_dialog_content = "コンサートが…めちゃくちゃだわ…",
  ui_story_5036_50361501_59_dialog_content = "ゴルディ、しっかりして！\nまだ危険は終わってない！",
  ui_story_5036_50361501_60_dialog_content = "分かってるわ、でも…",
  ui_story_5036_50361501_61_dialog_content = "時間がないようね。\n全員陣形を整えて！暗鬼と龍を引き離す！",
  ui_story_5036_50361501_62_dialog_content = "はっ！",
  ui_story_5036_50361501_63_dialog_content = "こっちだって負けてられない！ボス戦開始だよ！",
  ui_story_5036_50361501_64_dialog_content = "了解！！！",
  ui_story_5036_50361501_65_dialog_content = "バイスとPlayerNameは戦えない者を援護して、\n戦場から離れて。",
  ui_story_5036_50361501_66_dialog_content = "ソラヴァンと白夜城の飛空艇で、\n皆の避難を！",
  ui_story_5036_50361501_67_dialog_content = "分かった、任せて！",
  ui_story_5036_50361501_68_dialog_content = "ええ！",
  ui_story_5036_50361501_69_dialog_content = "さすがは白夜城の騎士だ、\nいざって時には頼りになるなぁ。",
  ui_story_5036_50361501_70_dialog_content = "あなたも棒立ちしていないで、\nあの龍を落ち着かせる方法を考えなさい。",
  ui_story_5036_50361501_71_dialog_content = "カンベンしてくれよ。\n俺は戦いには向いてないんでね…",
  ui_story_5036_50361501_72_dialog_content = "この期に及んで…\nはぁ、構わないわ…それなら早く避難しなさい。",
  ui_story_5036_50361501_73_dialog_content = "任せろ！逃げ足には自信がある！",
  ui_story_5036_50361501_74_dialog_content = "皆、こっちよ！",
  ui_story_5036_50361501_75_dialog_content = "PlayerName、ソラヴァンは？",
  ui_story_5036_50361501_76_dialog_content = "ウロボロスが暴れてて、\nソラヴァンが近づけないんだ！",
  ui_story_5036_50361501_77_dialog_content = "少しの間でもいいから、おとなしくなってくれれば…\nほんの少しの間でいいんだけど…",
  ui_story_5036_50361501_78_dialog_content = "簡単には行かないみたいね。",
  ui_story_5036_50361501_79_dialog_content = "白夜城の飛空艇は？",
  ui_story_5036_50361501_80_dialog_content = "言われずとも、とうに手配済みだ。",
  ui_story_5036_50361501_81_dialog_content = "もともとバカ騒ぎを見物しようと、貴族の飛空艇が出ていたようでな。\n数隻が救援に駆けつけている。",
  ui_story_5036_50361501_82_dialog_content = "城主殿下もすでに白夜城の飛空艇に召集をおかけになっているが、\nしばらく時間がかかるだろう。",
  ui_story_5036_50361501_83_dialog_content = "ただ、白夜城の飛空艇のほとんどは小型だ。\nこれだけの人数を避難させるには、1往復では足りん。",
  ui_story_5036_50361501_84_dialog_content = "なんとか時間を稼がないと…",
  ui_story_5036_50361501_85_dialog_content = "うわっ――！",
  ui_story_5036_50361501_X85_dialog_content = "持ちこたえなさい！",
  ui_story_5036_50361501_87_dialog_content = "<color=#e8d9bb>ギギギギギ――！</color>",
  ui_story_5036_50361501_88_dialog_content = "カレン殿下、敵が多すぎます。\nこのままでは陣形が崩れます！",
  ui_story_5036_50361501_89_dialog_content = "うわっ…白夜城の人たちも、早く撤退して！",
  ui_story_5036_50361501_90_dialog_content = "ただでさえボロボロだったのに、\n龍が大暴れしてるせいで…",
  ui_story_5036_50361501_91_dialog_content = "巨像の部品が震動に耐えきれずに、\n壊れ始めてる！",
  ui_story_5036_50361501_92_dialog_content = "飛空艇は？",
  ui_story_5036_50361501_93_dialog_content = "報告します！ソラヴァンの接近は難しいとのことです！\n白夜城の飛空艇がすでにこちらに向かっています！",
  ui_story_5036_50361501_94_dialog_content = "やむを得ない…各隊に通達、ウロボロスの防衛を中止！\n防衛線を下げて、民の護衛に集結！",
  ui_story_5036_50361501_95_dialog_content = "はっ！",
  ui_story_5036_50361501_96_dialog_content = "カレン！",
  ui_story_5036_50361501_97_dialog_content = "私は大丈夫よ。\nもう全員集合できている？",
  ui_story_5036_50361501_98_dialog_content = "ご報告いたします、殿下。\n全員集合しておりますぞ！",
  ui_story_5036_50361501_99_dialog_content = "すでに第一波の飛空艇が到着し、\n避難を開始しておりますが…",
  ui_story_5036_50361501_100_dialog_content = "全員の避難には時間がかかる。",
  ui_story_5036_50361501_101_dialog_content = "避難者の数に対して、\n飛空艇が小さすぎます。",
  ui_story_5036_50361501_102_dialog_content = "私が時間を稼ぐわ。",
  ui_story_5036_50361501_103_dialog_content = "でも、急いでね！\nこの巨像、いつひっくり返ってもおかしくないよ！",
  ui_story_5036_50361501_104_dialog_content = "ううっ…私…",
  ui_story_5036_50361501_105_dialog_content = "ゴルディ、大丈夫？",
  ui_story_5036_50361501_106_dialog_content = "もう大丈夫よ。コンサートは…失敗しちゃったけど…",
  ui_story_5036_50361501_107_dialog_content = "ファンのみんなを守らなきゃ。\nコンサートのせいでケガなんて、させられないわ。",
  ui_story_5036_50361501_108_dialog_content = "たとえ…たとえ、これが最後のコンサートになっても！",
  ui_story_5036_50361501_109_dialog_content = "そうだね…まずは、目の前のことを解決しよう！",
  ui_story_5036_50361501_110_dialog_content = "そうだ、ヴィック。ウロボロスは本当に…\nあれ？ヴィック？",
  ui_story_5036_50361501_111_dialog_content = "どこに行っちゃったんだろう？",
  ui_story_5036_50361501_112_dialog_content = "一緒にいたのではないの？",
  ui_story_5036_50361501_113_dialog_content = "付いてきてるとばかり思ってたから、\n気にしてなかったんだ！",
  ui_story_5036_50361501_114_dialog_content = "やれやれ、やっぱり俺は戦いなんてガラじゃないな…",
  ui_story_5036_50361501_115_dialog_content = "今の声は…？",
  ui_story_5036_50361501_116_dialog_content = "あそこよ！",
  ui_story_5036_50361501_117_dialog_content = "だが、珍獣の専門家を名乗ってる以上、\nそれっぽいところは見せておかないとな。",
  ui_story_5036_50361501_118_dialog_content = "どうしてあんなところに？",
  ui_story_5036_50361501_119_dialog_content = "早く戻りなさい、危険よ！",
  ui_story_5036_50361501_120_dialog_content = "お気遣いどうも。\nだが、今は気持ちだけもらっとくよ。",
  ui_story_5036_50361501_121_dialog_content = "そら、バケモノども、こっちだ！",
  ui_story_5036_50361501_122_dialog_content = "ウキューッ、キュー！",
  ui_story_5036_50361501_123_dialog_content = "グォォ…",
  ui_story_5036_50361501_124_dialog_content = "そうだ、いいぞ…",
  ui_story_5036_50361501_125_dialog_content = "ほれほれ、抵抗もしない光霊だぞ？\nウロボロスよりラクな獲物だ。",
  ui_story_5036_50361501_126_dialog_content = "（あと少しで、ウロボロスから引き離せる）",
  ui_story_5036_50361501_127_dialog_content = "（あとはアリガタモドキドリに任せりゃ、\n十分時間を稼げるはずだ）",
  ui_story_5036_50361501_128_option_content = "ヴィック、早くこっちへ！",
  ui_story_5036_50361501_129_dialog_content = "大丈夫だって、心配するな。",
  ui_story_5036_50361501_130_dialog_content = "俺は優秀な珍獣の専門家だからな。\n一緒にいる珍獣には、命を預けるもんなのさ！",
  ui_story_5036_50361501_131_dialog_content = "グォォ――！",
  ui_story_5036_50361501_132_dialog_content = "（よし、かかった！）",
  ui_story_5036_50361501_133_dialog_content = "（アリガタモドキドリの出番だ！）",
  ui_story_5036_50361501_134_dialog_content = "アリガタモドキドリ！",
  ui_story_5036_50361501_135_dialog_content = "ホゥ――ホゥホゥ！！",
  ui_story_5036_50361501_136_dialog_content = "おい、どうした！？\n逃げるなって――！",
  ui_story_5036_50361501_137_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5036_50361501_138_dialog_content = "キュウ――！",
  ui_story_5036_50361501_139_dialog_content = "何だ！？",
  ui_story_5036_50361501_140_dialog_content = "<color=#e8d9bb>シュッ――バシンッ！！</color>",
  ui_story_5036_50361501_141_dialog_content = "ヴィック！？",
  ui_story_5036_50361501_142_dialog_content = "イテテテテ！",
  ui_story_5036_50361501_143_dialog_content = "（ウロボロスの尻尾で飛ばされた！\n…まずい、あの辺りは…！）",
  ui_story_5036_50361501_144_dialog_content = "ヴィック、早く逃げて！",
  ui_story_5036_50361501_145_dialog_content = "まったく…手加減くらいしろよな。",
  ui_story_5036_50361501_146_dialog_content = "何か言ったか、PlayerName？\nよく聞こえなかったぞ。",
  ui_story_5036_50361501_147_dialog_content = "グォォ！",
  ui_story_5036_50361501_148_dialog_content = "あーらら…囲まれちまったか！？",
  ui_story_5036_50361501_149_dialog_content = "なあ、暗鬼さんよ…俺みたいな年寄り、\n食ったって、うまかないぜ！",
  ui_story_5036_50361501_150_dialog_content = "ほら、あそこの空の末裔を見てみろよ。\n若くて柔らかそうだろ？俺よりうまいに決まってる！",
  ui_story_5036_50361501_151_dialog_content = "グォォ！！！",
  ui_story_5036_50361501_152_dialog_content = "モジャ！助けてくれ！！",
  ui_story_5036_50361501_153_dialog_content = "PlayerName！！！",
  ui_story_5036_50361502_1_dialog_content = "やれやれ、危ないところだった。",
  ui_story_5036_50361502_2_dialog_content = "暗鬼を引きつけるのは失敗しちまったか。",
  ui_story_5036_50361502_3_dialog_content = "よく笑ってられるね…",
  ui_story_5036_50361502_4_dialog_content = "作戦があったなら、先に僕たちに言ってよ！",
  ui_story_5036_50361502_5_dialog_content = "すまんすまん、ウロボロスが心配でな。\nつい忘れちまった。",
  ui_story_5036_50361502_6_dialog_content = "あーあ、はたき飛ばされてなかったら、\n作戦成功だったんだがな～。",
  ui_story_5036_50361502_7_dialog_content = "今そんなことを言っても仕方ないよ！",
  ui_story_5036_50361502_8_dialog_content = "他にウロボロスをおとなしくさせる方法はないの？",
  ui_story_5036_50361502_9_dialog_content = "残念だが、暗鬼を全部やっつけちまう以外、\n思いつかないな。",
  ui_story_5036_50361502_10_dialog_content = "ウロボロスが自分で飛べるようになるまで待つのはどう？",
  ui_story_5036_50361502_11_dialog_content = "それはオススメできないな。\n暗鬼の勢いが強すぎる。",
  ui_story_5036_50361502_12_dialog_content = "このままじゃ、飛べるようになる前に、\n大けがで飛ぼうにも飛べなくなるぜ。",
  ui_story_5036_50361502_13_dialog_content = "そんな…",
  ui_story_5036_50361502_14_dialog_content = "カレン殿下、城主様より通達がございます。",
  ui_story_5036_50361502_15_dialog_content = "聞かせて。",
  ui_story_5036_50361502_16_dialog_content = "避難は間もなく完了いたします。\nまた、白夜城と啓光の上層部は、この巨像の危険性に対する評価を終えたとのことです。",
  ui_story_5036_50361502_17_dialog_content = "兵士たちは残って暗鬼の攻撃をしのぎ、\nできる限りあの龍を刺激せず、巨像の均衡を保てとの指示でございます。",
  ui_story_5036_50361502_18_dialog_content = "巨像が影ノ街上空から離れ次第、\nただちに撃墜するとの事で。",
  ui_story_5036_50361502_19_dialog_content = "ウロボロスもろとも撃ち落とすつもりか！？\nそれはダメだ！",
  ui_story_5036_50361502_20_dialog_content = "アイツが世界で最後の1頭かもしれないんだぞ。\nここで死なせたら、絶滅の可能性がある！",
  ui_story_5036_50361502_21_dialog_content = "僕もイクストウルを失いたくない！",
  ui_story_5036_50361502_22_dialog_content = "他に方法があるとでも？\n何もないなら、黙っているがいい。",
  ui_story_5036_50361502_23_dialog_content = "今、この巨像の真下は影ノ街で最も人の集まっている地区なのだ。\n何千何万という光霊の命を危険にさらせと言うか？",
  ui_story_5036_50361502_24_dialog_content = "…俺が意地でもここを離れないと言ったら、どうする？",
  ui_story_5036_50361502_25_dialog_content = "ヴィック、まさか――",
  ui_story_5036_50361502_26_dialog_content = "俺は珍獣の研究者なんだぜ？\nウロボロスを放っておけるワケないだろ？",
  ui_story_5036_50361502_27_dialog_content = "この巨像を撃ち落とすっていうなら、\n俺も一緒に撃ち落とせばいいさ。",
  ui_story_5036_50361502_28_dialog_content = "何を言ってるの！？危険よ！",
  ui_story_5036_50361502_29_dialog_content = "貴様、戯れ言も大概にせんか！",
  ui_story_5036_50361502_30_dialog_content = "（どうしよう…\nどうすれば、ウロボロスと巨像を助けられる？）",
  ui_story_5036_50361502_31_dialog_content = "（きっと何か方法があるはずだ…）",
  ui_story_5036_50361502_32_dialog_content = "イクストウルの設備があれば、\n100%歌声を地上のみんなに聴いてもらえる、間違いないわ！",
  ui_story_5036_50361502_33_dialog_content = "驚きました…空の末裔が巨像の操縦に使う旋律を、\n動物が交流の手段にするとは…",
  ui_story_5036_50361502_34_dialog_content = "巨像を動かす時に使われてたメロディなんだろ？\nウロボロスにとっちゃ、目覚ましの音に聞こえたのかもしれない。",
  ui_story_5036_50361502_35_dialog_content = "…方法があった！試させて！",
  ui_story_5036_50361502_36_dialog_content = "えっ？",
  ui_story_5036_50361502_37_dialog_content = "どんな方法だ？",
  ui_story_5036_50361502_38_dialog_content = "シャミナードが昔、気づいたことなんだ――\nウロボロスは空の末裔が巨像の操縦に使うメロディを理解できる。",
  ui_story_5036_50361502_39_dialog_content = "それなら、巨像を停めるメロディを聞かせてあげて、\n同時に暗鬼から守ってあげれば、おとなしくなるかもしれない！",
  ui_story_5036_50361502_40_dialog_content = "お？悪くなさそうだな。",
  ui_story_5036_50361502_41_dialog_content = "感知能力を使っても言うことを聞かなかったんでしょ？\nただの音だけで、本当に効くのかしら？",
  ui_story_5036_50361502_42_dialog_content = "そうだな…音がデカけりゃ、注意は引けると思うがな。",
  ui_story_5036_50361502_43_dialog_content = "ステージの音響設備でも使うか？",
  ui_story_5036_50361502_44_dialog_content = "うん…それなら、ゴルディの助けが必要だね。\nゴルディの力と設備があれば、たぶんやれる！",
  ui_story_5036_50361502_45_dialog_content = "え、私？",
  ui_story_5036_50361502_46_dialog_content = "…",
  ui_story_5036_50361502_47_dialog_content = "分かったわ。",
  ui_story_5036_50361502_48_dialog_content = "コンサートはまだ終わってないもの…\n歌だって中途半端…",
  ui_story_5036_50361502_49_dialog_content = "もう二度とアイドルとしてステージに上がることはできなくても、\nあなたと…ファンのみんなと…",
  ui_story_5036_50361502_50_dialog_content = "ここにいるみんなが必要としてくれる限り…私は歌うわ！",
  ui_story_5036_50361502_51_dialog_content = "今、巨像の真下にあるのは影ノ街…\n私とファンのみんなの家があるんだもの。",
  ui_story_5036_50361502_52_dialog_content = "PlayerName、勝算は？",
  ui_story_5036_50361502_53_option_content = "自信はない…",
  ui_story_5036_50361502_54_option_content = "どうしても試したい！",
  ui_story_5036_50361502_55_dialog_content = "それでいいわ。",
  ui_story_5036_50361502_56_dialog_content = "私も手伝う。",
  ui_story_5036_50361502_57_dialog_content = "カレン殿下！？正気であられるか！？",
  ui_story_5036_50361502_58_dialog_content = "当然でしょう？\n無論、失敗した場合の事も考えるわ。",
  ui_story_5036_50361502_59_dialog_content = "各隊に通達！戦闘準備！",
  ui_story_5036_50361502_60_dialog_content = "…かしこまりました…\n騎士隊、整列！",
  ui_story_5036_50361502_61_dialog_content = "カレン、ありがとう！",
  ui_story_5036_50361502_62_dialog_content = "私も手伝うわ！",
  ui_story_5036_50361502_63_dialog_content = "でも、設備のスタッフはさっきの飛空艇で、\nもう避難しちゃったはず…",
  ui_story_5036_50361502_64_dialog_content = "その心配はいらないよ～。\nあたしたちがいること、忘れてもらっちゃ困るね～！",
  ui_story_5036_50361502_65_dialog_content = "改造されてはいますが、基本的な使い方は同じです。\n私たちに任せてください。",
  ui_story_5036_50361502_66_dialog_content = "ガルー！シヴォーンさん！",
  ui_story_5036_50361502_67_dialog_content = "超ハードなステージに挑戦するんでしょ？",
  ui_story_5036_50361502_68_dialog_content = "そんな面白そうな話、\nあたしをのけ者なんて許さないもんね～！",
  ui_story_5036_50361502_69_dialog_content = "わ、私も手伝います！",
  ui_story_5036_50361502_70_dialog_content = "ここ数日の取材で、\n音響のスタッフにもインタビューしています…",
  ui_story_5036_50361502_71_dialog_content = "設備の使い方も、\n少しですが教わりました！",
  ui_story_5036_50361502_72_dialog_content = "き、危険そうではありますが…ど、どうか…私にも、\nゴルディさんとあなたたちのお手伝いをさせてください！",
  ui_story_5036_50361502_73_dialog_content = "ありがとう…",
  ui_story_5036_50361502_74_dialog_content = "所属を越えて一致団結ってヤツか？\nPlayerName、やるじゃないか！",
  ui_story_5036_50361502_75_dialog_content = "こんな能力を持ってるとは、\nさすがは珍獣、空の末裔だ！",
  ui_story_5036_50361502_76_dialog_content = "…僕は珍獣じゃないって…",
  ui_story_5036_50361502_77_dialog_content = "ハハハ、いいからいいから。",
  ui_story_5036_50361502_78_dialog_content = "とにかく、今は時間がない。\nまずはウロボロスを助けるぞ！",
  ui_story_5036_50361502_79_dialog_content = "ええ、ステージ目指して、出発よ！",
  ui_story_5036_50361601_1_dialog_content = "ゴルディ、さっき教えたメロディは覚えた？",
  ui_story_5036_50361601_2_dialog_content = "もちろん！完璧よ！",
  ui_story_5036_50361601_3_dialog_content = "でも、ステージまでの道に暗鬼が…",
  ui_story_5036_50361601_4_dialog_content = "暗鬼のことなら心配無用よ。\n私たちが道を確保する。",
  ui_story_5036_50361601_5_dialog_content = "その通りよ。\n戦いは私たちに任せて、ゴルディは歌に専念して！",
  ui_story_5036_50361601_6_dialog_content = "そうそう、俺は戦えないが、モジャたちも手伝うとさ。",
  ui_story_5036_50361601_7_dialog_content = "ウキュッ！",
  ui_story_5036_50361601_8_dialog_content = "ありがとう、ゴルディ。",
  ui_story_5036_50361601_9_dialog_content = "お礼なんか必要ないわ。",
  ui_story_5036_50361601_10_dialog_content = "この数日間ずっと、助けてくれてたでしょ。",
  ui_story_5036_50361601_11_dialog_content = "PlayerNameが手伝ってくれてなかったら、\nコンサートは開けなかったわ。",
  ui_story_5036_50361601_12_dialog_content = "でも、コンサートは失敗しちゃったし…",
  ui_story_5036_50361601_13_dialog_content = "そうだとしても、PlayerNameが頑張ってくれたことに\n変わりはないでしょ！",
  ui_story_5036_50361601_14_dialog_content = "コンサートが失敗したからって、\n努力したって事実がなくなるわけじゃないもの。",
  ui_story_5036_50361601_15_dialog_content = "だから、そのお返しがしたいの！",
  ui_story_5036_50361601_16_dialog_content = "…うん！",
  ui_story_5036_50361601_17_dialog_content = "行くわよ！",
  ui_story_5036_50361601_18_dialog_content = "ガオオ！",
  ui_story_5036_50361601_19_dialog_content = "暗鬼よ、戦闘準備！",
  ui_story_5036_50361602_1_dialog_content = "ステージに着いたわ、設備はどう？",
  ui_story_5036_50361602_2_dialog_content = "問題ありません！",
  ui_story_5036_50361602_3_dialog_content = "最大出力でいくよ――！",
  ui_story_5036_50361602_4_dialog_content = "グォォ――！",
  ui_story_5036_50361602_5_dialog_content = "え！？",
  ui_story_5036_50361602_6_dialog_content = "速射感知！",
  ui_story_5036_50361602_7_dialog_content = "あ、ありがとう！",
  ui_story_5036_50361602_8_dialog_content = "どういたしまして！",
  ui_story_5036_50361602_9_dialog_content = "暗鬼は私たちが倒すから、安心して作業に集中して！",
  ui_story_5036_50361602_10_dialog_content = "私たちがいる限り、1匹たりとも通しはしない！",
  ui_story_5036_50361602_11_dialog_content = "グォォ！",
  ui_story_5036_50361602_12_dialog_content = "逃がさない！",
  ui_story_5036_50361602_13_dialog_content = "チャンスだ、モジャ！後ろを狙え！",
  ui_story_5036_50361602_14_dialog_content = "ウキュッ！",
  ui_story_5036_50361602_15_dialog_content = "グオオ――",
  ui_story_5036_50361602_16_dialog_content = "へぇ、俺より逃げ足の速いヤツがいるとはな。\nモジャでも追いつけないか。",
  ui_story_5036_50361602_17_dialog_content = "逃げてばかりで、かえってやりにくいわ！",
  ui_story_5036_50361602_18_dialog_content = "何とかもちこたえて！\nゴルディが歌ってる間だけでいいんだ！",
  ui_story_5036_50361602_19_dialog_content = "分かったわ！",
  ui_story_5036_50361602_20_dialog_content = "（みんな、こんなに一生懸命戦ってる…\n私もやるべきことをやらなきゃ）",
  ui_story_5036_50361602_21_dialog_content = "キュウ――キュウ！",
  ui_story_5036_50361602_22_dialog_content = "<color=#e8d9bb>ガラガラ――！</color>",
  ui_story_5036_50361602_23_dialog_content = "ウロボロス、あなたも辛いのよね…",
  ui_story_5036_50361602_24_dialog_content = "あと少しだけ頑張って。\nかならず守ってあげるから、信じてほしいの。",
  ui_story_5036_50361602_25_dialog_content = "始めるわ！",
  ui_story_5036_50361602_26_dialog_content = "了解です！",
  ui_story_5036_50361602_27_dialog_content = "（落ち着くのよ、ゴルディ）",
  ui_story_5036_50361602_28_dialog_content = "（歌でウロボロスの恐怖をやわらげてあげるの）",
  ui_story_5036_50361602_29_dialog_content = "（それでアイドルとも、ステージとも…お別れしましょ）",
  ui_story_5036_50361602_30_dialog_content = "ウロボロス、この歌、あなたのために歌うわ！",
  ui_story_5036_50361602_31_dialog_content = "♪広がる空と大地、波打つ星の海♪",
  ui_story_5036_50361602_32_dialog_content = "♪私たちは流れ星のよう、思うままに生きる子供♪",
  ui_story_5036_50361602_33_dialog_content = "♪楽しく遊んで、いつかは疲れる♪",
  ui_story_5036_50361602_34_dialog_content = "♪照らす灯火、あたたかい家♪",
  ui_story_5036_50361602_35_dialog_content = "皆さん、指示に従い、落ち着いて避難してください！\nシャドウマスターが安全を保証します！",
  ui_story_5036_50361602_36_dialog_content = "♪照らす灯火、あたたかい家♪",
  ui_story_5036_50361602_37_dialog_content = "お姉ちゃん…今の、聞こえた？",
  ui_story_5036_50361602_38_dialog_content = "歌みたいだね？",
  ui_story_5036_50361602_39_dialog_content = "お嬢様、避難者は全員下船しました。",
  ui_story_5036_50361602_40_dialog_content = "分かったわ。もう一度出る準備をしなさい。\nまだ残っている人たちの救助に行くわ！",
  ui_story_5036_50361602_41_dialog_content = "♪照らす灯火、あたたかい家♪",
  ui_story_5036_50361602_42_dialog_content = "誰か…歌っているようですね？",
  ui_story_5036_50361602_43_dialog_content = "とてもやさしい歌声ね。\nあの巨像からかしら？",
  ui_story_5036_50361602_44_dialog_content = "♪子どもたちよ、ゆっくり眠れ♪",
  ui_story_5036_50361602_45_dialog_content = "♪子守歌に守られて♪",
  ui_story_5036_50361602_46_dialog_content = "♪ここは故郷、あなたの家♪",
  ui_story_5036_50361602_47_dialog_content = "キュウ――！",
  ui_story_5036_50361602_48_dialog_content = "（ウロボロスが反応したわ！）",
  ui_story_5036_50361602_49_dialog_content = "カレン、PlayerName！\nウロボロスが少しおとなしくなったわ！",
  ui_story_5036_50361602_50_dialog_content = "よかった！歌を聴いてくれたんだ！",
  ui_story_5036_50361602_51_dialog_content = "巨像の揺れも止まった！これなら大丈夫だ！",
  ui_story_5036_50361602_52_dialog_content = "今のうちよ、暗鬼の攻撃を止める！",
  ui_story_5036_50361602_53_dialog_content = "♪ここは故郷、あなたの家♪",
  ui_story_5036_50361602_54_dialog_content = "歌が…聞こえる？",
  ui_story_5036_50361602_55_dialog_content = "…巨像を停める時のメロディね。\n子守歌みたいに、優しい歌…",
  ui_story_5036_50361602_56_dialog_content = "ゴルディが歌ってる？でも…",
  ui_story_5036_50361602_57_dialog_content = "♪今は無きふるさと♪",
  ui_story_5036_50361602_58_dialog_content = "（シャミナードの歌が…聞こえる！？）",
  ui_story_5036_50361602_59_dialog_content = "（きっと悲しんでるのね。\n夢の世界に置き去りにしてしまったし…）",
  ui_story_5036_50361602_60_dialog_content = "（私の見たのは夢の世界にいる幻で、\n今、本当に存在するわけじゃないかもしれないけど…）",
  ui_story_5036_50361602_61_dialog_content = "（彼女の悲しみや孤独は、きっと幻じゃない…）",
  ui_story_5036_50361602_62_dialog_content = "（この歌をあなたにささげるわ。\nシャミナード…聞いて！）",
  ui_story_5036_50361602_63_dialog_content = "（あなたの悲しみが癒えることを願って…）",
  ui_story_5036_50361602_64_dialog_content = "♪今は無きふるさと♪",
  ui_story_5036_50361602_65_dialog_content = "♪若人は旅を続ける♪",
  ui_story_5036_50361602_66_dialog_content = "♪涙と共に過ごす夜♪",
  ui_story_5036_50361602_67_dialog_content = "♪別れと出会いを繰り返し♪",
  ui_story_5036_50361602_68_dialog_content = "♪待ち続ける夜明けの光♪",
  ui_story_5036_50361602_69_dialog_content = "♪その先には必ず光が待っている♪",
  ui_story_5036_50361602_70_dialog_content = "速射感知！",
  ui_story_5036_50361602_71_dialog_content = "いったいどれだけいるの…！？",
  ui_story_5036_50361602_72_dialog_content = "グォォ！！！",
  ui_story_5036_50361602_73_dialog_content = "気をつけて、来るわ！",
  ui_story_5036_50361602_74_dialog_content = "行かせない！",
  ui_story_5036_50361602_75_dialog_content = "ゴルディ、今のって、あなたの歌？",
  ui_story_5036_50361602_76_dialog_content = "すごくあったかい歌だね。\n天空ノ谷の日差しとそよ風みたい…",
  ui_story_5036_50361602_77_dialog_content = "そっか…天空ノ谷は壊されても、消えてはいなかったんだ…\n私の故郷は…生まれ変わるんだね。",
  ui_story_5036_50361602_78_dialog_content = "ゴルディ、あなたの歌、届いたよ。",
  ui_story_5036_50361602_79_dialog_content = "だから、私も――",
  ui_story_5036_50361602_80_dialog_content = "♪さあ涙を拭いて♪",
  ui_story_5036_50361602_81_dialog_content = "♪もう一度踏み出そう――♪",
  ui_story_5036_50361602_82_dialog_content = "♪はるか彼方まで歌を届けよう♪",
  ui_story_5036_50361602_83_dialog_content = "ありがとう、ゴルディ。",
  ui_story_5036_50361602_84_dialog_content = "未来からやってきたアイドルさん、\nウロボロスのこと…それから、これからのこと、よろしくね。",
  ui_story_5036_50361602_85_dialog_content = "シャミナード…消えた…？",
  ui_story_5036_50361602_86_dialog_content = "キュウ――",
  ui_story_5036_50361602_87_dialog_content = "ウロボロスが落ち着いたわ！",
  ui_story_5036_50361602_88_dialog_content = "PlayerName、作戦成功よ！",
  ui_story_5036_50361602_89_dialog_content = "よかった！",
  ui_story_5036_50361602_90_dialog_content = "こちらはそろそろ限界よ！",
  ui_story_5036_50361602_91_dialog_content = "くっ…！",
  ui_story_5036_50361602_92_dialog_content = "グォォ！！！",
  ui_story_5036_50361602_93_dialog_content = "速射感知！！！",
  ui_story_5036_50361602_94_dialog_content = "グ…グォォ！！！",
  ui_story_5036_50361602_95_dialog_content = "どれだけ打たれ強いの！？\nこれだけ攻撃を受けても、まだ倒れないなんて…",
  ui_story_5036_50361602_96_dialog_content = "この巨像の中で生き残っていた暗鬼よ。\n一筋縄では行かないでしょうね。",
  ui_story_5036_50361602_97_dialog_content = "あと少しだけ頑張ってくれよ！\nもうすぐウロボロスが飛べるようになりそうだ！",
  ui_story_5036_50361602_98_dialog_content = "グォォ――！！！",
  ui_story_5036_50361602_99_dialog_content = "カレン、危ない！",
  ui_story_5036_50361602_100_dialog_content = "キュウッ！",
  ui_story_5036_50361602_101_dialog_content = "<color=#e8d9bb>バン――！！</color>",
  ui_story_5036_50361602_102_dialog_content = "グオッ――",
  ui_story_5036_50361602_103_dialog_content = "え！？な、何があったの！？",
  ui_story_5036_50361602_104_dialog_content = "ウロボロスが暗鬼をはたき飛ばしたのよ！",
  ui_story_5036_50361602_105_dialog_content = "キュウキュウ～。",
  ui_story_5036_50361602_106_dialog_content = "もう怖がってはいないみたい…何だかうれしそうね？",
  ui_story_5036_50361602_107_dialog_content = "今が好機よ！\nあの暗鬼さえいなければ、残りは恐るるに足りない！",
  ui_story_5036_50361602_108_dialog_content = "氷花よ！",
  ui_story_5036_50361602_109_dialog_content = "グォォ…",
  ui_story_5036_50361602_110_dialog_content = "キュウ――！",
  ui_story_5036_50361602_111_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_5036_50361602_112_dialog_content = "巨像がまた揺れ始めたわ！",
  ui_story_5036_50361602_113_dialog_content = "ウロボロスは落ち着いたんじゃないの！？",
  ui_story_5036_50361602_114_dialog_content = "しっかりつかまってろよ。あいつは飛ぶ気だ！",
  ui_story_5036_50361602_115_dialog_content = "キュウ――",
  ui_story_5036_50361602_116_dialog_content = "キュウッ！！！",
  ui_story_5036_50361602_117_dialog_content = "見て、龍が飛んだ！",
  ui_story_5036_50361602_118_dialog_content = "ほんとだ！歌のお姉ちゃん、まだ巨像の上じゃないの？\n大丈夫かな？",
  ui_story_5036_50361602_119_dialog_content = "あのお姉ちゃんは、とても立派なアイドルだもの。",
  ui_story_5036_50361602_120_dialog_content = "どんなことがあっても、必ず乗り越えられるわ。",
  ui_story_5036_50361602_121_dialog_content = "だから…信じましょ。",
  ui_story_5036_50361602_122_dialog_content = "うん！",
  ui_story_5036_50361602_123_dialog_content = "私、信じる！",
  ui_story_5036_50361602_124_dialog_content = "さ、あなたたちも皆と一緒に避難して。",
  ui_story_5036_50361602_125_dialog_content = "…龍が飛び立ったということは、\nうまく片付いたってことかしら？",
  ui_story_5036_50361602_126_dialog_content = "急いで連絡を取って、状況を確かめないといけないわね。",
  ui_story_5036_50361602_127_dialog_content = "報告しますっ！\n巨像から避難してきた人たちの安全はすでに確保しました！",
  ui_story_5036_50361602_128_dialog_content = "かすり傷が数名いますが、\n重傷者、死者はいません！",
  ui_story_5036_50361602_129_dialog_content = "…うーん、城主様が飛空艇で\n巨像の近くにいたおかげかな～。",
  ui_story_5036_50361602_130_dialog_content = "そうじゃなきゃ、こんなに速く対応できなかったし、\nけが人ももっと出ていたかも…",
  ui_story_5036_50361602_131_dialog_content = "巨像と龍の状況は？",
  ui_story_5036_50361602_132_dialog_content = "龍は巨像から飛んで行って、\nカレンちゃんたちはまだ巨像に残ってます！",
  ui_story_5036_50361602_133_dialog_content = "…",
  ui_story_5036_50361602_134_dialog_content = "PlayerNameとバイスちゃんが一緒だから、\nカレンちゃんはきっと大丈夫です！",
  ui_story_5036_50361602_135_dialog_content = "飛空艇には引き続き、\n巨像からの避難を継続させよ。",
  ui_story_5036_50361602_136_dialog_content = "はいっ！",
  ui_story_5036_50361602_137_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_5036_50361602_138_dialog_content = "きゃあ！？",
  ui_story_5036_50361602_139_dialog_content = "巨像が傾いてるわ！？",
  ui_story_5036_50361602_140_dialog_content = "えっ！？",
  ui_story_5036_50361602_141_dialog_content = "ウロボロスがいなくなったことで、\nバランスが崩れたようです！",
  ui_story_5036_50361602_142_dialog_content = "巨像が高度を上げ始めているようです！",
  ui_story_5036_50361602_143_dialog_content = "じゃ、ステージクリアってとこかな！",
  ui_story_5036_50361602_144_dialog_content = "でしたら、急いで撤退しましょう。\n暗鬼が多すぎます。今の戦力では手に負えません！",
  ui_story_5036_50361602_145_dialog_content = "PlayerName！",
  ui_story_5036_50361602_146_dialog_content = "ウロボロスが飛び立ったわ、成功よ！",
  ui_story_5036_50361602_147_dialog_content = "やれやれ、めでたしめでたしだな！",
  ui_story_5036_50361602_148_option_content = "シャミナードは？",
  ui_story_5036_50361602_149_dialog_content = "さっき、シャミナードの歌が聞こえたんだ。\n君と一緒に歌ってた。",
  ui_story_5036_50361602_150_dialog_content = "シャミナードは…消えちゃったみたいね…",
  ui_story_5036_50361602_151_dialog_content = "ウロボロスと一緒に飛んで行ったんじゃなくて、\n完全に…",
  ui_story_5036_50361602_152_dialog_content = "そうなんだ…",
  ui_story_5036_50361602_153_dialog_content = "最後に言われたの…あとのことはお願いって。",
  ui_story_5036_50361602_154_dialog_content = "きっと歌を、アストラ大陸のみんなに聴いてもらいたいんだわ。",
  ui_story_5036_50361602_155_option_content = "イクストウルはどうなってるの？",
  ui_story_5036_50361602_156_dialog_content = "大事はありません。ただ、ウロボロスがいなくなったせいか、\n針路が変わってしまいました。",
  ui_story_5036_50361602_157_dialog_content = "高度が上がり始めています。",
  ui_story_5036_50361602_158_dialog_content = "PlayerName、話している時間はないわ。\n急いで撤退を！",
  ui_story_5036_50361602_159_dialog_content = "ウロボロスが飛び立って、イクストウルの針路がずれたようね。\n速度も上がっているわ。軽くなったからかしら。",
  ui_story_5036_50361602_160_dialog_content = "今の速度なら…10分ちょっとで、\n呼吸ができない高度に到達しそうよ！",
  ui_story_5036_50361602_161_dialog_content = "急いでここを離れましょ！",
  ui_story_5036_50361602_162_dialog_content = "じゃあ、イクストウルは――",
  ui_story_5036_50361602_163_dialog_content = "残念だけど…",
  ui_story_5036_50361602_164_dialog_content = "ガルー先輩がいても、\n今すぐイクストウルの制御システムを直すなんて無理よ。",
  ui_story_5036_50361602_165_dialog_content = "じゃあ、僕たちの努力はムダだったってこと…？",
  ui_story_5036_50361602_166_dialog_content = "ムダなんかじゃないわ！",
  ui_story_5036_50361602_167_dialog_content = "コンサートがダメになったって、\nステージをみんなに見せることはできたもの。",
  ui_story_5036_50361602_168_dialog_content = "それに、イクストウルとシャミナードの物語も\n知ることができたでしょ。",
  ui_story_5036_50361602_169_dialog_content = "私たちが忘れさえしなければ、\n2人は永遠に生き続けるわ。",
  ui_story_5036_50361602_170_dialog_content = "…",
  ui_story_5036_50361602_171_option_content = "行こう",
  ui_story_5036_50361602_172_option_content = "ずっと忘れない",
  ui_story_5036_50361602_173_dialog_content = "うん！",
  ui_story_5036_50361602_174_dialog_content = "PlayerName、急いで！",
  ui_story_5036_50361602_175_dialog_content = "ここから出ましょう！",
  ui_story_5036_50361602_176_dialog_content = "うん。",
  ui_story_5036_50361602_177_dialog_content = "ごめん、イクストウル…",
  ui_story_5036_50361602_178_dialog_content = "さようなら。",
  ui_story_5036_50361701_1_dialog_content = "ソラヴァン、起動！",
  ui_story_5036_50361701_2_dialog_content = "<color=#e8d9bb>ガラガラ――</color>",
  ui_story_5036_50361701_3_dialog_content = "イクストウルが…\n遠くの星空に向かって、飛んでいくわ…",
  ui_story_5036_50361701_4_dialog_content = "きっとシャミナードの歌声を\n星たちに届けにいくんだよ。",
  ui_story_5036_50361701_5_dialog_content = "とにかく、私たちはもう安全ね。",
  ui_story_5036_50361701_6_dialog_content = "コンサートは失敗しちゃったし、\nイクストウルも守れなかった…",
  ui_story_5036_50361701_7_dialog_content = "でも、みんなは無事だったし、影ノ街の人たちももう怖がらずに済むわ。\nこれでいいのよ。",
  ui_story_5036_50361701_8_dialog_content = "それにしても、ウロボロスの卵、\nどうしてこんな時に孵化したんだろう？",
  ui_story_5036_50361701_9_dialog_content = "もう少し待っててくれれば、\nこうはならずに済んだかもしれないのに…",
  ui_story_5036_50361701_10_dialog_content = "PlayerName、考えたんだけど…\nきっと私のせいだわ。",
  ui_story_5036_50361701_11_dialog_content = "シャミナードが夢に出てきて…違う…\nウロボロスの夢の中で、私、シャミナードに会ったの。",
  ui_story_5036_50361701_12_dialog_content = "「会った」？「夢で見た」じゃなくて？",
  ui_story_5036_50361701_13_dialog_content = "そう、「会った」の。",
  ui_story_5036_50361701_14_dialog_content = "…それってどういうこと？",
  ui_story_5036_50361701_15_dialog_content = "まさか本当に、\n死んだ人が何かの形でこの世に存在し続けてたってこと？",
  ui_story_5036_50361701_16_dialog_content = "ちょっとゾッとするわね…",
  ui_story_5036_50361701_17_dialog_content = "夢の中のシャミナードは…\nたぶんウロボロスの想像が作り出したものだと思うわ。",
  ui_story_5036_50361701_18_dialog_content = "え？本物のシャミナードじゃないってこと？",
  ui_story_5036_50361701_19_dialog_content = "ええ。夢の中のシャミナードが言ってたの――",
  ui_story_5036_50361701_20_dialog_content = "家に帰りたいって言う願いを感じ取って、\n夢の世界に天空ノ谷と「彼女」を作り出したって。",
  ui_story_5036_50361701_21_dialog_content = "…夢の中に出てきた天空ノ谷やシャミナードは、\nウロボロスの想像の中にあるものだと私は思ってるわ。",
  ui_story_5036_50361701_22_dialog_content = "私たちが巨像で夢を見たのは、\nウロボロスが皆の心をどうにかしていたのではなくて――",
  ui_story_5036_50361701_23_dialog_content = "ウロボロス自身の夢を、私たちが見てたんじゃないかしら？",
  ui_story_5036_50361701_24_dialog_content = "つまり、たまたま皆が同じ夢を見たんじゃなくて、\nみんながウロボロスの夢の世界に行ったのよ。",
  ui_story_5036_50361701_25_dialog_content = "どうしてそんな夢の世界を作ったんだろう？",
  ui_story_5036_50361701_26_dialog_content = "なつかしさと…悔しさ、かしら…",
  ui_story_5036_50361701_27_dialog_content = "ウロボロスは卵になった後に、\nシャミナードが危ないって感じたみたいね。",
  ui_story_5036_50361701_28_dialog_content = "でも、何もできなかった…\nけど、シャミナードの家に帰りたいっていう願いを感じとったの。",
  ui_story_5036_50361701_29_dialog_content = "だから、シャミナードを思って、\n夢の世界の中で、家に帰らせてあげたんだと思うわ。",
  ui_story_5036_50361701_30_dialog_content = "その夢の世界を守るために、\nウロボロスはずっと眠ったままだったのよ。",
  ui_story_5036_50361701_31_dialog_content = "なるほどなぁ。\nそれでずっと卵のままだったのか。",
  ui_story_5036_50361701_32_dialog_content = "じゃ、どうしてまた突然起きる気になったんだ？\nそれも夢と関係あるのか？",
  ui_story_5036_50361701_33_dialog_content = "私が口を滑らせちゃったの…",
  ui_story_5036_50361701_34_dialog_content = "天空ノ谷が滅んだって知ってしまって…\nシャミナードがひどく悲しんだわ。",
  ui_story_5036_50361701_35_dialog_content = "夢の世界もそれと同時に壊れ始めたわ。\n元の状態に戻せなくなっちゃったの。",
  ui_story_5036_50361701_36_dialog_content = "謝る時間もなかったわ。",
  ui_story_5036_50361701_37_dialog_content = "でも、シャミナードは最後に\nあの歌をみんなに聴かせてあげてほしいって言ったわ。",
  ui_story_5036_50361701_38_dialog_content = "アイドルを続けることはもうできなくても、\nシャミナードの願いはかなえてあげたいの…",
  ui_story_5036_50361701_39_dialog_content = "<color=#e8d9bb>ピピピ――</color>",
  ui_story_5036_50361701_40_dialog_content = "あ！シェオルさんから通信要請だ！",
  ui_story_5036_50361701_41_dialog_content = "ど、どうする…？出る？",
  ui_story_5036_50361701_42_dialog_content = "何だかイヤな予感がするな。",
  ui_story_5036_50361701_43_dialog_content = "待って、「幸運の弾丸」で決めるわ！",
  ui_story_5036_50361701_44_dialog_content = "<color=#e8d9bb>カチャン――</color>",
  ui_story_5036_50361701_45_dialog_content = "頭が下ね。ラッキーの兆しよ！",
  ui_story_5036_50361701_46_dialog_content = "本当に出ていいの？",
  ui_story_5036_50361701_47_dialog_content = "ええ、構わないわ。",
  ui_story_5036_50361701_48_dialog_content = "逃げていたって何の解決にもならないもの。\nきちんと向き合えば、チャンスは必ず訪れるはずよ！",
  ui_story_5036_50361701_49_dialog_content = "じゃあ、出るよ――",
  ui_story_5036_50361701_50_dialog_content = "PlayerName？",
  ui_story_5036_50361701_51_dialog_content = "シェオルさん！",
  ui_story_5036_50361701_52_dialog_content = "あなたたち、今どこ？\nどういう状況？",
  ui_story_5036_50361701_53_dialog_content = "ソラヴァンの中です。\n全員無事です。けが人もいません。",
  ui_story_5036_50361701_54_dialog_content = "そう、けが人は出なかったのね。それじゃあ…",
  ui_story_5036_50361701_55_dialog_content = "ゴ・ル・ディ？",
  ui_story_5036_50361701_56_dialog_content = "うっ――！",
  ui_story_5036_50361701_57_dialog_content = "きちんと説明してもらえるかしら？\n絶対成功させるって言ったのに。この有り様、どういうこと？",
  ui_story_5036_50361701_58_dialog_content = "え、ええと…",
  ui_story_5036_50361701_59_dialog_content = "ごめんなさい。私のせいよ…",
  ui_story_5036_50361701_60_dialog_content = "きちんと会場の下見をしなかったから、\nウロボロスの卵があるのに気付かなくて…",
  ui_story_5036_50361701_61_dialog_content = "おまけに私の歌を聞いて\n目覚めるなんて、思ってなかったから…",
  ui_story_5036_50361701_62_dialog_content = "ん？説明が下手だな～。\nもっとウロボロスに責任を押しつけたっていいと思うぜ？",
  ui_story_5036_50361701_63_dialog_content = "いいえ、これは全部、私の責任よ…\n契約どおり、違約金を支払うわ。",
  ui_story_5036_50361701_64_dialog_content = "まったく…あなたのせいで、こっちは散々よ。",
  ui_story_5036_50361701_65_dialog_content = "大金をかけて宣伝したのに、巨像は飛んで行っちゃうし、\n設備の修理費もステージの設営費用もムダになっちゃったし…",
  ui_story_5036_50361701_66_dialog_content = "想定外の費用がかなりかかったわ。\n観客の騒ぎを抑えるのにも苦労したんだから。",
  ui_story_5036_50361701_67_dialog_content = "ごめんなさい…",
  ui_story_5036_50361701_68_dialog_content = "でも、心配しないで。\n全額私が補償するわ…",
  ui_story_5036_50361701_69_dialog_content = "アイドルはもうできなくても、\n仕事を見つけて、お金を稼いで――",
  ui_story_5036_50361701_70_dialog_content = "あら？補償しろなんて言ったかしら？",
  ui_story_5036_50361701_71_dialog_content = "…えっ？",
  ui_story_5036_50361701_72_dialog_content = "コンサート自体は失敗したけど、\n想像以上の反響があったわ！",
  ui_story_5036_50361701_73_dialog_content = "あなたが歌に込めた気持ち、\nウロボロスだけじゃなく、観客にもちゃんと伝わったみたいよ？",
  ui_story_5036_50361701_74_dialog_content = "アイドルなんて興味なかったって人たちが、\n今回の事件で、あなたのことを知ったわ。",
  ui_story_5036_50361701_75_dialog_content = "おかげで、「アイドル」に関する問い合わせが殺到してるの！",
  ui_story_5036_50361701_76_dialog_content = "ええ…！？",
  ui_story_5036_50361701_77_dialog_content = "契約はきちんと果たしてもらったわ。しかも、想像以上にね。",
  ui_story_5036_50361701_78_dialog_content = "わ、私の聞き間違いじゃないわよね！？",
  ui_story_5036_50361701_79_dialog_content = "あら、信じられない？\nだったら、自分の耳で確かめればいいわ。",
  ui_story_5036_50361701_80_dialog_content = "歌のお姉ちゃん、聞こえる！？",
  ui_story_5036_50361701_81_dialog_content = "あ…あなたはあの時の！\n2人とも元気？",
  ui_story_5036_50361701_82_dialog_content = "うん、元気だよ！歌のお姉ちゃん、ほんとにすごいね！",
  ui_story_5036_50361701_83_dialog_content = "歌が上手なだけじゃなくて、\n龍に言うこと聞かせちゃうんだもん！",
  ui_story_5036_50361701_84_dialog_content = "みんな、カッコいいって、見とれてた！",
  ui_story_5036_50361701_85_dialog_content = "ホントに？\n…ふふ、そんな風に言ってもらえて、うれしいわ！",
  ui_story_5036_50361701_86_dialog_content = "ほかにもお姉ちゃんと話したい人がいるんだって！",
  ui_story_5036_50361701_87_dialog_content = "あなたがゴルディ？",
  ui_story_5036_50361701_88_dialog_content = "は、はい。ええと…あなたは？",
  ui_story_5036_50361701_89_dialog_content = "私の専属歌手になる気はないかしら？",
  ui_story_5036_50361701_90_dialog_content = "えっ？",
  ui_story_5036_50361701_91_dialog_content = "今日の行いを見て、あなたは高潔、勇敢で、\n信頼に値する人だと感じたの。",
  ui_story_5036_50361701_92_dialog_content = "私の専属歌手になりなさい！\n白夜城に最高のステージを用意してあげるわ！",
  ui_story_5036_50361701_93_dialog_content = "ありがとうございます。でも…",
  ui_story_5036_50361701_94_dialog_content = "不満かしら？何でも条件を言いなさい。\n望み通りの報酬を出してあげるわ。",
  ui_story_5036_50361701_95_dialog_content = "いいえ、報酬の問題じゃないわ。\n私は誰かの専属じゃなくて、アイドルになりたいの。",
  ui_story_5036_50361701_96_dialog_content = "アイドルは観客がどんな身分だろうと、\n関係なく平等に喜びと希望を与えることができる存在よ。",
  ui_story_5036_50361701_97_dialog_content = "それに、アイドルの先輩と約束したの。\n2人の歌を、すべての人に届けるって。",
  ui_story_5036_50361701_98_dialog_content = "そう？とても残念ね…",
  ui_story_5036_50361701_99_dialog_content = "けれど、あなたの夢がかなうことを心から祈っているわ。\n次のコンサートも、必ず見に行くわね。",
  ui_story_5036_50361701_100_dialog_content = "ありがとう！",
  ui_story_5036_50361701_101_dialog_content = "どう？これで分かったでしょ？",
  ui_story_5036_50361701_102_dialog_content = "ええ！",
  ui_story_5036_50361701_103_dialog_content = "良かったわ。じゃ、元気を出して。\n次の挑戦にむけて、さっそく準備開始よ！",
  ui_story_5036_50361701_104_dialog_content = "スケジュールはもうびっちり詰まってるから、\n影ノ街に戻ったらすぐに取りかかってもらうわよ。",
  ui_story_5036_50361701_105_dialog_content = "すぐに戻るわ！",
  ui_story_5036_50361701_106_dialog_content = "それから、ヴィックって言ったかしら？\nいいアイドルの原石を見つけたって聞いてるけど、近くにいる？",
  ui_story_5036_50361701_107_dialog_content = "ん？俺に用か？",
  ui_story_5036_50361701_108_dialog_content = "どう？私の商会で専属アイドルになる気はない？",
  ui_story_5036_50361701_109_dialog_content = "ん？\n…ハハハ、やめとくよ！",
  ui_story_5036_50361701_110_dialog_content = "他人から注目されるなんて性に合わないんでね。\n動物たちと一緒の暮らしの方が、俺には合ってる。",
  ui_story_5036_50361701_111_dialog_content = "まったく考えてみる気はないの？",
  ui_story_5036_50361701_112_dialog_content = "報酬はたっぷり出すわよ。\n影ノ街で出せる最高品質のシャンパンもつけてあげる。",
  ui_story_5036_50361701_113_dialog_content = "ん？そりゃ悪くない話だな。モジャたちの世話なんか止めて、\n毎日飲んで暮らせるってのも――",
  ui_story_5036_50361701_114_dialog_content = "ウキュ！？",
  ui_story_5036_50361701_115_dialog_content = "ウキュッ！！！",
  ui_story_5036_50361701_116_dialog_content = "なんだ！？おい、モジャ、俺を引きずるな！\n放せ、おい！モジャ――",
  ui_story_5036_50361701_117_dialog_content = "…家族の同意が得られなかったみたいですね。",
  ui_story_5036_50361701_118_dialog_content = "じゃ、その話はまた今度にしましょ。",
  ui_story_5036_50361701_119_dialog_content = "とりあえず、影ノ街で待ってるわ。",
  ui_story_5036_50361701_120_dialog_content = "よかった、ホントによかったわ…！",
  ui_story_5036_50361701_121_dialog_content = "私、アイドルを続けられるのね！",
  ui_story_5036_50361701_122_dialog_content = "おめでとう、ゴルディ！",
  ui_story_5036_50361701_123_dialog_content = "今回のコンサートはいろいろあったけど…\n次こそ成功させてみせるわ！",
  ui_story_5036_50361701_124_dialog_content = "PlayerName、かならず観に来てね。\n一番いい席を用意しておくから！",
  ui_story_5036_50361701_125_dialog_content = "もちろん、約束だよ！",
  ui_story_5036_50361701_126_dialog_content = "でも、少し時間がかかっちゃうかも！",
  ui_story_5036_50361701_127_dialog_content = "帰ったらまず、この経験を曲にしてみたいし！",
  ui_story_5036_50361701_128_dialog_content = "どうやら、一件落着のようね。",
  ui_story_5036_50361701_129_dialog_content = "そうね。気が楽になったら、どっと疲れちゃったわ。",
  ui_story_5036_50361701_130_dialog_content = "私も眠くなってきました。ふわぁ～…",
  ui_story_5036_50361701_131_dialog_content = "フン、こんな騒ぎになっていなければ、\n今頃ゆっくり風呂に入れていたというに…",
  ui_story_5036_50361701_132_dialog_content = "どっちでもいいだろう。",
  ui_story_5036_50361701_133_dialog_content = "入っても入らなくても、変わらない。",
  ui_story_5036_50361701_134_dialog_content = "それにしても、動いてる古代の科学技術を生で見ることができて、\n本当にラッキーだったね～！",
  ui_story_5036_50361701_135_dialog_content = "あのスクリーンと音響設備もスゴかったな～。\n今のあたしの頭の中、インスピレーションでいっぱいだよ！",
  ui_story_5036_50361701_136_dialog_content = "原理を分析して、レプリカを作って…\n王座にも取り付けよっかな～？",
  ui_story_5036_50361701_137_dialog_content = "まさか…",
  ui_story_5036_50361701_138_dialog_content = "そうすれば、いつでもどこでもゲームができそうでしょ！",
  ui_story_5036_50361701_139_dialog_content = "やはり…",
  ui_story_5036_50361701_140_dialog_content = "とにかく、まずは地上まで送ってくよ。",
  ui_story_5036_50361701_141_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_5036_50361701_142_dialog_content = "こんなに時間が経ってたんだね。\nもう夜が明けてる。",
  ui_story_5036_50361701_143_dialog_content = "やっと地上に戻れたか。いや～、一苦労だったな。\nお前もそう思うだろ、モジャ？",
  ui_story_5036_50361701_144_dialog_content = "ウキュッ！",
  ui_story_5036_50361701_145_dialog_content = "ヴィック、僕たちが戦ってるのを見てただけじゃなかった？",
  ui_story_5036_50361701_146_dialog_content = "つれない事を言うなよ。\n俺だって命がけでウロボロスを守ってたろ？",
  ui_story_5036_50361701_147_dialog_content = "…まあ、いいや。\n確かに命がけだったし、これ以上は何も言わないよ。",
  ui_story_5036_50361701_148_dialog_content = "じゃ、俺はここらで失礼するぞ。\nフィアとシーラがウロボロスの情報を楽しみにしてるからな。",
  ui_story_5036_50361701_149_dialog_content = "またな！",
  ui_story_5036_50361701_150_dialog_content = "またね、ヴィック。",
  ui_story_5036_50361701_151_dialog_content = "気を付けて！また誘拐されないようにね！",
  ui_story_5036_50361701_152_dialog_content = "心配するなって。俺は頼れるオトナなんだぜ！",
  ui_story_5036_50361701_153_dialog_content = "我々も飛空艇で白夜城に戻るとするか…",
  ui_story_5036_50361701_154_dialog_content = "（まったく、次にこういう事が有る時は\n風呂を事前に用意させておかねば、やっていられん…）",
  ui_story_5036_50361701_155_dialog_content = "そうだ、そこのR・Wの賊ども。\n次に会う時は監獄送りにしてやるぞ。覚悟しておくがいい。",
  ui_story_5036_50361701_156_dialog_content = "あん？でかい口をたたく野郎だな。\nやれるモンならやってみな！",
  ui_story_5036_50361701_157_dialog_content = "空の末裔、また。",
  ui_story_5036_50361701_158_dialog_content = "またね！",
  ui_story_5036_50361701_159_dialog_content = "みんな帰っちゃったの？\nじゃ、あたしたちも帰ろっか！",
  ui_story_5036_50361701_160_dialog_content = "そうですね。休暇ももうすぐ明けますし、\n仕事に戻らなければ…",
  ui_story_5036_50361701_161_dialog_content = "一緒に巨像で帰らないんですか？",
  ui_story_5036_50361701_162_dialog_content = "あたしとシヴォーンは車で帰るから気にしないで。\n次の予定もあるんでしょ？",
  ui_story_5036_50361701_163_dialog_content = "王座にスクリーンとゲーム機を取り付ける方法、\n2人でたっぷり車の中で議論したいしね！",
  ui_story_5036_50361701_164_dialog_content = "ええ…？",
  ui_story_5036_50361701_165_dialog_content = "さ、行くよ、シヴォーン！",
  ui_story_5036_50361701_166_dialog_content = "た…助けてください！",
  ui_story_5036_50361701_167_dialog_content = "シヴォーンさんみたいにしっかりした人でも、\nどうにもできないことってあるんだね…",
  ui_story_5036_50361701_168_dialog_content = "じゃ、私たちも帰るとするか。",
  ui_story_5036_50361701_169_dialog_content = "うん…そうだ！",
  ui_story_5036_50361701_170_dialog_content = "決めた！",
  ui_story_5036_50361701_171_dialog_content = "なんだ？\nどうせまた、くだらない思いつきだろうが…",
  ui_story_5036_50361701_172_dialog_content = "帰ったらボスを説得して、\nトラベラーの頭にステージを造ってもらうの！",
  ui_story_5036_50361701_173_dialog_content = "お！？悪くないな！",
  ui_story_5036_50361701_174_dialog_content = "私のアイデアだからね！\nアイドル風のステージにしてもらおっと！",
  ui_story_5036_50361701_175_dialog_content = "おい、待ちやがれ！メタルこそ本物の音楽だ！",
  ui_story_5036_50361701_176_dialog_content = "あの2人、いつもにぎやかね！",
  ui_story_5036_50361701_177_dialog_content = "PlayerName、私もここでいいわ。",
  ui_story_5036_50361701_178_dialog_content = "ホントにお疲れ様！",
  ui_story_5036_50361701_179_dialog_content = "君の方こそ！コンサートどころか、\nあれだけたくさん戦ったんだ。ゆっくり休んでね。",
  ui_story_5036_50361701_180_dialog_content = "私はプロのアイドルよ。\n少し休めば、すぐに元気になるわ！",
  ui_story_5036_50361701_181_dialog_content = "次のコンサート、楽しみにしててね！",
  ui_story_5036_50361701_182_dialog_content = "うん、待ってるよ！",
  ui_story_5036_50361701_183_dialog_content = "またね～！",
  ui_story_5036_50361701_184_dialog_content = "ゴルディさんが暴力的になっているというのは、やはりデマでした…\n私がきちんと記事にして、濡れ衣を晴らさなければ！",
  ui_story_5036_50361701_185_dialog_content = "…編集長？",
  ui_story_5036_50361701_186_dialog_content = "<size=45>ブランディ！今ごろになって連絡をよこすとは、\nいったいどういうつもりだ！？</size>",
  ui_story_5036_50361701_187_dialog_content = "私を満足させられるような大スクープが獲れないのなら、\nさっさと辞めてしまえ！",
  ui_story_5036_50361701_188_dialog_content = "ア、アイドルのゴルディが暴力的になっているというウワサに関して、\nデマだということが分かりました！",
  ui_story_5036_50361701_189_dialog_content = "…",
  ui_story_5036_50361701_190_dialog_content = "これだけ長く例の巨像で取材していて、\nたったそれだけか？",
  ui_story_5036_50361701_191_dialog_content = "デマだから何だというのだ？読者が喜ぶと思うか？\nその程度の記事しか出ないような新聞社はつぶれるぞ。",
  ui_story_5036_50361701_192_dialog_content = "ブランディ、お前には失望した。\nお前は――",
  ui_story_5036_50361701_193_dialog_content = "待ってください！それだけではありません。\n巨像のコンサートで起こった事件に関する独占スクープもありますよ！",
  ui_story_5036_50361701_194_dialog_content = "何？本当か？さっさと見せろ！",
  ui_story_5036_50361701_195_dialog_content = "お見せするのは構いませんが、1つ条件があります。",
  ui_story_5036_50361701_196_dialog_content = "何だ？",
  ui_story_5036_50361701_197_dialog_content = "ゴルディの件に関する真実を伝える記事と、\n漂泊の巨像事件の記事は、必ず同時に掲載してください！",
  ui_story_5036_50361701_198_dialog_content = "彼女に対する世間の誤解を解きたいのです！",
  ui_story_5036_50361701_199_dialog_content = "ほう？言うじゃないか…",
  ui_story_5036_50361701_200_dialog_content = "<size=45>いいだろう！</size>",
  ui_story_5036_50361701_201_dialog_content = "約束する。その代わり、今すぐネタを持ってこい！",
  ui_story_5036_50361701_202_dialog_content = "ただちに！",
  ui_story_5036_50361701_203_dialog_content = "――つまり、動物クッキーでドラゴライオンを手なずけてまで\n漂流してる巨像の調査に行ったのに、収穫ゼロだったってこと！？",
  ui_story_5036_50361701_204_dialog_content = "あたし、ドラゴライオンのことずいぶん探したんだよ！？\nおまけに暗鬼には襲われかけたし…",
  ui_story_5036_50361701_205_dialog_content = "ダメ師匠、どう埋め合わせしてくれるつもり！？",
  ui_story_5036_50361701_206_dialog_content = "いやいや、確かにウロボロスはほとんど調べられなかったが、\n目覚めさせることはできたんだ。情報だって収集できた。",
  ui_story_5036_50361701_207_dialog_content = "ウロボロスが戻ったんだ、\nアストラ大陸全体にもきっと変化が起こる！",
  ui_story_5036_50361701_208_dialog_content = "師匠を信じろ！今回集まった情報があれば、\n次は簡単に見つけられるさ！",
  ui_story_5036_50361701_209_dialog_content = "なーんか聞き覚えがあるな～？",
  ui_story_5036_50361701_210_dialog_content = "この前はこう言ってたわね――",
  ui_story_5036_50361701_211_dialog_content = "「師匠を信じろ！次は絶対大金を稼げるぞ～。」",
  ui_story_5036_50361701_212_dialog_content = "先輩、よく覚えてるね？",
  ui_story_5036_50361701_213_dialog_content = "前にも同じことを言ったからよ。",
  ui_story_5036_50361701_214_dialog_content = "その割には、今のところお金のことに何の改善もみられないわ。\nそれどころか、ますますド貧乏になってるみたいね。",
  ui_story_5036_50361701_215_dialog_content = "そういえば先月の珍獣たちのごはん代、\nまだ払ってもらってない！",
  ui_story_5036_50361701_216_dialog_content = "ううっ…お前たちにとって、俺はそんなに信用できないのか？",
  ui_story_5036_50361701_217_dialog_content = "当然でしょ？",
  ui_story_5036_50361701_218_dialog_content = "あ～あ、傷つくなぁ！",
  ui_story_5036_50361701_219_dialog_content = "俺、やっぱりアイドルの方が向いてるかもな…？",
  ui_story_5036_50361701_220_dialog_content = "お情けで拍手してくれてたんでしょ。\nカン違いしないことね。",
  ui_story_5036_50361701_221_dialog_content = "うっ…",
  ui_story_5036_50361701_222_dialog_content = "でも、ダメ師匠の言うこと、珍しく本当だったね。\nウロボロス、ほんとにあの巨像にいたんだ。",
  ui_story_5036_50361701_223_dialog_content = "どうして分かったの？",
  ui_story_5036_50361701_224_dialog_content = "ウロボロスにとっちゃ、「巨像を目指す」ってのは、\n「家に帰る」のと同じことなんじゃないか？",
  ui_story_5036_50361701_225_dialog_content = "「家に帰る」？どういうこと？",
  ui_story_5036_50361701_226_dialog_content = "要するに、ウロボロスは何年生きようが、\n何度生まれ直そうが…",
  ui_story_5036_50361701_227_dialog_content = "始まりの始まりは、結局他のウロボロスが生んだ卵だ。",
  ui_story_5036_50361701_228_dialog_content = "幼体期の動物ってのは、本能で親に付いていく。\n自分を守ってくれる存在だからな。",
  ui_story_5036_50361701_229_dialog_content = "成長周期の中で、\n徐々に幼体に戻っていく時のウロボロスも同じだろう。",
  ui_story_5036_50361701_230_dialog_content = "ただ、ウロボロスはきわめて希少だ。\n生みの親なんて、まず見つからないだろうな。",
  ui_story_5036_50361701_231_dialog_content = "だから、自分と深いつながりのある\n巨像のところへ帰るしかなかったんだろうな。",
  ui_story_5036_50361701_232_dialog_content = "巨像を親だと思ってるってこと？\nなんだかかわいそう…",
  ui_story_5036_50361701_233_dialog_content = "じゃあ、ウロボロスと血のつながりのある師匠も、\nいつか巨像に帰るの？",
  ui_story_5036_50361701_234_dialog_content = "俺の正体は謎に満ちてるのさ。\n子どもがあれこれ推測するもんじゃない…",
  ui_story_5036_50361701_235_dialog_content = "ま、ダメ師匠に人の心をどうにかする力なんてないし、\nウロボロスと血のつながりがあるっていうトコから、どうせウソでしょ。",
  ui_story_5036_50361701_236_dialog_content = "そこは本当だぞ！",
